insert into private_case_citations (id, citations, updated_at) values
('main', $${"unpaid_rent": [{"url": "https://caselaw.findlaw.com/court/ca-court-of-appeal/1689590.html", "year": 2015, "notes": "Widely cited California case on when a lease remedy provision (cotenancy/rent-abatement, not a classic 'acceleration' clause) is struck down as an unenforceable penalty versus a valid liquidated-damages-style term. Also available at Justia/law.justia.com (case no. F067327) and caselaw.findlaw.com/ca-court-of-appeal/1691835.html.", "outcome": "Jury awarded landlord $672,100 in unpaid rent plus roughly $3.1 million in termination damages (about $3.785 million total, plus ~$916,275 in attorney fees). On appeal, the rent-abatement provision was held an unenforceable penalty (no reasonable relationship to anticipated harm), but the termination provision itself was upheld as valid. Judgment was modified to award only the $672,100 in unpaid rent (final modified judgment approximately $1,588,375.97 with costs).", "caseName": "Grand Prospect Partners, L.P. v. Ross Dress for Less, Inc.", "citation": "F067327 (Cal. Ct. App., 5th Dist., Jan. 12, 2015) (unpublished/partially published)", "confidence": "high", "dollarAmount": 672100, "jurisdiction": "CA"}, {"url": "https://caselaw.findlaw.com/court/ca-court-of-appeal/2181216.html", "year": 2023, "notes": "One of several 2022-2023 California appellate decisions rejecting COVID-19-based defenses to commercial rent obligations. Also reported at law.justia.com/cases/california/court-of-appeal/2023/d079903.html.", "outcome": "Trial court granted summary judgment for the landlord, finding $520,361.29 in unpaid rent owed as of October 2021; the Court of Appeal affirmed, holding that force majeure, impossibility, impracticability, and frustration-of-purpose defenses did not excuse the tenant's rent obligation because payment of rent (not operation of the gym) was the relevant contractual performance.", "caseName": "SVAP III Poway Crossings, LLC v. Fitness International, LLC", "citation": "D079903 (Cal. Ct. App., 4th Dist., Div. 1, Jan. 20, 2023)", "confidence": "high", "dollarAmount": 520361, "jurisdiction": "CA"}, {"url": "https://www.mpamag.com/us/mortgage-industry/industry-trends/indiana-court-dismantles-35m-damages-award-in-commercial-lease-dispute/573141", "year": 2026, "notes": "Relied on secondary reporting (Mortgage Professional America) and search-engine summaries rather than a directly retrieved primary opinion; the $3,559,407.17 figure is the trial court's original (since-vacated) award, not a final affirmed number. Treat this figure as illustrative of exposure magnitude in an industrial lease default, not a final judgment amount.", "outcome": "After a damages hearing, the trial court awarded Anson $3,559,407.17 plus post-judgment interest, attorney fees, and costs. The Court of Appeals affirmed the finding of breach but reversed and remanded the damages calculation, holding the trial court improperly accrued interest and late fees on the full unpaid balance before subtracting the replacement tenant's rent, instead of crediting the mitigation offset starting when the new tenant's rent obligation began (February 2024).", "caseName": "CPUS Anson Building 8A, LP v. Tradewinds Holding Company, Inc.", "citation": "Court of Appeals of Indiana (2026) (exact docket number not independently confirmed)", "confidence": "medium", "dollarAmount": 3559407, "jurisdiction": "IN"}, {"url": "https://caselaw.findlaw.com/court/nc-court-of-appeals/1431214.html", "year": 2006, "notes": "Good illustrative small-business/retail fact pattern with a modest dollar figure. Initial jury verdict was $13,110 (net of an improperly-applied mitigation offset); the correct, appellate-endorsed recovery figure is the full $35,511.70. Relied on a findlaw case-summary extraction rather than the full opinion text.", "outcome": "At trial, actual damages were calculated at $35,511.70, but the jury applied a mitigation offset of $22,401.70, awarding the landlord only $13,110.00. On appeal, the North Carolina Court of Appeals held the lease's clause relieving the landlord of any duty to mitigate was enforceable and not against public policy, vacating the reduced verdict and remanding for entry of judgment on the full $35,511.70 in actual damages without any mitigation offset.", "caseName": "Sylva Shops Limited Partnership v. Hibbard", "citation": "No. COA04-1485 (N.C. Ct. App. Jan. 17, 2006) (unpublished)", "confidence": "medium", "dollarAmount": 35511, "jurisdiction": "NC"}, {"year": 2020, "notes": "INCOMPLETE VERIFICATION: only the $6,391.63 attorney's-fee component and the general procedural posture (landlord appealing for a larger recovery, including real estate taxes) were confirmed from available secondary sources -- the full opinion text was not directly accessible, so the underlying base rent judgment amount and the Appellate Court's ultimate holding on the real-estate-tax and fee issues are NOT confirmed here. Included primarily because it's a real, citable, tenant-AND-guarantor unpaid-rent judgment distinct from the other citations in this claim type, but treat the dollarAmount and outcome with more caution than any other citation in this dataset -- verify directly against the full opinion before relying on it.", "outcome": "Landlord sued a commercial lessee and its guarantor for unpaid amounts due under a lease of property at 482 Glenbrook Road, Stamford. The trial court (an attorney trial referee) awarded the landlord damages and $6,391.63 in attorney's fees; the landlord appealed, arguing the court erred by not including unpaid real estate taxes owed under the lease in the judgment and by awarding only that amount in fees.", "caseName": "Sclafani Properties, LLC v. Sport-N-Life Distributing, LLC", "citation": "198 Conn. App. 292 (2020)", "sourceUrl": "https://law.justia.com/cases/connecticut/court-of-appeals/2020/ac40066.html", "confidence": "low", "dollarAmount": 6392, "jurisdiction": "CT"}, {"year": 2024, "notes": "A strong, current, appellate-affirmed illustration of two compounding features this claim type should account for when a corporate guarantor is involved: (1) a multi-year unpaid-rent exposure period (4.5+ years here) plus statutory/contractual interest can dwarf the base monthly rent figure, and (2) a broadly-worded guaranty waiver-of-defenses clause can foreclose essentially every defense the guarantor might otherwise raise, including ones related to the landlord's own subsequent default and foreclosure. dollarAmount left null since the specific total judgment figure (rent x 55+ months x lease rate, plus compounding 9% interest) was not independently confirmed from available sources, though the multi-year exposure period itself is well documented.", "outcome": "Department store operator CPS leased anchor retail space in an Illinois mall from WEC 98C-3 LLC; Saks Inc. (CPS's corporate affiliate) guaranteed CPS's rent obligations. When CPS stopped paying rent, Saks made no payments under the guaranty either, contributing to the landlord's own mortgage default and the property's sale at foreclosure to a successor landlord. The successor sued Saks on the guaranty. The Seventh Circuit affirmed judgment holding Saks liable for CPS's unpaid rent from February 2018 through September 2022 -- more than four and a half years -- plus 9% interest under the lease's penalty provision, rejecting Saks's affirmative defenses because the guaranty's waiver-of-defenses clause expressly barred asserting any defense to liability.", "caseName": "WEC 98C-3 LLC v. SFA Holdings Inc.", "citation": "99 F.4th 961 (7th Cir. 2024)", "sourceUrl": "https://law.justia.com/cases/federal/appellate-courts/ca7/23-1489/23-1489-2024-04-24.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal (7th Cir., applying IL law)"}, {"year": 2026, "notes": "A significant, CURRENT (2026) appellate-level tenant win directly contradicting the more landlord-friendly COVID-rent outcomes already in this dataset (e.g., SVAP III Poway Crossings). Confirms that lease-specific takings/casualty clause language -- not a generic force-majeure argument -- can still excuse rent for a pandemic-era closure period years after most COVID rent litigation resolved in landlords' favor; the outcome turns entirely on the particular clause's wording, which should be checked lease-by-lease. Also reported at law.justia.com/cases/federal/appellate-courts/ca2/25-148/25-148-2026-05-05.html.", "outcome": "Landlord Delshah won summary judgment in the district court on its breach-of-contract claim for $6,707,916.84 in unpaid rent against retail tenant Free People, which had stopped paying rent when NYC's COVID-19 emergency orders shut down non-essential retail in March 2020. The Second Circuit REVERSED, holding the lease's takings/casualty provision excused rent because the government orders prevented Free People from operating its brick-and-mortar clothing store -- even though the tenant retained some minimal physical access to the space -- distinguishing 'inability to operate the business' from 'total loss of access.' The court granted summary judgment to the tenant instead on its own breach-of-contract counterclaim.", "caseName": "Delshah 60 Ninth, LLC v. Free People of PA LLC", "citation": "Nos. 25-148 & 25-237 (2d Cir. May 5, 2026)", "sourceUrl": "https://caselaw.findlaw.com/court/us-2nd-circuit/118329373.html", "confidence": "high", "dollarAmount": 6707916, "jurisdiction": "Federal (2d Cir., applying NY law)"}, {"year": 2025, "notes": "Useful real-world illustration that a landlord can win on liability yet still lose the liquidated-damages multiplier it drafted for, recovering only actual unpaid rent instead -- reinforcing that this claim type's damages formula (unpaidRentAmount, not a multiplier) is the right default absent a separately-vetted enforceable liquidated-damages clause. Case caption sometimes rendered 'Newark Shopping Center Owner, LLC v. Saudades Group, LLC, et al.'; individual guarantors Phillip and Pamela Piraino were co-defendants.", "outcome": "After a one-day bench trial, the court found for the landlord on breach of a commercial lease and guaranty, holding the tenant (a restaurant operator) breached by never opening for business. However, the court held the lease's liquidated-damages provision was VOID as against public policy (an unenforceable penalty), and instead awarded the landlord only actual proven damages: $352,525.49 in unpaid rent plus $58,229.44 in attorney's fees and litigation costs.", "caseName": "Newark Shopping Ctr. Owner, L.L.C. v. Saudades Group, LLC", "citation": "N23C-02-091 JRJ (Del. Super. Ct. Jan. 27, 2025)", "sourceUrl": "https://courts.delaware.gov/Opinions/Download.aspx?id=375990", "confidence": "high", "dollarAmount": 352525, "jurisdiction": "DE"}, {"year": 2026, "notes": "DOCTRINAL CITATION, not a dollar comparable -- no damages figure was confirmed from available sources. Included because it's a current, high-court-level clarification of what counts as 'rent due and unpaid' for commercial nonpayment proceedings specifically (as opposed to residential), and of the notice a landlord must give the tenant before including ancillary charges (taxes, utilities, fees) in that rent figure -- directly relevant to whether a given unpaidRentAmount figure will actually support the pursued remedy.", "outcome": "Landlord leased retail space to a beer-and-wine store tenant that stayed current on base rent but fell behind on other lease charges (utilities, taxes, late fees) defined as 'Additional Rent.' The landlord filed a summary ejectment action based partly on charges the tenant only learned of after suit was filed. The Supreme Court of Maryland held (1) the residential pre-suit notice statute does not apply to nonresidential tenancies, but (2) a landlord may obtain possession in a summary ejectment action only for rent that was actually due and unpaid under the lease AS OF THE FILING -- a summary ejectment action cannot be predicated on charges the tenant first learns of after the case is filed.", "caseName": "Kapneck 14-16, LLC v. Bkeezy's Speakeasy, LLC", "citation": "No. 33, Sept. Term 2025, 2026 WL 1158049 (Md. Apr. 29, 2026)", "sourceUrl": "https://www.mdcourts.gov/data/opinions/coa/2026/33a25.pdf", "confidence": "medium", "dollarAmount": null, "jurisdiction": "MD"}], "attorney_fees": [{"url": "https://www.txcourts.gov/media/1443994/160006.pdf", "year": 2019, "notes": "Landmark case establishing Texas's modern lodestar proof requirements for contractual fee-shifting; frequently invoked in commercial lease litigation statewide.", "outcome": "The Texas Supreme Court affirmed that UTSW was the prevailing party but reversed the attorney's-fee award for legally insufficient evidence, holding fee-shifting claimants must prove fees under the lodestar method (reasonable hours x reasonable rate, supported by contemporaneous billing records), not generalized testimony about a fee range; the case was remanded for a new fee determination.", "caseName": "Rohrmoos Venture v. UTSW DVA Healthcare, LLP", "citation": "578 S.W.3d 469 (Tex. 2019)", "confidence": "high", "dollarAmount": 800000, "jurisdiction": "TX"}, {"url": "https://law.justia.com/cases/georgia/court-of-appeals/2021/a20a2043.html", "year": 2021, "notes": "Good illustration that 'prevailing party' status for a lease fee clause is assessed relative to the parties' comparative success on the substantive claims, not any single sub-issue won.", "outcome": "The trial court granted the landlord's fee motion in part but denied the tenant's competing fee motion, rejecting the tenant's argument that it was the 'prevailing party' merely because the landlord had separately failed on a bad-faith fee claim under O.C.G.A. \u00a7 13-6-11; the Court of Appeals affirmed both rulings in companion appeals.", "caseName": "Wells & McElwee, P.C. v. Tiffany & Tomato, Inc. (companion appeals: Tiffany & Tomato, Inc. v. Wells & McElwee, P.C.)", "citation": "358 Ga. App. 311, 855 S.E.2d 55 (Ga. Ct. App. 2021) (Case Nos. A20A2042 & A20A2043)", "confidence": "medium", "dollarAmount": 45667, "jurisdiction": "GA"}, {"url": "https://www.deflaw.com/insights/georgia-supreme-court-affirms-application-of-attorney-fees-cap-commercial-leases/", "year": 2007, "notes": "A leading, cautionary Georgia case for commercial landlords: even an actual-fees clause in a lease can be statutorily capped well below fees actually incurred.", "outcome": "The Georgia Supreme Court held that O.C.G.A. \u00a7 13-1-11 \u2014 a statute historically applied to promissory notes \u2014 also applies to commercial leases, capping recoverable attorney's fees at the statutory formula (15% of the first $500 collected plus 10% of the remainder) rather than the actual contractual fee amount, cutting the landlord's fee recovery to roughly $17,000\u2013$17,288 instead of the ~$280,000 sought.", "caseName": "RadioShack Corp. v. Cascade Crossing II, LLC", "citation": "282 Ga. 841, 653 S.E.2d 680 (Ga. 2007) (answering a certified question from the U.S. Court of Appeals for the Eleventh Circuit)", "confidence": "medium", "dollarAmount": 280000, "jurisdiction": "GA"}, {"url": "https://www.poolehuffman.com/blog/commercial-leases-attorneys-fees-provisions-and-breach-of-lease-cases-in-georgia/", "year": 1981, "notes": "Foundational Kansas authority on enforceability of commercial-lease fee-shifting clauses; dollar figures for the fee award were not available in sources reviewed.", "outcome": "The Court of Appeals held that an agreement in a commercial lease for recovery of reasonable attorney's fees is valid and enforceable under Kansas law.", "caseName": "Oak Park Investment Co. v. Lundy's, Inc.", "citation": "6 Kan. App. 2d 133, 626 P.2d 1236 (Kan. Ct. App. 1981)", "confidence": "medium", "dollarAmount": null, "jurisdiction": "KS"}, {"url": null, "year": 2022, "notes": "Same filing as the accelerated_rent and releasing_mitigation_costs citations for this category. Anchors the LOW/uncontested end of the fee-to-damages ratio for a large accelerated-rent claim -- do not extrapolate this ratio to a contested matter; contrast with the smaller claims in this array, where fees run a much higher percentage of the principal. No public URL available for this record -- verify via the case number and court above.", "outcome": "The landlord's motion sought attorneys' fees of $52,905.00 plus $3,526.06 in costs -- together representing only about 1.3% of the $4,189,177.66 in rental damages sought in the same filing. IMPORTANT SCOPE NOTE (per counsel of record): this matter was essentially UNCONTESTED -- the tenant and guarantor did not meaningfully oppose summary judgment, and the court was asked to enter judgment for the exact amount sought. This low fee ratio reflects an unopposed rocket-docket resolution, not a genuinely contested matter with real discovery, motion practice, and possible trial -- a contested matter of the same size would see meaningfully higher fees, likely several times this ratio.", "caseName": "The Village at Brocks Gap, LLC v. Singleton Ventures, LLC", "citation": "Case No. CV-2020-900604 (Cir. Ct. Jefferson Cnty., Ala., Bessemer Div.) (Pl.'s Mot. Summ. J., filed Feb. 17, 2022)", "confidence": "high", "dollarAmount": 52905, "jurisdiction": "AL"}, {"year": 2021, "notes": "Also directly useful for the quiet_enjoyment_breach claim type (see that citation set) -- the fee award here (~36% of the compensatory damages) is a real contested-litigation data point on the higher end, usefully bracketing against the Village at Brocks Gap uncontested ~1.3% ratio already in this dataset and illustrating this claim's SUPERSEDING posture-tiered flat-dollar model (a real trial/appeal here plausibly falls in the $50,000-$200,000 trial tier, and $69,002.68 sits comfortably within it).", "outcome": "Commercial tenant sued its landlord for breach of lease, negligent misrepresentation (about the condition of and the landlord's intent to repair the building's roof), and constructive eviction after the landlord failed to timely repair the building and keep it tenantable. The trial court found for the tenant on all theories, awarding $193,006.35 in compensatory damages plus $69,002.68 in attorney's fees under the lease's fee-shifting clause; the Court of Appeals affirmed in full, finding no reversible error.", "caseName": "Pryority Partnership v. AMT Properties, LLC", "citation": "No. E2020-00511-COA-R3-CV (Tenn. Ct. App. Mar. 10, 2021)", "sourceUrl": "https://www.courtlistener.com/opinion/?q=Pryority+Partnership+AMT+Properties", "confidence": "medium", "dollarAmount": 69002, "jurisdiction": "TN"}, {"year": 2019, "notes": "DOLLAR AMOUNT NOT CONFIRMED for the fee award itself. Valuable for the 'main issue' prevailing-party doctrine it applies -- directly comparable to, and reinforcing, the existing Wells & McElwee v. Tiffany & Tomato (Ga. 2021) citation's point that prevailing-party status turns on overall/main-issue success, not any single sub-issue. Also independently useful for the property_damage claim type (see that citation set) since the landlord's own property-damage claim is what failed here for lack of proof.", "outcome": "In a commercial lease dispute where the landlord's own property-damage claim failed at directed verdict for lack of causation evidence, the tenant was nonetheless found to be the 'prevailing party' under the lease's fee-shifting clause on the 'main issue' of the case, even though the landlord had won on some minor sub-issues (a flagpole item and real estate tax charges). The Eighth District affirmed the tenant's entitlement to reasonable attorney's fees and expenses, applying a 'main issue' prevailing-party test for sophisticated, counseled commercial parties and holding the tenant did not need to prove it had already paid its attorneys before judgment.", "caseName": "Simbo Properties, Inc. v. M8 Realty, L.L.C.", "citation": "2019-Ohio-3091 (8th Dist. Ct. App., Cuyahoga Cnty., Aug. 1, 2019)", "sourceUrl": "https://www.courtlistener.com/opinion/?q=Simbo+Properties+M8+Realty", "confidence": "medium", "dollarAmount": null, "jurisdiction": "OH"}], "property_damage": [{"url": "https://law.justia.com/cases/federal/appellate-courts/ca11/16-17656/16-17656-2017-07-03.html", "year": 2017, "notes": "Large, affirmed property-damage/surrender-condition award; useful as a high-end data point for claims tied to a lease's specific condition-on-return standard rather than ordinary wear and tear.", "outcome": "Landlord awarded over $6.2 million for tenant's failure to return the premises in the 'first class condition' the lease required, based on 26 listed deficiencies identified by the landlord's expert. The Eleventh Circuit affirmed, rejecting the tenant's arguments that the expert testimony was unreliable and that the damages should have been split out defect-by-defect rather than assessed as a whole.", "caseName": "Apple Glen Investors, L.P. v. Express Scripts, Inc.", "citation": "700 Fed. Appx. 935 (11th Cir. 2017)", "confidence": "high", "dollarAmount": 6200000, "jurisdiction": "Federal (11th Cir., applying GA law)"}, {"url": "https://www.courtlistener.com/opinion/2593554/45-broadway-owner-llc-v-nysa-ila-pension-trust-fund/", "year": 2013, "notes": "Not a landlord-recovery data point -- included as a real, binding illustration that a mutual waiver-of-subrogation/casualty-release clause (common in commercial leases) can completely bar an otherwise well-evidenced property-damage claim. This claim's baseProbability range assumes no such clause; a lease containing one would take a property damage claim toward $0 regardless of the repair evidence. Flagged for a possible future model refinement (a lease-clause question) rather than folded into the current formula unilaterally.", "outcome": "Trial court had awarded the landlord $166,013.96 for HVAC/flood repair costs. The Appellate Division reversed and granted the tenant's cross-motion for summary judgment instead, holding a mutual waiver-of-subrogation/casualty-release clause in the lease (Sections 7.03/7.04) barred the landlord's claim entirely, regardless of the tenant's fault.", "caseName": "45 Broadway Owner LLC v. NYSA-ILA Pension Trust Fund", "citation": "2013 NY Slip Op 04895 (App. Div., 1st Dep't, June 27, 2013)", "confidence": "high", "dollarAmount": 0, "jurisdiction": "NY"}, {"year": 1992, "notes": "DOCTRINAL CITATION, not a dollar comparable -- the underlying case is a lease-forfeiture dispute (unauthorized assignment plus a municipal weed-ordinance violation), not a repair-cost recovery, and its own damages figures (liquidated damages for continued use, costs, attorney fees) don't map onto this claim's propertyDamageAmount formula. What it DOES supply is the actual legal standard the normalWearHaircut parameter is meant to operationalize: the wear-vs-waste line turns on the tenant's willful conduct or negligence, not just visible deterioration. Cited for that standard specifically, the way a claim's underlying legal test is cited even when the case supplying it isn't itself a clean damages comparable.", "outcome": "In a dispute centering on a ground lessee's material breach (unauthorized assignments/encumbrances of the leasehold plus persistent weed growth violating a city ordinance), the court articulated the governing standard for what a tenant is obligated to repair: damage the tenant must repair or pay for 'is not that which is caused by ordinary wear and tear, but by the tenant's willful conduct or negligence and which amounts to waste.'", "caseName": "Howe v. Professional Manivest, Inc.", "citation": "829 P.2d 160, 164 (Utah Ct. App. 1992)", "sourceUrl": "https://www.courtlistener.com/opinion/1423966/howe-v-professional-manivest-inc/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "UT"}, {"year": 2019, "notes": "A landlord-LOSES counter-example -- useful balance against the large Apple Glen Investors v. Express Scripts ($6.2M) win already in this dataset. Confirms that even a facially plausible property-damage claim can fail entirely for a basic evidentiary gap (failure to prove CAUSATION, not just failure to prove amount), which is a distinct failure mode from the normalWearHaircut this claim's damages formula already models.", "outcome": "Commercial landlord sought damages from its former tenant for alleged property damage (among other claims, including a flagpole item and real estate taxes). The trial court granted a DIRECTED VERDICT against the landlord on the property-damage claim specifically, holding the landlord failed to introduce evidence establishing the tenant CAUSED the alleged damage. The Eighth District affirmed.", "caseName": "Simbo Properties, Inc. v. M8 Realty, L.L.C.", "citation": "2019-Ohio-3091 (8th Dist. Ct. App., Cuyahoga Cnty., Aug. 1, 2019)", "sourceUrl": "https://www.courtlistener.com/opinion/?q=Simbo+Properties+M8+Realty", "confidence": "medium", "dollarAmount": 0, "jurisdiction": "OH"}, {"year": 2011, "notes": "INCOMPLETE VERIFICATION: only the general fact pattern (tenant demolition mid-renovation, then cessation of operations) was confirmed from available sources -- the court's actual holding, any damages figure, and which party ultimately prevailed on the property-condition dispute were NOT confirmed. Cited cautiously and only for the fact pattern (a tenant leaving a property mid-demolition/renovation is a distinct property-damage scenario from ordinary wear-and-tear or willful destruction); do not rely on this entry for outcome or dollar-amount guidance without pulling the full opinion first.", "outcome": "Landlord leased vacant warehouse/office space to a tenant that intended to convert it into a retail facility; the tenant demolished the existing office structures as part of that conversion, then ceased operations before completing the project. A dispute followed over the resulting condition of the property and the parties' respective obligations.", "caseName": "Avalon Pacific-Santa Ana, L.P. v. HD Supply Repair & Remodel, LLC", "citation": "192 Cal. App. 4th 1183, 122 Cal. Rptr. 3d 417 (Cal. Ct. App., 4th Dist. 2011)", "sourceUrl": "https://www.courtlistener.com/opinion/?q=Avalon+Pacific-Santa+Ana+HD+Supply", "confidence": "low", "dollarAmount": null, "jurisdiction": "CA"}, {"year": 2017, "notes": "PARTIAL VERIFICATION -- sourced from a law-firm secondary summary (JD Supra/Cozen O'Connor) rather than a direct read of the docketed opinion; the exact docket number and precise procedural posture were not independently re-confirmed in this session. A significant landlord-LOSES counter-example at the high end of the dollar range (landlord sought $11M, recovered $0 on this theory) -- important balance against this claim type's existing Apple Glen Investors v. Express Scripts ($6.2M landlord win) citation, and a useful outer boundary on how far a 'first class condition'/surrender-condition clause can be stretched: it reaches ordinary repair-covenant compliance, not a mandate to fund code-compliance capital upgrades regardless of the lease's specific repair language.", "outcome": "Landlord H.F.S. Properties sued long-term tenant Foot Locker over the condition of the historic Woolworth Building in St. Paul, Minnesota at the end of two long-running leases (dating to 1920 and 1949). The building had sat vacant for 15 years and had accumulated roughly 110 building-code violations by lease end. The landlord argued the lease's 'good condition and repair' surrender covenant required the tenant to fund approximately $11 million in code-compliance upgrades (new elevators, stairwells, windows, plumbing, and sprinklers) to bring the building up to current municipal code. The federal district court rejected that theory, holding that 'wear and tear excepted' surrender language means a tenant satisfies its surrender obligation by returning the premises in the condition required by the lease's own repair covenant (ordinary deterioration from time and use excluded), not by funding code upgrades to meet current standards -- regardless of whether the building was up to code. Foot Locker was held not liable for the $11 million in demanded code-compliance work.", "caseName": "H.F.S. Properties v. Foot Locker Specialty, Inc.", "citation": "D. Minn., decided Feb. 2, 2017 (specific docket number not independently confirmed in this session -- verify via PACER/court docket before citing)", "sourceUrl": "https://www.jdsupra.com/legalnews/recent-federal-court-decision-adds-91176/", "confidence": "medium", "dollarAmount": 0, "jurisdiction": "Federal (D. Minn., applying MN law)"}, {"year": 2011, "notes": "INCOMPLETE VERIFICATION -- this is an UNPUBLISHED Arizona memorandum decision known to this session only through a secondary legal-blog citation (which supplies the WL/LEXIS numbers and the general fact pattern), not a direct read of the opinion; the court's actual holding (whether the landlord's roof-replacement theory succeeded or failed) and any dollar figure were NOT confirmed in this session. Included only because the underlying fact pattern -- whether a general 'repairs' obligation extends to full roof replacement, or whether that is a capital replacement outside ordinary repair/normal-wear obligations -- is squarely relevant to this claim type's normalWearHaircut parameter. Given the low verification confidence, treat this as a research LEAD rather than a reliable citation unless and until pulled from a primary source (Westlaw/Arizona Court of Appeals docket).", "outcome": "At the end of a roughly 20-year commercial lease, the landlord argued the tenant's general contractual obligation to make 'repairs' required the tenant to replace the building's roof rather than merely maintain it, and sought to recover the roof-replacement cost from the tenant.", "caseName": "Dorian v. S.S. Restaurant Corp.", "citation": "2011 WL 1856014, 2011 Ariz. App. Unpub. LEXIS 673 (Ariz. Ct. App. 2011) (UNPUBLISHED memorandum decision -- not citable as precedent under Arizona court rules)", "sourceUrl": "https://www.robertdmitchell.com/article/leased-property-wear-damage/", "confidence": "low", "dollarAmount": null, "jurisdiction": "AZ"}, {"year": 2025, "notes": "The award is characterized in the opinion as breach-of-lease damages rather than an itemized property-damage/repair-cost recovery, so it is most directly useful for the allocation-of-repair-duty issue (tenant cannot blame disrepair on landlord under a true NNN lease) rather than as a pure repair-cost quantum precedent. Corroborated independently via nycourts.gov handdown listing, Justia, and CourtListener case listings.", "outcome": "Commercial landlord sued a tenant who had assumed a triple-net lease for a Valhalla, NY property (originally a dog day-spa business) and vacated in February 2018 without further payment. The tenant defended on a constructive-eviction theory, arguing it was forced out because the landlord failed to maintain the premises, and counterclaimed on that basis. The Appellate Division, Second Department affirmed summary judgment for the landlord in the principal sum of $19,432.93, holding that because the lease was a true triple-net lease placing all maintenance and repair costs on the tenant, the landlord owed no duty to maintain the premises, so the tenant's failure-to-maintain defense and counterclaim failed as a matter of law and raised no triable issue of fact.", "caseName": "14 Broadway Valhalla, LLC v. Mendez", "citation": "2025 NY Slip Op 03784 (App. Div., 2d Dep't, June 25, 2025)", "sourceUrl": "https://caselaw.findlaw.com/court/ny-supreme-court/117420353.html", "confidence": "high", "dollarAmount": 19432.93, "jurisdiction": "NY"}, {"year": 1991, "notes": "Citation and holding corroborated by an independent practitioner summary (robertdmitchell.com) that cites the same reporter citation and diminution-in-value holding; direct full-text retrieval from Casemine was blocked (403), so this relies on search-engine-cached summaries rather than the full opinion text. Specific dollar figure could not be confirmed.", "outcome": "A commercial landlord sued a tenant who had covenanted to return leased premises in good condition but instead surrendered the property damaged, after which the landlord elected to demolish the building rather than repair it. The Arizona Court of Appeals held that where damaged property either cannot be restored to its former condition or repair would be economically impractical, the proper measure of damages is the diminution in value of the property immediately before and immediately after the damage, rather than repair cost, and affirmed a damages award to the landlord on that basis (subject to ordinary mitigation-of-damages principles).", "caseName": "SDR Associates v. ARG Enterprises, Inc.", "citation": "170 Ariz. 1, 821 P.2d 268 (Ariz. Ct. App. 1991)", "sourceUrl": "https://www.casemine.com/judgement/us/59148818add7b049344ee691", "confidence": "medium", "dollarAmount": null, "jurisdiction": "AZ"}, {"year": 1985, "notes": "Full opinion text confirmed directly via Justia. The specific dollar judgment amount was not stated in the excerpted portions retrieved.", "outcome": "Landlord Polster, Inc. sued its former tenant (an interior-design/retail furniture business) for failing to return a leased Sherman Oaks store in the same condition as received, ordinary wear and tear excepted, after a five-year commercial lease. The trial court found substantial evidence of damage to the drop ceiling, ceiling tiles, lighting fixtures, ceiling support bars, interior walls, and the front door sill and jamb, and entered judgment for the landlord including prejudgment interest. The Court of Appeal affirmed the finding that the wear-and-tear exception had been exceeded and that the tenant breached the surrender covenant, but reversed the judgment in part (on a portion of the damages/interest calculation), illustrating that even a clear landlord win on liability can still be partially unwound on the amount of damages awarded.", "caseName": "Polster, Inc. v. Swing", "citation": "164 Cal. App. 3d 427, 210 Cal. Rptr. 567 (Cal. Ct. App. 1985)", "sourceUrl": "https://law.justia.com/cases/california/court-of-appeal/3d/164/427.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "CA"}, {"year": 1969, "notes": "Verified only through a single secondary source (a detailed practitioner article whose other citations were independently spot-checked and confirmed accurate, e.g., Polster above). Attempts to pull the primary opinion from Justia/Leagle/FindLaw were blocked (403/404) within the available search budget; treat as needing a final primary-source check before citing in a filed brief.", "outcome": "In a commercial lease dispute, the California Court of Appeal held that a former tenant was not liable to the landlord for vandalism damage to the premises that occurred after the lease term had already expired and possession had reverted to the landlord, reasoning that a tenant's surrender-condition obligations run only through the end of the leasehold and do not extend to post-expiration damage caused by third parties once the landlord has resumed control of the property. This is a tenant-favorable precedent limiting the temporal scope of surrender-condition liability.", "caseName": "Kanner v. Globe Bottling Co.", "citation": "273 Cal. App. 2d 559, 78 Cal. Rptr. 25 (Cal. Ct. App. 1969)", "sourceUrl": "https://www.robertdmitchell.com/article/leased-property-wear-damage/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "CA"}, {"year": 2000, "notes": "Citation and the 'lesser of repair cost or diminution in value' holding are corroborated by two independent sources (a CourtListener search-result listing and a separate practitioner article quoting the same rule with this citation), but the full opinion text itself could not be retrieved (CourtListener page returned no fetchable content within budget).", "outcome": "In a federal diversity case applying Arizona law to a commercial lease damage claim, the court held that where leased premises are damaged, the landlord's recoverable damages are capped at the lesser of (a) the cost of repair or replacement, or (b) the diminution in value of the property caused by the damage \u2014 a tenant-protective ceiling that prevents landlords from recovering a repair-cost windfall where the diminution in value is smaller than the cost to fix the damage.", "caseName": "Founders Bank of Arizona v. Chrysler Realty Corp.", "citation": "86 F. Supp. 2d 968 (D. Ariz. 2000)", "sourceUrl": "https://www.courtlistener.com/opinion/2398297/founders-bank-of-arizona-v-chrysler-realty-corp/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (D. Ariz.)"}], "accelerated_rent": [{"url": "https://caselaw.findlaw.com/court/ma-supreme-judicial-court/115141290.html", "year": 2023, "notes": "Reversed a 2022 Massachusetts Appeals Court decision (Cummings Props., LLC v. Hines, No. 21-P-1153) that had found the same clause an unenforceable penalty; the SJC's 2023 reversal is the controlling precedent. Also reported at law.justia.com/cases/massachusetts/supreme-court/2023/sjc-13406.html.", "outcome": "Trial court awarded Cummings $68,650.24, the balance of accelerated rent owed after crediting payments already made and rent from the replacement tenant. The Supreme Judicial Court affirmed, holding the guarantor (a sophisticated businessperson) failed to prove the liquidated-damages clause was an unreasonable forecast of damages at lease signing, applying the 'single look' approach to assess reasonableness at contract formation rather than in hindsight.", "caseName": "Cummings Properties, LLC v. Hines", "citation": "492 Mass. 867, 217 N.E.3d 604 (2023) (SJC-13406)", "confidence": "high", "dollarAmount": 68650, "jurisdiction": "MA"}, {"url": "https://www.supremecourt.ohio.gov/rod/docs/pdf/5/2025/2025-Ohio-2645.pdf", "year": 2025, "notes": "Full opinion read directly (primary source). Court relied on its own prior precedent, Scott Holding Co. v. Turbo Restaurants US, LLC, 2024-Ohio-5240, and the Ohio Supreme Court's Frenchtown Square Partnership v. Lemstone, Inc., 2003-Ohio-3648, which allows landlords and tenants to contract around the default duty to mitigate.", "outcome": "Trial court granted summary judgment to the landlord and, after a damages hearing, awarded $6,616,025.53 total, including $4,603,463.36 in accelerated rent for the remaining ~3.5 years of the lease term. The Court of Appeals affirmed, holding that two sophisticated commercial parties may contractually waive the landlord's common-law duty to mitigate, and the express no-mitigation/acceleration language was clear, unambiguous, and enforceable (not a void penalty), even though the landlord in fact tried but failed to re-let the space for 21 months.", "caseName": "CSRA Columbus OH Fitness Master Lessee, L.L.C. v. Fitness & Sports Clubs, L.L.C.", "citation": "2025-Ohio-2645 (5th Dist. Ct. App., Delaware County, July 24, 2025) (Case No. 24 CAE 08 0052)", "confidence": "high", "dollarAmount": 6616025, "jurisdiction": "OH"}, {"url": "https://law.justia.com/cases/virginia/court-of-appeals-published/2025/0463-23-4.html", "year": 2025, "notes": "Recent (2025) published Virginia appellate decision validating rent-acceleration clauses in commercial restaurant leases; relied on search-derived summaries of the Justia case page rather than a full read of the opinion text.", "outcome": "The circuit court entered judgment for the landlord of $410,391.77 in damages plus $18,000 in attorney fees; the Court of Appeals of Virginia affirmed, holding the accelerated-rent liquidated-damages clause enforceable (since it included mechanisms preventing over-recovery) and that the landlord had no duty to mitigate under the lease's terms.", "caseName": "Bistro Manila, LLC v. Alvah I, LLC", "citation": "83 Va. App. 300 (2025) (Record No. 0463-23-4)", "confidence": "medium", "dollarAmount": 410391, "jurisdiction": "VA"}, {"url": "https://caselaw.findlaw.com/court/tx-supreme-court/1013257.html", "year": 1997, "notes": "Leading Texas precedent establishing the commercial landlord's duty to mitigate future/accelerated rent damages; frequently cited as limiting the practical value of acceleration clauses unless mitigation is contractually waived. Underlying jury verdict facts drawn from Justia's summary of the 1995 Texas Court of Appeals decision, 938 S.W.2d 469.", "outcome": "Jury awarded Palisades $29,716 in damages plus $16,500 in attorney's fees; trial court entered judgment on the verdict, and the court of appeals affirmed. The Texas Supreme Court then held, as a matter of first impression for the state, that a commercial landlord has a duty to use reasonable efforts to mitigate damages when a tenant breaches and abandons the lease, unless the lease itself provides otherwise -- rejecting the trial judge's instruction that landlords have no such duty.", "caseName": "Austin Hill Country Realty, Inc. v. Palisades Plaza, Inc.", "citation": "948 S.W.2d 293 (Tex. 1997); jury verdict from underlying case at 938 S.W.2d 469 (Tex. App.-Austin 1995)", "confidence": "medium", "dollarAmount": 29716, "jurisdiction": "TX"}, {"url": null, "year": 2022, "notes": "Primary source: full motion, brief, and supporting affidavit read directly. The best available real-world illustration in this dataset of the standard commercial-lease accelerated-rent methodology -- present-value discounting of NET future rent (required under, e.g., HealthSouth Rehabilitation Corp. v. Falcon Management Co., 799 So.2d 177, 185 (Ala. 2001)), itemized dollar-for-dollar credit for specific replacement tenants rather than a flat mitigation percentage, and a distinct re-leasing/mitigation-costs damages category (see releasing_mitigation_costs citations). No public URL available for this record -- verify via the case number and court above.", "outcome": "Landlord sought summary judgment on breach of a 20.5-year grocery-store shopping-center lease after the tenant defaulted and abandoned the premises. The damages methodology in the motion and supporting affidavit computed gross unpaid past rent ($677,726.58) plus gross future accelerated rent ($8,814,297.71), net of specific dollar credits for three actual/anticipated replacement tenants (down to $6,061,315.06), then discounted that net future-rent figure to present value using a 6.0% annual rate reflecting a replacement tenant's anticipated creditworthiness -- yielding $3,511,451.08 and total rental damages of $4,189,177.66. This is the requested relief as of the February 2022 filing; no order or judgment on the motion was reviewed, so this illustrates the damages methodology, not a confirmed award.", "caseName": "The Village at Brocks Gap, LLC v. Singleton Ventures, LLC", "citation": "Case No. CV-2020-900604 (Cir. Ct. Jefferson Cnty., Ala., Bessemer Div.) (Pl.'s Mot. Summ. J., filed Feb. 17, 2022)", "confidence": "high", "dollarAmount": 4189177, "jurisdiction": "AL"}, {"year": 2022, "notes": "Directly validates this claim's reletOverride mechanic: an acceleration clause that does NOT net out actual replacement rent before calculating the accelerated-rent claim is a real, live penalty risk, not a theoretical one -- this is the same landlord (Cummings Properties) that WON on a similarly large accelerated-rent claim in the companion 2007 citation below, where the clause's structure avoided this double-dip problem. The contrast between the two Cummings cases is itself instructive: it's the accounting-for-re-let-rent mechanic that determines enforceability, not the size of the claim or the landlord's identity.", "outcome": "Lease's acceleration clause let the landlord retake possession, re-let the premises, collect the new tenant's rent, AND recover the full remaining rent owed by the defaulting tenant for the balance of the original term -- with no requirement to credit or account for the rent actually collected from the replacement tenant. The Appeals Court held this 'double-dip' structure was an unenforceable penalty rather than valid liquidated damages.", "caseName": "Cummings Properties, LLC v. Hines", "citation": "101 Mass. App. Ct. 1108 (2022) (unpublished)", "sourceUrl": "https://caselaw.findlaw.com/court/ma-court-of-appeals/2067888.html/", "confidence": "high", "dollarAmount": 0, "jurisdiction": "MA"}, {"year": 2007, "notes": "The landlord's 2007 win here (large accelerated-rent recovery upheld despite re-letting) versus its 2022 loss in the companion Hines citation above turns on exactly the distinction this claim's damages formula is built around -- properly accounting for re-let income versus impermissibly double-dipping.", "outcome": "The Massachusetts Supreme Judicial Court held a liquidated damages clause entitling the landlord to nearly five years of remaining rent payments after tenant default was enforceable as valid liquidated damages, not a penalty, even though the landlord had re-let the premises.", "caseName": "Cummings Properties, LLC v. National Communications Corp.", "citation": "449 Mass. 490, 869 N.E.2d 617 (2007)", "sourceUrl": "https://www.richmaylaw.com/case-alert-a-massachusetts-appeals-court-strikes-down-a-commercial-landlords-right-to-collect-acceleration-of-rent-on-tenant-default/", "confidence": "high", "dollarAmount": null, "jurisdiction": "MA"}, {"year": 2024, "notes": "Directly reinforces this claim's reletOverride mechanic (net future rent = gross future rent minus actual/anticipated overlapping new rent, BEFORE PV discounting) with a current, real dollar figure -- a live, current-law illustration of the same double-dip problem the existing 2022 Cummings Properties v. Hines citation identifies. Related First Department authority on similar acceleration-clause limits: ALQ, LLC v. Kane, 197 A.D.3d 1029 (1st Dep't 2021) (no dual remedy); Chelsea 8th Ave. LLC v. Chelseamilk LLC, 220 A.D.3d 565 (1st Dep't 2023) (no acceleration while tenant remains in possession).", "outcome": "Trial court granted the landlord summary judgment for $576,069.05 on its accelerated-rent cause of action against the tenant and its corporate and 'good guy' guarantors. On appeal, the landlord conceded it had relet the premises and begun collecting a new tenant's rent as of January 2023 -- yet still sought to keep the full accelerated-rent judgment. The First Department held the lease permitted the landlord to accelerate rent OR to relet and collect actual/anticipated rent, but NOT both simultaneously without netting one against the other.", "caseName": "Elk 33 E. 33rd LLC v. Sticky's Corporate LLC", "citation": "228 A.D.3d 455, 2024 NY Slip Op 03132 (1st Dep't 2024)", "sourceUrl": "https://www.nycourts.gov/reporter/3dseries/2024/2024_03132.htm", "confidence": "high", "dollarAmount": 576069, "jurisdiction": "NY"}, {"year": 2025, "notes": "A clean, current, small-dollar illustration of the gate condition already built into this claim's damages model ('No confirmed acceleration clause' drops probability to 0.15-0.3) -- confirms Florida courts will affirmatively strike out the unaccrued portion of a damages award, not just discount it, when no acceleration clause exists. Consistent with the existing Austin Hill Country Realty v. Palisades Plaza (Tex. 1997) mitigation-duty citation in spirit: both limit what a landlord can collect for the remaining term absent specific contractual authority.", "outcome": "Landlord NRG sued tenant Hourglass over a parking-lot lease after Hourglass stopped paying rent in April 2021 while remaining contractually obligated through the lease's August 2024 expiration. The trial court's amended final judgment awarded $39,858 in damages, calculated using the full 40-month unpaid period through August 2024 -- but that period ran roughly four months PAST the date of the judgment itself. The Second District Court of Appeal held it was error to award rent for the four months between the judgment date and lease expiration because the lease contained NO express acceleration clause, and Florida law does not allow a landlord to recover future/unaccrued rent absent one.", "caseName": "Hourglass Entertainment, LLC v. NRG Investments, Inc.", "citation": "50 Fla. L. Weekly D1538, No. 2D2024-1251 (Fla. 2d DCA 2025)", "sourceUrl": "https://law.justia.com/cases/florida/second-district-court-of-appeal/2025/2d2024-1251.html", "confidence": "high", "dollarAmount": 39858, "jurisdiction": "FL"}, {"year": 2012, "notes": "INCOMPLETE VERIFICATION: the final dollar amount ultimately awarded was not independently confirmed from available sources -- only that present-value discounting of a contractual future-rent damages formula was a genuinely contested, appellately-significant issue in this case (parallel to the HealthSouth Rehabilitation Corp. v. Falcon Management Co. and Village at Brocks Gap present-value citations already in this dataset). Cited for that damages-methodology significance (62+ citing cases per CourtListener), not as a clean dollar comparable -- verify the final Superior Court damages figure directly before relying on any number from this matter.", "outcome": "Landlord sued a supermarket tenant and its corporate successor for breach of a long-term ground/commercial lease. Following a bench trial in the Court of Common Pleas of Chester County, the case turned in part on how to calculate damages under the lease's Section 20.2.2 formula, including whether and how those damages should be reduced to present value -- a Pennsylvania Supreme Court justice specifically noted disagreement over 'the reduction to present value of the Section 20.2.2 damages.' The Supreme Court's principal holding addressed a procedural question (whether post-trial motions were required after a remand), sending the substantive damages dispute back for further proceedings culminating in the 2014 Superior Court decision.", "caseName": "Newman Development Group of Pottstown, LLC v. Genuardi's Family Market, Inc.", "citation": "52 A.3d 1233, 617 Pa. 265 (Pa. 2012); on remand, 98 A.3d 645, 2014 Pa. Super. 173 (2014)", "sourceUrl": "https://www.courtlistener.com/opinion/2249897/newman-dev-group-of-pottstown-llc-v-genuardis-family-mkt-inc/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "PA"}], "holdover_damages": [{"url": "https://www.nycourts.gov/reporter/pdfs/2022/2022_31356.pdf", "year": 2022, "notes": "This litigation had multiple stages and partial-payment amounts (e.g., a later 'Office Judgment Amount' after tenant payments); the figure here reflects the initial summary-judgment holdover-damages calculation under the lease's treble-rent clause, not a single final net judgment number. Verify current docket status before citing an exact final collected amount.", "outcome": "The landlord was granted summary judgment enforcing Article 21(A) of the lease, which fixed holdover rent at three times the rent otherwise payable; the trial court calculated additional holdover damages of $17,589,819.91 for the retail portion and $2,331,106.71 for the office portion, and the First Department affirmed treble-rent holdover damages as an enforceable liquidated-damages provision.", "caseName": "Victoria's Secret Stores, LLC v. Herald Sq. Owner LLC", "citation": "2022 N.Y. Slip Op. 31356(U) (Sup. Ct., N.Y. Cnty. 2022); aff'd, 211 A.D.3d 657, 181 N.Y.S.3d 531 (1st Dep't 2022)", "confidence": "high", "dollarAmount": 19920927, "jurisdiction": "NY"}, {"url": "https://www.leagle.com/decision/incaco20250210002", "year": 2025, "notes": "Useful as a 'holdover claim denied' precedent \u2014 illustrates the risk to landlords of accepting rent after a termination notice.", "outcome": "The trial court had ruled for the landlord, finding no consent to continued tenancy. The Court of Appeal reversed, holding the landlord's unconditional acceptance and deposit of the post-termination rent check created a presumption of a new month-to-month tenancy that the landlord failed to rebut, defeating the double-rent holdover claim.", "caseName": "Baca v. Kuang", "citation": "108 Cal. App. 5th 666 (Cal. Ct. App., 1st Dist., Div. 5, 2025)", "confidence": "high", "dollarAmount": null, "jurisdiction": "CA"}, {"url": "https://law.justia.com/cases/new-york/appellate-division-first-department/2022/index-no-655960-20-appeal-no-16109-16109a-case-no-2021-04815-2022-00031.html", "year": 2022, "notes": "Total dollar figure for the holdover rent recovered was not confirmed in the sources reviewed; the 200%-of-rent multiplier is confirmed.", "outcome": "The Appellate Division upheld the lease's holdover-rent provision requiring the tenant to pay 200% of its prior rent for the holdover period, treating it as an enforceable liquidated-damages clause rather than an unenforceable penalty.", "caseName": "ESRT 501 Seventh Ave., LLC v. Regine, Ltd.", "citation": "Appeal Nos. 16109, 16109A, Index No. 655960/20 (App. Div., 1st Dep't, June 9, 2022)", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NY"}, {"url": "https://case-law.vlex.com/vid/lincoln-oldsmobile-inc-v-886790420", "year": 1990, "notes": "Illustrates an important limitation on double-rent recovery: it is not automatic and does not reach back before the landlord's demand.", "outcome": "The Court of Appeal reversed, holding Florida's statutory double-rent remedy is a penalty the landlord must affirmatively invoke by demand, and cannot be recovered retroactively for the holdover period preceding that demand; it also held damages belonging to a corporation cannot be awarded directly to an individual shareholder.", "caseName": "Lincoln Oldsmobile, Inc. v. Branch", "citation": "574 So. 2d 1111 (Fla. 2d DCA 1990)", "confidence": "medium", "dollarAmount": null, "jurisdiction": "FL"}, {"year": 2013, "notes": "A second, independent limitation on double-rent recovery distinct from the Lincoln Oldsmobile demand-precondition above -- here it's a good-faith colorable claim of right to possess, not any procedural failure by the landlord, that defeats the statutory penalty. Both citations point the same direction: courts read holdover-penalty statutes narrowly against automatic doubling.", "outcome": "Successor property owner sued a commercial tenant for eviction and back rent after the lease expired; the tenant claimed it had validly exercised a purchase option before the lease expired and therefore had a right to remain in possession. The Illinois Appellate Court affirmed denial of the landlord's request for statutory double rent, holding a holdover tenant who stays for 'colorably justifiable reasons' -- a reasonable, good-faith claim of a right to occupy -- is not subject to the double-rent penalty even though it did, in fact, hold over.", "caseName": "Spatz v. 2263 North Lincoln Corp.", "citation": "2013 IL App (1st) 122076", "sourceUrl": "https://paulporvaznik.com/commercial-landlord-not-entitled-to-double-rent-under-holdover-statute-where-tenant-had-legitimate-belief-it-had-right-to-possess-space-il-1st-dist/9591", "confidence": "high", "dollarAmount": null, "jurisdiction": "IL"}, {"year": 2013, "notes": "Directly relevant to what a landlord's damages can look like when a holdover tenant isn't just failing to pay double rent, but is actively blocking the landlord's ability to strike a NEW deal with a replacement tenant or vendor -- a real, substantial (~$1.5M jury-awarded, high-court-affirmed-in-part) tort theory beyond the statutory holdover penalty modeled elsewhere in this claim type's damages formula. Worth flagging as a distinct, additive damages theory when facts show the holdover specifically obstructed an identifiable replacement deal, not just ordinary continued occupancy.", "outcome": "Coinmach leased space at an apartment complex to install and service coin-operated laundry machines under a 10-year contract; a 1994 foreclosure sale terminated the lease, but Coinmach refused to vacate for roughly six years, becoming a tenant at sufferance. The new owner, Aspenwood, sued for trespass, DTPA violations, and tortious interference -- specifically that Coinmach's continued refusal to leave blocked Aspenwood from contracting with a replacement laundry vendor. A jury awarded Aspenwood approximately $1.5 million (actual damages plus DTPA treble damages and exemplary damages). The Texas Supreme Court held that a tenant at sufferance is a trespasser who CAN be held liable in tort, including for tortious interference with the landlord's own prospective business relations, remanding for further review of whether the interference element was properly proven.", "caseName": "Coinmach Corp. v. Aspenwood Apartment Corp.", "citation": "417 S.W.3d 909 (Tex. 2013)", "sourceUrl": "https://caselaw.findlaw.com/court/tx-supreme-court/1651463.html", "confidence": "high", "dollarAmount": 1500000, "jurisdiction": "TX"}, {"year": 2016, "notes": "DOLLAR AMOUNT NOT CONFIRMED. A landlord-LOSES counter-example on the 'willfulness' element some states require before a holdover multiplier applies -- joins Spatz v. 2263 North Lincoln Corp. (good-faith colorable claim of right) and Lincoln Oldsmobile v. Branch (no retroactive demand) already in this dataset as a third, independent way a holdover multiplier claim can fail even where the tenant did, in fact, remain in possession past term. Cited 12 times per CourtListener, suggesting real doctrinal weight in jurisdictions with a willfulness requirement.", "outcome": "Landlord Cheetah Properties appealed a district court judgment finding that commercial tenant Panther Pressure Testers did NOT 'willfully' hold over after its lease ended, which defeated the landlord's claim for statutory double damages for the holdover period. The district court also denied the landlord's request for attorney's fees. The North Dakota Supreme Court affirmed, rejecting the landlord's holdover claim.", "caseName": "Cheetah Properties 1, LLC v. Panther Pressure Testers, Inc.", "citation": "2016 ND 102, 879 N.W.2d 423", "sourceUrl": "https://www.courtlistener.com/opinion/?q=Cheetah+Properties+Panther+Pressure+Testers", "confidence": "medium", "dollarAmount": null, "jurisdiction": "ND"}, {"year": 1986, "notes": "PARTIAL VERIFICATION -- confirmed via case-law search summary rather than a full read of the opinion; treat the precise reasoning for denying the double-rent claim with some caution pending direct verification. A good, older but clean illustration that a facially plausible holdover multiplier claim (properly pled, tied to an actual lease clause) can still be denied in whole by the trial court, with the landlord recovering only a fraction (about 33%) of what it originally sought across all categories combined.", "outcome": "Commercial landlord sued a saloon tenant seeking $34,200 in unpaid rent, interest, property-damage costs, AND double rent for a holdover period under the lease's holdover clause. The trial court awarded the landlord only $11,400 in unpaid rent and denied all other requested categories, including the double-rent holdover claim; the Missouri Court of Appeals affirmed this partial, reduced recovery.", "caseName": "Mel-Lo Enterprises, Inc. v. Belle Starr Saloon, Inc.", "citation": "716 S.W.2d 828 (Mo. Ct. App. 1986)", "sourceUrl": "https://www.courtlistener.com/opinion/?q=Mel-Lo+Enterprises+Belle+Starr+Saloon", "confidence": "medium", "dollarAmount": 11400, "jurisdiction": "MO"}], "security_deposit": [{"url": "https://www.courtlistener.com/opinion/2281319/250-llc-v-photopoint-corpusa/", "year": 2005, "notes": "Frequently cited California authority for the proposition that a commercial security deposit cannot be applied to future/anticipated rent damages absent an express lease waiver of Civil Code \u00a7 1950.7.", "outcome": "The Court of Appeal held Civil Code \u00a7 1950.7 unambiguously limits a commercial security deposit to covering unpaid rent and damages accrued as of the date the deposit is statutorily due back, and requires the landlord to calculate and return any 'excess.' The landlord's retention of the full deposit against speculative future-rent damages violated the statute.", "caseName": "250 L.L.C. v. PhotoPoint Corp. (USA)", "citation": "131 Cal. App. 4th 703, 32 Cal. Rptr. 3d 296 (Cal. Ct. App., 1st Dist., 2005)", "confidence": "high", "dollarAmount": null, "jurisdiction": "CA"}, {"url": "https://www4.courts.ca.gov/opinions/nonpub/D076214.PDF", "year": 2020, "notes": "This is an unpublished California opinion; under Cal. R. Ct. 8.1115 it may not be cited as precedent in California courts. Included here only as an illustrative, real, verifiable fact pattern \u2014 not as binding authority. Flag this limitation to any user of the valuation tool.", "outcome": "The Court of Appeal held that, under Civil Code \u00a7 1950.7(c), a commercial landlord may apply a security deposit to repair costs only if the lease expressly authorizes that use; because this lease contained no such authorization, FISM's withholding of the $680 was improper.", "caseName": "Aljabban v. Fontana Indoor Swap Meet, Inc.", "citation": "54 Cal. App. 5th 482 (Cal. Ct. App., 4th Dist., Div. 1, 2020) (unpublished; nonciteable under Cal. R. Ct. 8.1115)", "confidence": "medium", "dollarAmount": 680, "jurisdiction": "CA"}, {"url": "https://caselaw.findlaw.com/court/apl-crt-ill-fir-dis-fir-div/1955186.html", "year": 2018, "notes": "Illinois Rule 23 order \u2014 unpublished and of limited precedential value under Illinois court rules, but the facts and dollar figures are independently verifiable from the opinion text. Useful for showing that a small deposit-return win can be swamped by, and irrelevant to, the outcome of much larger contract claims in the same suit.", "outcome": "After a two-week trial, the court ordered the security deposit returned to the tenant, but held the tenant did not achieve 'prevailing party' status for purposes of the lease's fee-shifting clause because the deposit's value was insignificant relative to the much larger, more complex breach-of-contract claims at issue; the Appellate Court affirmed.", "caseName": "Oak Forest Properties LLC v. RER Financial, Inc.", "citation": "2018 IL App (1st) 161704-U (Ill. App. Ct., 1st Dist., Sept. 24, 2018) (unpublished Rule 23 order)", "confidence": "medium", "dollarAmount": 3404, "jurisdiction": "IL"}, {"url": "https://www.schlamstone.com/blogs/commercial/2016-08-10-not-maintaining-security-deposit-in-new-york-bank-branch-violates-gol-7-103-no-damages", "year": 2016, "notes": "Important nuance case: a technical statutory violation regarding where a commercial deposit is held does not, by itself, entitle the tenant to damages absent commingling or actual harm.", "outcome": "The court found Royal Wine Corp. technically violated GOL \u00a7 7-103(2) by holding the deposit outside New York, but held this was a 'technical statutory violation' without fiduciary implications; because there was no commingling and Urban Soccer suffered no actual damages, the statute provided no remedy and the tenant was not entitled to relief.", "caseName": "Urban Soccer Inc. v. Royal Wine Corp.", "citation": "2016 N.Y. Slip Op. 26250 (Sup. Ct., N.Y. Cnty., Commercial Div. 2016)", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 2016, "notes": "DOLLAR AMOUNT NOT CONFIRMED (the underlying deposit/judgment figure was not available from sources reviewed in this session). Directly on point for the existing note in this claim type flagging that a bad-faith-withholding doubling penalty should be checked per-state -- Texas Property Code \u00a7 93.011 is exactly that kind of statute for COMMERCIAL tenancies specifically (distinct from the residential deposit statutes most states have), and this is a real, appellate-affirmed application of it against a landlord who could not substantiate its retention decision with evidence.", "outcome": "Commercial landlord FP Stores retained tenant Tramontina's security deposit after the lease ended. Tramontina sued for breach of contract and for violation of Texas Property Code \u00a7 93.011 (the commercial security-deposit bad-faith-retention statute), alleging the deposit was withheld in bad faith. The trial court granted Tramontina summary judgment. The Court of Appeals AFFIRMED, holding the landlord failed to present sufficient evidence justifying its retention of the deposit.", "caseName": "FP Stores, Inc. v. Tramontina US, Inc.", "citation": "513 S.W.3d 684 (Tex. App.-Houston [1st Dist.] 2016)", "sourceUrl": "https://www.courtlistener.com/opinion/?q=FP+Stores+Tramontina", "confidence": "medium", "dollarAmount": null, "jurisdiction": "TX"}, {"year": 2022, "notes": "Not a 'landlord wrongfully withheld the deposit' fact pattern like the rest of this claim type's citations -- instead illustrates a DIFFERENT, real risk this claim type's current formula does not price in at all: if the lease/state law does not require the landlord to hold the deposit in trust (true in most states, including Illinois, absent a specific statute or lease clause), the tenant's deposit is exposed to the LANDLORD's own creditors and can be effectively lost in the landlord's bankruptcy even where the tenant did nothing wrong and the landlord never disputed owing the money back. Worth flagging as a real, separate, damages-formula-breaking scenario (depositAmount recoverable could functionally go to ~$0 through no fault of either party's dispute) distinct from the 'depositDisputed' trigger this claim type currently models.", "outcome": "The assignee of a commercial sublessee (10FN, as assignee of Nitel/Network Innovations) sued the sublandlord's secured lenders (Cerberus Business Finance and PEPI Capital) for conversion and unjust enrichment after the lenders swept all cash from the sublandlord's (Sizmek's) bank accounts -- including an account holding the sublessee's $271,092.87 security deposit -- shortly before the sublandlord filed Chapter 11 bankruptcy. The court held that because neither the sublease nor Illinois law required the deposit to be held in trust, the deposit was not segregated/protected property but was, in effect, an unsecured loan to the landlord; the tenant's claim to it was treated the same as any other unsecured creditor's claim in the landlord's bankruptcy, not as a right to recover the specific deposited funds.", "caseName": "10FN, Inc. v. Cerberus Business Finance, LLC", "citation": "No. 1:21-cv-05996-VEC (S.D.N.Y. Oct. 18, 2022)", "sourceUrl": "https://www.mondaq.com/unitedstates/landlord-tenant-leases/1258280/tenant-security-deposit-or-unsecured-loan-state-law-disparity-leads-to-forfeiture", "confidence": "medium", "dollarAmount": 271092, "jurisdiction": "Federal (S.D.N.Y., applying IL law)"}, {"year": 2018, "notes": "A strong, real, dollar-substantial commercial security-deposit case directly on point for this claim type's existing note flagging that a bad-faith-withholding doubling penalty should be checked per-state -- Massachusetts c. 93A operates similarly for commercial tenants where the withholding is willful, and here produced a total recovery (treble damages plus fees, roughly $104,852) about 6.5x the disputed $14,780 -- larger than a simple doubling. A useful, well-documented data point for how large the ultimate exposure can get for a landlord who withholds a commercial deposit without adequate proof, once a state consumer-protection-style fee/multiplier statute is triggered.", "outcome": "Commercial landlord withheld $14,780 of a tenant's $15,982 security deposit, claiming it covered damage caused when the tenant removed certain shelving and signage upon vacating. The jury found for the tenant on common-law claims (initial award $25,366.70, later reduced by the trial judge on remittitur to $14,780 in actual damages). The judge separately found, under Mass. Gen. Laws c. 93A, section 11 (the state's unfair/deceptive trade practices statute), that the landlord's retention was a willful violation, and trebled the actual damages to $44,340, plus awarding the tenant $60,511.74 in attorney's fees and costs. The Massachusetts Appeals Court affirmed.", "caseName": "The Exhibit Source, Inc. v. Wells Avenue Business Center, LLC", "citation": "94 Mass. App. Ct. 497, 114 N.E.3d 993 (2018)", "sourceUrl": "https://www.courtlistener.com/opinion/4566255/the-exhibit-source-inc-v-wells-avenue-business-center-llc/", "confidence": "high", "dollarAmount": 44340, "jurisdiction": "MA"}, {"year": 2019, "notes": "Full opinion text read and verified directly. Modest-dollar-amount, clean tenant-win commercial deposit dispute.", "outcome": "Tenant sued its commercial landlord in small-claims court for return of a $5,000 security deposit after vacating a cosmetology-salon space leased since 2007; landlord counterclaimed for $15,000 in holdover-rent breach-of-lease damages. Trial court awarded the tenant its $5,000 deposit but also awarded the landlord $15,000 on the counterclaim. On appeal, the Eleventh District affirmed the $5,000 deposit award but reversed the landlord's $15,000 holdover award, holding the landlord waived the holdover provision by silently accepting pre-holdover rent for a full year and was estopped by laches. Net result: tenant kept its full $5,000 deposit with no offsetting liability.", "caseName": "Ultimate Salon & Spa, Inc. v. Legends Construction Group", "citation": "2019-Ohio-2506 (Ohio Ct. App., 11th Dist., Lake Cnty.)", "sourceUrl": "https://www.supremecourt.ohio.gov/rod/docs/pdf/11/2019/2019-Ohio-2506.pdf", "confidence": "high", "dollarAmount": 5000, "jurisdiction": "OH"}, {"year": 2024, "notes": "This is a 'landlord failed to properly account for/credit the deposit' pattern rather than a freestanding bad-faith-withholding suit, but squarely on point -- shows a court will force-correct a judgment where a deposit isn't credited.", "outcome": "Commercial landlord sued a former tenant and guarantors for unpaid rent/damages through lease termination; tenant's COVID-19 pandemic defenses (frustration of purpose, impossibility, failure of consideration) were rejected. The Appellate Division modified the judgment in the tenant's favor on one point: the landlord held a $30,000 security deposit but its ledger failed to account for it against the damages award, so the court reduced the judgment by $30,000 to reflect the un-applied deposit.", "caseName": "841-853 Fee Owner, LLC v. Space Initiatives LLC", "citation": "N.Y. Sup. Ct., App. Div., 1st Dep't, May 7, 2024 (Appeal Nos. 2214-2215)", "sourceUrl": "https://caselaw.findlaw.com/court/ny-supreme-court-appellate-division/116141702.html", "confidence": "high", "dollarAmount": 30000, "jurisdiction": "NY"}, {"year": 2023, "notes": "Case name, docket (Index No. 650593/2021), dollar figure and core facts corroborated across independent sources (Justia, Leagle, Trellis, NY court calendar, 2024 appellate record), but full underlying opinion text was blocked, so the deposit's specific dollar amount (distinct from the total judgment) is not independently confirmed. The 2024 appellate decision affirmed only on a personal-jurisdiction/service issue and did not revisit the deposit ruling.", "outcome": "Landlord leased commercial space in Manhattan under a 2015 five-year lease; tenant vacated in September 2020 but never executed the lease-required surrender agreement, apparently trying to negotiate a release from accrued liabilities in exchange for its deposit. After a virtual inquest, tenant and guarantor were found jointly liable for $667,599.52, and the landlord was permitted to withhold/not credit the security deposit because the tenant had not formally 'surrendered' as the lease required.", "caseName": "Amcojor Realty Corp. v. Butter Mgt. LLC", "citation": "2023 N.Y. Slip Op. 30583(U) (Sup. Ct., N.Y. Cnty. 2023); aff'd on other grounds sub nom. Amcojor Realty Corp. v. Akiva, 2024 N.Y. Slip Op. 05476 (App. Div., 1st Dep't, Nov. 7, 2024)", "sourceUrl": "https://www.nycourts.gov/reporter/pdfs/2023/2023_30583.pdf", "confidence": "medium", "dollarAmount": 667599.52, "jurisdiction": "NY"}], "wrongful_lockout": [{"url": "https://www.hklaw.com/en/insights/publications/2022/09/can-a-commercial-landlord-engage-in-self-help-against-a-tenant", "year": 2016, "notes": "Widely cited as the leading example of a large commercial wrongful-eviction verdict; landlord's contractual self-help clause was unenforceable because Florida statute requires judicial process regardless of lease terms.", "outcome": "Directed verdict for the tenant on wrongful eviction affirmed on appeal; the appellate court held that Florida Statutes section 83.20 requires a landlord to recover possession only by court order, tenant surrender, or tenant abandonment, and a lease's private self-help clause cannot override that statutory requirement. The $8.8 million damages award was affirmed.", "caseName": "Palm Beach Florida Hotel & Office Building Corp. v. Nantucket Enterprises, Inc.", "citation": "211 So. 3d 42", "confidence": "high", "dollarAmount": 8800000, "jurisdiction": "FL"}, {"url": "https://law.justia.com/cases/minnesota/supreme-court/1978/47317-1.html", "year": 1978, "notes": "Landmark case establishing Minnesota's flat prohibition on commercial self-help eviction; frequently cited nationwide in property-law casebooks.", "outcome": "Minnesota Supreme Court affirmed judgment for the tenant, holding that a landlord may no longer use self-help/forcible re-entry against a tenant in possession, even a holdover tenant, and must use judicial process. This case abolished self-help eviction for commercial landlords in Minnesota.", "caseName": "Berg v. Wiley", "citation": "264 N.W.2d 145", "confidence": "high", "dollarAmount": 34540, "jurisdiction": "MN"}, {"url": "https://caselaw.findlaw.com/tx-court-of-appeals/1642239.html", "year": 2013, "notes": "Rare case actually applying Chapter 93's specific notice requirement (93.002(f)) rather than just citing the statute generally. Total judgment in the case (~$152,000) mixes lockout damages with unrelated claims, so only the wrongful-eviction component is reported as dollarAmount.", "outcome": "Court of appeals affirmed judgment largely for the tenant on the wrongful-eviction/Property Code 93.002 claim, but reversed a treble-damages award tied to the security deposit because that theory was not properly pleaded or tried by consent. Tenant also recovered on unrelated unjust-enrichment and overcharged-rent claims.", "caseName": "Eun Bok Lee v. Ho Chang Lee", "citation": "No. 01-12-00117-CV", "confidence": "high", "dollarAmount": 7375, "jurisdiction": "TX"}, {"url": "https://www.casemine.com/judgement/us/59149050add7b04934574675", "year": 1983, "notes": "One of the larger punitive-damages awards found for a commercial lockout/conversion claim; illustrates that egregious conduct during a lockout (not just the exclusion itself) can support outsized punitive damages even in a state that otherwise recognizes some rights of self-help.", "outcome": "On retrial, the jury found for the tenants on their conversion claim (the breach-of-contract count having been dismissed) and awarded substantial compensatory and punitive damages; the appellate court's judgment addressed post-trial issues from that verdict.", "caseName": "Janes v. Country Escrow Service", "citation": "135 Ariz. 231", "confidence": "high", "dollarAmount": 117741, "jurisdiction": "AZ"}, {"year": 2020, "notes": "A landlord-WIN counter-example, appellate-level and fully reversed on the merits -- important balance against this claim type's other citations, most of which involve a landlord losing. Confirms the two-part peaceable-and-entitled test for lawful self-help is a real, live defense that can completely defeat a wrongful-lockout claim on appeal even after a plaintiff wins at the trial-court level. dollarAmount reflects the $0 the tenant ultimately recovered on its own claim, not the unpaid-rent judgment entered against it.", "outcome": "Landlord used self-help to re-enter a hair salon tenant's leased premises, evict the tenant, and take possession of its personal property after default. The circuit court initially awarded the tenant $139,938.87 in compensatory damages for conversion; the Court of Special Appeals reversed and directed entry of judgment for the LANDLORD instead, for $43,304.91 in unpaid rent, holding the self-help reentry was lawful because the landlord was legally entitled to possession and reentry was accomplished peaceably.", "caseName": "Donegal Associates, LLC v. Christie-Scott, LLC", "citation": "Md. Ct. Spec. App. (2020)", "sourceUrl": "https://www.gfrlaw.com/what-we-do/insights/commercial-landlord-has-right-self-help", "confidence": "high", "dollarAmount": 0, "jurisdiction": "MD"}, {"year": 1986, "notes": "Seminal MI Court of Appeals authority on the anti-lockout statute's commercial application, still cited in current MI treatises. Tenant win on liability; remanded for damages, with trebling contingent on a separate 'forcible' finding under MCL 600.2918(1). No final dollar figure publicly available (remanded).", "outcome": "Landlord used self-help to exclude a commercial tenant occupying premises on Mackinac Island. The circuit court dismissed the tenant's anti-lockout claim on the theory the lease had expired; the Michigan Court of Appeals reversed, holding self-help is generally unavailable even against an arguably wrongfully-possessing tenant absent abandonment/surrender, and remanded for a determination of actual damages and whether the eviction was 'forcible' (which would trigger treble damages under MCL 600.2918(1)).", "caseName": "Deroshia v. Union Terminal Piers", "citation": "151 Mich. App. 715, 391 N.W.2d 458 (Mich. Ct. App. 1986)", "sourceUrl": "https://www.courtlistener.com/opinion/1815013/deroshia-v-union-terminal-piers/", "confidence": "high", "dollarAmount": null, "jurisdiction": "MI"}, {"year": 2002, "notes": "DOLLAR AMOUNT NOT CONFIRMED. Directly useful for calibrating the file's confirmed NJ 3x-multiplier mechanism -- clarifies a real computational nuance the current formula ('multiply actualDamages by 3') does not address: how a landlord's legitimate unpaid-rent offset interacts with the order of operations for trebling. If a jurisdiction requires (as this case suggests for NJ) that any rent offset be netted BEFORE trebling rather than after, that produces a materially different -- and larger -- damages figure than netting the offset against an already-trebled amount.", "outcome": "In a commercial forcible-entry-and-detainer dispute, the New Jersey Law Division held that a landlord's claim for unpaid rent is not entitled to any priority or preferential offset against the tenant's statutory treble-damages claim for unlawful eviction under N.J.S.A. 2A:39-8 -- any unpaid-rent offset should be applied BEFORE trebling, not used to reduce or extinguish the treble-damages claim itself, because the purpose of the treble-damages provision is specifically to deter landlord self-help.", "caseName": "Truesdell v. Carr", "citation": "351 N.J. Super. 217 (Law Div. 2002)", "sourceUrl": "https://www.courtlistener.com/opinion/7403741/truesdell-v-carr/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NJ"}, {"year": 2020, "notes": "A landlord/operator-WINS counter-example directly relevant to this claim type's own state-law-mechanism framework -- illustrates that even in a strong multiplier state (NY, confirmed 3x under this file's own model), the entire RPAPL 853 treble-damages remedy is unavailable at the threshold if the occupant is found to be a licensee rather than a tenant, regardless of how the removal was carried out. This tenant-vs-licensee threshold question is a real, litigated, and outcome-determinative issue this claim type's appliesIf/baseProbabilityByState framework does not currently distinguish.", "outcome": "A food vendor occupying three stalls at a Brooklyn food hall under a 2016 license agreement was given 7 days' written notice of termination and, when it did not vacate, had its equipment removed by the food hall operator. The vendor sought restoration of possession under RPAPL 713(10) and treble damages under RPAPL 853. The New York City Civil Court held the vendor was a LICENSEE, not a tenant, under the terms of its agreement -- the space had no doors or walls separating it from other vendors' stalls, and the agreement expressly reserved the operator's right to terminate -- and that the common-law self-help remedy against a mere licensee (rather than a tenant) was lawful when exercised peaceably. Because the ouster was therefore lawful, the vendor could not prevail on its RPAPL 853 treble-damages claim.", "caseName": "Shack Collective Inc. v. Dekalb Mkt. Hall, LLC", "citation": "2020 N.Y. Slip Op. 51156(U) (N.Y. Civ. Ct., Kings Cnty. 2020)", "sourceUrl": "https://caselaw.findlaw.com/court/ny-civil-court/2090201.html", "confidence": "high", "dollarAmount": 0, "jurisdiction": "NY"}, {"year": 2023, "notes": "DOLLAR AMOUNTS NOT YET FIXED as of the decision located (actual/compensatory and treble damages were both ordered 'in an amount to be determined at inquest' -- a later inquest order with final figures was not located in this session; verify before citing a specific number). A good, current, real illustration of NY's confirmed 3x multiplier mechanism actually being applied, and of a lockout being invalidated on a narrow, procedural ground (marshal executed the warrant based on address rather than confirming tenant identity) distinct from the substantive lockout-notice or self-help-authorization issues in this claim type's other citations.", "outcome": "A restaurant tenant in Mount Vernon, NY was locked out via a marshal's eviction warrant that did not match the tenant's business name to the address where the lockout was carried out -- the marshals testified they execute evictions based on address, not the name listed on the warrant. After a bench trial (Sept. 12-13, 2022), the court found the lockout unlawful and ruled for the tenant on breach of quiet enjoyment, RPAPL 853, conversion, and unjust enrichment, awarding rent abatement for a prior period plus actual/compensatory damages (including attorney's fees, costs, and disbursements) AND treble damages under RPAPL 853, with exact dollar amounts left to a subsequent inquest; the court declined to award punitive damages.", "caseName": "Emma Green Rest. LLC v. Blackridge Dev. Corp.", "citation": "2023 N.Y. Slip Op. 30749(U) (Sup. Ct., Westchester Cnty., decided May 3, 2023) (Index No. 53554/2020)", "sourceUrl": "https://www.law.com/newyorklawjournal/almID/1677509208NY535542020/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 2023, "notes": "Illustrates the limits of NY's RPAPL 853 multiplier mechanism: treble damages require force or genuinely unlawful means, not merely a later-reversed judicial removal. Good landlord-win / claim-dismissed data point for the 'Available_ProcessFollowed' low-probability bucket.", "outcome": "Landlord sued a former commercial tenant for wrongful eviction under RPAPL 853 (NY's treble-damages self-help/forcible-ejectment statute) after an earlier eviction was reversed on appeal on procedural grounds. The Appellate Division, Second Department affirmed dismissal of the RPAPL 853 claim, holding the complaint failed to allege the removal was by force or 'unlawful means' -- a judicially sanctioned removal, even one later reversed on appeal, does not automatically trigger treble damages.", "caseName": "5 Star Holdings NY, LLC v. Kohl's Dept. Stores, Inc.", "citation": "220 A.D.3d 830, 198 N.Y.S.3d 169 (N.Y. App. Div., 2d Dep't 2023); 2023 NY Slip Op 05240", "sourceUrl": "https://law.justia.com/cases/new-york/appellate-division-second-department/2023/2021-00262.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 2010, "notes": "Leading modern NY statement of the 4-element commercial self-help test, tenant win (restored to possession). The RPAPL 853 treble-damages claim itself was not finally adjudicated at this stage -- only restoration to possession was decided.", "outcome": "Commercial landlord used self-help to change locks and exclude a tenant over a rent dispute without a court order. The Appellate Term affirmed restoration of the tenant to possession, articulating the governing 4-element test for lawful commercial self-help re-entry in NY (lease specifically reserves right of re-entry, valid rent demand served, peaceable re-entry, tenant actually in default) -- because the lease did not authorize self-help, the lockout was unlawful and the tenant was restored.", "caseName": "Sol De Ibiza, LLC v. Panjo Realty, Inc.", "citation": "29 Misc. 3d 72, 911 N.Y.S.2d 567 (N.Y. App. Term, 1st Dep't 2010)", "sourceUrl": "https://www.nycourts.gov/REPORTER/3dseries/2010/2010_20386.htm", "confidence": "high", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 2005, "notes": "Intended as a second TX data point for the Prop. Code \u00a7 93.002 floor mechanism (greater of $500 or one month's rent) alongside the existing Eun Bok Lee citation. Case confirmed real and indexed (228 S.W.3d 684; docket 14-03-01092-CV), and CourtListener's own snippet confirms it is 'a commercial landlord/tenant dispute that ultimately resulted in the tenant...being locked out,' but full opinion text was blocked (403s from Justia/FindLaw/Leagle) so the exact holding, whether \u00a7 93.002/93.003 was applied, and any damages figure could not be independently confirmed. Verified-real-case / unverified-holding-detail -- recommend pulling the full slip opinion before relying on specific damages language.", "outcome": "Commercial tenant/guarantor was locked out of leased premises by the landlord via self-help; the Fourteenth Court of Appeals (Houston) addressed the resulting wrongful-lockout and related contract claims.", "caseName": "Cole Chemical & Distributing, Inc. v. Gowing", "citation": "228 S.W.3d 684 (Tex. App.\u2014Houston [14th Dist.] 2005); docket 14-03-01092-CV", "sourceUrl": "https://www.courtlistener.com/opinion/2357972/cole-chemical-distributing-inc-v-gowing/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "TX"}, {"year": 1961, "notes": "IMPORTANT CALIBRATION FLAG: California Civil Code \u00a7 789.3 (the $100/day statute the model currently cites for CA in the 'per-day' bucket) applies ONLY to property 'used by a tenant as his or her residence' -- it does NOT reach commercial tenancies. Commercial self-help lockouts in California are instead governed by this common-law/CCP \u00a71159-1161 framework, which yields ACTUAL damages only, not a statutory per-diem penalty. Old (1961) but remains controlling CA Supreme Court authority on commercial self-help; no more recent CA appellate decision squarely re-affirming it in a commercial context was found, but nothing suggests it has been narrowed.", "outcome": "Tenant was two months in arrears under a lease with a contractual right-of-re-entry clause. While the tenant was briefly away, the landlord unlocked her unit, removed her possessions to a warehouse, and refused re-entry. The California Supreme Court held that even an express lease right-of-re-entry can be enforced only through judicial process, not self-help; a lease clause purporting to authorize forcible entry is void against the public policy in CCP \u00a7 1159, and California's summary (3-day) unlawful detainer procedure under \u00a7 1161 answers any claimed necessity for self-help.", "caseName": "Jordan v. Talbot", "citation": "55 Cal. 2d 597, 361 P.2d 20, 12 Cal. Rptr. 488 (Cal. 1961)", "sourceUrl": "https://law.justia.com/cases/california/supreme-court/2d/55/597.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "CA"}, {"year": 2020, "notes": "ACTUAL-DAMAGES-ONLY state mechanism: Hawaii has no commercial anti-lockout multiplier/per-day/floor statute analogous to NY/NJ/MI/TX; proceeded as an ordinary lost-business-income damages claim. (A separate HRS \u00a7 480-13 unfair-trade-practices claim in the same case carries its own treble/statutory-minimum damages but is a distinct theory not resolved by this opinion -- should not be conflated with the lockout claim.) Fully verified via the complete 29-page slip opinion PDF. Good recent (2020) tenant-win data point for the 'actual-only' jurisdiction bucket.", "outcome": "Commercial tenant (hair salon) was locked out by the landlord without judicial process over a rent dispute, for 16 days, losing customers/income/an employee. Trial court found no damages owed because the tenant had materially breached the lease; the Hawaii Supreme Court held the alleged breaches were not material, the tenant WAS entitled to recover for the self-help lockout, and remanded for entry of a damages judgment 'in an amount it determines appropriate' -- a tenant win on liability with the dollar amount left to be fixed on remand.", "caseName": "Kahawaiolaa v. Hawaiian Sun Investments, Inc.", "citation": "146 Hawai#i 424, 463 P.3d 1081 (Haw. 2020); No. SCWC-17-0000317", "sourceUrl": "https://www.courts.state.hi.us/wp-content/uploads/2020/04/SCWC-17-0000317.pdf", "confidence": "high", "dollarAmount": null, "jurisdiction": "HI"}], "regulatory_taking": [{"year": 2015, "outcome": "The Federal Circuit affirmed the Court of Federal Claims' finding that the permit denial was a categorical (Lucas-type) regulatory taking of the parcel, entitling the owner to compensation for the full pre-denial value.", "caseName": "Lost Tree Village Corp. v. United States", "citation": "787 F.3d 1111 (Fed. Cir. 2015)", "sourceUrl": "https://caselaw.findlaw.com/court/us-federal-circuit/1702560.html", "confidence": "high", "dollarAmount": 4200000}, {"year": 2024, "outcome": "The Supreme Court unanimously held that the Nollan/Dolan 'unconstitutional conditions' framework applies to permit conditions imposed by legislation, not just individualized administrative conditions, rejecting the county's argument that legislatively-set fees are categorically exempt from heightened takings scrutiny. Remanded for further proceedings on whether this specific fee satisfies Nollan/Dolan.", "caseName": "Sheetz v. County of El Dorado, California", "citation": "601 U.S. 267 (2024)", "sourceUrl": "https://www.ballardspahr.com/insights/alerts-and-articles/2024/04/us-supreme-court-rules-in-favor-of-property-owner-in-exaction-takings-case", "confidence": "high", "dollarAmount": 23420}, {"year": 2024, "outcome": "The Supreme Court unanimously held the case should proceed under the cause of action available under Texas law rather than a freestanding federal one, vacating and remanding for the claims to continue in the lower courts; the case did not resolve or disclose any compensation figure.", "caseName": "DeVillier v. Texas", "citation": "601 U.S. 285 (2024)", "sourceUrl": "https://supreme.justia.com/cases/federal/us/601/22-913/", "confidence": "high", "dollarAmount": null}, {"year": 2013, "outcome": "The Supreme Court held 8-0 that temporary, government-induced flooding is not automatically exempt from Takings Clause liability and remanded for a multi-factor analysis; on remand, the Federal Circuit affirmed that a compensable taking had occurred and upheld the original damages calculation.", "caseName": "Arkansas Game & Fish Commission v. United States", "citation": "568 U.S. 23 (2012); on remand, 736 F.3d 1364 (Fed. Cir. 2013)", "sourceUrl": "https://en.wikipedia.org/wiki/Arkansas_Game_%26_Fish_Commission_v._United_States", "confidence": "medium", "dollarAmount": 5700000}, {"year": 2025, "notes": "IMPORTANT: this is a preliminary TRO ruling on likelihood of success, not a final judgment on the regulatory-taking claim's merits -- include as a current, real illustration that a short-term-rental ban applied to a property with an established pre-ban rental use and history CAN support a Penn Central claim at the threshold stage, not as a confirmed final win. A meaningfully different fact pattern from most regulatory-taking cases in this sample (a use-restriction ordinance rather than a development-density or wetlands-type regulation), reflecting a growing and currently unsettled area of takings litigation nationally.", "outcome": "Owner had rented a five-bedroom home on short-term platforms since 2022; the village annexed the property in 2024 and then enacted an ordinance banning short-term rentals. The district court granted a temporary restraining order, finding the owner likely to succeed on the merits of a Penn Central regulatory-taking claim because the ban would prevent economically feasible use of the property and interfered with the owner's investment-backed expectations formed before annexation.", "caseName": "Blakelick Properties LLC v. Village of Glen Ellyn", "citation": "No. 25-cv-04569 (N.D. Ill., TRO granted May 8, 2025)", "sourceUrl": "https://www.thefreelibrary.com/Federal+judge+halts+Glen+Ellyn,C%5BR%5Ds+ban+on+short-term+home+rentals.-a0840698001", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (N.D. Ill., applying IL law)"}, {"year": 2026, "notes": "A loss for the property owner even though the court expressly conceded the takings theory 'has something to it' -- the court declined to extend Koontz to this fact pattern and applied ordinary Penn Central deference instead.", "outcome": "Chicago's Keep Chicago Renting Ordinance requires a property owner who acquires a residential building through foreclosure to either offer existing tenants new one-year leases or pay each tenant a $10,600 relocation fee. The owner of a roughly 220-unit building (five tenants elected the cash payment) challenged the ordinance as an unconstitutional taking. The Seventh Circuit acknowledged the takings argument 'has something to it' but ultimately rejected it, characterizing the requirement as a 'clunky form of rent control' -- permissible regulation of the landlord-tenant relationship under the Penn Central framework -- rather than a compensable taking, and affirmed dismissal.", "caseName": "BBLI Edison, LLC v. City of Chicago", "citation": "7th Cir., No. 25-1713 (decided July 22, 2026)", "sourceUrl": "https://www.inversecondemnation.com/2026/07/ca7-takings-claim-has-something-to-it-but-city-requiring-owner-pay-relocation-fee-to-tenants-is-a-clunky-form-of-rent-control-so-you-lose.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal (7th Cir., applying IL law)"}, {"year": 2025, "notes": "Important complement to the Sheetz entry already in the file: the 2024 U.S. Supreme Court decision was a purely procedural win establishing that legislative fees don't get a free pass from Nollan/Dolan scrutiny -- but once that scrutiny was actually applied to the real fee on remand, the property owner LOST on the merits. Don't let the earlier SCOTUS win overstate this claim type's real odds; the final, substantive result was a defeat for the fee-payer.", "outcome": "After the U.S. Supreme Court held in 2024 that the Nollan/Dolan unconstitutional-conditions framework applies to legislatively-enacted development impact fees (not just individualized administrative conditions), the case returned to the California Court of Appeal to actually apply that framework to El Dorado County's traffic impact fee. On remand, the Court of Appeal rejected Sheetz's constitutional challenge on the merits, holding the County's legislatively-enacted fee satisfied Nollan/Dolan's nexus and rough-proportionality requirements.", "caseName": "Sheetz v. County of El Dorado (on remand from the U.S. Supreme Court)", "citation": "Cal. Ct. App., 3d Dist., No. C093682A (certified for publication, filed July 29, 2025)", "sourceUrl": "https://www.eminentdomainreport.com/supreme-court-shuts-the-door-on-sheetz", "confidence": "high", "dollarAmount": 23420, "jurisdiction": "CA"}, {"year": 2026, "notes": "Included for topical relevance to the Blakelick Properties v. Village of Glen Ellyn entry already in this claim's sample (both concern STR-ban litigation), not as a regulatory-takings holding itself -- this case turns on statutory preemption and delegation-of-authority doctrine, not the Takings Clause. Flag this distinction if it's surfaced to end users; it illustrates the broader trend of contested STR regulation but should not be cited as a Penn Central precedent.", "outcome": "Not itself a Penn Central/Lucas takings claim, but a closely related, currently-litigated short-term-rental-regulation dispute: property owners in a common-interest development successfully argued below that a City ordinance provision letting HOA boards opt their community out of the City's generally-applicable STR minimum-stay ban was preempted by the Davis-Stirling Act and an unconstitutional delegation of legislative authority, winning a writ of mandate ordering the City to issue them an unrestricted STR permit, plus attorney's fees. The Court of Appeal reversed on both theories, upholding the City's opt-out ordinance and the STR restriction as applied to the owners.", "caseName": "Matthew Parsons, et al. v. City of Indian Wells", "citation": "Cal. Ct. App., 4th Dist., Div. 2, No. E082591 (certified for publication, filed Aug. 31, 2026)", "sourceUrl": "https://www.courtlistener.com/opinion/10666454/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "CA"}, {"year": 2025, "notes": "A genuine, recent, appellate-level WIN for the property owner under Lucas -- a useful counterweight to the file's existing mostly-loss Penn Central sample (BBLI Edison, Sheetz-on-remand, Matthew Parsons) and directly on point for a post-natural-disaster permit-denial fact pattern relevant to commercial/multifamily property. Verified via a single specialty legal-commentary source rather than the court's own opinion text.", "outcome": "After Hurricane Harvey flood damage, Houston denied the owner a permit to rebuild/redevelop an apartment complex, effectively preventing any reconstruction. The City argued the land retained economic value because the owner could simply hold it for investment pending a future change in the regulation. The Fifth Circuit rejected that argument as a matter of Lucas doctrine, reasoning that treating speculative future value as an 'economically beneficial use' would immunize virtually any regulation that eliminates a property's present economic viability -- 'a brighter tomorrow is only a day away' does not answer whether the property has a beneficial use TODAY. The court reversed the district court and held the denial likely effected a categorical taking, remanding for further proceedings.", "caseName": "DM Arbor Court, Ltd. v. City of Houston", "citation": "Fifth Circuit, No. 23-20385 (decided Aug. 12, 2025)", "sourceUrl": "https://www.inversecondemnation.com/2025/08/ca5-land-value-from-holding-for-investment-aka-speculation-is-not-an-economically-beneficial-use.html", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (5th Cir., applying TX law)"}, {"year": 2026, "notes": "A clean, real loss establishing a basic but important threshold requirement -- there must be an identifiable regulation for a Penn Central/regulatory-taking theory to apply at all (as opposed to a physical-taking or ad hoc government-action theory). Verified via a single specialty legal-commentary source (a monthly digest page) rather than the court's own opinion text; full case facts beyond this holding were not independently confirmed.", "outcome": "The plaintiff attempted to bring a regulatory-takings claim without identifying any actual adopted regulation, ordinance, or rule that restricted the property's use. The Sixth Circuit rejected the claim, holding that a regulatory taking requires an actual regulation -- takings-clause protection for a REGULATORY taking cannot rest on informal government conduct, discretionary decisions, or the mere anticipation of future regulation absent a concrete regulatory act to point to.", "caseName": "Banks v. Charter Township of Bloomfield", "citation": "Sixth Circuit, No. 25-1833 (decided Apr. 28, 2026, unpublished)", "sourceUrl": "https://www.inversecondemnation.com/2026/05/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (6th Cir., applying MI law)"}, {"year": 2025, "notes": "An important, well-corroborated (multiple independent sources: CourtListener, State Court Report, FindLaw, The Texan, Texas Civil Justice League) 2025 Texas Supreme Court decision rejecting the 'valid police power = automatic defense' argument that municipalities in this exact post-Harvey floodplain-ordinance fact pattern had been raising -- directly relevant to the file's existing Blakelick Properties (STR ban) entry's broader 2020s pattern of post-hoc regulatory tightening being challenged as takings. Procedural win only (ripeness/remand), not a final merits win -- no dollar figure was set or awarded at this stage.", "outcome": "After Hurricane Harvey, Houston amended its floodplain ordinance to raise elevation requirements for new construction, and a developer sued for inverse condemnation, alleging the stricter elevation rules effected a regulatory taking of its property under the Texas Constitution. The court of appeals had dismissed the claim outright, reasoning that because the ordinance was a valid police-power exercise (and needed to comply with federal flood-insurance program requirements), it could not also be a taking. The Texas Supreme Court reversed, holding that a regulation being a valid exercise of police power does NOT categorically immunize it from a takings claim -- the Penn Central economic-impact analysis still applies -- and held the claim ripe for adjudication, remanding for a full Penn Central analysis on the merits.", "caseName": "The Commons of Lake Houston, Ltd. v. City of Houston, Texas", "citation": "Texas Supreme Court, No. 23-0474 (decided Mar. 21, 2025)", "sourceUrl": "https://www.courtlistener.com/opinion/10603750/the-commons-of-lake-houston-ltd-v-city-of-houston-texas/", "confidence": "high", "dollarAmount": null, "jurisdiction": "TX"}, {"year": 2026, "notes": "Fact pattern is residential (SWAT destruction), not commercial/industrial, and details beyond the 'reelection of remedy' holding were not independently confirmed (single specialty-blog source, brief description only). Included because it illustrates a live, generalizable trend -- since DeVillier v. Texas (2024, already in this file) confirmed federal takings claims often cannot proceed as freestanding federal causes of action, litigants are increasingly pursuing STATE constitutional takings claims as the live vehicle even where a parallel federal claim already failed on the merits, not just on the DeVillier cause-of-action/procedural point.", "outcome": "In the long-running litigation over a SWAT team's destruction of a homeowner's house during a standoff with a fugitive, the Fifth Circuit addressed a remedy-election question after the plaintiff's original 42 U.S.C. Sec. 1983 federal just-compensation claim had previously been rejected (on the theory that the police-power/necessity exception defeats a federal takings claim for emergency-response property destruction). The court approved the plaintiff's option to instead pursue relief under the Texas Constitution's separate takings clause, which does not necessarily share the same police-power carve-out as the federal claim.", "caseName": "Baker v. City of McKinney", "citation": "Fifth Circuit, No. 25-40396 (decided May 22, 2026)", "sourceUrl": "https://www.inversecondemnation.com/2026/05/", "confidence": "low", "dollarAmount": null, "jurisdiction": "Federal (5th Cir., applying TX law)"}, {"year": 2026, "notes": "CAVEAT: an entity also named 'Article 13 LLC' was separately involved in an unrelated New York state-court foreclosure/Foreclosure Abuse Prevention Act dispute (Article 13 LLC v. Ponce De Leon Fed. Bank, N.Y. Ct. App. 2025) that surfaced in initial research; this citation is a DIFFERENT, federal Second Circuit takings claim against the New York Attorney General, verified only via a single specialty-blog monthly digest rather than the court's own opinion. Given the risk of conflating two same-named-party cases, treat this entry with caution and verify independently before relying on it.", "outcome": "The plaintiff attempted to bring a Penn Central regulatory-takings claim premised on New York's Foreclosure Abuse Prevention Act, arguing the statute barred it from collaterally challenging the validity of a prior foreclosure action years after the limitations period had expired. The Second Circuit rejected the claim, holding the plaintiff never had a cognizable property interest in bringing such a stale collateral challenge in the first place, and that even assuming such an interest existed, any negative economic impact was the result of the plaintiff's own inaction (failing to timely raise the challenge) rather than the challenged statute -- defeating the claim under ordinary Penn Central causation principles.", "caseName": "Article 13 LLC v. New York Attorney General", "citation": "Second Circuit, No. 23-7247 (decided May 13, 2026)", "sourceUrl": "https://www.inversecondemnation.com/2026/05/", "confidence": "low", "dollarAmount": null, "jurisdiction": "Federal (2d Cir., applying NY law)"}], "cercla_cost_recovery": [{"year": 2026, "outcome": "647-page consent decree between EPA/Montana DEQ and CFAC requiring a $57.6 million cleanup, including a groundwater slurry wall and low-permeability landfill caps to stop contaminant migration toward the Flathead River. Open for public comment through Aug. 6, 2026.", "caseName": "United States v. Columbia Falls Aluminum Company, LLC", "citation": "Consent Decree, U.S. District Court for the District of Montana (Missoula Division), lodged July 2026", "sourceUrl": "https://www.epa.gov/newsreleases/columbia-falls-aluminum-corporation-llc-agrees-57-million-cleanup-former-smelter-site", "confidence": "high", "dollarAmount": 57600000}, {"year": 2024, "outcome": "Consent decree requiring a $150 million collective payment toward EPA's past and anticipated future cleanup response costs; approved and entered by the district court Dec. 18, 2024.", "caseName": "United States v. Alden Leeds, Inc., et al. (Lower Passaic River Study Area / Diamond Alkali Superfund Site)", "citation": "Consent Decree, D.N.J., approved and entered Dec. 18, 2024 (Judge Madeline Cox Arleo)", "sourceUrl": "https://www.epa.gov/newsreleases/parties-agree-pay-150-million-toward-clean-lower-passaic-river-new-jersey", "confidence": "high", "dollarAmount": 150000000}, {"year": 2024, "outcome": "Proposed consent decree totaling $151.1 million: $132.4 million to reimburse EPA for past and future cleanup costs, plus $18.7 million to resolve natural resource damage claims.", "caseName": "United States v. NL Industries, Inc., et al. (Raritan Bay Slag Superfund Site)", "citation": "Proposed Consent Decree, D.N.J., lodged Sept. 5, 2024", "sourceUrl": "https://www.epa.gov/newsreleases/epa-proposes-settlement-provide-151-million-cleanup-raritan-bay-slag-superfund-site", "confidence": "high", "dollarAmount": 151100000}, {"year": 2026, "outcome": "$668 million settlement requiring the Group to design and perform the in-water cleanup remedy (dredging and capping), estimated to take at least 10 years; the Group will receive roughly $130 million from other PRPs and $140 million from federal agencies toward the total.", "caseName": "United States v. Boeing Co., City of Seattle, and King County (Lower Duwamish Waterway Superfund Site)", "citation": "Settlement Agreement, W.D. Wash., announced March 2026", "sourceUrl": "https://www.justice.gov/opa/pr/justice-department-reaches-668m-settlement-agreement-continued-cleanup-lower-duwamish", "confidence": "high", "dollarAmount": 668000000}, {"year": 2000, "outcome": "DOCTRINAL CITATION, not a dollar-amount data point: on reconsideration, the court laid out the exact fork this claim type turns on. A current owner is normally a PRP itself and generally limited to a Sec. 113(f)(1) contribution claim against another PRP (recovering only that party's equitable share) -- UNLESS the owner qualifies as an 'innocent landowner' under Sec. 107(b), in which case it may bring a full Sec. 107(a) cost-recovery action and recover the ENTIRE cost. The court set out five factors the owner (ATC) had to prove: (1) a party other than ATC was the sole cause of the release; (2) the defendant is a liable party; (3) ATC did not actually know of the contamination at acquisition; (4) ATC undertook appropriate inquiry before acquiring the property; and (5) ATC exercised due care once the contamination was discovered. The court found disputed fact issues on factors 4-5 and denied summary judgment to both sides on that question -- so this case establishes the doctrine clearly without itself resolving whether ATC ultimately qualified.", "caseName": "Advanced Tech. Corp. v. Eliskim, Inc. (True Temper Site)", "citation": "No. 1:96CV755, __ F. Supp. 2d __ (N.D. Ohio May 3, 2000)", "sourceUrl": "https://www.honigman.com/media/site_files/244_imgimgWoolstrumA406314.pdf", "confidence": "high", "dollarAmount": null}, {"year": 2018, "outcome": "Third Circuit held that a current owner is liable under CERCLA Sec. 107(a)(1) for ALL response costs at a site -- including costs incurred before that owner even acquired the property -- rejecting the owner's argument that it should only be liable for post-acquisition costs. The owner in this case did not establish innocent-landowner or bona fide prospective purchaser protection. Illustrates the downside of NOT qualifying as an innocent landowner: not just a reduced recovery in a cost-recovery action, but potentially full personal liability as a defendant in someone else's action, including for costs predating ownership entirely.", "caseName": "Pennsylvania Dep't of Envtl. Prot. v. Trainer Custom Chem., LLC", "citation": "906 F.3d 85 (3d Cir. 2018)", "sourceUrl": "https://www2.ca3.uscourts.gov/opinarch/183287p.pdf", "confidence": "high", "dollarAmount": null}, {"year": 2020, "notes": "A strongly plaintiff-favorable allocation (95%/5%) for a current owner who did not cause the contamination -- useful as a high-end data point alongside the innocent-landowner citations elsewhere in this claim type, and the statute-of-limitations holding is independently significant for any multi-phase, multi-decade remediation site.", "outcome": "Current owner/operator sued to recover $374,540.25 in past PCB-cleanup costs and for a declaratory judgment on liability for future removal costs at a site Union Carbide had contaminated decades earlier. After a bench trial, the district court allocated 95% of future removal costs to Union Carbide and 5% to the plaintiff-owner, reasoning Union Carbide was the party that introduced and benefited from the PCBs. The Second Circuit's opinion also resolved a significant statute-of-limitations question: a single site can have more than one CERCLA 'removal action' triggering its own limitations period, rather than one clock running from the first remediation activity ever performed there.", "caseName": "MPM Silicones, LLC v. Union Carbide Corp.", "citation": "966 F.3d 200 (2d Cir. July 23, 2020)", "sourceUrl": "https://www.hodgsonruss.com/newsroom/publications/Second-Circuit-Clarifies-CERCLA-Statute-of-Limitations-Rules-There-Can-be-More-Than-One-Remediation-on-a-Site", "confidence": "high", "dollarAmount": 374540, "jurisdiction": "Federal (2d Cir., applying NY law)"}, {"year": 2021, "notes": "A significant, current U.S. Supreme Court clarification of when a party is limited to the narrower, time-barred \u00a7113(f) contribution remedy versus the broader \u00a7107(a) cost-recovery remedy this claim type models -- directly relevant to correctly classifying a fact pattern into cercla_cost_recovery versus cercla_contribution_claim before applying either claim's damages formula.", "outcome": "The Supreme Court unanimously held that a settlement resolving only Clean Water Act claims (not CERCLA claims specifically) can still trigger CERCLA's three-year contribution-claim statute of limitations, and clarified the line between a \u00a7107(a) cost-recovery action and a \u00a7113(f) contribution action -- allowing Guam to proceed with its cost-recovery claim against the United States for cleanup of the Ordot Dump rather than being time-barred as an untimely contribution claim.", "caseName": "Guam v. United States", "citation": "593 U.S. 310 (2021)", "sourceUrl": "https://www.congress.gov/crs-product/LSB10609", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal (U.S. Supreme Court)"}, {"year": 2026, "notes": "Multi-site, multi-state legacy PFAS manufacturing case -- fits the waterwayOrMultiDecadeLegacyIndustrialCorridor benchmark tier alongside Lower Duwamish/Solvay/Raritan Bay/Anaconda, and is itself close in size to the current NJ state PFAS consent judgments cited under state_cleanup_consent_decree (same underlying PFAS-manufacturer fact pattern, different sovereign plaintiff).", "outcome": "EPA, DOJ, and the West Virginia Dep't of Environmental Protection announced a $450 million settlement with Chemours resolving PFAS contamination and other environmental-law violations at four facilities: Chambers Works and Parlin, NJ; Fayetteville Works, NC; and Washington Works, WV. The package includes a $22.5 million civil penalty, a $90 million program to mitigate ongoing PFAS discharges into the Cape Fear, Delaware, and Ohio Rivers, plus additional injunctive-relief/remediation obligations making up the balance of the $450 million total. Subject to a 30-day public comment period before final court approval.", "caseName": "United States v. The Chemours Company, et al.", "citation": "Proposed Consent Decree, U.S. District Court for the Southern District of West Virginia, lodged/announced June 24, 2026", "sourceUrl": "https://www.epa.gov/enforcement/chemours-settlement-summary-june-2026", "confidence": "high", "dollarAmount": 450000000, "jurisdiction": "Federal (S.D. W. Va.)"}, {"year": 2025, "notes": "Falls in a dollar range ($20M-$130M) with NO current benchmark tier -- too large for singleParcelSoilOnly ($3M-$19M) but below the $130M floor of waterwayOrMultiDecadeLegacyIndustrialCorridor. See calibration note.", "outcome": "EPA secured commitments covering roughly $62 million in cleanup work (with more than $30 million in cleanup cost commitments specifically secured in FY2025) to remove over 50,000 cubic yards of contaminated soil/waste threatening the Biscayne Aquifer, the primary drinking-water source for approximately 5.2 million South Florida residents.", "caseName": "United States EPA cost-recovery settlement \u2014 Petroleum Products Corporation Superfund Site", "citation": "EPA enforcement settlement, Pembroke Park, Florida, announced June 2025 (FY2025 Superfund Cleanup Enforcement Annual Results)", "sourceUrl": "https://www.epa.gov/enforcement/enforcement-and-compliance-assurance-annual-results-fy-2025-superfund-cleanup", "confidence": "medium", "dollarAmount": 62000000, "jurisdiction": "Federal (S.D. Fla.)"}, {"year": 2025, "notes": "Sits at the upper end of the current singleParcelSoilOnly tier ($3M-$19M) -- though this is groundwater, not soil-only, so it also illustrates that tier's label may be narrower than the actual data it should cover.", "outcome": "$12 million settlement with Honeywell International to fund groundwater-contamination cleanup work aimed at restoring drinking-water access for approximately 144,000 residents drawing on the San Fernando Valley aquifer.", "caseName": "United States EPA cost-recovery settlement \u2014 Honeywell International (San Fernando Valley Area 1 Superfund Site)", "citation": "EPA enforcement settlement, North Hollywood/Burbank, California, announced February 2025 (FY2025 Superfund Cleanup Enforcement Annual Results)", "sourceUrl": "https://www.epa.gov/enforcement/enforcement-and-compliance-assurance-annual-results-fy-2025-superfund-cleanup", "confidence": "high", "dollarAmount": 12000000, "jurisdiction": "Federal (C.D. Cal.)"}, {"year": 2026, "notes": "Useful because it shows the government itself as a cost-recovery DEFENDANT/PRP (from historical war-materiel production contracts) -- a fact pattern this claim type's current sample doesn't otherwise illustrate. Full case caption/docket not independently confirmed beyond the trade-press summary; underlying consent decree/complaint not directly reviewed.", "outcome": "REVERSE-POSTURE cost-recovery settlement: the private owners (including Celanese Corp.) of the Chemtronics Superfund site near Asheville, NC -- contaminated by decades of Vietnam-era chemical-weapons/tear-gas manufacturing conducted at points under government direction -- sued the United States as a PRP under CERCLA Sec. 107. The owners agreed to drop their claims for further reimbursement of cleanup costs in exchange for a $3.9 million payment from the United States.", "caseName": "Celanese Corp., et al. v. United States (Chemtronics Superfund Site)", "citation": "Consent Decree / settlement, W.D.N.C., reported March 2026 (Mealey's Pollution Liability)", "sourceUrl": "https://www.law360.com/mealeys/mealeys-pollution-liability/articles/2448225/u-s-to-pay-3-9m-to-north-carolina-superfund-site-owners-to-settle-cercla-suit", "confidence": "medium", "dollarAmount": 3900000, "jurisdiction": "Federal (W.D.N.C.)"}, {"year": 2025, "notes": "Falls below the current singleParcelSoilOnly floor of $3M despite being a real, EPA-negotiated cost-recovery settlement -- and involves a much larger number of PRPs (231) than any tier currently models. See calibration note.", "outcome": "Proposed CERCLA Sec. 122(h) cost-recovery settlement resolving liability for 231 separate settling parties (a large de minimis-style multi-party settlement), who collectively agreed to pay $1,427,692.56 to reimburse EPA's past response costs at the site.", "caseName": "Proposed CERCLA Cost Recovery Settlement \u2014 Pure Earth Recycling Superfund Site", "citation": "Proposed settlement, EPA Region 2, Vineland, Cumberland County, NJ, published Federal Register Feb. 28, 2025", "sourceUrl": "https://www.federalregister.gov/documents/2025/02/28/2025-03208/proposed-cercla-cost-recovery-settlement-for-the-pure-earth-recycling-superfund-site-vineland", "confidence": "high", "dollarAmount": 1427692.56, "jurisdiction": "Federal (D.N.J.)"}, {"year": 2026, "notes": "An order of magnitude below even the smallCommercialStateEnforcementPenalty tier floor of $85,000 -- confirms real EPA cost-recovery settlements can be extremely small when the PRP's actual contribution to a site was minor.", "outcome": "Proposed settlement requiring the settling respondent to pay $22,171.29 plus interest to reimburse EPA's past response costs at a single polymer-release site.", "caseName": "Proposed CERCLA Cost Recovery Settlement \u2014 Trinseo Polymer Release Site", "citation": "Proposed settlement, Bristol, Bucks County, Pennsylvania, published Federal Register Jan. 16, 2026", "sourceUrl": "https://regulations.justia.com/regulations/fedreg/2026/01/16/2026-00783.html", "confidence": "high", "dollarAmount": 22171.29, "jurisdiction": "Federal (E.D. Pa.)"}, {"year": 2013, "notes": "A commercial-shopping-center-specific dry-cleaner PCE fact pattern (like Regency Centers/Indian Harbor under the insurance-dispute claim type, and the Sigma Realty/Knapp-estate small dry-cleaner state actions) but decided as a CERCLA cost-recovery cross-claim rather than an insurance or state-penalty action -- useful for cross-referencing how the same underlying contamination type plays out across different claim types in this dataset. dollarAmount left null because no source reviewed disclosed a confirmed final total.", "outcome": "Decades of PCE seepage from a former dry-cleaning tenant ('Al Phillips the Cleaner') migrated from a Las Vegas shopping center into an adjoining residential neighborhood's soil and groundwater. Neighboring homeowners obtained injunctive relief against the shopping-center owner and dry-cleaner operators under RCRA Sec. 7002; the Nevada Division of Environmental Protection separately pursued and (on summary judgment, affirmed on appeal) recovered its past CERCLA response costs from the same parties. NDEP's April 2007 PRP notice put its expended costs at approximately $160,000 at that stage, with additional response costs anticipated; the final total recovery is not confirmed by the sources reviewed.", "caseName": "Voggenthaler v. Maryland Square LLC", "citation": "724 F.3d 1050 (9th Cir. 2013); related district court docket 2:08-cv-01618-RCJ-GWF (D. Nev.)", "sourceUrl": "https://law.justia.com/cases/federal/appellate-courts/ca9/10-17520/10-17520-2013-07-26.html", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (9th Cir., applying NV law)"}], "guaranty_enforcement": [{"year": 2011, "outcome": "Trial court and Court of Appeals held the guarantor personally liable for the full loan deficiency after the mall's foreclosure sale, because the borrower's insolvency breached the SPE covenant and triggered the springing full-recourse carve-out. (While on appeal, the Michigan legislature passed the Non-Recourse Mortgage Loan Act specifically to reverse this outcome prospectively, but it did not undo the judgment against Schostak.)", "caseName": "Wells Fargo Bank, N.A. v. Cherryland Mall Ltd. Partnership", "citation": "300 Mich. App. 361, 813 N.W.2d 891 (Mich. Ct. App. 2011)", "sourceUrl": "https://www.commercialsearch.com/news/guest-column-the-cherryland-decision-full-recourse-enforcement-of-non-recourse-loans/", "confidence": "high", "dollarAmount": 2100000}, {"year": 2009, "outcome": "Trial court granted summary judgment holding the borrower and guarantors personally liable for the full loan amount. Appellate Division affirmed, holding as a matter of first impression in New Jersey that a non-recourse carve-out triggered by unauthorized subordinate financing fixes liability (not merely an estimate of damages) and is fully enforceable even though the triggering breach (the $400K loan) had long since been cured.", "caseName": "CSFB 2001-CP-4 Princeton Park Corporate Center, LLC v. SB Rental I, LLC", "citation": "410 N.J. Super. 114, 980 A.2d 1 (App. Div. 2009)", "sourceUrl": "https://www.quimbee.com/cases/csfb-2001-cp-4-princeton-park-corporate-center-llc-v-sb-rental-i-llc", "confidence": "high", "dollarAmount": 5195933}, {"year": 2011, "outcome": "Following the Cherryland precedent, the district court granted the lender summary judgment, holding that the borrower's insolvency breached the SPE covenant and triggered full-recourse liability against the guarantor for the entire deficiency.", "caseName": "51382 Gratiot Avenue Holdings, LLC v. Chesterfield Development Co., LLC", "citation": "835 F. Supp. 2d 384 (E.D. Mich. 2011)", "sourceUrl": "https://law.justia.com/cases/federal/district-courts/michigan/miedce/2:2011cv12047/258665/99/", "confidence": "high", "dollarAmount": 12240109}, {"year": 2026, "outcome": "Complaint filed seeking roughly $18.25M in principal, interest, and fees, plus appointment of a receiver over TIG's restaurant operations; no ruling had been reported as of this research.", "caseName": "Bank Midwest, N.A. v. The Integritty Group", "citation": "U.S. District Court, Eastern District of Pennsylvania, filed August 6, 2026", "sourceUrl": "https://sbj.net/stories/kc-bank-sues-philadelphia-qdoba-operator,105343", "confidence": "high", "dollarAmount": null}, {"year": 2025, "notes": "A significant, current state-supreme-court-level limiting citation: over $1M sought under a guaranty clause was entirely unenforceable against the individual signatories due to a signature-formality defect, despite clear substantive guaranty language in the contract. Directly relevant to calibrating guaranty_enforcement's probability downward where the guaranty was signed without a clearly dual/individual-capacity signature block -- a common drafting gap in short-form supply and vendor agreements, not just loan guaranties.", "outcome": "Supplier sued a construction-materials buyer and its two principals personally on a guaranty clause within a two-page supply agreement, seeking $1,016,627.65 allegedly owed. The two individuals had signed the guaranty paragraph with their signatures labeled only '(No Title)', without a separate signature line clarifying they signed in their individual capacity. The New Jersey Supreme Court held the personal guaranty unenforceable against them, adopting a rule that a guarantor must clearly and unambiguously express intent to be personally bound through one of three methods: a separate guaranty agreement, a dual signature (once as company representative, once individually), or a single signature on an agreement that expressly states it binds both the company and the individual.", "caseName": "Extech Building Materials, Inc. v. E&N Construction, Inc.", "citation": "A-28-24 (N.J. Dec. 2, 2025)", "sourceUrl": "https://www.newjerseylawyersblog.com/new-jersey-supreme-court-explains-requirements-of-enforceable-personal-guarantees/", "confidence": "high", "dollarAmount": 0, "jurisdiction": "NJ"}, {"year": 2013, "notes": "A bankruptcy-filing trigger case (rather than the SPE-insolvency-covenant trigger common to the Cherryland/Gratiot Avenue line already in the file), and notable for holding the springing guaranty enforceable even against New York's normally borrower-protective 'one action' rule.", "outcome": "UBS Securities made a $29 million non-recourse loan in 2007 secured by Midtown Manhattan real property; the borrower's principal executed a standard non-recourse carve-out guaranty. After the borrower defaulted and the lender commenced a foreclosure action including a guaranty claim, the borrower later filed for bankruptcy. The court held that the voluntary bankruptcy filing triggered the guaranty's full-recourse springing provision, entitling the lender to seek immediate full repayment from the guarantor notwithstanding New York's 'one action' rule, which normally would have required the lender to exhaust the mortgaged property first.", "caseName": "172 Madison (NY) LLC v. NMP-Group, LLC, et al.", "citation": "Index No. 650087/2010 (N.Y. Sup. Ct., N.Y. Cnty., Commercial Div.)", "sourceUrl": "https://www.alston.com/-/media/files/insights/publications/2013/10/ifinance-advisoryi-bad-boy-guaranties-and-bankrupt/files/click-to-view-finance-advisory-pdf/fileattachment/13778madison172.pdf", "confidence": "high", "dollarAmount": 29000000, "jurisdiction": "NY"}, {"year": 2010, "notes": "A strong pro-lender landmark on a distinct doctrinal point from the existing sample: a guaranty is legally independent of the underlying mortgage debt, so procedural elections that extinguish a borrower's deficiency exposure (redemption-period elections, anti-deficiency statutes, etc.) do not automatically protect a guarantor unless the guaranty itself says so.", "outcome": "After the mortgaged properties sold at sheriff's sale for $1,180,000 against roughly $1.4 million owed, the bank elected a shortened statutory redemption period, which under Wisconsin law waives any deficiency claim against the BORROWER. The Wisconsin Supreme Court held that election does not also waive the lender's separate claim against the GUARANTOR, because guarantor liability arises under an entirely separate contract of guaranty rather than from the mortgage debt itself -- allowing the bank to obtain judgment against the guarantor for the full guaranteed debt even after forfeiting a deficiency claim against the primary obligor.", "caseName": "Bank Mutual v. S.J. Boyer Construction, Inc.", "citation": "2010 WI 74, 785 N.W.2d 462 (Wis. 2010)", "sourceUrl": "https://kmksc.com/good-news-for-lenders-wisconsin-supreme-court-strengthens-lenders-remedies-against-guarantors/", "confidence": "high", "dollarAmount": 1400000, "jurisdiction": "WI"}, {"year": 2015, "notes": "A direct, important counterweight to Cherryland and Gratiot Avenue (both already in the file, both pre-NMLA and both full guarantor losses on the same insolvency-covenant theory): this case shows Michigan's 2011 legislative fix actually working in a guarantor's favor to defeat an otherwise-identical full-recourse claim. Confirms that jurisdiction and TIMING relative to a state's legislative response matters enormously for this claim type -- a state-law modifier tracking which states have passed anti-full-recourse statutes (Michigan, and per the existing file's note, Ohio) would likely sharpen this claim type more than a flat national probability range does.", "outcome": "A purchaser standing in the original lender's shoes sued the borrower and guarantor Joseph Schwebel to collect a roughly $6 million deficiency, relying on a solvency covenant in the guaranty as the full-recourse trigger. The Sixth Circuit affirmed summary judgment FOR the guarantor, holding that Michigan's post-Cherryland Nonrecourse Mortgage Loan Act (NMLA) rendered the solvency covenant unenforceable and therefore barred the deficiency action entirely -- the guarantor owed nothing on the $6 million claim.", "caseName": "Borman, LLC v. Borman, LLC; Joseph Schwebel", "citation": "No. 14-1419 (6th Cir. Feb. 3, 2015)", "sourceUrl": "https://caselaw.findlaw.com/court/us-6th-circuit/1691249.html", "confidence": "high", "dollarAmount": 6000000, "jurisdiction": "Federal (6th Cir., applying MI law)"}, {"year": 2024, "notes": "Same underlying case as the citation added to foreclosure_deficiency_judgment -- included here too because it bears directly on guaranty enforcement mechanics: which state's deficiency-judgment framework (if any) governs a guaranty-collection suit can itself become a contested threshold question, independent of the guaranty's substantive terms. Confidence marked medium because the final merits ruling on guarantor liability was not confirmed.", "outcome": "Lender sued guarantors Dr. Rappaport and an estate to collect a roughly $4.9 million judgment already entered in the underlying mortgage foreclosure, via breach-of-contract and unjust-enrichment claims under the guaranty (the lender had already taken the collateral at a nominal sheriff's sale price). The court held Pennsylvania's Deficiency Judgment Act did not apply to the action because the property's only Pennsylvania connection was the pledged vacant collateral, and expressly reserved the question of the guarantors' ultimate contractual liability for further proceedings rather than resolving it on this motion.", "caseName": "Lifestyle Real Estate Lender, LLC v. Fred Rappaport, et al.", "citation": "No. 2:21-cv-01781 (E.D. Pa.)", "sourceUrl": "https://www.courtlistener.com/opinion/10710710/lifestyle-real-estate-lender-llc-v-fred-rappaport-et-al/", "confidence": "medium", "dollarAmount": 4900000, "jurisdiction": "Federal (E.D. Pa.)"}], "quick_take_challenge": [{"year": 2018, "outcome": "The jury found the property's fair market value to be $16.83 million \u2014 nearly 3.6x the quick-take deposit \u2014 and separately awarded MAC $2,933,700 for the district's breach of the implied covenant of good faith and fair dealing. The court ordered the district to increase its deposit by about $12.2 million to match the verdict, and the Court of Appeal addressed the novel procedural question of what security/bonding the owner could be required to post to withdraw the increased post-judgment deposit.", "caseName": "Medical Acquisition Company, Inc. v. Superior Court (Tri-City Healthcare District)", "citation": "20 Cal. App. 5th 34, D072509 (Cal. Ct. App., 4th Dist., Div. 1, Jan. 11, 2018)", "sourceUrl": "https://www4.courts.ca.gov/opinions/documents/D072509.PDF", "confidence": "high", "dollarAmount": 16830000}, {"year": 2011, "outcome": "The California Supreme Court held that a party's withdrawal of a quick-take deposit does not, by itself, waive the right to continue challenging the condemnor's right to take. The underlying valuation dispute was ultimately resolved through a confidential settlement in 2011 after the property owner's parent entity went through bankruptcy, ending seven years of litigation.", "caseName": "Los Angeles County Metropolitan Transportation Authority v. Alameda Produce Market, LLC", "citation": "52 Cal. 4th 1100 (Cal. 2011)", "sourceUrl": "https://scocal.stanford.edu/opinion/la-cty-metro-trans-v-alameda-produce-34028", "confidence": "high", "dollarAmount": null}, {"year": 2013, "outcome": "The Virginia Supreme Court unanimously held NRHA had no right to take the property because it was not validly part of a blighted redevelopment area, voiding the condemnation and ordering the property returned to the owner \u2014 mooting the earlier jury compensation verdict since no taking occurred.", "caseName": "PKO Ventures, LLC v. Norfolk Redevelopment & Housing Authority (Norva Properties)", "citation": "747 S.E.2d 826 (Va. 2013)", "sourceUrl": "https://www.courtlistener.com/opinion/8686764/norfolk-redevelopment-housing-authority-v-norva-properties-lc/", "confidence": "medium", "dollarAmount": null}, {"year": 2024, "notes": "A stark, multi-level-litigated illustration of just how deferential post-Kelo public-use review is: the condemnation was requested by, and directly benefited, the owner's own business competitor, yet the taking was still upheld as serving a valid public purpose once framed as traffic/parking mitigation. Directly supports keeping this claim's baseProbability at the low end of its 0.05-0.15 range even where the challenger has a sympathetic 'this taking exists only to help my competitor' narrative.", "outcome": "A business competitor of the property owner asked the county industrial development agency to condemn the owner's under-contract parcel so the agency could instead build a parking lot serving the competitor's adjacent medical office building. The Appellate Division had first annulled the taking, but the Court of Appeals reversed and remanded; on remand the Appellate Division dismissed the owner's petition, holding the parking-lot project served a valid public purpose (mitigating parking and traffic congestion) regardless of the competitor's role in initiating it. The U.S. Supreme Court denied certiorari.", "caseName": "Matter of Bowers Development, LLC v. Oneida County Industrial Development Agency", "citation": "2024 NY Slip Op 00523 (App. Div., 4th Dep't, Feb. 2, 2024); cert. denied, U.S. Sup. Ct. (Mar. 24, 2025)", "sourceUrl": "https://www.romesentinel.com/news/bowers-development-411-columbia-st-oneida-county-supreme-court/article_52f43350-be3f-11ef-8304-0fe1f1968cca.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 2026, "notes": "A genuine, state-high-court-level landowner win on a right-to-take theory -- but note the taking failed for lack of statutory authority for this specific land-swap structure, not because the underlying open-space goal was found illegitimate; an ordinary public-use/necessity challenge to a taking that directly serves the stated project would very likely still fail post-Kelo.", "outcome": "Jackson Township condemned two privately owned lots (owned by Getzel Bee, LLC and Bellevue Jackson LLC) not to use the land itself for a public purpose, but to trade them to a private developer in exchange for a different, unrelated 35-acre tract the Township wanted preserved as open space. The New Jersey Supreme Court unanimously held that neither the Local Lands and Buildings Law nor the Eminent Domain Act authorizes a municipality to condemn private property to use purely as exchange 'currency' in a land swap, because the public-use requirement attaches to the condemned property itself, not merely to the overall transaction's ultimate goal. The condemnation was invalidated.", "caseName": "Township of Jackson v. Getzel Bee, LLC", "citation": "N.J. Supreme Court, No. A-3-25 (decided July 2026)", "sourceUrl": "https://www.njlm.org/m/newsflash/Home/Detail/3919", "confidence": "high", "dollarAmount": null, "jurisdiction": "NJ"}, {"year": 2023, "notes": "Another loss for the party resisting the condemning authority's right to take -- consistent with this claim type's existing low baseProbability -- though notable for showing how long and costly the underlying right-to-take fight can run (roughly two decades of litigation) even where the challenger ultimately loses.", "outcome": "In a decades-long dispute over the irrigation district's bid to acquire PG&E's local electric distribution system via eminent domain to run it as a public utility, the Court of Appeal upheld the district's resolution of necessity and the underlying LAFCO determination that the district has authority to provide electric service in its territory. The California Supreme Court subsequently denied PG&E's petition for review, and PG&E was ordered to pay the district's litigation costs from the multi-year fight.", "caseName": "Pacific Gas and Electric Co. v. Superior Court (South San Joaquin Irrigation District, Real Party in Interest)", "citation": "Cal. Ct. App., 3d Dist., No. C097529 (certified for publication, filed Sept. 21, 2023)", "sourceUrl": "https://www.horvitzlevy.com/pacific-gas-electric-co-v-superior-court-south-san-joaquin-irrigation-district-2023/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "CA"}, {"year": 2026, "notes": "A significant, real WIN for a challenger to a condemning authority's right to take, in the specific sub-context of utility municipalization -- the new preponderance-of-evidence standard is more challenger-friendly than the deferential standard applied to ordinary public-use/necessity challenges, and the $13M+ fee-shifting outcome shows the stakes when a challenge succeeds.", "outcome": "Resolving a split among California appellate districts, the California Supreme Court held that when a utility challenges a public agency's resolution of necessity to condemn (municipalize) the utility's system, courts must independently review whether the agency has proven by a preponderance of the evidence that the taking is authorized, rather than applying the traditional highly deferential 'gross abuse of discretion' standard. Applying the more searching standard, the utility had already prevailed at a 67-day bench trial below, with the Town's resolution of necessity found invalid and the Town ordered to pay the utility more than $13 million in attorneys' fees.", "caseName": "Town of Apple Valley v. Apple Valley Ranchos Water", "citation": "Cal. Supreme Court, No. S289391 (decided Aug. 24, 2026)", "sourceUrl": "https://www.eminentdomainreport.com/supreme-court-delivers-huge-win-for-utilities-facing-municipalization", "confidence": "high", "dollarAmount": 13000000, "jurisdiction": "CA"}, {"year": 2026, "notes": "A genuine landowner win with a confirmed dollar figure ($122,144.50 in fees), and a rare finding of outright bad faith by the condemning authority -- a starker fact pattern than most necessity-challenge losses. Independently corroborated by inversecondemnation.com's contemporaneous case summary.", "outcome": "The Town of Colchester sought to condemn a lakeside parcel on Malletts Bay (Lake Champlain) to build a stormwater treatment facility, after a town attorney had previously threatened the owner in 2020 that 'if you sue the town we will take your house by eminent domain.' The trial court found the town failed to prove the statutory elements of necessity -- it did not meaningfully consider cheaper alternative sites and the parcel was conspicuously absent from the town's own prior stormwater planning studies -- and separately found the taking was initiated in bad faith as a pretextual move against a landowner the town considered a 'thorn in its side.' The Vermont Supreme Court affirmed the invalidation of the taking. On remand, the trial court ordered the Town to pay Mongeon Bay $122,144.50 in legal fees.", "caseName": "Mongeon Bay Properties, LLC v. Town of Colchester", "citation": "Vermont Supreme Court, No. 25-AP-125 (decided Jan. 23, 2026)", "sourceUrl": "https://www.colchestersun.com/news/government/town-of-colchester-hit-with-120000-legal-fee/article_8142388d-be1f-49ba-a240-7d4b681a9e8a.html", "confidence": "high", "dollarAmount": 122145, "jurisdiction": "VT"}, {"year": 2026, "notes": "A commercial/industrial-property win (LNG port complex) directly on point for the post-Kelo state-constitutional-amendment trend already reflected in the file's existing Jackson Township v. Getzel Bee (NJ) entry. Verified via a single specialty legal-commentary source (inversecondemnation.com, a well-established eminent domain law blog) rather than the court's own opinion text.", "outcome": "The port authority sought to condemn a vacant 29-acre parcel within its 630-acre Delta LNG Project complex in order to lease the land to Venture Global LNG for that private company's own LNG processing and transportation operations, depositing $441,600 as alleged just compensation. The Louisiana Supreme Court invalidated the taking under Louisiana Constitution Article I, Section 4(B)(1) -- enacted post-Kelo specifically to bar takings 'for predominant use by any private person or entity' -- holding that a public port authority condemning land only to lease it to a private company for that company's own exclusive private port operations is exactly the kind of taking the 2006 amendment was written to prohibit, 'essentially what Kelo allowed.'", "caseName": "Plaquemines Port Harbor & Terminal District v. Nguyen", "citation": "Louisiana Supreme Court, No. 2025-C-00827 (decided Mar. 6, 2026)", "sourceUrl": "https://www.inversecondemnation.com/2026/03/post-kelo-amendments-to-louisiana-constitution-prohibit-taking-to-lease-to-private-company-for-its-own-use.html", "confidence": "medium", "dollarAmount": 441600, "jurisdiction": "LA"}, {"year": 2025, "notes": "Not yet a final merits win (reversed and remanded for fact-finding, not an outright invalidation), but a genuine appellate-level rejection of automatic deference where a 99-year private lease-back is involved -- a useful middle case between an outright win (Mongeon Bay, Plaquemines) and a loss. dollarAmount set to the jury verdict figure; the case also has a $1.1M initial offer and $1,545,500 commissioners' award in the record.", "outcome": "The City sought to condemn a 3.5-acre parcel adjoining its municipal golf course to expand a short-game practice facility, ultimately intending to lease the expanded facility to a private golf operator under a 99-year agreement. The City's last offer was $1.1 million; special commissioners awarded $1,545,500; a jury separately found $1,313,675 in damages. The Court of Appeals reversed summary judgment against the owner's public-use challenge, holding courts may not simply defer to the government's stated public purpose where the taking's primary effect is a long-term private benefit transfer -- the case was remanded for fact-finding on whether the project's true primary purpose was impermissible private/economic-development benefit.", "caseName": "Burgess v. City of Wentworth Village", "citation": "Texas Court of Appeals (2d Dist.), No. 02-24-00252-CV (decided June 19, 2025)", "sourceUrl": "https://www.inversecondemnation.com/2025/06/texas-app-no-a-taking-for-a-short-game-practice-area-isnt-entitled-to-judicial-deference.html", "confidence": "medium", "dollarAmount": 1313675, "jurisdiction": "TX"}, {"year": 2025, "notes": "A clean, real landowner win on a distinct and useful theory -- lack of PARTICULARITY in the stated public use/project, as opposed to a lack of public use in the abstract -- for a commercial/industrial port-expansion project. Verified via a single specialty legal-commentary source rather than the court's own opinion text.", "outcome": "Port Freeport sought to condemn property in a historic community for vaguely described 'expansion of the Port Facilities' and 'development of business industries,' with the Port's own CEO able only to speculate about possible future uses (offices, warehouses, refrigerated facilities). The Court of Appeals held that 'merely parroting the language in the code for the permissible uses of eminent domain is not enough' -- a condemnor must articulate a specific, particularized public use tied to the specific property, not a generic list of authorized use-categories -- and reversed the taking, remanding with instructions that the Port must replead with the required specificity or face dismissal.", "caseName": "Jones v. Port Freeport", "citation": "Texas Court of Appeals (14th Dist.), No. 14-23-00948 (decided Sept. 18, 2025)", "sourceUrl": "https://www.inversecondemnation.com/2025/09/tex-app-no-plan-no-public-use-no-eminent-domain.html", "confidence": "medium", "dollarAmount": null, "jurisdiction": "TX"}], "receivership_dispute": [{"year": 2026, "outcome": "Complaint filed seeking appointment of a receiver rather than proceeding directly to foreclosure; as of this research, no ruling on the receivership motion had been reported.", "caseName": "U.S. Bank National Association v. Brookfield Republic Plaza LLC", "citation": "Denver District Court, Colorado, filed August 10, 2026", "sourceUrl": "https://www.denvergazette.com/2026/08/14/downtown-denvers-tallest-building-faces-receivership-after-loan-default/", "confidence": "high", "dollarAmount": null}, {"year": 2026, "outcome": "Cook County court granted the lender's request and appointed Scott Shefman of Friedman Real Estate Management as receiver on June 16, 2026, giving the special servicer (LNR Partners) operational control of the office component pending resolution.", "caseName": "Citibank, N.A. / LNR Partners v. Golub & Company and BlueFive Capital (625 North Michigan Avenue)", "citation": "Cook County Circuit Court, Illinois, receiver appointed June 16, 2026", "sourceUrl": "https://therealdeal.com/chicago/2026/06/27/receiver-appointed-in-625-n-michigan-ave-foreclosure/", "confidence": "high", "dollarAmount": null}, {"year": 2025, "outcome": "The court granted the receivership motion on August 27, 2025, installing Lewis Taulbee of JLL as receiver. As of March 2026, the property remained under receivership, with the receiver managing operations and positioning the asset for sale; no foreclosure auction had yet been scheduled.", "caseName": "Wells Fargo Bank, N.A. (as trustee) v. Hertz Investment Group (Riverfront Plaza)", "citation": "Richmond Circuit Court, Virginia, receiver appointed August 27, 2025", "sourceUrl": "https://richmondbizsense.com/2025/08/21/lawsuit-looks-to-put-riverfront-plaza-office-towers-into-receivership-ahead-of-potential-foreclosure/", "confidence": "high", "dollarAmount": null}, {"year": 2026, "outcome": "Lake County Judge Daniel Jasica granted CWCapital's emergency motion on February 11, 2026, appointing Matthew Tarshis of Frontline Real Estate Partners as receiver over the property while the underlying foreclosure litigation proceeds.", "caseName": "CWCapital (special servicer) v. Kawa Capital (One Parkway North Boulevard, Deerfield)", "citation": "Lake County Circuit Court, Illinois, receiver granted February 11, 2026", "sourceUrl": "https://therealdeal.com/chicago/2026/04/23/cwcapital-hits-suburban-chicago-office-with-foreclosure/", "confidence": "high", "dollarAmount": null}, {"year": 2026, "notes": "A rich, current appellate-level confirmation of real receiver powers in a distressed-loan context: modifying a self-dealing, affiliate-favorable lease term put in place after default, and the availability of civil contempt as a real enforcement tool against a borrower/principal who stonewalls a receivership's accounting demands. dollarAmount reflects the underlying loan amount, not a separate damages figure -- this citation is about receiver authority and enforcement, not a compensatory award.", "outcome": "Commercial mortgage foreclosure on a $20.5 million loan secured by a Jenkintown, Pennsylvania property. After the borrower defaulted and failed to timely answer, the district court entered default and later default judgment, then appointed a receiver. The Third Circuit affirmed on all three fronts: (1) the borrower could not set aside the default/default judgment on its asserted grounds; (2) the court-appointed receiver had authority to modify an affiliate-friendly lease term (a 1,000-day cure period for a related-party tenant) despite an attornment clause, because it was a self-dealing term inserted after default; and (3) the district court did not abuse its discretion holding the borrower and its principal in civil contempt for failing to provide the accounting and records the receivership orders required.", "caseName": "ICON PSG 1 FL, LLC v. Jenkins Court Realty Co., L.P.", "citation": "No. 25-2598 (3d Cir. July 16, 2026)", "sourceUrl": "https://law.justia.com/cases/federal/appellate-courts/ca3/25-2598/25-2598-2026-07-16.html", "confidence": "high", "dollarAmount": 20500000, "jurisdiction": "Federal (3d Cir., applying PA law)"}, {"year": 2024, "notes": "A clean, recent example of a receivership motion being DENIED even with a contractual consent-to-receiver clause in hand -- a useful counterweight to this claim type's currently grant-heavy sample, and doctrinally distinct from the Adelaide Pointe pattern (there, the issue was factual disputes; here, the court exercised pure equitable discretion despite no apparent dispute about default).", "outcome": "In a commercial mortgage foreclosure action over property at 2310 Second Avenue in Manhattan, the plaintiff-lender moved for appointment of a receiver, relying on a consent-to-receivership clause in the mortgage. The court denied the motion, holding that under New York Real Property Law Sec. 254(10) a receiver-consent clause makes appointment proper without notice or regard to the sufficiency of the security, but does not make appointment automatic -- the court retains equitable discretion to deny it even where the parties contractually agreed to it. A referee was appointed instead to compute the amount due and assess whether the property could be sold in parcels.", "caseName": "Brick Air Capital LLC v. NLD Props., Inc.", "citation": "Index No. 850613/2023 (N.Y. Sup. Ct., N.Y. Cnty.), order dated October 11, 2024", "sourceUrl": "https://law.justia.com/cases/new-york/other-courts/2025/2025-ny-slip-op-33721-u.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 2026, "notes": "Smaller-balance loan than most of this claim type's sample (~$2.56M vs. the eight/nine-figure office towers dominating the file), showing the fact pattern -- payment default plus a life-safety/habitability angle -- also recurs at the smaller end of the multifamily market, not just trophy office assets.", "outcome": "Freddie Mac sued to appoint a receiver over Lakeview Apartments, a 96-unit Fort Valley, Georgia multifamily property, after the borrower made no monthly payment on its $2,564,000 loan since February 1, 2025. The lender invoked a consent-to-receiver clause in the security instrument (agreed in advance, requiring no separate notice) and cited a 2025 HUD inspection finding 'significant and life-threatening issues' at the property. As of this research, no ruling on the receivership motion had been reported.", "caseName": "Federal Home Loan Mortgage Corporation (Freddie Mac) v. VE Lakeview LP", "citation": "U.S. District Court, Middle District of Georgia, Macon Division, filed June 30, 2026", "sourceUrl": "https://www.mpamag.com/us/specialty/commercial/georgia-apartment-complex-faces-receivership-as-freddie-mac-alleges-default/581137", "confidence": "high", "dollarAmount": 2564000, "jurisdiction": "Federal (11th Cir., M.D. Ga.)"}, {"year": 2025, "notes": "By far the largest-dollar receivership in this claim type's sample and a useful data point on multi-state, multi-property portfolio receiverships (as opposed to single-asset receiverships, which make up the rest of the sample) -- occupancy decline from ~89% to ~75% over the loan's life is a similar distress signature to the office-sector fact pattern already noted for this claim type.", "outcome": "The lender sued to foreclose on a CMBS-securitized loan portfolio of 143 suburban office/flex properties across Arizona, Florida, Minnesota, and Pennsylvania, with an unpaid principal balance of roughly $1.23 billion (down from a $1.63 billion issuance value per Morningstar Credit) against a portfolio that had fallen from about 89% occupancy at origination to roughly 75%. Trigild was appointed receiver over the entire portfolio pending resolution of the foreclosure.", "caseName": "Wells Fargo Bank, N.A. (as Trustee, by and through KeyBank National Association as Special Servicer and Attorney-in-Fact) v. Workspace Property Trust (portfolio entities)", "citation": "Maricopa County Superior Court, Arizona, filed September 2025", "sourceUrl": "https://www.bisnow.com/news/national/capital-markets/wells-fargo-moves-to-foreclose-workspace-property-trust-portfolio", "confidence": "high", "dollarAmount": 1230000000, "jurisdiction": "AZ"}, {"year": 2026, "notes": "This is the final resolution of the SAME case already referenced in this claim type's existing note ('the lone initial denial, Independent Bank v. Adelaide Pointe, was later granted on renewed motion once factual disputes were developed') -- included here as a full citation because the existing file only mentioned it in a narrative note, without a citation entry giving the actual holding, dollar amount, and doctrinal basis (Assignment of Rents Act satisfied by a receiver-on-default clause in the mortgage, even without a matching clause in the rent assignment).", "outcome": "On the bank's renewed motion following development of the factual record, the Business Court held Independent Bank entitled to appointment of a receiver over the mixed-use marina/boat-services development under Michigan's Assignment of Rents Act, on more than $28 million in construction loans in default. The court held that where the assignor is in default and the underlying mortgage authorizes a receiver upon default, the statutory requirement is satisfied even absent a separate receiver clause in the rent assignment itself, and proceeded to select a receiver after considering the parties' competing nominees.", "caseName": "Independent Bank v. Adelaide Pointe Boaters Services, LLC, et al.", "citation": "Kent County (Mich.) Circuit Court, Business Court, Case No. 17-2025-20760-CBB, opinion dated January 9, 2026", "sourceUrl": "https://www.courts.michigan.gov/48dd9f/siteassets/business-court-opinions/c17-2025-20760-cbb(january9,2026).pdf", "confidence": "high", "dollarAmount": 28000000, "jurisdiction": "MI"}, {"year": 2026, "notes": "Confidence marked low because the source article did not name the specific hotel, borrower, lender, or case/docket number -- the loan amount, jurisdiction, and outcome (receiver appointed) are reported, but this citation cannot be independently verified against a primary court record the way the others in this set can. Included only as a directional data point that receivership activity in the current distress cycle extends to hospitality assets, not just office and multifamily.", "outcome": "A Missouri state judge appointed a receiver over a downtown St. Louis hotel following a $35 million loan default, with the receiver expected to keep the hotel operating while filing an operating plan and periodic reports with the court.", "caseName": "In re receivership of a downtown St. Louis hotel (lender v. hotel ownership entity)", "citation": "Missouri state court (St. Louis City Circuit Court), receiver appointed April 30, 2026", "sourceUrl": "https://hoodline.com/2026/05/downtown-st-louis-hotel-drama-as-judge-hands-control-to-receiver/", "confidence": "low", "dollarAmount": 35000000, "jurisdiction": "MO"}], "merger_objection_suit": [{"year": 2013, "outcome": "The court dismissed the case with prejudice on October 22, 2013. Plaintiffs appealed; the appeal was itself dismissed on July 31, 2014, but as part of that resolution the defendants agreed to reimburse plaintiffs' counsel in the consolidated Cole Holdings Action $100,000.", "caseName": "Cole Credit Property Trust III, Inc. Shareholder Litigation", "citation": "Circuit Court for Baltimore City, Maryland (consolidated, filed March 2013)", "sourceUrl": "http://chimicles.com/cole-credit-property-trust-iii-inc-class-and-derivative-litigation/", "confidence": "medium", "dollarAmount": 100000}, {"year": 2018, "outcome": "The merger closed; the parallel disclosure suits followed the common 'disclosure-only' resolution pattern for merger-objection suits \u2014 the companies filed supplemental proxy disclosures addressing the alleged omissions (visible in the SEC Form S-4/A amendments filed shortly before the shareholder vote), after which the suits were mooted/withdrawn. No separate cash settlement fund to shareholders was disclosed.", "caseName": "In re Government Properties Income Trust / Select Income REIT Merger Litigation (Chen v. Select Income REIT; Schwartz v. Select Income REIT; Sinkula v. Select Income REIT; Scarantino v. Fraiche)", "citation": "Four parallel actions: S.D.N.Y. (filed Nov. 9 & 19, 2018), D. Mass. (filed Nov. 15, 2018), and Circuit Court for Baltimore City, MD (filed Nov. 16, 2018)", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/1456772/000104746918007257/a2237140zex-99_1.htm", "confidence": "medium", "dollarAmount": null}, {"year": 2024, "outcome": "RTL shareholders sued AR Global and CEO Michael Weil for aiding and abetting alleged breaches of fiduciary duty and unjust enrichment arising from the merger of Necessity Retail REIT and Global Net Lease -- alleging conflicts of interest in the merger process, an inadequate price, and inadequate disclosure of material information, and that defendants received $375 million (18% of the combined entity's value) through the internalization transaction bundled into the merger. Judge Audrey Carrion (Circuit Court for Baltimore City) dismissed the fiduciary-duty claim under Maryland's business-judgment-rule presumption, which in turn defeated the derivative aiding-and-abetting and unjust-enrichment claims. A confirmed, real DISMISSAL outcome (not merely mooted by supplemental disclosures) despite a large alleged self-dealing figure -- illustrates how much the business judgment rule can insulate a merger even against a substantial, specifically-quantified conflict-of-interest allegation. A separate, narrower breach-of-fiduciary-duty action against the same defendants over related RTL governance conduct (Meyer v. Weil) settled for $3.25M -- see the breach_fiduciary_duty_derivative citation for that companion case.", "caseName": "The Necessity Retail REIT, Inc. Shareholder Litigation v. AR Global Investments, LLC and Michael Weil (Global Net Lease Merger)", "citation": "Circuit Court for Baltimore City, Maryland, filed August 2023, dismissed July 2024", "sourceUrl": "https://www.paulweiss.com/practices/litigation/securities-litigation/news/ar-global-wins-dismissal-of-class-action-over-reit-merger?id=53363", "confidence": "high", "dollarAmount": null}, {"year": 2010, "notes": "A structurally different settlement currency than the cash settlements elsewhere in this claim type -- relief here was a share givebook (9 of 37.5 million shares returned to the company, diluting the internalization sellers rather than paying cash to class members directly). Useful for showing that merger-objection relief in an internalization-style REIT transaction can take the form of unwinding part of the equity consideration itself, not just a cash fund. dollarAmount left null since no cash settlement figure was reported; the real relief was the share transfer.", "outcome": "Shareholders sued alleging federal securities-law violations and breach of fiduciary duty in connection with the REIT's internalization transaction -- its merger with its own external business manager/advisor and property managers -- claiming the deal terms improperly enriched the manager's owners at shareholders' expense. The case settled: the sellers who had received 37.5 million shares of company stock in the all-stock internalization deal agreed to give back 9 million of those shares to the company, diluting their own stake to partially compensate remaining shareholders, plus $10,000 in court-awarded plaintiffs'-counsel fees.", "caseName": "In re Inland Western Retail Real Estate Trust, Inc. Shareholder Litigation", "citation": "Class action and derivative complaint; settlement approved Nov. 8, 2010", "sourceUrl": "https://www.chicagobusiness.com/article/20100723/CRED03/200038980/inland-western-settles-shareholder-lawsuit", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal"}, {"year": 2022, "outcome": "In connection with CyrusOne's approximately $15 billion take-private acquisition by KKR and Global Infrastructure Partners ($90.50/share cash), seven purported stockholders filed suit and additional stockholders sent demand letters alleging the proxy statement omitted material information in violation of Section 14(a)/Rule 14a-9. CyrusOne stated it believed the claims were without merit but voluntarily supplemented the proxy statement via an 8-K filing in January 2022 'to avoid the risk that the [Stockholder] Litigation may delay or otherwise adversely affect the consummation of the Merger and to minimize the costs, risks and uncertainties inherent in litigation,' expressly denying that any additional disclosure was legally required. Stockholders approved the merger; no separate cash settlement fund to shareholders was disclosed.", "caseName": "In re CyrusOne Inc. Stockholder Litigation", "citation": "Seven complaints filed in S.D.N.Y., D.N.J., and E.D. Pa. following the Nov. 15, 2021 merger announcement", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/1553023/000110465922010326/tm225019d1_8k.htm", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal (S.D.N.Y., D.N.J., E.D. Pa.)"}, {"year": 2021, "outcome": "In connection with QTS Realty Trust's approximately $10 billion take-private acquisition by Blackstone Infrastructure Partners and BREIT, two purported stockholders sued alleging the preliminary proxy statement omitted material information in violation of Section 14(a)/Rule 14a-9 and asserting Section 20(a) control-person claims against the board, seeking to enjoin the merger. QTS stated the suits were without merit and intended to defend vigorously; the merger closed on schedule in 2021, and the suits followed the standard disclosure-supplement/mootness resolution pattern with no disclosed per-share cash recovery.", "caseName": "QTS Realty Trust, Inc. Stockholder Litigation (Stein v. QTS Realty Trust, Inc.; Waterman v. QTS Realty Trust, Inc.)", "citation": "Two actions filed July 9 and July 15, 2021, S.D.N.Y.", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/1577368/000110465921107329/tm2125390d2_8k.htm", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (S.D.N.Y.)"}, {"year": 2023, "outcome": "In connection with the roughly $15 billion all-stock merger of Life Storage into Extra Space Storage, five purported Life Storage stockholders filed substantially similar suits alleging the joint proxy statement/prospectus omitted or misstated material information (including inputs to the financial advisor's fairness analyses), seeking to enjoin the merger absent corrective disclosure. Life Storage and Extra Space filed supplemental disclosures (including additional detail on 'Life Storage Financial Analyses') via an 8-K; both companies' stockholders approved the merger at special meetings on July 18, 2023, and the transaction closed July 20, 2023. No separate cash settlement to Life Storage shareholders was disclosed; Life Storage stockholders were not entitled to appraisal rights in the transaction.", "caseName": "Life Storage, Inc. Stockholder Litigation", "citation": "Five complaints filed in S.D.N.Y. following the Apr. 3, 2023 merger announcement", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/944314/000119312523185331/d513688d8k.htm", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal (S.D.N.Y.)"}, {"year": 2024, "outcome": "In connection with Realty Income's approximately $9.3 billion all-stock acquisition of Spirit Realty Capital, purported stockholders sent demand letters and at least one stockholder filed suit alleging the joint proxy statement/prospectus was materially incomplete in violation of the Exchange Act's disclosure requirements. Although Spirit and Realty Income maintained the existing disclosures fully complied with the law, the companies voluntarily supplemented the proxy statement/prospectus 'to moot plaintiffs' disclosure claims and to avoid nuisance, potential expense and delay.' The merger closed in January 2024; no separate cash settlement to Spirit shareholders was disclosed.", "caseName": "Spirit Realty Capital, Inc. Stockholder Litigation", "citation": "Demand letters beginning Dec. 19, 2023; at least one suit filed in federal court in Michigan following the Oct. 29, 2023 merger announcement", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/1308606/000119312524006684/d706160d8k.htm", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (E.D. Mich. and other venues)"}, {"year": 2022, "outcome": "Following announcement of Blackstone Real Estate Income Trust's (BREIT) approximately $5.8 billion all-cash acquisition of Preferred Apartment Communities ($25.00/share), six purported stockholders filed substantially similar suits alleging the proxy statement omitted material information -- including non-GAAP reconciliations, levered free cash flow data, and inputs/assumptions behind Goldman Sachs' fairness analysis -- in violation of Section 14(a)/Rule 14a-9 and Section 20(a) of the Exchange Act. The suits sought to enjoin the merger and, if it closed anyway, rescission or rescissory damages. The company voluntarily supplemented the proxy statement with additional disclosures via a DEFA14A filed May 27, 2022 to moot the claims while expressly denying any disclosure violation. Stockholders approved the acquisition on June 17, 2022 and the deal closed; no separate cash settlement to shareholders was disclosed.", "caseName": "Preferred Apartment Communities, Inc. Stockholder Litigation (Blackstone/BREIT Acquisition)", "citation": "Six parallel actions: Whitfield v. Preferred Apartment Communities, Inc., No. 2:22-cv-01542-RBS (E.D. Pa.); Weinrib v. Bartkowski, No. 24-C-22-002041, and Milbourne v. Bartkowski, No. 24-C-22-002038 (Circuit Court for Baltimore City, MD); Grady v. Preferred Apartment Communities, No. 1:22-cv-02588-AMD-SJB (E.D.N.Y.); Taylor v. Preferred Apartment Communities, No. 1:22-cv-04044 (S.D.N.Y.); Watson v. Preferred Apartment Communities, No. 1:22-cv-04053 (S.D.N.Y.)", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/1481832/000148183222000093/mergerdefinitiveproxy-defa.htm", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal (E.D. Pa., E.D.N.Y., S.D.N.Y.) and MD (state)"}, {"year": 2021, "outcome": "In connection with the approximately $7.5 billion all-stock strategic merger of equals between Kite Realty Group Trust and Retail Properties of America (RPAI), six purported stockholders beginning August 27, 2021 filed suits alleging the joint proxy statement/registration statement omitted material information in violation of Section 14(a)/Rule 14a-9 and Section 20(a). Kite Realty voluntarily supplemented the disclosures 'to moot plaintiffs' disclosure claims, avoid nuisance and possible expense and business delays,' while stating the existing disclosures already complied fully with the law and denying any admission of legal merit or necessity. The merger closed in early 2022; no separate cash settlement to shareholders was disclosed.", "caseName": "Retail Properties of America, Inc. / Kite Realty Group Trust Stockholder Litigation", "citation": "Six parallel actions: Wang v. Retail Properties of America, Inc., No. 1:21-cv-07237 (S.D.N.Y.); Hopkins v. Retail Properties of America, Inc., No. 1:21-cv-07324 (S.D.N.Y.); Callebs v. Retail Properties of America, Inc., No. 1:21-cv-07593 (S.D.N.Y.); Sheridan v. Retail Properties of America, Inc., No. 1:21-cv-04066-SCJ (N.D. Ga.); Whitfield v. Retail Properties of America, Inc., No. 2:21-cv-04390 (E.D. Pa.); Gentry v. Kite Realty Group Trust, No. 1:21-cv-05142 (E.D.N.Y.)", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/1222840/000119312521295627/d221303d8k.htm", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal (S.D.N.Y., N.D. Ga., E.D. Pa., E.D.N.Y.)"}, {"year": 2022, "outcome": "In connection with the roughly $18 billion all-stock merger of equals between Healthcare Trust of America (HTA) and Healthcare Realty Trust, a purported HTA stockholder filed the Stein action in the Southern District of New York on May 6, 2022 alleging the preliminary proxy statement omitted or misstated material information in violation of Section 14(a)/Rule 14a-9 and Section 20(a), seeking injunctive relief, rescission or rescissory damages, and a corrected proxy. Three more purported stockholders filed substantially similar actions in the Eastern District of New York by June 10, 2022. HTA stated it believed the claims were without merit and that no supplemental disclosure was legally required, but voluntarily supplemented the definitive proxy statement to avoid the risk of delay and litigation cost. The merger closed July 20, 2022; no separate cash settlement to shareholders was disclosed.", "caseName": "Healthcare Trust of America, Inc. / Healthcare Realty Trust Merger Litigation", "citation": "Stein v. Healthcare Trust of America, Inc., No. 1:22-cv-03703 (S.D.N.Y., filed May 6, 2022); three additional purported-stockholder actions filed in the U.S. District Court for the Eastern District of New York by June 10, 2022", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/1360604/000136060422000048/htamootingdisclosures-fo.htm", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal (S.D.N.Y. and E.D.N.Y.)"}, {"year": 2022, "outcome": "In connection with Prologis's approximately $26 billion all-stock acquisition of Duke Realty, eight federal purported-stockholder actions against Prologis and/or Duke Realty alleged the joint Form S-4/proxy statement omitted or misstated material information (including background-of-the-merger narrative and financial-advisor analysis inputs) in violation of Section 14(a)/Rule 14a-9 and Section 20(a); a ninth action in California state court (Garfield v. Moghadam) separately alleged breach of fiduciary duty and securities fraud on overlapping facts. The companies made supplemental disclosures amending several sections of the registration statement to address the claims. Prologis and Duke Realty stockholders approved the merger at special meetings on September 28, 2022, and the transaction closed; no separate cash settlement to shareholders was disclosed.", "caseName": "Duke Realty Corporation / Prologis, Inc. Merger Litigation", "citation": "Nine parallel actions: Bushansky v. Prologis, Inc., No. 3:22-cv-04320 (N.D. Cal., filed July 26, 2022); Curtis v. Prologis, Inc., No. 1:22-cv-07833 (S.D.N.Y., filed Sept. 13, 2022); Stein v. Duke Realty Corp., No. 1:22-cv-06387 (S.D.N.Y., filed July 27, 2022); O'Dell v. Duke Realty Corp., No. 1:22-cv-06425 (S.D.N.Y., filed July 28, 2022); Whitfield v. Duke Realty Corp. (S.D.N.Y., filed Aug. 2, 2022 -- docket number as reported, 1:22-cv-0658, appears truncated in the source and could not be fully confirmed); McCollum v. Duke Realty Corp., No. 1:22-cv-06585 (S.D.N.Y., filed Aug. 3, 2022); Moore v. Duke Realty Corp., No. 1:22-cv-07837 (S.D.N.Y., filed Sept. 13, 2022); Riley v. Duke Realty Corp., No. 1:22-cv-07883 (S.D.N.Y., filed Sept. 14, 2022); and Garfield v. Moghadam, No. C22-01579 (Superior Court of California, Contra Costa County, filed Aug. 3, 2022)", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/783280/000110465922100893/tm2224957d6_425.htm", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal (N.D. Cal., S.D.N.Y.) and CA (state)"}, {"year": 2022, "notes": "Distinct fact pattern from the rest of this claim type's sample: not a disclosure-only Section 14(a) suit but a substantive merits challenge (breach of contract / breach of fiduciary duty) brought by preferred stockholders seeking to enjoin the underlying transaction outright, decided and rejected on the merits at the preliminary-injunction stage rather than mooted by supplemental disclosures. A real, adjudicated LOSS for the objecting stockholders that reinforces the low real-recovery probability from a different angle than the usual mootness-fee pattern.", "outcome": "Separately from the disclosure-only Section 14(a) suits filed by common stockholders over the same transaction (Stein, Wang, Whitfield, Waterman, and Thornburgh actions, filed April-May 2022 in E.D.N.Y. and E.D. Pa.), Cedar Realty Trust's PREFERRED stockholders brought substantive breach-of-contract and breach-of-fiduciary-duty claims, alleging the company's sale of its grocery-anchored shopping-center portfolio and related merger into Wheeler Real Estate Investment Trust would extinguish or impair their conversion and other contractual rights without fair consideration, and moved for a preliminary injunction to block the transaction. On June 22, 2022, the U.S. District Court for the District of Maryland denied both consolidated preliminary-injunction motions (Sydney and Kim), holding the plaintiffs were unlikely to succeed on the merits of any of their contractual or fiduciary-duty claims. The ruling allowed the asset sale and Wheeler merger to proceed without an injunction. No final judgment or settlement on the merits was located in this research pass.", "caseName": "Cedar Realty Trust, Inc. Preferred Stockholder Litigation (Sydney v. Cedar Realty Trust, Inc.; Kim v. Cedar Realty Trust, Inc.)", "citation": "Sydney v. Cedar Realty Trust, Inc., originally Case No. C-15-CV-22-00152 (Circuit Court for Montgomery County, MD, filed Apr. 8, 2022, amended May 6, 2022), removed May 11, 2022 to the U.S. District Court for the District of Maryland as No. 8:22-cv-01142-GLR; consolidated with Kim v. Cedar Realty Trust, Inc., No. 22-cv-01103 (D. Md., filed May 6, 2022); preliminary-injunction ruling issued June 22-23, 2022", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/761648/000119312522180323/d353464d8k.htm", "confidence": "high", "dollarAmount": null, "jurisdiction": "MD (Federal, D. Md.)"}], "securities_fraud_10b5": [{"year": 2020, "outcome": "Settled on the eve of trial. Judge Alvin K. Hellerstein granted final approval on January 21, 2020 to an aggregate $1.025 billion settlement fund, one of the largest securities class action recoveries ever against a REIT: VEREIT/ARCP itself contributed $738.5 million, the AR Capital/AR Global-affiliated manager entities and Schorsch-controlled parties contributed approximately $225-286.5 million (reported inconsistently across sources), former auditor Grant Thornton LLP paid $49 million, and former CFO Brian Block personally paid $12.5 million.", "caseName": "In re American Realty Capital Properties, Inc. Litigation (VEREIT/ARCP Securities Litigation)", "citation": "No. 1:15-mc-00040-AKH (S.D.N.Y.)", "sourceUrl": "https://www.cohenmilstein.com/case-study/re-american-realty-capital-properties-inc-litigation/", "confidence": "high", "dollarAmount": 1025000000}, {"year": 2009, "outcome": "The U.S. District Court for the Eastern District of Pennsylvania granted final approval on December 10, 2009 to a $32 million cash settlement, funded by RAIT's directors' and officers' liability insurers. The action was dismissed with prejudice and all defendants received a full release.", "caseName": "In re RAIT Financial Trust Securities Litigation", "citation": "Consolidated securities class action, E.D. Pa. (2009)", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/0001045425/000129993309004874/exhibit1.htm", "confidence": "high", "dollarAmount": 32000000}, {"year": 2008, "outcome": "W.P. Carey settled the SEC's securities fraud charges by agreeing to pay approximately $30 million total (roughly $20 million in disgorgement and prejudgment interest plus a $10 million civil penalty). Two senior executives separately settled individual charges (one barred from serving as an officer/director for five years and paying a $240,000 penalty; the accountant suspended from practicing before the SEC for two years and paying a $75,000 penalty).", "caseName": "SEC v. W. P. Carey & Co. LLC, et al.", "citation": "SEC Litigation Release No. 20501; SEC Admin. Proc. File No. 3-13294 (2008-2009)", "sourceUrl": "https://www.sec.gov/enforcement-litigation/litigation-releases/lr-20501", "confidence": "high", "dollarAmount": 30000000}, {"year": 2018, "outcome": "In July 2018, the entities and certain individuals consented to SEC judgments enjoining future securities-law violations and agreed to pay a combined $8.2 million in disgorgement, prejudgment interest, and civil penalties. Separately and later, four top UDF executives (including CEO Hollis Greenlaw) were criminally convicted in January 2022 on multiple counts including securities fraud and conspiracy.", "caseName": "SEC v. United Development Funding III, L.P., United Development Funding IV, et al.", "citation": "SEC settled civil action; consent judgment entered July 2018, N.D. Tex.", "sourceUrl": "https://www.sec.gov/divisions/enforce/claims/docs/united-development-funding-final-judgment-073118.pdf", "confidence": "high", "dollarAmount": 8200000}, {"year": 2023, "outcome": "Consolidated securities class action on behalf of purchasers of CBL & Associates (a mall/shopping-center REIT) common stock between July 29, 2014 and March 26, 2019, alleging the company and certain officers made materially false and misleading statements about the company's contingent liabilities, occupancy metrics, and overall business condition (CBL filed Chapter 11 in November 2020, emerging in November 2021). Judge J. Ronnie Greer held a final settlement approval hearing on August 21, 2023 and granted final approval to a $17.5 million cash settlement funded by CBL's D&O insurers.", "caseName": "In re CBL & Associates Properties, Inc. Securities Litigation", "citation": "No. 1:19-cv-00181-JRG-CHS (E.D. Tenn.)", "sourceUrl": "https://www.prnewswire.com/news-releases/abraham-fruchter--twersky-llp-and-pomerantz-llp-announce-proposed-settlement-of-class-action-involving-purchasers-of-cbl--associates-properties-inc-securities-301835051.html", "confidence": "high", "dollarAmount": 17500000, "jurisdiction": "Federal (E.D. Tenn.)"}, {"year": 2023, "outcome": "Class action on behalf of purchasers of Omega Healthcare Investors (a skilled-nursing/healthcare-facility REIT) common stock between February 8, 2017 and October 31, 2017, alleging the company and three named officers (CEO C. Taylor Pickett, CFO Robert O. Stephenson, COO Daniel J. Booth) made materially false and misleading statements about the deteriorating financial condition of a major operator-tenant (Orianna Health Systems), that operator's ability to make timely rent payments, and the resulting lease impairments and uncollectible receivables. The court entered judgment approving the settlement on April 25, 2023, effective May 25, 2023, for a $30.75 million cash payment to the class.", "caseName": "In re Omega Healthcare Investors, Inc. Securities Litigation", "citation": "No. 1:17-cv-08983 (S.D.N.Y.)", "sourceUrl": "https://law.justia.com/cases/federal/district-courts/new-york/nysdce/1:2017cv08983/484014/167/", "confidence": "high", "dollarAmount": 30750000, "jurisdiction": "Federal (S.D.N.Y.)"}, {"year": 2022, "notes": "A clean, confirmed dismissal-with-prejudice outcome for a non-traded-adjacent, publicly-traded mid-cap REIT securities fraud claim built on short-seller allegations -- useful as a real data point on the low end of the outcome distribution, balancing the large settlement figures already in this sample.", "outcome": "Securities class action against Farmland Partners (an agricultural-land REIT) and its CEO and CFO, alleging materially misleading statements that concealed an undisclosed related-party lending arrangement between the company and certain insider-affiliated tenants/borrowers -- allegations that substantially adopted a 2018 anonymous short-seller report published under the pseudonym 'Rota Fortunae.' The District of Colorado dismissed the consolidated complaint with prejudice; Farmland Partners announced the dismissal on April 7, 2022. In a related twist, the short-seller report's author (Quinton Mathews) later admitted in a separate defamation/business-tort action brought by Farmland Partners that his allegations were false and that he had been paid by a hedge fund that profited from shorting the stock. A parallel derivative complaint against the company's officers and directors over the same underlying conduct was voluntarily dismissed by the plaintiff without a settlement.", "caseName": "Farmland Partners Inc. Securities Litigation (Turner Insurance Agency, Inc. v. Farmland Partners Inc.)", "citation": "No. 1:18-cv-02351-NYW (D. Colo.)", "sourceUrl": "https://www.businesswire.com/news/home/20220407005368/en/Farmland-Partners-Defeats-Class-Action-Lawsuit-Stemming-From-2018-Short-and-Distort-Attack", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal (D. Colo.)"}, {"year": 2024, "notes": "A second confirmed dismissal (no recovery), and the most recent in time of the dismissals in this sample -- pairs with the Farmland Partners and Medical Properties Trust dismissals below to show that outright defense wins are common even against REITs that went on to file bankruptcy shortly after the alleged misstatements.", "outcome": "Securities class action against the mall-REIT and certain officers alleging false and misleading statements about the company's liquidity, leasing pipeline, and ability to avoid bankruptcy during 2020-2021, shortly before Washington Prime Group filed for Chapter 11 in June 2021 (the company was later liquidated and delisted; it did not survive as a going concern the way CBL did). The lead case was captioned Slipher v. Washington Prime Group Inc., filed May 24, 2021; a consolidated complaint was filed April 1, 2022. The court granted defendants' motion to dismiss the consolidated complaint on March 27, 2024, finding the pleadings failed to raise a strong inference of scienter.", "caseName": "In re Washington Prime Group, Inc. Securities Litigation (Slipher v. Washington Prime Group Inc.)", "citation": "Consolidated action, S.D. Ohio (order granting motion to dismiss entered Mar. 27, 2024)", "sourceUrl": "https://www.courtlistener.com/opinion/9917728/slipher-v-washington-prime-group-inc/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (S.D. Ohio)"}, {"year": 2025, "notes": "Docket numbers for the Sw\u00e4rd action are drawn from law-firm case-tracking pages rather than a directly-verified PACER printout, since the underlying court opinion page could not be retrieved during this research pass (access blocked) -- treat the exact S.D.N.Y. docket number with some caution even though the overall dismissal outcome is corroborated across multiple independent sources. A third confirmed dismissal in this sample (two parallel actions, same underlying facts, both losses for plaintiffs), against a REIT with one of the largest tenant-concentration exposures in the sector.", "outcome": "Class actions on behalf of purchasers of Medical Properties Trust (a large hospital-REIT) securities during a putative class period beginning mid-2019 through early 2023, alleging the company concealed the deteriorating finances of its largest tenant, Steward Health Care (which filed for bankruptcy in May 2024), including undisclosed loans and related-party financing arrangements allegedly used to prop up Steward's ability to pay rent. The Northern District of Alabama action (Pirani) was dismissed with prejudice for failing to satisfy the heightened, 'triple-layered' pleading standard applicable to private securities-fraud plaintiffs. The parallel Southern District of New York action (Sw\u00e4rd) was separately dismissed with prejudice, with the court most recently denying a post-dismissal motion on or about August 14, 2025. Companion shareholder-derivative suits arising from the same related-party-loan allegations remain pending in the Northern District of Alabama (filed October and December 2023) -- see the corresponding new citation under breach_fiduciary_duty_derivative.", "caseName": "In re Medical Properties Trust, Inc. Securities Litigation (Pirani v. Medical Properties Trust, Inc.; Sw\u00e4rd v. Medical Properties Trust, Inc.)", "citation": "Two parallel actions: Pirani, No. 2:23-cv-00486 (N.D. Ala.); Sw\u00e4rd, No. 1:23-cv-03070 (S.D.N.Y.)", "sourceUrl": "https://www.rgrdlaw.com/cases-medical-properties-trust-inc-class-action-lawsuit-mpw.html", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (N.D. Ala. and S.D.N.Y.)"}], "spot_zoning_challenge": [{"year": 2020, "outcome": "The zoning hearing board found, and the Court of Common Pleas and Commonwealth Court affirmed, that the rezoning constituted invalid spot zoning; the rezoning ordinances were struck down and the industrial development could not proceed under that zoning.", "caseName": "Allen Distribution v. West Pennsboro Township Zoning Hearing Board", "citation": "No. 524 C.D. 2019 (Pa. Commw. Ct. May 11, 2020)", "sourceUrl": "https://www.babstcalland.com/news-article/commonwealth-court-sees-spot-zoning-overturns-industrial-rezoning/", "confidence": "medium", "dollarAmount": null}, {"year": 1980, "outcome": "The Court of Appeals held, as a matter of law, that the rezoning constituted invalid spot zoning and invalidated the ordinance.", "caseName": "Lathan v. Union County Board of Commissioners", "citation": "47 N.C. App. 357, 267 S.E.2d 30 (1980)", "sourceUrl": "https://law.justia.com/cases/north-carolina/court-of-appeals/1980/7920sc1181-1.html", "confidence": "medium", "dollarAmount": null}, {"year": 2024, "outcome": "The Commonwealth Court struck down the rezoning ordinance as illegal spot zoning.", "caseName": "Chaffier v. Hellertown Borough Zoning Hearing Board", "citation": "No. 907 C.D. 2022 (Pa. Commw. Ct. Jan. 10, 2024) (unpublished memorandum opinion)", "sourceUrl": "https://www.law.com/thelegalintelligencer/2024/01/31/commonwealth-court-strikes-down-ordinance-due-to-illegal-spot-zoning/", "confidence": "medium", "dollarAmount": null}, {"year": 2023, "outcome": "UNSUCCESSFUL challenge -- balances the prior all-successful sample flagged as possibly outcome-selection-biased. Adjacent property owners challenged the Borough's rezoning of a parcel from residential to mixed-use (to permit a parking lot) as impermissible spot zoning, characterizing it as a 'peninsula' of commercial property surrounded by residential. The Commonwealth Court rejected that characterization, finding the parcel bordered residential zones on only two sides (not three) and was a 'natural extension' of existing adjacent mixed-use zoning that served the legitimate purpose of creating a buffer between commercial and residential uses. The rezoning was upheld.", "caseName": "Burd v. Borough of Brentwood Zoning Hearing Board", "citation": "1049 C.D. 2021 (Pa. Commw. Ct. Apr. 18, 2023)", "sourceUrl": "https://lawoftheland.wordpress.com/2023/11/15/pa-commonwealth-court-upholds-mixed-use-rezoning-ordinance-in-rejection-of-spot-zoning-argument/", "confidence": "high", "dollarAmount": null}, {"year": 2020, "notes": "A clean textbook spot-zoning annulment with two independently sufficient grounds (single-beneficiary drafting history plus no genuine comprehensive-plan consistency), pairing well with the PA Commonwealth Court citation above where a similar-looking targeted rezoning was upheld because it WAS shown consistent with an actual comprehensive plan -- the comprehensive-plan-consistency question is the real hinge in most of these cases, more than the rezoning's narrowness alone.", "outcome": "The town rezoned a parcel specifically to permit 'campgrounds' in its Business-Recreational district, drafted after the town attorney suggested it as a 'solution' to the existing campground owner's site-plan application, which otherwise violated the pre-amendment zoning code. The court annulled the rezoning as illegal spot zoning, holding it was enacted to benefit one specific landowner and was inconsistent with any comprehensive plan -- the town board had mistakenly believed a comprehensive plan existed when none had ever been formally adopted. The court also invalidated the accompanying environmental (SEQRA) review for failing to assess impacts on parcels other than the campground owner's own.", "caseName": "Lewis Point Neighborhood Association, Inc. v. Town of Lenox", "citation": "Index No. EF2019-2130 (N.Y. Sup. Ct., Madison Cnty., July 17, 2020)", "sourceUrl": "https://nyenvlaw.com/blog/state-supreme-court-annuls-towns-spot-zoning/", "confidence": "high", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 2001, "outcome": "Residents challenged the Village's zoning ordinance amendment permitting construction of a cellular telecommunications monopole on municipal property as illegal spot zoning and contract zoning. The Appellate Court upheld the amendment, holding it was not arbitrary or unreasonable because the plaintiffs failed to show any illegal motive by the Village or that the amendment was inconsistent with a comprehensive plan for the property. Municipality win -- the rezoning was upheld.", "caseName": "Thornber v. Village of North Barrington", "citation": "321 Ill. App. 3d 318, 747 N.E.2d 496 (2d Dist. 2001)", "sourceUrl": "https://caselaw.findlaw.com/il-court-of-appeals/1124140.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "IL"}, {"year": 2017, "notes": "Outcome and acreage as summarized by the UNC School of Government's compiled legal summary of North Carolina spot-zoning case law, not independently verified against the full opinion text.", "outcome": "The North Carolina Court of Appeals invalidated a roughly 29.95-acre rezoning to heavy industrial use as illegal spot zoning. Challenge win -- the rezoning was struck down.", "caseName": "McDowell v. Randolph County", "citation": "256 N.C. App. 708, 808 S.E.2d 513 (2017)", "sourceUrl": "https://www.sog.unc.edu/resources/legal-summaries/spot-zoning", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NC"}, {"year": 2009, "notes": "Outcome as summarized by the UNC School of Government's compiled legal summary; not independently verified against the full opinion text.", "outcome": "The Court of Appeals held the challenged rezoning was not spot zoning at all, in part because the rezoned area was not limited to a single owner's small parcel. Municipality win -- the rezoning was upheld.", "caseName": "Musi v. Town of Shallotte", "citation": "200 N.C. App. 379, 684 S.E.2d 892 (2009)", "sourceUrl": "https://www.sog.unc.edu/resources/legal-summaries/spot-zoning", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NC"}, {"year": 2015, "notes": "Outcome as summarized by the UNC School of Government's compiled legal summary; not independently verified against the full opinion text.", "outcome": "The Court of Appeals held the challenged rezoning did not constitute spot zoning because the affected parcels were in joint or related ownership rather than the kind of single-beneficiary carve-out the doctrine targets. Municipality win -- the rezoning was upheld.", "caseName": "Good Neighbors of Oregon Hill v. County of Rockingham", "citation": "242 N.C. App. 280, 774 S.E.2d 902 (2015)", "sourceUrl": "https://www.sog.unc.edu/resources/legal-summaries/spot-zoning", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NC"}, {"year": 2014, "notes": "Outcome as summarized by the UNC School of Government's compiled legal summary; not independently verified against the full opinion text.", "outcome": "The Court of Appeals invalidated a rezoning enacted to permit a recycling center as illegal spot zoning. Challenge win -- the rezoning was struck down; industrial/waste-facility fact pattern relevant to commercial/industrial development disputes specifically.", "caseName": "Etheridge v. County of Currituck", "citation": "235 N.C. App. 469, 762 S.E.2d 289 (2014)", "sourceUrl": "https://www.sog.unc.edu/resources/legal-summaries/spot-zoning", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NC"}, {"year": 2007, "notes": "Outcome as summarized by the UNC School of Government's compiled legal summary; not independently verified against the full opinion text.", "outcome": "The Court of Appeals upheld a rezoning between similar residential zoning districts, finding it did not amount to illegal spot zoning. Municipality win -- the rezoning was upheld.", "caseName": "Childress v. Yadkin County", "citation": "186 N.C. App. 30, 650 S.E.2d 55 (2007)", "sourceUrl": "https://www.sog.unc.edu/resources/legal-summaries/spot-zoning", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NC"}], "lender_liability_claim": [{"year": 2026, "outcome": "New York's highest court held that the lender's contractual 'sole discretion' to assign the loan does not categorically exculpate it from implied-covenant-of-good-faith claims where the discretion is alleged to have been exercised as part of a scheme to strip a joint-venture partner's equity, reinstating the good-faith claim and remitting the case to the Supreme Court, New York County for further proceedings (while affirming dismissal of a related tortious-interference claim).", "caseName": "111 West 57th Investment LLC v. 111 W57 Mezz Investor LLC (Steinway Tower)", "citation": "New York Court of Appeals, 2026 NY Slip Op 03376, decided May 28, 2026", "sourceUrl": "https://www.nycourts.gov/reporter/current/3dseries/2026/2026_03376.shtml", "confidence": "high", "dollarAmount": null}, {"year": 2026, "outcome": "Justice Andrew Borrok signed a temporary restraining order blocking the UCC Article 9 equity sale and set a hearing on preliminary relief for October 1, 2026. The case remains pending with no ruling on the merits of the $500M+ lender-liability claim.", "caseName": "Via Mizner Owner III LLC v. Via Mizner Lender 1 LLC (Mandarin Oriental Residences, Boca Raton)", "citation": "Supreme Court of the State of New York, New York County, Commercial Division, filed August 17, 2026", "sourceUrl": "https://therealdeal.com/miami/2026/08/17/mandarin-oriental-boca-raton-developer-sues-lender-madison/", "confidence": "high", "dollarAmount": null}, {"year": 1985, "outcome": "Jury found Irving Trust breached an implied duty of good faith by cutting off funding without notice, and awarded $7.5M in damages plus pre-judgment interest; the Sixth Circuit affirmed, holding the lender owed a duty to give notice before exercising discretion to stop funding.", "caseName": "K.M.C. Co., Inc. v. Irving Trust Co.", "citation": "757 F.2d 752 (6th Cir. 1985)", "sourceUrl": "https://law.justia.com/cases/federal/appellate-courts/F2/757/752/426206/", "confidence": "medium", "dollarAmount": 7500000}, {"year": 1986, "outcome": "After a three-month trial, the jury found the bank liable for improperly controlling the construction project and awarded $6.6M in punitive damages (with compensatory damages determined separately); the Court of Appeal later reversed on an unrelated jury-instruction issue regarding constructive fraud and remanded.", "caseName": "Barrett v. Bank of America", "citation": "183 Cal. App. 3d 1362, 229 Cal. Rptr. 16 (Ct. App. 1986)", "sourceUrl": "https://law.justia.com/cases/california/court-of-appeal/3d/183/1362.html", "confidence": "medium", "dollarAmount": 6600000}, {"year": 2026, "notes": "A current, real example of a CMBS-specific lender-liability theory -- a certificateholder suing the special servicer itself for mishandling defaulted loans, rather than a borrower suing an originating lender. Settled confidentially before any ruling on the motion to dismiss, so no dollar figure or judicial holding on the merits is available; included primarily to document that this claim theory is being actively brought and resolved in the current CMBS distress cycle, consistent with market commentary describing distressed-debt/special-servicer disputes as a currently very active litigation area.", "outcome": "As directing certificateholder of the FREMF 2016-KS06 CMBS pool, ROC sued the special servicer CWCAM for breach of the pooling and servicing agreement and violation of the contractual servicing standard, alleging negligent handling of nine loans that entered special servicing starting in 2022, and sought a declaratory judgment that CWCAM was not entitled to indemnification or expense reimbursement from the trust. CWCAM moved to dismiss (fully briefed, hearing held Aug. 25, 2025); while that motion was pending, the parties reached a confidential business resolution and stipulated to dismissal with prejudice on Jan. 22, 2026.", "caseName": "ROC Debt Strategies II Bond Investments LLC v. CWCapital Asset Management LLC", "citation": "Supreme Court of the State of New York, filed Jan. 13, 2025", "sourceUrl": "https://www.businesswire.com/news/home/20250723952228/en", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 2023, "notes": "Not a borrower-vs-originating-lender dispute like most of this claim type's sample -- Claymore was itself a sophisticated institutional CRE lender/investor suing an arranging bank for fraud in how a loan was marketed/appraised, a distinct but real lender-liability-adjacent theory relevant to syndicated/participated CRE debt. The arc from a combined $274M in trial awards down to zero is a vivid, well-documented illustration of appellate erosion risk even after a plaintiff wins outright at trial on a lender-misconduct theory -- directly relevant to calibrating the damages formula's realistic expected value, not just the probability of an initial finding of liability.", "outcome": "Claymore (an affiliate of Highland Capital Management) alleged Credit Suisse, which arranged a $250 million tranche of $540 million in loans refinancing a Henderson, Nevada residential development, fraudulently inflated the underlying appraisal to induce Claymore's participation. A jury awarded $40 million in fraud damages and a separate bench trial added $211 million in equitable rescissory damages plus a further ~$23 million for Claymore's secondary-market purchases. The Texas Supreme Court affirmed the $40 million fraud verdict in 2020 but reversed the $211 million rescissory award as duplicative of an adequate legal remedy. On remand, the Dallas Court of Appeals in 2023 went further, vacating the $23 million secondary-market award entirely and reducing the $40 million fraud verdict itself to a take-nothing judgment after crediting Credit Suisse for settlements Claymore had already reached with other co-liable tortfeasors -- leaving Claymore with a net recovery of zero after roughly a decade of litigation.", "caseName": "Credit Suisse AG, Cayman Islands Branch v. Claymore Holdings, LLC", "citation": "No. 18-0403 (Tex. Apr. 24, 2020); on remand, No. 05-21-00649-CV (Tex. App.-Dallas Feb. 14, 2023)", "sourceUrl": "https://www.jdsupra.com/legalnews/the-texas-court-of-appeals-reverses-2007126/", "confidence": "high", "dollarAmount": 0, "jurisdiction": "TX"}, {"year": 2026, "notes": "Directly comparable to the 111 West 57th/Steinway Tower citation already in the file (same theory -- a lender's contractual discretion in a mezzanine-loan enforcement context challenged as bad-faith/commercially unreasonable) but with the OPPOSITE outcome: here the borrower-side challenge was rejected outright at the injunction stage rather than reinstated on appeal, underscoring how fact-specific and procedurally contingent (preliminary injunction vs. post-dismissal appeal) these outcomes are.", "outcome": "SL Green (indirect owner of the mezzanine borrower at Worldwide Plaza) sought a preliminary injunction to block a UCC Article 9 sale of the pledged equity interests after a mezzanine loan default, arguing the sale terms (including 'Qualified Bidder' requirements) were commercially unreasonable and that the lender's conduct violated the implied covenant of good faith. Justice Andrea Masley denied the preliminary injunction, holding the proposed sale terms were commercially reasonable under UCC Sec. 9-610(b) and rejecting the borrower-side challenge, allowing the sale to proceed as scheduled.", "caseName": "WWP Mezz LLC v. WWP Mezz Investment Company LLC (Worldwide Plaza)", "citation": "Supreme Court of the State of New York, New York County, Commercial Division, decision dated January 27, 2026", "sourceUrl": "https://www.whiteandwilliams.com/resources-alerts-Court-Denies-Injunction-in-Battle-of-Titans-of-New-York-Real-Estate-and-Allows-UCC-Sale-of-Pledged-Equity-Interests-to-Proceed", "confidence": "high", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 2024, "notes": "One of a documented wave of CMBS-borrower counterclaims against special servicers (Rialto in particular) emerging from the 2023-2025 office distress cycle -- useful alongside the already-cited ROC Debt Strategies case to show this fact pattern (special-servicer-as-defendant rather than originating-lender-as-defendant) recurring across multiple, unrelated properties and courts.", "outcome": "After the underlying $164 million loan (with accrued interest and fees exceeding $195 million) on Chicago's Civic Opera House building went into pandemic-era default, borrower 601W alleged it proactively sought a workout, but special servicer Rialto Capital negotiated in bad faith and made repeated unreasonable refusals of proposed solutions, filing a counterclaim describing Rialto's special-servicing conduct as 'predatory.' As of this research, no ruling on the counterclaim's merits had been reported.", "caseName": "601W Companies (Civic Opera House / 20 N. Wacker Drive) v. Rialto Capital Advisors", "citation": "Counterclaim filed in CMBS special-servicer foreclosure action, Circuit Court of Cook County, Illinois, filed May 31, 2024", "sourceUrl": "https://therealdeal.com/chicago/2024/06/04/601w-countersues-servicer-rialto-in-195m-foreclosure/", "confidence": "high", "dollarAmount": null, "jurisdiction": "IL"}, {"year": 2025, "notes": "A fast-settled, dismissed-with-prejudice outcome from the same current wave of CMBS-servicer lender-liability suits as the 601W/Rialto and ROC Debt Strategies citations -- illustrates that these theories, even when filed as headline-grabbing class actions with aggressive 'predatory'/'deception' framing, often resolve quickly and confidentially rather than through adjudicated wins. Confidence marked medium because the settlement's terms (and thus whether Midtown recovered anything of value) were not disclosed.", "outcome": "Midtown Equities filed a putative class action alleging Rialto (as special servicer on a $45 million Signature Bank-originated loan) and Blackstone engaged in a 'campaign of deception' to manufacture a default and coerce the borrower into paying default interest and fees rather than granting a routine loan extension. Ten days after filing, the parties reached a settlement, and the lawsuit was dismissed with prejudice in March 2025.", "caseName": "Midtown Equities (Joseph Cayre) v. Rialto Capital Advisors / Blackstone (205 Montague Street, Brooklyn Heights)", "citation": "Supreme Court of the State of New York, New York County, filed February 25, 2025; dismissed with prejudice March 2025", "sourceUrl": "https://therealdeal.com/new-york/2025/03/07/rialto-midtown-equities-settle-signature-loan-lawsuit/", "confidence": "medium", "dollarAmount": 0, "jurisdiction": "NY"}, {"year": 2026, "notes": "dollarAmount is set to 0 because it reflects the BORROWER/guarantor's recovery on the lender-liability-style counterclaims (usury and fraud) at issue for this claim type -- those counterclaims were rejected in full. The plaintiff/investor separately won an affirmative judgment of roughly $7.3 million enforcing its own guaranty claims, which is a different claim type (guaranty_enforcement) already modeled elsewhere in this spec. A clean, fully-litigated, very recent (Feb. 2026) example of a usury/bad-faith-style borrower theory failing outright once a transaction is found to be equity rather than debt.", "outcome": "Plaintiffs GC Broadway, LLC and Bryan Gortikov made a nearly $8 million preferred-equity investment in January 2023 to rescue a distressed commercial redevelopment project at 1925 Broadway in Santa Monica, California, securing a mandatory redemption obligation by September 2024 and personal payment/recourse guaranties from defendant Alex Nerush. After the venture defaulted on the redemption and plaintiffs discovered Nerush had secretly leased the property (which was supposed to remain vacant pending redevelopment) to a medi-spa and kept the rent for himself, plaintiffs sued to enforce the guaranties. Nerush and his entity counterclaimed, in lender-liability-style fashion, that the 'investment' was actually a disguised usurious loan in violation of California's usury statute and the California Constitution, and separately alleged breach of contract/fraud over an undisclosed $21,000 referral fee paid to a broker, seeking rescission of the entire transaction. Following a multi-day post-trial proceeding, the Delaware Court of Chancery rejected every counterclaim -- holding the transaction was bona fide preferred equity rather than debt (so no usury violation could occur as a matter of law) and that the fraud/breach-of-contract claims over the referral fee were factually unsupported -- and entered judgment for the plaintiffs of over $7 million in principal damages for breach of the payment guaranty plus $300,000 in restitutionary damages for Nerush's own fraud, plus pre- and post-judgment interest and attorneys' fees.", "caseName": "GC Broadway, LLC v. AN SM 1925 Broadway Holdings, LLC (and Alex Nerush)", "citation": "Delaware Court of Chancery, C.A. No. 2024-1070-LWW, Memorandum Opinion (Vice Chancellor Will), submitted Dec. 5, 2025, decided Feb. 26, 2026", "sourceUrl": "https://courts.delaware.gov/Opinions/Download.aspx?id=392070", "confidence": "high", "dollarAmount": 0, "jurisdiction": "DE"}, {"year": 2025, "notes": "Court name and docket number could not be independently confirmed in this research pass; multiple independent trade-press sources (Bloomberg, Dec. 24, 2025; The Real Deal, Dec. 23, 2025 and Jan. 28, 2026) corroborate the substance and the private-settlement/dismissal outcome. This is a variant of the certificateholder-vs-special-servicer theory already represented by the ROC Debt Strategies citation in this sample, but here the alleged misconduct is deliberately PROLONGING a default to keep collecting fees, rather than mishandling a workout -- both settled short of any ruling on the merits, reinforcing the pattern that CMBS-servicer lender-liability disputes rarely reach adjudication.", "outcome": "400 Capital Management, an investment firm holding certificates in a CMBS trust, sued special servicer Rialto Capital Advisors, alleging Rialto engineered a scheme to keep a $130 million CMBS loan secured by a Herald Square (Manhattan) hotel/retail property in default status. Specifically, the suit alleged Rialto proposed structuring a two-year (with a possible third-year option) loan extension as a 'forbearance agreement' rather than a loan modification, specifically so the loan would remain in special servicing -- allowing Rialto to continue collecting elevated special-servicing fees and nearly $10 million in default interest that a straightforward modification would have eliminated, to the detriment of other certificateholders. The parties reached a confidential private settlement, and a judge granted approval to dismiss the case in March 2026.", "caseName": "400 Capital Management LP v. Rialto Capital Advisors LLC", "citation": "Lawsuit reported filed on or about Dec. 23, 2025; court and docket number could not be independently confirmed in this research pass (primary reporting is behind a Bloomberg paywall)", "sourceUrl": "https://www.trustedmortgagecapital.com/400-capital-sues-over-alleged-fee-grab-tactic-in-cmbsloan/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 2019, "notes": "Included primarily for a well-documented substantive theory not otherwise represented in this sample: a HUD MAP-program lender allegedly padding quoted interest rates to inflate its own compensation. The 2019 Eleventh Circuit opinion resolved only an appellate-jurisdiction question (procedurally in the borrowers' favor, since it kept them in their preferred Georgia forum), not the merits, and the follow-on 2023 Georgia Court of Appeals opinion's content/outcome could not be retrieved -- flag for follow-up research before relying on this case for the final-outcome side of probability calibration.", "outcome": "Four Georgia apartment developers (Overlook Gardens Properties, Creekwood Apartments, Iverness II, and Greystone Farms Apartment Community) sued their HUD-insured Multifamily Accelerated Processing (MAP) program lender, Red Mortgage Capital, and related Red Capital/ORIX USA entities, alleging breach of contract, fraud, and violation of Georgia's RICO statute. The developers claimed the lender intentionally and deceptively quoted them interest rates on their HUD-insured loans that were not actually the best market rates available, in order to secretly inflate its own fees and profits at closing. The lender removed the case to federal court and moved to enforce a forum-selection clause requiring the dispute be litigated in Dallas County, Texas; the district court instead found a conflicting, controlling forum-selection clause in the actual loan notes/security instruments required Georgia venue, and remanded the case to Georgia state court. The Eleventh Circuit held that 28 U.S.C. Sec. 1447(d) precluded it from reviewing that remand order and dismissed the lender's appeal for lack of appellate jurisdiction, sending the underlying fraud/RICO claims back to Georgia state court to proceed. This research pass could not independently confirm any final ruling on the merits, settlement, or damages figure for the underlying fraud/RICO claims, including in the subsequent 2023 Georgia Court of Appeals decision in the same case series.", "caseName": "Overlook Gardens Properties, LLC, et al. v. ORIX USA, L.P., et al.", "citation": "No. 17-14967 (11th Cir. June 25, 2019) (jurisdictional appeal from remand order); underlying district court No. 4:17-cv-00101-CDL (M.D. Ga.); a further Georgia Court of Appeals decision followed at No. A22A1590 (decided Feb. 21, 2023), whose substantive content could not be retrieved in this research pass", "sourceUrl": "http://media.ca11.uscourts.gov/opinions/pub/files/201714967.pdf", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (11th Cir.)"}, {"year": 2013, "notes": "A genuine, appellately-affirmed BORROWER WIN on a lender-liability-adjacent theory -- a lender's wrongful/improvident declaration of default defeating the lender's own foreclosure action -- and a real counter-example to this claim type's usual pattern of borrower losses, though it arose as a defense to the lender's foreclosure suit rather than as an affirmative borrower-initiated damages claim. No specific dollar recovery figure for Kraz could be confirmed from the sources reviewed in this pass (the opinion excerpts available describe the issues and the improvident-default finding but not a stated final dollar judgment amount), so dollarAmount is left null rather than estimated.", "outcome": "In the underlying state-court commercial foreclosure action, a Florida trial court denied Branch Banking & Trust Co.'s (BB&T) attempt to foreclose its mortgage on borrower Kraz, LLC's commercial property, finding that BB&T had improvidently declared the loan in default, and entered a final judgment in Kraz's favor. On BB&T's appeal, Florida's Second District Court of Appeal affirmed the judgment on all but one of the twelve issues BB&T raised, reversing only as to a credit the judgment had awarded Kraz against its loan principal for certain amounts BB&T had received. The dispute continued for years afterward in Kraz's related Chapter 11 bankruptcy case, where BB&T's successor (whose acquisition of the failed bank's assets was covered by an FDIC loss-share agreement) pursued its claim against the debtor; the bankruptcy court's 2015 and 2017 decisions addressed further disputes over that claim and the FDIC loss-sharing arrangement's effect on it.", "caseName": "Kraz, LLC v. Branch Banking & Trust Co.", "citation": "Branch Banking & Trust Co. v. Kraz, LLC, 114 So. 3d 273 (Fla. 2d DCA 2013); related bankruptcy-court proceedings at In re Kraz, LLC, 539 B.R. 887 (Bankr. M.D. Fla. 2015), and Kraz, LLC v. Branch Banking & Trust Co. (In re Kraz, LLC), 570 B.R. 389 (Bankr. M.D. Fla. 2017)", "sourceUrl": "https://www.courtlistener.com/opinion/4991427/branch-banking-trust-co-v-kraz-llc/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "FL"}], "proxy_disclosure_claim": [{"year": 2012, "outcome": "Piedmont announced on October 22, 2012 that it had reached agreements in principle to settle both consolidated class actions for a combined $7.5 million ($4.9 million and $2.6 million respectively), resolving the litigation and related appeals following court approval.", "caseName": "In re Wells Real Estate Investment Trust, Inc. Securities Litigation (Piedmont Office Realty Trust)", "citation": "No. 1:07-cv-00862-CAP (N.D. Ga.)", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/0001042776/000104277612000112/ex991pressreleasedatedocto.htm", "confidence": "high", "dollarAmount": 7500000}, {"year": 2019, "outcome": "The district court (Judge Lorna G. Schofield) dismissed the second amended complaint for failure to state a claim on September 23, 2019, holding the proxy disclosures were not materially misleading because AFIN had adequately warned of internalization-related conflicts and discount-trading risk, and industry-wide skepticism of externally-managed REITs was already public knowledge. The Second Circuit affirmed the dismissal in 2020.", "caseName": "St. Clair-Hibbard v. American Finance Trust, Inc., et al.", "citation": "No. 1:18-cv-01148 (S.D.N.Y.), aff'd, 2d Cir. 2020", "sourceUrl": "https://caselaw.findlaw.com/court/us-2nd-circuit/2063139.html", "confidence": "high", "dollarAmount": null}, {"year": 2026, "outcome": "U.S. District Judge Michael A. Shipp denied the defendants' motion to dismiss on August 5, 2026, finding the proxy materials may have omitted the material conflict of interest and allowing all four counts (including breach of fiduciary duty) to proceed into discovery. No settlement or trial outcome yet; case is ongoing as of this research.", "caseName": "In re Lightstone REIT Proxy Litigation (Lightstone Value Plus REIT I, II, and III)", "citation": "D.N.J. (motion to dismiss denied Aug. 5, 2026)", "sourceUrl": "https://altswire.com/lightstone-reit-directors-must-face-suit-over-59-8m-undisclosed-conflict/", "confidence": "high", "dollarAmount": null}, {"year": 2019, "notes": "One of the largest confirmed dollar outcomes in this claim type's sample -- an SEC enforcement action rather than private shareholder litigation, but arising from the same underlying conduct (merger-related proxy/disclosure misconduct around fee calculations) this claim type is meant to capture. Useful as a high-end benchmark for what regulatory exposure can look like when incentive-fee manipulation is proven, distinct from the private-litigation settlement figures elsewhere in this sample.", "outcome": "SEC enforcement action alleging AR Capital, its founder Schorsch, and former CFO Block inflated an incentive fee calculation in connection with two non-traded-REIT mergers into American Realty Capital Properties, Inc. (ARCP) -- the 2013 merger with American Realty Capital Trust III and the 2014 merger with American Realty Capital Trust IV -- improperly obtaining roughly 2.92 million additional ARCP operating-partnership units. Without admitting or denying the allegations, defendants agreed to a final judgment with permanent injunctions and cumulative disgorgement, prejudgment interest, and civil penalties exceeding $60 million.", "caseName": "SEC v. AR Capital, LLC, Nicholas S. Schorsch, and Brian S. Block", "citation": "S.D.N.Y., settled 2019", "sourceUrl": "https://www.sec.gov/newsroom/press-releases/2019-133", "confidence": "high", "dollarAmount": 60000000, "jurisdiction": "Federal (S.D.N.Y.)"}, {"year": 2013, "notes": "An older but well-documented REIT-specific proxy/disclosure settlement figure, useful alongside the more recent citations in this claim type for showing the range of outcomes across different eras of REIT disclosure litigation.", "outcome": "Two 2007-filed securities class actions -- one challenging disclosures around Piedmont's internalization transaction, the other challenging disclosures in a tender offer and charter amendment -- were consolidated and settled together for a combined $4.9 million cash payment by Piedmont and its insurers.", "caseName": "In re Piedmont Office Realty Trust, Inc. Securities Litigation (consolidating the 'Wells Action' and the 'Piedmont Action')", "citation": "N.D. Ga., settlement hearing Apr. 18, 2013", "sourceUrl": "https://investor.piedmontreit.com/news-releases/news-release-details/piedmont-office-realty-trust-reaches-agreements-principle-settle", "confidence": "medium", "dollarAmount": 4900000, "jurisdiction": "Federal (N.D. Ga.)"}, {"year": 2022, "outcome": "Following announcement of STORE Capital's approximately $14 billion all-cash acquisition by GIC and Oak Street Real Estate Capital ($32.25/share), six purported stockholders filed substantially similar suits alleging the preliminary and definitive proxy statements omitted material information (financial projections, banker conflicts, valuation-analysis inputs) in violation of Section 14(a)/Rule 14a-9. STORE Capital voluntarily supplemented its proxy disclosures via SEC filing to address the claims and avoid delay; stockholders approved the merger on December 9, 2022, and the suits were mooted/withdrawn without a court-approved settlement or a disclosed per-share cash recovery.", "caseName": "STORE Capital Corp. Stockholder Litigation (O'Dell v. STORE Capital Corp.; Klein v. STORE Capital Corp.; Grossman v. STORE Capital Corp.; Smith v. STORE Capital Corp.; Bushansky v. STORE Capital Corp.)", "citation": "Six complaints filed Oct. 28 - Nov. 28, 2022, S.D.N.Y.", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/1538990/000119312522301800/d266910d8k.htm", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal (S.D.N.Y.)"}, {"year": 2022, "outcome": "In connection with American Campus Communities' approximately $13 billion take-private acquisition by Blackstone real estate funds, multiple purported stockholders filed suit alleging the proxy statement omitted material information regarding the special committee's process, confidentiality agreements with Blackstone, director/officer conflicts of interest, equity-award treatment, post-closing employment discussions, and the financial advisor's projections/valuation analyses. An earlier-filed action (the Acuna Lawsuit) was dismissed; American Campus Communities' stockholders approved the merger on August 3, 2022, and the remaining suits followed the standard disclosure-only resolution pattern -- the company issued supplemental proxy disclosures and the suits were mooted/withdrawn, with no disclosed per-share cash recovery.", "caseName": "American Campus Communities, Inc. Stockholder Litigation (Charfauros v. American Campus Communities, Inc.; Justice v. American Campus Communities, Inc.)", "citation": "Jeffrey D. Justice, II v. American Campus Communities, Inc., et al., No. 1:22-cv-03069 and related actions", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/1283630/000119312522212615/d373681dex991.htm", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal"}, {"year": 2022, "notes": "Included because the fact pattern (proxy disclosure claim layered on top of an active, competing-bidder situation) is a variant not otherwise represented in this sample, but the final resolution could not be verified with confidence in this pass -- flag for a follow-up research pass before relying on it for probability calibration.", "outcome": "Filed amid a high-profile bidding war for Monmouth Real Estate Investment Corp. (Equity Commonwealth's original ~$3.4 billion all-stock deal was rejected by Monmouth stockholders in August 2021 after Starwood Capital's Barry Sternlicht intervened, and Industrial Logistics Properties Trust ultimately won with a $4 billion all-cash deal that closed February 25, 2022), plaintiffs alleged Monmouth's directors breached fiduciary duties by misrepresenting or omitting material information in the definitive proxy statement concerning the (ultimately terminated) Equity Commonwealth merger agreement, and sought attorneys' fees tied to corrective disclosures. Given the underlying Equity Commonwealth transaction was superseded and never closed, this claim most plausibly resolved on a mootness basis; this research pass could not independently confirm a final settlement amount, fee award, or dismissal order.", "caseName": "Ross v. Conway (Monmouth Real Estate Investment Corp. Proxy Litigation)", "citation": "Putative class action filed Aug. 4, 2021, amended Jan. 14, 2022 (D.N.J. or related federal venue)", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/67625/000121390021024925/ea140445-dfan14a_blackwells.htm", "confidence": "low", "dollarAmount": null, "jurisdiction": "Federal (D.N.J.)"}, {"year": 2024, "outcome": "In connection with the roughly $21 billion all-stock merger of equals between Healthpeak Properties and Physicians Realty Trust, purported shareholders alleged the companies and their trustees violated federal securities laws and/or Maryland fiduciary-duty principles by omitting or misstating material information in the joint proxy statement filed January 11, 2024. Shareholders of both companies approved the merger at meetings held February 21, 2024, following the customary practice of supplementing the proxy with additional disclosures; no separate cash settlement to shareholders was disclosed.", "caseName": "Physicians Realty Trust / Healthpeak Properties Merger Proxy Litigation", "citation": "Proxy statement filed Jan. 11, 2024; special meeting held Feb. 21, 2024", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/765880/000110465924026567/tm246967d1_ex99-1.htm", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal / Maryland"}], "quiet_enjoyment_breach": [{"url": "http://masscases.com/cases/sjc/437/437mass708.html", "year": 2002, "notes": "Good illustration that even where liability is found, damages actually proven/awarded can be modest relative to what a tenant claims. Also established Massachusetts' 'dependent covenants' rule for commercial leases.", "outcome": "Judgment for the tenant. The trial court (jury-waived) found constructive eviction; the SJC affirmed the result on a different theory (mutual dependence of lease covenants in commercial leases) and upheld an award of $1,063 in relocation damages for moving machinery and the telephone system, well below the tenant's claimed $14,000+ in moving costs.", "caseName": "Wesson v. Leone Enterprises, Inc.", "citation": "437 Mass. 708, 774 N.E.2d 661 (2002)", "confidence": "high", "dollarAmount": 1063, "jurisdiction": "MA"}, {"url": "https://www.leagle.com/decision/1969678460p2d2181677", "year": 1969, "notes": "Foundational Colorado constructive-eviction definition, arising from a landlord's active construction interference rather than mere disrepair \u2014 useful as an 'interference by landlord conduct' fact pattern.", "outcome": "Judgment for the tenant. The Colorado Supreme Court defined constructive eviction as any landlord disturbance of the tenant's possession that renders the premises unfit for their leased purpose or deprives the tenant of beneficial enjoyment, causing abandonment. The trial court's $2,212 judgment for the tenant was upheld and the landlord's counterclaim for remaining rent was dismissed.", "caseName": "Radinsky v. Weaver", "citation": "170 Colo. 169, 460 P.2d 218 (1969)", "confidence": "high", "dollarAmount": 2212, "jurisdiction": "CO"}, {"url": "https://www.courtlistener.com/opinion/2393408/reste-realty-corporation-v-cooper/", "year": 1969, "notes": "Landmark, widely cited constructive-eviction case establishing that recurring flooding the landlord fails to remedy breaches quiet enjoyment. Opinion does not state a specific dollar recovery for the tenant beyond relief from unpaid rent; treat as a principle-establishing case.", "outcome": "Judgment for the tenant. The New Jersey Supreme Court held the tenant was constructively evicted and relieved of liability for rent for the balance of the term (roughly 2.25 years remaining on the lease).", "caseName": "Reste Realty Corp. v. Cooper", "citation": "53 N.J. 444, 251 A.2d 268 (1969)", "confidence": "high", "dollarAmount": null, "jurisdiction": "NJ"}, {"url": "https://law.justia.com/cases/new-york/court-of-appeals/1970/26-n-y-2d-77-0.html", "year": 1970, "notes": "Negative/defense-side outcome. Useful as a principle case: (1) constructive eviction requires abandonment, and (2) landlord conduct must breach an actual lease obligation, not merely a pre-lease representation negated by a merger clause.", "outcome": "Judgment for the landlord. The Court of Appeals held there was no actual or constructive eviction because the landlord did not fail to provide anything actually required by the lease, and, separately, that a tenant who remains in possession cannot claim constructive eviction.", "caseName": "Barash v. Pennsylvania Terminal Real Estate Corp.", "citation": "26 N.Y.2d 77, 308 N.Y.S.2d 649, 256 N.E.2d 707 (1970)", "confidence": "high", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 2025, "notes": "Sourced from the plaintiff's own firm's case-results reporting rather than a published opinion or court filing directly reviewed -- the formal case caption and docket number were not independently confirmed, and the specific appellate holding that preceded the settlement is described only in general terms. Included because the underlying facts (toxic mold/asbestos/VOC contamination forcing vacatur, landlord's failure to remediate despite notice) and the settlement figure are specific and plausible, but treat the dollar amount with more caution than the primary-source-verified citations in this claim type.", "outcome": "Tenant leased a commercial unit in Delray Beach that proved uninhabitable due to toxic mold, asbestos, and volatile organic compounds; the landlord allegedly failed to remediate despite repeated complaints, forcing the tenant to vacate. After the tenant secured a favorable appellate ruling, the case settled for $435,000, covering relocation and restoration costs, shortly before trial.", "caseName": "Commercial tenant v. SW Delray Artist Alley, LLC", "citation": "Palm Beach County, Florida (settled shortly before trial, following an appellate ruling in the tenant's favor)", "sourceUrl": "https://themold.lawyer/tenant-rights/toxic-commercial-lease-settlement-appeal-success/", "confidence": "medium", "dollarAmount": 435000, "jurisdiction": "FL"}, {"year": 2021, "notes": "A strong, real, dollar-substantial (nearly $193K) constructive-eviction/failure-to-repair win for a tenant, arising from a genuinely commercial fact pattern (a roof-repair failure and related misrepresentation about repair intentions) -- meaningfully larger than the existing Wesson v. Leone ($1,063) and Radinsky v. Weaver ($2,212) citations, which the file itself already flags as illustrating modest actual recoveries relative to what's claimed. Also independently useful for the attorney_fees claim type (see that citation set).", "outcome": "Commercial tenant sued its landlord for breach of lease, negligent misrepresentation, and constructive eviction after the landlord misrepresented the condition of the building's roof and its intent to repair it, then failed to timely repair the roof and keep the building tenantable. The trial court found constructive eviction and awarded the tenant $193,006.35 in compensatory damages plus $69,002.68 in attorney's fees; the Court of Appeals affirmed in full.", "caseName": "Pryority Partnership v. AMT Properties, LLC", "citation": "No. E2020-00511-COA-R3-CV (Tenn. Ct. App. Mar. 10, 2021)", "sourceUrl": "https://www.courtlistener.com/opinion/?q=Pryority+Partnership+AMT+Properties", "confidence": "medium", "dollarAmount": 193006, "jurisdiction": "TN"}, {"year": 2026, "notes": "A current (2026), real, landlord-WINS counter-example on a repair/interference-adjacent theory -- useful balance against this claim type's other citations, most of which are tenant wins or doctrine-establishing cases. Illustrates a real limiting principle: quiet-enjoyment/repair-failure liability requires the INTERFERENCE TO STEM FROM AN ACTUAL LEASE OBLIGATION the landlord failed to meet, not from a third party's separate, subsequent conduct or from a regulatory compliance burden the lease placed on the tenant itself -- directly parallel to the existing Barash v. Pennsylvania Terminal Real Estate Corp. principle already in this dataset. No dollar amount at issue since the tenant recovered nothing.", "outcome": "Commercial tenant operating a karaoke establishment sued its landlord after a third party removed bollards protecting the tenant's required emergency-exit egress path and then told fire authorities the tenant no longer had egress rights through that exit -- threatening the tenant's continued lawful operation. The tenant argued the landlord breached the lease and Connecticut's unfair trade practices act by failing to secure a written egress agreement. The Connecticut Appellate Court affirmed judgment for the LANDLORD, holding an implied emergency-access agreement existed (evidenced by the tenant's continued fee payments to the third party accepted without objection), that the lease itself only obligated the landlord to secure alleyway ingress/egress, and that the tenant bore responsibility for its own post-signature legal/regulatory compliance.", "caseName": "Karaoke Heroes NH, LLC v. RVRM Enterprises, LLC", "citation": "Docket No. AC48149 (Conn. App. Ct. Mar. 3, 2026)", "sourceUrl": "https://www.courtlistener.com/opinion/?q=Karaoke+Heroes+RVRM+Enterprises", "confidence": "medium", "dollarAmount": null, "jurisdiction": "CT"}], "cercla_contribution_claim": [{"year": 2018, "outcome": "The district court allocated 62% of the $9 million cleanup cost to Greenlease and 38% to Trinity under CERCLA Section 113(f). The Third Circuit affirmed the parent-subsidiary/operator liability findings (applying United States v. Bestfoods) while addressing related allocation issues.", "caseName": "Trinity Industries, Inc. v. Greenlease Holding Co.", "citation": "903 F.3d 333 (3d Cir. 2018)", "sourceUrl": "https://www.taftlaw.com/news-events/law-bulletins/trinity-the-corporate-form-and-how-to-avoid-parent-subsidiary-cercla-liability/", "confidence": "medium", "dollarAmount": 9000000}, {"year": 2024, "outcome": "Court awarded $1.17 million of $1.43 million in past response costs claimed, and allocated future response-cost shares: PPG 50%, Hydrite 20%, an unrecoverable \"orphan share\" of 20% assigned to plaintiff, Barclay/Sherman 10%, and 0% each to two other defendants. Hydrite separately settled for $550,000 (past costs) plus a $3 million escrow (future costs).", "caseName": "Barclay Lofts LLC v. PPG Industries, Inc.", "citation": "No. 20-CV-1694, 2024 WL 4224731 (E.D. Wis. Sept. 18, 2024)", "sourceUrl": "https://www.mgkflitigationblog.com/Barclay_Lofts_PPG_Allocation_CERCLA_Superfund", "confidence": "medium", "dollarAmount": 1170000}, {"year": 2023, "outcome": "A jury awarded Walnut Creek Manor $350,000 in past damages and $1,597,000 in future damages ($1,947,000 total) against Mayhew; the district court held Mayhew 100% liable for future response costs. A successor entity, GP Vincent II, later pursued a related CERCLA cost-recovery claim against the Beard estate; the Ninth Circuit reversed a claim-preclusion dismissal in 2023 and remanded for further proceedings.", "caseName": "Walnut Creek Manor, LLC v. Mayhew Center, LLC", "citation": "No. 4:07-cv-05664-CW (N.D. Cal.); related appeal GP Vincent II v. Estate of Beard, No. 21-16555 (9th Cir. May 17, 2023)", "sourceUrl": "https://law.justia.com/cases/federal/appellate-courts/ca9/21-16555/21-16555-2023-05-17.html", "confidence": "medium", "dollarAmount": 1947000}, {"year": 2024, "notes": "A detailed, multi-party equitable allocation ruling -- useful both for the recoverable-past-costs figure ($1.17M of $1.43M claimed) and as a real illustration of how courts split CERCLA liability among multiple historical operators plus the current owner, including assigning an insolvent party's 'orphan share' to the plaintiff rather than leaving it unallocated. dollarAmount reflects only the confirmed recoverable past costs; future costs remained a wide, unresolved range at the time of this decision.", "outcome": "Milwaukee industrial-to-residential redevelopment site contaminated with hexavalent chromium, arsenic, mercury, lead, and TCE. The court allocated CERCLA liability for future response costs among the historical operators/current owner: PPG Industries 50%, Hydrite Chemical Co. 20%, Wayne Pigment Corporation 20% (its share reassigned to Barclay as an uncollectible 'orphan share'), and Barclay Lofts/Sherman Associates (the current owner/redeveloper) 10%; Wayne Chemical Corp. and Lumimove Inc. were allocated 0%. Of Barclay's claimed $1.43 million in past/pre-remediation costs, the court found $1.17 million necessary and recoverable. Future cleanup cost estimates from the parties' experts ranged from $6.7 million to over $28 million; codefendant Hydrite separately settled for a $3 million escrow allocation plus $550,000 toward past costs.", "caseName": "Barclay Lofts LLC v. PPG Industries, Inc.", "citation": "No. 20-CV-1694 (E.D. Wis. Sept. 18, 2024)", "sourceUrl": "https://www.mgkflitigationblog.com/Barclay_Lofts_PPG_Allocation_CERCLA_Superfund", "confidence": "high", "dollarAmount": 1170000, "jurisdiction": "Federal (E.D. Wis.)"}, {"year": 2025, "outcome": "DOCTRINAL, not a dollar data point: sulfuric acid leaked into a Colorado river from a plant near a mine; after EPA ordered Atlantic Richfield to build water-treatment systems (costing several million dollars), Atlantic Richfield sued NL Industries. The district court held the claim was cost-recovery under Sec. 107 (six-year limitations period) and time-barred it; the Tenth Circuit reversed, holding the claim was actually a Sec. 113(f) contribution action (three-year period, but running from a different trigger), so the suit was timely after all, and remanded. Directly illustrates the same 107-vs-113(f) classification fork that this dataset already flags under cercla_cost_recovery (Guam v. United States) -- now from the reverse direction, where a party arguing for LONGER treatment (cost recovery) was instead held to be a contribution plaintiff.", "caseName": "Atlantic Richfield Company v. NL Industries, Inc.", "citation": "No. 23-1349 (10th Cir. Feb. 19, 2025)", "sourceUrl": "https://law.justia.com/cases/federal/appellate-courts/ca10/23-1349/23-1349-2025-02-19.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal (10th Cir., applying CO law)"}, {"year": 2025, "notes": "VERIFICATION CAVEAT: the May 12, 2025 decision date and Sixth Circuit slip-opinion number (25a0127p-06) were confirmed against the court's own opinion index, and the subject matter (Kalamazoo River, Sec. 107 vs. 113(f) declaratory relief) is confirmed via a secondary-source summary. The exact party caption for this specific 2025 phase (as opposed to the confirmed 2022 phase of the same litigation family, Georgia-Pacific Consumer Prods. LP v. NCR Corp., No. 18-1806, 2022 WL 1209013 (6th Cir. Apr. 25, 2022)) was NOT independently re-confirmed from primary text in this research session -- flagged here rather than presented as fully verified.", "outcome": "Continuing installment of the decades-long Kalamazoo River PCB-contamination litigation among historical paper-mill operators. The 2025 published opinion held that a party already found liable for response costs under CERCLA Sec. 107 in an earlier phase of the case is not entitled to declaratory relief for FUTURE cleanup costs under Sec. 107 -- it is limited to a Sec. 113(f) contribution claim for those future costs, reinforcing that a single multi-decade site can generate successive, doctrinally distinct claims at different phases of the same litigation.", "caseName": "Georgia-Pacific Consumer Products LP v. NCR Corp. (Kalamazoo River Superfund Site litigation)", "citation": "6th Cir., published opinion filed May 12, 2025 (slip op. no. 25a0127p-06)", "sourceUrl": "https://www.mcglinchey.com/insights/sixth-circuit-clarifies-cercla-statute-of-limitations/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (6th Cir., applying MI law)"}, {"year": 2014, "notes": "No single dollar figure applies (multiple sites/dockets); value here is doctrinal -- a real, verified illustration of how a bankruptcy-triggered contribution clock can extinguish an otherwise-valid contribution claim entirely, consistent with this claim type's existing 'orphan share' and equitable-reduction themes (Trinity Industries, Barclay Lofts) but for a different, timing-based reason. Citations confirmed via CourtListener docket search; full opinion text not independently re-read in this session.", "outcome": "A landmark, multi-circuit trilogy arising from ASARCO's bankruptcy reorganization: ASARCO's post-bankruptcy Sec. 113(f) contribution claims against Union Pacific (a 19th-century-era business partner at several historical lead/mining/smelting sites in Idaho, Montana, and elsewhere) were held time-barred because they were filed more than three years after the bankruptcy court approved the underlying CERCLA settlements -- with the Ninth, Tenth, and Eighth Circuits all reaching the same result within months of each other on parallel sites.", "caseName": "ASARCO LLC v. Union Pacific Railroad Co.", "citation": "765 F.3d 999 (9th Cir. 2014); parallel rulings same year in 755 F.3d 1183 (10th Cir. 2014) and 762 F.3d 744 (8th Cir. 2014)", "sourceUrl": "https://www.courtlistener.com/opinion/587606/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (9th, 10th & 8th Cir.)"}, {"year": 2025, "notes": "Directly relevant to the contribution-protection mechanic this claim type should account for: once these six utilities settle for ~25% of total costs, any remaining non-settling PRPs lose the ability to seek contribution from them, concentrating the unrecovered ~75% balance onto whoever is left -- the flip side of the 'orphan share' dynamic already noted for Barclay Lofts.", "outcome": "The United States sued six electrical utilities (Entergy Louisiana, LLC; Entergy Texas, Inc.; City of Garland, TX; Lighthouse Electric Cooperative; Southwestern Electric Power Co.; and Oncor Electric Delivery Co.) under CERCLA Sec. 107(a) to recover costs of cleaning up PCB-contaminated transformers sent to the F.J. Doyle Salvage Superfund Site in Leonard, Texas. The six settling defendants agreed to pay $1,001,630.21 collectively -- roughly 25% of the $4,006,520.83 in EPA response costs at issue -- in exchange for a covenant not to sue and Sec. 113(f)(2) contribution protection against future claims by non-settling PRPs.", "caseName": "United States v. Entergy Louisiana, LLC, et al. (F.J. Doyle Salvage Superfund Site)", "citation": "Proposed Consent Decree, D.J. Ref. No. 90-11-3-12574, E.D. Tex., proposed Dec. 2025", "sourceUrl": "https://www.federalregister.gov/public-inspection/2025-23505/proposed-consent-decree-cercla", "confidence": "medium", "dollarAmount": 1001630.21, "jurisdiction": "Federal (E.D. Tex.)"}, {"year": 2021, "notes": "Total dollar value of the allocated cleanup obligation was not disclosed in the sources reviewed in this session (secondary sources note only that ARCO has separately spent 'over $1 billion' on the broader Superfund site since the 1980s and CFAC made '$95 million' in site improvements after its 1985 purchase -- neither figure is the specific dollar amount split 65/35 under this contribution judgment). dollarAmount left null rather than guessed. Directly responsive to this round's research directive: a real, court-affirmed, percentage-based PRP-vs-PRP equitable allocation, distinct from this claim type's existing SOL/classification-heavy sample.", "outcome": "CONFIRMED EQUITABLE-ALLOCATION PERCENTAGE -- exactly the data point this claim type's sample was missing. In a CERCLA Section 113(f) contribution action over cleanup of a former aluminum smelter site in Columbia Falls, Montana, the district court applied the Gore factors and initially found they 'warranted an equal assignment of liability' between the two parties, but then shifted the split by 15 percentage points based on qualitative considerations (the parties' 1985 sale contract terms and each side's relative economic benefit from the facility's operations), ultimately allocating 65% of response costs to Columbia Falls Aluminum Co. (CFAC, the current owner/operator) and 35% to Atlantic Richfield Co. (ARCO, a prior owner, later acquired by BP). CFAC appealed, arguing ARCO's share should have been higher; the Ninth Circuit affirmed the district court's methodology and the 65/35 split as within its discretion (reviewed for clear error), and the U.S. Supreme Court denied certiorari in 2023, leaving the allocation final.", "caseName": "Columbia Falls Aluminum Company, LLC v. Atlantic Richfield Company", "citation": "2021 U.S. Dist. LEXIS 160987, No. CV 18-131-M-DWM (D. Mont. Aug. 25, 2021), aff'd, No. 21-36042 (9th Cir. Jan. 31, 2023) (unpublished mem. disp.), cert. denied, No. 22-1207 (U.S. Oct. 2, 2023)", "sourceUrl": "http://acoel.org/blog/superfund-allocation-future-valuation-of-remediated-property/", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal (D. Mont.; aff'd 9th Cir.)"}, {"year": 2021, "notes": "dollarAmount reflects Von Duprin's total confirmed remediation spend ($3.2M, including the $1.5M third-party settlement) -- NOT a final, allocated dollar recovery, since the percentage allocation itself was vacated and remanded rather than left standing. Valuable precisely because it is a real, recent example of a court-assigned PRP percentage split (50/20/20/10) that did not survive appellate review -- a genuine reversal-risk data point this claim type's damages model should account for, distinct from the SOL/timing rulings already in the sample.", "outcome": "A CONFIRMED trial-court equitable-allocation percentage that was then VACATED on appeal -- a useful, real illustration of allocation risk/reversal rather than a clean data point. Von Duprin and its predecessor used degreasers containing TCE/PCE at a Northeast Indianapolis property; after Indiana regulators identified groundwater contamination, Von Duprin spent $3.2 million on remediation (including a $1.5 million settlement with a subsequent property owner) and sued neighboring historical operators (Moran Electric, Zimmer, Ertel) for contribution over a commingled groundwater plume. The district court found liability divisible along property lines and allocated the harm 50% to the Von Duprin property, 20% to Moran, 20% to Zimmer, and 10% to Ertel (then held each defendant 100% responsible for its own property's share). The Seventh Circuit VACATED that apportionment/allocation determination, holding the trial court had (1) framed the divisibility question at 'too high a level of generality' rather than asking whether the evidentiary record actually supported dividing liability, and (2) improperly 'merged and conflated' causation-based apportionment factors with equitable allocation factors, making the legal basis for the percentages indiscernible; the court affirmed the bona fide prospective purchaser and National Contingency Plan rulings and remanded for a redo of the divisibility/allocation analysis under the correct standard.", "caseName": "Von Duprin LLC v. Moran Electric Service, Inc.; Von Duprin LLC v. Major Holdings, LLC (companion appeals, same underlying site)", "citation": "Nos. 20-1793 & 20-1711 (7th Cir. Sept. 3, 2021), vacating in relevant part No. 1:16-cv-01942-TWP-DML (S.D. Ind.)", "sourceUrl": "https://www.mgkflitigationblog.com/Von_Duprin_Vacate_Seventh_Circuit_Divisibility", "confidence": "high", "dollarAmount": 3200000, "jurisdiction": "Federal (7th Cir., applying IN law)"}, {"year": 2017, "notes": "No specific percentage was set by this opinion itself (that was left to the district court on remand, and this session's research could not confirm what percentage, if any, resulted on remand -- flagged rather than guessed). Included because it is real, on point for equitable-allocation mechanics specifically involving a government PRP, and pairs naturally with this claim type's existing 'orphan share' theme (Barclay Lofts) by showing the flip side: a government defendant being pulled INTO a nonzero share rather than a private orphan share being pushed onto the plaintiff.", "outcome": "DOCTRINAL, not a final percentage data point, but directly relevant to how contribution percentages against government/quasi-orphan-share PRPs get set: a CERCLA contribution action over remediation at a former San Diego aeronautical manufacturing plant used for WWII- and Korean War-era military aircraft production. The district court had allocated the United States government a 0% equitable share of the contractor's remediation costs. The Ninth Circuit reversed that 0% allocation, reasoning that the contractor's wartime production was undertaken for the government's benefit and 'Americans should pay' some share of the resulting contamination costs, and remanded for the district court to assign the government a nonzero equitable share under a corrected Gore-factors analysis.", "caseName": "TDY Holdings, LLC v. United States", "citation": "No. 15-56483, 2017 U.S. App. LEXIS 19371 (9th Cir. Oct. 4, 2017)", "sourceUrl": "https://www.mgkflitigationblog.com/ninth-circuit-TDY-defense-contractor-cercla-allocation", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (9th Cir., applying CA law)"}, {"year": 2023, "notes": "The $700 million figure is the total expected remediation cost at issue, not a dollar amount actually allocated to any single PRP -- no percentage split had been announced as of the source reviewed, and this session's research (constrained by search budget) could not confirm whether a later 2024-2026 ruling assigned specific percentages. Included for scale/context and because it exemplifies exactly the apportionment-vs-allocation threshold fight that determines whether a percentage-based contribution claim is even available -- but it should NOT be over-weighted as an allocation-percentage data point, and a follow-up search for any subsequent allocation ruling in this matter is recommended before the next data-refresh round.", "outcome": "DOCTRINAL/scale data point, NOT a percentage allocation (none has been publicly reported yet as of the sources reviewed). California's DTSC sued eight former owners/operators connected to a former lead-acid-battery recycling/smelting operation in Vernon, California, seeking to recover approximately $700 million in expected remediation costs. After a three-day bench trial on the PRPs' divisibility defense (testimony from industrial historians and environmental engineers), the court rejected apportionment on causation grounds -- holding that gaps in historical site records and commingled contamination made it impossible to divide harm among the defendants by causation -- and held the case would proceed instead to equitable ALLOCATION among the PRPs (i.e., a Gore-factors percentage split, not yet decided as of this ruling).", "caseName": "California Department of Toxic Substances Control v. NL Industries, Inc., et al.", "citation": "U.S. District Court, Central District of California; ruling on apportionment/divisibility defense issued August 2023 (exact docket number not confirmed in sources reviewed)", "sourceUrl": "https://www.afslaw.com/perspectives/environmental-law-advisor/california-court-rejects-cercla-apportionment-defense", "confidence": "medium", "dollarAmount": 700000000, "jurisdiction": "Federal (C.D. Cal.)"}], "premises_punitive_damages": [{"year": 2017, "notes": "A clean illustration of what actually elevates ordinary premises negligence into punitive-damages territory: not the severity of the resulting injury, but documented evidence the owner already knew (via the exact same hazard recurring on camera) and did nothing before this plaintiff was hurt.", "outcome": "See full outcome under 'Slip-and-Fall / Hazardous Condition' above. The $5 million punitive component (on top of $2.5 million compensatory) rested specifically on camera evidence that the SAME hazard had already caught multiple other customers' feet before the plaintiff's fall -- the jury found that record sufficient to establish wantonness (Alabama's willful/wanton standard) rather than mere ordinary negligence.", "caseName": "Henry Walker v. Walmart Stores, Inc.", "citation": "Russell County, Alabama (Phenix City) jury verdict, November 2017 (docket number not independently confirmed)", "sourceUrl": "https://www.cbsnews.com/news/walmart-shopper-hurt-while-buying-melon-wins-7-5m-verdict/", "confidence": "medium", "dollarAmount": 5000000, "jurisdiction": "AL"}, {"year": 2010, "notes": "A DIFFERENT premises sub-context (a licensed medical/care facility, not a typical commercial property) and relied on secondary reporting rather than a directly retrieved court record -- included because it's a real, large, well-documented illustration of the DEGREE of egregious, profit-motivated conduct that can drive a punitive award far above the compensatory figure (roughly 4x here), which a typical commercial slip-and-fall or negligent-security fact pattern rarely reaches. Do not treat the specific multiple as a benchmark for an ordinary commercial premises case.", "outcome": "A nursing-home resident was malnourished, dehydrated, and denied medical care for a broken hip, and died after what was supposed to be a temporary post-operative stay; evidence showed the facility owner diverted resident-care insurance payments to personal use rather than adequate staffing/supplies. Jury awarded $8.5 million in compensatory damages and $35 million in punitive damages -- reported as the largest judgment against a nursing home in Georgia history at the time.", "caseName": "Terhune v. Forum Medical (Moran Lake Road Nursing Home)", "citation": "Floyd County, Georgia jury verdict, 2010 (docket number not independently confirmed)", "sourceUrl": "https://www.aboutlawsuits.com/wrongful-death-lawsuit-nursing-home-owner-12905/", "confidence": "low", "dollarAmount": 35000000, "jurisdiction": "GA"}, {"year": 2023, "notes": "A near-perfect on-point PUNITIVE-DAMAGES-DENIED case for a premises/negligent-security fact pattern (broken security gate, documented prior complaints, a resulting death) -- exactly the kind of fact pattern a plaintiff would expect to clear the willful/wanton bar, and the appellate court still said no. Exact reporter citation not independently confirmed; recommend verifying via Westlaw/Lexis before filing use.", "outcome": "A resident was killed by an intruder who entered an apartment complex through an open window after gaining access via the complex's front gate, which had been broken for months despite at least two tenants having emailed complaints about it. The trial court allowed the case to proceed on punitive damages against the property manager. The Fourth District Court of Appeal reversed, holding the alleged conduct -- a broken gate, known and complained-of for months, that was not repaired -- supported at most ordinary/simple negligence, not the gross negligence Florida's punitive-damages statute (Fla. Stat. Sec. 768.72) requires.", "caseName": "Pinnacle Property Services, LLC v. Forde", "citation": "Florida Fourth District Court of Appeal, 2023 (exact So. 3d reporter citation not independently confirmed)", "sourceUrl": "https://www.rumberger.com/insights/punitive-damages-2023-the-statute-means-what-it-says/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "FL"}, {"year": 2023, "notes": "Fact pattern is a parking-lot vehicle collision rather than a classic slip-and-fall or negligent-security injury, so its fit with this claim type is somewhat tangential -- included because it applies the identical Florida corporate-punitive-damages 'managing agent' standard that would govern a premises_punitive_damages claim against any corporate property owner/operator in Florida, and reinforces the Pinnacle Property Services holding from the same court and year.", "outcome": "An intoxicated dealership employee, who had a prior DUI conviction and prior reports of drinking on the job, struck the plaintiff's vehicle in the dealership's parking lot. The trial court granted a motion allowing punitive damages against the corporate employer; the Fourth District Court of Appeal reversed, holding that corporate punitive liability requires evidence that a 'managing agent' of the corporation itself was actively and knowingly at fault -- a corporation cannot be punished merely because a lower-level employee, even a repeat offender, caused harm.", "caseName": "Napleton's North Palm Beach Auto Park, Inc. v. Agosto", "citation": "Florida Fourth District Court of Appeal, 2023 (exact So. 3d reporter citation not independently confirmed)", "sourceUrl": "https://www.rumberger.com/insights/punitive-damages-2023-the-statute-means-what-it-says/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "FL"}, {"year": 2025, "notes": "Included specifically for calibration purposes: it is not clear from available reporting whether punitive damages were pled and rejected, or simply not pursued/instructed on, so this should NOT be read as an appellate holding that these facts couldn't support punitives -- only as a data point that even an extremely large, egregious-sounding verdict can land as 100% compensatory.", "outcome": "See full outcome under 'Inadequate Security / Third-Party Criminal Act' above. Despite a fact pattern including an alleged 'long history of violent incidents and repeated warnings' that the nightclub ignored before a gunman was let in and killed a patron, the reported $66.575 million verdict was entirely compensatory (pain-and-suffering and wrongful-death damages) with no punitive-damages component identified in reporting.", "caseName": "Creighton v. Elleven45 Lounge, LLC, et al.", "citation": "Fulton County State Court, Georgia, jury verdict Oct. 27, 2025; order entered Nov. 14, 2025", "sourceUrl": "https://www.beasleyallen.com/article/66-5-million-verdict-awarded-after-nightclub-negligence/", "confidence": "medium", "dollarAmount": 66575000, "jurisdiction": "GA"}], "section_1983_zoning_claim": [{"year": 1999, "outcome": "The case was tried to a jury, which found for the developer on the takings theory and awarded damages. The Ninth Circuit and, in a 5-4 decision, the Supreme Court affirmed both the jury's verdict and its authority to decide the takings-liability question -- a first for a regulatory-takings damages suit.", "caseName": "City of Monterey v. Del Monte Dunes at Monterey, Ltd.", "citation": "526 U.S. 687 (1999)", "sourceUrl": "https://supreme.justia.com/cases/federal/us/526/687/", "confidence": "high", "dollarAmount": 1450000}, {"year": 1996, "outcome": "The Court of Appeals affirmed reinstatement of the building permit and a damages award to the developer for the Town's Section 1983 violation of the developer's vested property rights, plus costs and attorneys' fees.", "caseName": "Town of Orangetown v. Magee", "citation": "88 N.Y.2d 41, 665 N.E.2d 1061, 643 N.Y.S.2d 25 (1996)", "sourceUrl": "https://www.law.cornell.edu/nyctap/I96_0091.htm", "confidence": "high", "dollarAmount": 5137126}, {"year": 2023, "outcome": "The Sixth Circuit affirmed summary judgment for the City, holding Green Genie failed to identify valid similarly-situated comparators and that the City had denied numerous other applicants for the same drug-free-zone reason. The plaintiff lost.", "caseName": "Green Genie, Inc. v. City of Detroit", "citation": "63 F.4th 521 (6th Cir. 2023)", "sourceUrl": "https://law.justia.com/cases/federal/appellate-courts/ca6/22-1441/22-1441-2023-03-21.html", "confidence": "high", "dollarAmount": null}, {"year": 2026, "outcome": "The district court granted summary judgment for the City; the Sixth Circuit affirmed, holding the developer lacked a constitutionally protected property interest in discretionary permits and that the bureaucratic delay, however frustrating, was not 'extraordinary' enough to constitute a taking or a due process violation.", "caseName": "Rubicon Real Estate Holdings, LLC v. City of Pontiac", "citation": "No. 25-1631 (6th Cir. June 18, 2026)", "sourceUrl": "https://caselaw.findlaw.com/court/us-6th-circuit/139569.html", "confidence": "high", "dollarAmount": null}, {"year": 1999, "notes": "A rare example of a landowner actually PREVAILING on an equal-protection theory against a municipality's discretionary land-use decision, with real, large damages plus fees and interest -- a useful counterweight to the Sixth Circuit citation above (developer lost on due process) in this same claim type, since equal protection and due process theories succeed at meaningfully different rates in zoning litigation. dollarAmount reflects the reported total exposure figure, which blends principal damages with interest and fees rather than isolating a single compensatory-damages number.", "outcome": "Landowners challenged a series of official actions by the Town, including a development moratorium and the denial of their application for an exemption from it. After a nonjury trial, the court found the December 1993 denial of the plaintiffs' moratorium-exemption application denied them equal protection, and awarded damages plus 9% prejudgment interest and reasonable attorney's fees -- total exposure reported as potentially exceeding $13 million.", "caseName": "W.J.F. Realty Corp. v. Town of Southampton", "citation": "261 A.D.2d 609, 690 N.Y.S.2d 725 (N.Y. App. Div., 2d Dep't, 1999)", "sourceUrl": "https://scholarship.law.stjohns.edu/cgi/viewcontent.cgi?article=1480&context=lawreview", "confidence": "medium", "dollarAmount": 13000000, "jurisdiction": "NY"}, {"year": 2025, "notes": "Included specifically because it shows a plausibly-pled personal-animus/selective-enforcement theory clearing the motion-to-dismiss stage post-2020s, consistent with the file's existing directEvidenceOfDiscriminatoryIntent modifier -- but it is NOT yet a resolved case and should not be treated as a win for calibration purposes until (if) it produces a final judgment or settlement.", "outcome": "Homeowners alleged Town officials trespassed on their property and selectively enforced zoning and building codes against them out of personal animus in a years-long dispute over their home/barn construction, a small dog-breeding operation, and agricultural activity. On the Town's motion to dismiss, the district court allowed the plaintiffs' federal and state equal protection claims and their federal substantive due process claim to proceed, along with a Monell municipal-liability theory against policymaking officials. This is a procedural win only (surviving a motion to dismiss, not a merits verdict or settlement) -- no damages have been established and the case's ultimate outcome is unknown as of this writing.", "caseName": "Masic v. Town of Franklinville, New York", "citation": "No. 1:24-cv-00018 (W.D.N.Y. Aug. 27, 2025)", "sourceUrl": "https://dockets.justia.com/docket/new-york/nywdce/1:2024cv00018/148891", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 2003, "notes": "Drawn from a secondary law-firm summary of Eleventh Circuit land-use Section 1983 case law rather than the full opinion; older case (2003) but consistent in direction with the file's existing observation that most Section 1983 zoning claims fail.", "outcome": "The Eleventh Circuit expressed reluctance to constitutionalize an ordinary zoning dispute and declined to find a substantive due process or equal protection violation in the City's zoning decision affecting the developer's property. Municipality win.", "caseName": "Greenbriar Village, LLC v. Mountain Brook City", "citation": "345 F.3d 1258 (11th Cir. 2003)", "sourceUrl": "https://www.jbwpc.com/Articles/Zoning-and-Land-Use-Litigation/LAND-USE-LITIGATION-UNDER-THE-CIVIL-RIGHTS-ACT.shtml", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (11th Cir.)"}, {"year": 1988, "notes": "Found via two independent routes: a WebSearch summary of the Justia/CourtListener opinion, and a 2002 municipal-defense CLE article (Davis, Malm & D'Agostine, 'Suing the Scoundrels!') that cites it as the leading contrary-authority case where a circuit (unlike the First Circuit) DID find a viable Section 1983 cause of action for a bad-faith, singled-out permit denial. This is exactly the 'denied permit + specific intent' fact pattern the research brief asked to target, and it is a real, well-documented PLAINTIFF WIN -- a useful additional counterweight alongside the file's existing Orangetown v. Magee and W.J.F. Realty citations. Damages figure not independently confirmed; treat as null rather than guessed.", "outcome": "Bateson, a self-employed Montana builder, submitted a building permit application that facially complied with the City of Billings' zoning and building ordinances. Rather than process it, city council members initiated an emergency rezoning of the site specifically to block Bateson's project, then continued withholding the permit. The district court found the City's calculated, arbitrary singling-out of Bateson's application -- after he had already met every generally-applicable requirement -- violated his substantive due process rights, that the council's action reflected official municipal policy rather than a rogue employee's conduct (satisfying Monell/Pembaur municipal-liability requirements), and that this caused Bateson compensable damages; the Ninth Circuit affirmed liability on all points on appeal. The specific dollar amount of the damages award could not be confirmed from the sources available in this research round.", "caseName": "Bateson v. Geisse", "citation": "857 F.2d 1300 (9th Cir. 1988)", "sourceUrl": "https://law.justia.com/cases/federal/appellate-courts/F2/857/1300/115015/", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal (9th Cir.)"}, {"year": 2016, "notes": "This is the actual case the file's existing 'directEvidenceOfDiscriminatoryIntent' modifier note already refers to by name ('Avenue 6E Investments got past summary judgment...') but it had never been added to the citations array itself -- so it counts as a genuinely new addition per the literal instruction to check the citations array. Confirmed independently via a law-firm blog write-up (landusedevelopments.com) plus Justia/FindLaw/Quimbee/CourtListener case pages surfaced in search. No final damages figure exists because the case was remanded rather than resolved on the merits.", "outcome": "Developers who owned land in a predominantly white area of Yuma, Arizona sought rezoning to build housing affordable to the city's mostly-Hispanic, lower-income population. The City Council denied the request over the recommendation of its own planning staff and zoning commission, at a hearing marked by racially-charged opposition from neighboring residents -- the only rezoning denial among 76 applications the City processed in the prior three years. The district court granted the City summary judgment; the Ninth Circuit reversed, holding the developers had presented triable claims of intentional race discrimination under both the Equal Protection Clause and the Fair Housing Act, and that a municipality cannot defeat a disparate-impact theory merely by pointing to the theoretical availability of similar housing elsewhere in the city. This is a procedural reversal only -- remanded for further proceedings, not a final plaintiff verdict or damages award.", "caseName": "Avenue 6E Investments, LLC v. City of Yuma", "citation": "818 F.3d 493 (9th Cir. 2016)", "sourceUrl": "https://www.landusedevelopments.com/2016/03/rezoning-denial-may-give-rise-liability-discriminatory-zoning-practices/", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal (9th Cir.)"}, {"year": 2025, "notes": "IMPORTANT CAVEAT: this citation was surfaced via a WebSearch summary of the DOJ Civil Rights Division's case-listing page, but this round's automated page-fetch (WebFetch) to justice.gov, CourtListener, and Justia was blocked (HTTP 403) for the remainder of the session, so the underlying DOJ page could not be independently re-read to double-check the docket number, exact filing date, or additional detail. The case itself is real (a live, actively-covered DOJ Fair Housing/equal-protection matter) but is included here only to illustrate the discriminatory-zoning-enforcement fact pattern the research brief asked to target -- it is NOT a resolved case and should not be used for base-rate/calibration purposes, consistent with how the file already treats the similarly-pending Masic v. Town of Franklinville citation.", "outcome": "A private developer affiliated with an Orthodox Jewish community sued the Town of Forestburgh, New York and other municipal defendants, alleging the Town used its zoning and land-use approval process to obstruct a proposed residential subdivision specifically because officials believed the project would attract Orthodox Jewish residents to the area. The U.S. Department of Justice's Civil Rights Division filed a statement of interest supporting the developer's discriminatory-intent theory in March 2025. As of the information available in this research round, the case remains pending with no trial verdict, judgment, or settlement disclosed.", "caseName": "Lost Lake Holdings, LLC v. Town of Forestburgh", "citation": "Civil action pending, S.D.N.Y.; U.S. Department of Justice statement of interest filed Mar. 7, 2025 (no merits decision as of this research)", "sourceUrl": "https://www.justice.gov/crt/housing-and-civil-enforcement-cases?page=10", "confidence": "low", "dollarAmount": null, "jurisdiction": "Federal (S.D.N.Y.)"}], "releasing_mitigation_costs": [{"url": null, "year": 2022, "notes": "Primary source: full motion, brief, and supporting affidavit read directly. Same filing as the accelerated_rent citation above -- illustrates that re-leasing/mitigation costs are a distinct, separately itemized, and potentially large damages category, not folded into the rent-acceleration figure. No public URL available for this record -- verify via the case number and court above.", "outcome": "In addition to past and accelerated future rent, the landlord's motion sought $714,926.86 in costs incurred/anticipated to re-lease the premises to three replacement tenants -- itemized as landlord's work (buildout), tenant-improvement allowances, and leasing commissions for each replacement lease -- as damages proximately caused by the tenant's breach and abandonment under the lease's default-remedies clause. These costs represented roughly 17% of the total damages sought ($714,926.86 of $4,904,104.52 combined rental and re-leasing damages).", "caseName": "The Village at Brocks Gap, LLC v. Singleton Ventures, LLC", "citation": "Case No. CV-2020-900604 (Cir. Ct. Jefferson Cnty., Ala., Bessemer Div.) (Pl.'s Mot. Summ. J., filed Feb. 17, 2022)", "confidence": "high", "dollarAmount": 714926, "jurisdiction": "AL"}, {"url": "https://www.courts.nh.gov/sites/g/files/ehbemt471/files/documents/2026-03/20250067.pdf", "year": 2026, "notes": "This is a Rule 3 summary-disposition-style appellate order; the specific dollar figures for the landlord-work and tenant-allowance line items were not independently confirmed from secondary reporting, only that the trial court's recovery theory itself was affirmed on appeal. Useful as current (2026), state-supreme-court-level confirmation that landlord-work and tenant-allowance costs are a recognized, recoverable damages category after tenant breach -- corroborating the Village at Brocks Gap citation above with a second, independent jurisdiction.", "outcome": "Trial court awarded the landlord damages for breach of a commercial lease agreement including 'landlord work' and 'tenant allowance' costs -- the tenant argued on appeal that the landlord was not entitled to recover these categories. The New Hampshire Supreme Court affirmed the trial court's award.", "caseName": "Brixmor GA Seacoast Shopping Center LLC v. NH1 Motorplex LLC", "citation": "No. 2025-0067 (N.H. Sup. Ct.)", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NH"}, {"year": 2019, "notes": "DOCTRINAL CITATION -- no dollar amount for re-leasing costs specifically was confirmed from available sources, and this litigation has multiple related opinions (842 F.3d 816 (4th Cir. 2016); a further 2025 appeal at 134 F.4th 265) addressing different sub-issues in the same underlying lease dispute; verify which opinion covers which issue before citing a specific holding. Useful for this claim type because it establishes the CEILING on the mitigation-failure risk: a landlord's re-leasing costs and effort are not all-or-nothing -- imperfect mitigation shrinks the recovery rather than zeroing it out, which supports this claim's damages formula using a modest haircut (0.85-1.0 of costs) rather than a steeper discount tied to mitigation-effort disputes.", "outcome": "In a long-running dispute over a 12-year commercial office lease in Baltimore (this being the second of several appeals in the same litigation), the Fourth Circuit clarified the scope of a commercial landlord's obligation to mitigate damages after a tenant's early termination/breach: if a landlord fails to properly mitigate (e.g., by making reasonable efforts to re-let, which can include efforts that generate re-leasing costs), that failure only REDUCES the damages recoverable -- it does not categorically bar the landlord's damages claim altogether.", "caseName": "NCO Financial Systems, Inc. v. Montgomery Park, LLC", "citation": "918 F.3d 388 (4th Cir. 2019)", "sourceUrl": "https://www.courtlistener.com/opinion/4600526/nco-financial-systems-inc-v-montgomery-park-llc/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (4th Cir., applying MD law)"}, {"year": 2024, "notes": "PARTIAL VERIFICATION: the primary source (the opinion itself) confirms the breach, the mitigation-defense rejection, and that the lease's own damages formula governed -- but the precise $265,595.86 figure and its exact characterization as 'renovation cost' damages come from secondary reporting/search-derived summaries, not from a direct read of the full opinion text, so treat that specific number with more caution than the primary-source-confirmed citations in this dataset. If accurate, it is a good illustration that 'releasing/mitigation cost' damages can be measured by what the landlord spent to LAND a replacement deal, not only by out-of-pocket repair costs for the vacated space.", "outcome": "A prospective commercial tenant (Brand Castle) never took possession of leased space -- the landlord never provided keys and the tenant never occupied the premises -- and the parties' lease-related damages provision was triggered on that non-commencement/breach. The trial court awarded the landlord approximately $265,595.86, reported as the cost of renovations/improvements the landlord had performed as consideration for arranging a more lucrative replacement lease with a new tenant, rejecting the defaulting tenant's argument that the landlord failed to satisfy its duty to mitigate. The Eighth District affirmed.", "caseName": "Naiman Richmond Properties, Ltd. v. Brand Castle, L.L.C.", "citation": "2024-Ohio-2910 (8th Dist. Ct. App., Cuyahoga Cnty., Aug. 15, 2024)", "sourceUrl": "https://www.supremecourt.ohio.gov/rod/docs/pdf/8/2024/2024-Ohio-2910.pdf", "confidence": "medium", "dollarAmount": 265595, "jurisdiction": "OH"}, {"year": 2026, "notes": "A current, real, appellate-level illustration that re-leasing costs (TI allowance + broker commissions) are a substantial damages category (here ~30% of the total award) but are NOT automatically fully recoverable -- a landlord must have an enforceable, properly documented (here, written) basis for each component, and the timing of when each cost becomes 'ascertained' matters. Directly relevant to calibrating this claim type's [0.85, 1.0] recovery-rate range: a landlord can lose a meaningful slice (here, 30%) of claimed re-leasing costs on a technicality unrelated to whether the costs were reasonable or actually incurred. Secondary confirmation via https://www.mpamag.com/us/mortgage-industry/industry-trends/indiana-court-dismantles-35m-damages-award-in-commercial-lease-dispute/573141.", "outcome": "Landlord CPUS Anson Building 8A, LP leased industrial space to Tradewinds Holding Company under a lease running February 2021-February 2026; Tradewinds stopped paying rent in April 2022. The trial court granted partial summary judgment for the landlord on breach and, after a damages hearing, awarded over $3.5 million (~$2,585,984.93 in rent, ~$1,070,062.97 in recovery/repair/reletting expenses -- including a $695,992.50 tenant-improvement allowance and $321,464.99 in broker commissions paid to secure a replacement tenant, Rockwell Automation -- plus ~$2,319,686.29 in accruing interest), plus attorneys' fees and costs. The Court of Appeals of Indiana affirmed the breach finding but reversed the damages calculation, holding (1) the $321,464.99 in broker commissions was not chargeable to the tenant because Indiana law requires real-estate commission agreements to be in writing and no such signed agreement existed when the replacement lease was executed, making the landlord's payment voluntary and non-recoverable from the tenant, and (2) each reletting-cost item is only chargeable to the defaulting tenant when it becomes actually ascertained, not lumped in as of the date of re-entry. Remanded for recalculation.", "caseName": "Tradewinds Holding Company, Inc. v. CPUS Anson Building 8A, LP", "citation": "No. 25A-PL-347 (Ind. Ct. App. Apr. 23, 2026)", "sourceUrl": "https://www.courtlistener.com/opinion/10847207/tradewinds-holding-company-inc-v-cpus-anson-building-8a-lp/", "confidence": "high", "dollarAmount": 1070062, "jurisdiction": "IN"}, {"year": 2023, "notes": "Directly relevant to the mitigation/re-leasing-costs interplay this claim type addresses: Colorado will void an acceleration/liquidated-damages clause that ignores the landlord's mitigation obligation and the reasonable rental value of a re-let space, pushing the landlord back onto ordinary actual-damages principles -- consistent with where this engine's own accelerated_rent and releasing_mitigation_costs formulas already sit. A useful state-level confirmation that the mitigation duty can invalidate an otherwise-drafted acceleration clause outright, not just reduce a recovery piecemeal. Secondary source: https://businessden.com/2023/06/20/appeals-court-landlord-not-required-to-sell-to-mitigate-losses-when-tenant-leaves/.", "outcome": "Landlord Tremitek sued tenant Resilience Code and its guarantor after the tenant stopped paying rent roughly three years into a 10-year lease and vacated in February 2021. The lease's liquidated-damages clause let the landlord accelerate and recover the full present value of all remaining rent for the balance of the term. A bench trial awarded the landlord only unpaid rent through the vacate date (about $53,000), and the Colorado Court of Appeals went further on the landlord's cross-appeal, holding the accelerated/liquidated-damages clause was UNENFORCEABLE because it let the landlord recover the full remaining rent without deducting the reasonable rental value of the property for the remainder of the term -- i.e., without accounting for mitigation/re-letting value -- making it an unenforceable penalty rather than a reasonable pre-estimate of damages. Remanded for a revised damages award under ordinary, mitigation-sensitive breach-of-contract principles.", "caseName": "Tremitek, LLC v. Resilience Code, LLC", "citation": "2023 COA 54, 535 P.3d 1005 (Colo. App. 2023)", "sourceUrl": "https://law.justia.com/cases/colorado/court-of-appeals/2023/22ca1009.html", "confidence": "high", "dollarAmount": 53000, "jurisdiction": "CO"}, {"year": 1969, "notes": "DOCTRINAL CITATION, older case, no dollar comparable -- included because it supports the structural assumption underlying this claim type: a landlord CAN relet (incurring the very re-leasing/mitigation costs this claim type compensates) without that act itself being treated as forgiving the tenant's liability for the landlord's resulting out-of-pocket costs.", "outcome": "Addressing whether a landlord's reletting of premises after a tenant's abandonment automatically constitutes an acceptance of surrender (which would terminate the lease and cut off the landlord's damages claim), the Wisconsin Supreme Court held it does not -- following Selts Investment Co. v. Promoters of Federated Nations of the World, 197 Wis. 476 (1929) -- and confirmed that a landlord's duty to mitigate damages by reasonable reletting efforts exists independent of any lease clause permitting reletting.", "caseName": "Ross v. Smigelski", "citation": "42 Wis. 2d 654, 167 N.W.2d 793 (Wis. 1969)", "sourceUrl": "https://www.courtlistener.com/opinion/1611526/ross-v-smigelski/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "WI"}, {"year": 2023, "notes": "IMPORTANT SCOPE NOTE: this case concerns the enforceability of an accelerated-rent/liquidated-damages CLAUSE, not itemized out-of-pocket re-leasing costs -- it is most directly relevant to this category's accelerated_rent claim type. Included here because it stands in useful tension with the Tremitek (CO) citation above: Massachusetts (a 'single-look,' clause-enforceability jurisdiction) does NOT require a liquidated-damages clause to offset re-letting income to be enforceable, while Colorado's Tremitek decision effectively does. This is a real, current (2023) jurisdictional split relevant to whether re-leasing/mitigation costs get folded into liquidated damages or must be proven and recovered as their own itemized category -- verify which regime applies before applying this claim type's damages formula in a given state.", "outcome": "A tenant company's principal personally guaranteed a 5-year Woburn, MA office lease; the tenant defaulted after 4 months, and the landlord terminated and invoked the lease's liquidated-damages clause accelerating the full remaining ~56 months of rent. The guarantor argued the clause was an unenforceable penalty because it did not require the landlord to deduct anticipated future re-letting income. The Massachusetts SJC disagreed and affirmed the damages award, holding it has never required a liquidated-damages clause to account for future rents collected from a replacement tenant in order to be enforceable, and that the guarantor failed to prove the clause was an unreasonable forecast of damages at signing.", "caseName": "Cummings Properties, LLC v. Hines", "citation": "492 Mass. 867, 217 N.E.3d 604 (2023) (SJC-13406, decided Sept. 25, 2023)", "sourceUrl": "https://law.justia.com/cases/massachusetts/supreme-court/volumes/492/492mass867.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "MA"}, {"year": 2025, "notes": "Also reported as VLW 024-7-386. Cross-checked against the CourtListener docket listing and FindLaw's case page for the same parties/date. Directly relevant to this claim type because it represents the opposite pole from a re-leasing-cost recovery claim: a jurisdiction where the landlord need not show mitigation/re-leasing efforts at all to recover full contractual damages.", "outcome": "Tenant Bistro Manila LLC, along with individual guarantors, leased restaurant space in Alvah's Stafford County shopping center from September 2020 through a term running to July 2028. After COVID-related financial strain, the tenant stopped paying rent in February 2022 and abandoned the premises. The Stafford County Circuit Court found the tenant in breach, held that Virginia commercial landlords owe no duty to mitigate damages by reletting after a tenant's abandonment, and enforced the lease's rent-acceleration clause, awarding Alvah $410,391.77 in damages plus $18,000 in attorney's fees. On appeal, the Virginia Court of Appeals affirmed in full, rejecting the tenant's argument that a landlord invoking a contractual acceleration remedy should nonetheless be required to mitigate through re-leasing efforts, and confirming that Virginia's acceleration/liquidated-damages framework does not require the landlord to have incurred or proven re-leasing costs at all.", "caseName": "Bistro Manila LLC v. Alvah I LLC", "citation": "Record No. 0463-23-4 (Va. Ct. App. Jan. 7, 2025)", "sourceUrl": "https://valawyersweekly.com/2025/01/20/024-7-386-bistro-manila-llc-v-alvah-i-llc/", "confidence": "high", "dollarAmount": 410391.77, "jurisdiction": "VA"}, {"year": 2025, "notes": "SCOPE CAVEAT: this case is about a keep-open-covenant liquidated-damages penalty and rent acceleration, not specifically about recovery of TI allowances, buildout costs, or leasing commissions as re-leasing damages -- the opinion does not quantify or address the landlord's actual re-leasing/mitigation costs at all, it only notes reletting occurred. Weaker fit than the other citations for this specific claim type; consider dropping if a narrower, more on-point set is preferred.", "outcome": "Landlord Newark Shopping Center Owner (later assigned to Newark Shopping Center Venture) sued its restaurant tenant, Saudades Group, and its individual guarantors after the tenant closed its business in September 2022 in violation of a lease covenant requiring it to remain open, then stopped paying rent and vacated. Following a one-day bench trial, the Delaware Superior Court found the tenant and guarantors liable for breach of the keep-open covenant, breach of the payment obligations, and breach of the guaranty, and found no breach of the implied covenant of good faith by the landlord in refusing to approve two proposed lease assignments. However, the court held the lease's liquidated-damages clause (a per-diem penalty for the keep-open breach, roughly 4x the rate the tenant's own expert testified was customary) was an unenforceable penalty under Delaware's two-prong test, declined to 'blue-pencil' it down to a reasonable amount, and awarded only $352,525.49 in accelerated/unpaid rent plus $58,229.44 in attorney's fees and costs \u2014 entirely excluding the liquidated-damages penalty claim. The court noted the shopping center had, by the time of trial, already relet the premises to a new tenant, whose rent would offset the landlord's ongoing damages once that tenant began paying.", "caseName": "Newark Shopping Center Owner, L.L.C. and Newark Shopping Center Venture, LLC v. Saudades Group, LLC, Phillip Piraino, and Pamela Piraino", "citation": "C.A. No. N23C-02-091 JRJ (Del. Super. Ct. Feb. 26, 2025)", "sourceUrl": "https://courts.delaware.gov/Opinions/Download.aspx?id=375990", "confidence": "medium", "dollarAmount": 410754.93, "jurisdiction": "DE"}], "just_compensation_valuation": [{"year": 2025, "outcome": "Settled for $1,150,000, exceeding NCDOT's highest initial offer of $693,800 by $456,200.", "caseName": "North Carolina Department of Transportation v. AJA Investments", "citation": "Moore County Superior Court, Case No. 23 CVS 1525", "sourceUrl": "https://nclawyersweekly.com/2026/01/05/condemnation-case-ends-in-1-15m-settlement-for-commercial-property-owner/", "confidence": "high", "dollarAmount": 1150000}, {"year": 2019, "outcome": "Jury awarded $19.4 million in combined just compensation for the two parcels \u2014 292% above the State's combined initial offer, representing 100% of the compensation the landowner sought at trial. Judgment affirmed on appeal.", "caseName": "State v. Gleannloch Commercial Development, LP", "citation": "585 S.W.3d 509 (Tex. App.\u2014Houston [1st Dist.] 2019)", "sourceUrl": "https://www.velaw.com/practices/houston-i-45-highway-expansion-project/", "confidence": "high", "dollarAmount": 19400000}, {"year": 2013, "outcome": "After a jury trial, Arrington was awarded $969,243 for its leasehold and billboard-structure interest (affirmed on appeal); Moore Outdoor Properties separately settled for $480,000.", "caseName": "State v. Moore Outdoor Properties, LP / Arrington Outdoor of Fort Worth, L.P.", "citation": "No. 08-12-00034-CV (Tex. App.\u2014El Paso, Nov. 13, 2013) (transferred from Fort Worth)", "sourceUrl": "https://caselaw.findlaw.com/court/tx-court-of-appeals/1649615.html", "confidence": "high", "dollarAmount": 969243}, {"year": 2025, "outcome": "The Fifth District reversed, holding that county-auditor property-tax valuations are admissible evidence in an eminent-domain trial to help the jury determine fair compensation, and remanded for a new compensation trial.", "caseName": "City of North Canton v. Julius Brown, LLC", "citation": "Case No. 2024CA00030 (Ohio Ct. App., 5th Dist., Jan. 6, 2025)", "sourceUrl": "https://harpstbecker.com/2025/01/06/appellate-court-ruling-protects-commercial-property-owners-from-government-overreach-in-eminent-domain-cases/", "confidence": "high", "dollarAmount": null}, {"year": 2025, "notes": "A strong, current example for the severanceAccessOrBusinessValueDispute uplift tier (3x here) -- notable because the compensable harm wasn't to the condemned parcels themselves but to OTHER property the owners held that was merely appurtenant to them, a real expansion of what counts as 'part of a larger parcel' for severance-damages purposes.", "outcome": "The State condemned easements (not fee title) in two undeveloped common-area parcels appurtenant to homeowners' titles in a planned community, to build the Loop 202 South Mountain Freeway. The Arizona Supreme Court held homeowners could recover 'proximity damages' for the diminished value of their own homes caused by the freeway's proximity, even though only the easements -- not the homeowners' own land -- were condemned, because the condemned property was part of a larger parcel under Arizona's constitution. Compensation tripled from an initial $6 million (value of the easements alone) to $18 million ($6M plus $12M in proximity/severance damages).", "caseName": "State of Arizona v. Foothills/Hanke", "citation": "CV230292PR (Ariz. Jan. 31, 2025)", "sourceUrl": "https://www.ballardspahr.com/insights/alerts-and-articles/2025/01/arizona-supreme-court-expands-just-compensation-rights-in-eminent-domain-case", "confidence": "high", "dollarAmount": 18000000, "jurisdiction": "AZ"}, {"year": 2024, "notes": "A real, published federal appellate reinstatement of a landowner jury verdict a district judge had cut nearly in half -- useful evidence that a valuation verdict resting on legitimate alternative evidentiary theories can survive post-trial second-guessing on appeal.", "outcome": "A jury awarded the Terry family $523,327 in just compensation for permanent and temporary pipeline easements across 8.37 acres of their 560-acre Bent Mountain farm, crediting testimony that the land was worth $1.9 million with a roughly 30% reduction from the pipeline's impact. The district court trimmed the award to $261,033 post-trial, reasoning the jury must have relied on an unsupported commercial-development valuation theory. A Fourth Circuit panel (Judges Thacker, Gregory, and Wynn) reversed, holding the original $523,327 verdict was independently sustainable on the trial record using only the property's residential valuation evidence, and restored the full jury award.", "caseName": "Mountain Valley Pipeline, LLC v. 8.37 Acres of Land, More or Less, Situate in Roanoke County (Terry family)", "citation": "No. 23-1532 (4th Cir. May 14, 2024)", "sourceUrl": "https://cardinalnews.org/2024/05/14/judges-side-with-family-in-mountain-valley-pipeline-compensation-case-reversing-earlier-decision/", "confidence": "high", "dollarAmount": 523327, "jurisdiction": "Federal (4th Cir., applying VA law)"}, {"year": 2025, "notes": "The county's initial written offer was not disclosed in available reporting, so the exact uplift multiple can't be independently computed -- included for the confirmed, large, real dollar figures and jury-exceeds-condemnor's-valuation pattern, not as a precise ratio data point.", "outcome": "In a county-roadway condemnation, a Williamson County jury awarded J.A. Davidson Holdings $4,437,000 for the portion of property taken -- a figure the reporting describes as exceeding the valuation the county itself presented at trial. The parties subsequently resolved the balance of the dispute via a Rule 11 settlement agreement adding $2,913,000, for a combined total recovery of approximately $7.35 million.", "caseName": "Williamson County, Texas v. J.A. Davidson Holdings, L.P.", "citation": "Williamson County District Court, Texas (jury verdict Apr. 2025; Rule 11 settlement filed July 2025)", "sourceUrl": "https://www.hellogeorgetown.com/williamson-county-news/williamson-county-eminent-domain-case-ends-in-7-35m-settlement-after-jury-verdict/", "confidence": "medium", "dollarAmount": 7350000, "jurisdiction": "TX"}, {"year": 2024, "notes": "An extreme-outlier multiple (roughly 9,400x the opening offer) driven by New Jersey's practice of opening beach-easement condemnations with a token statutory-minimum offer, not a genuine first market bid -- do not use this ratio to recalibrate the general uplift tiers; it reflects a state/property-type-specific quirk, not typical negotiating behavior.", "outcome": "The State condemned a permanent easement over roughly 6 acres of oceanfront property owned by a homeowners' association for a post-Hurricane Sandy dune and storm-protection project, opening with a nominal $500 statutory offer. After trial, the jury returned a verdict of $4,707,631.36 -- described as the largest verdict obtained in any New Jersey beach-replenishment condemnation matter -- essentially matching the owner's own $4.69 million appraisal. Final judgment (with pre-judgment interest resolved by stipulation) entered roughly a year later.", "caseName": "New Jersey Department of Environmental Protection v. Midway Beach Condominium Association, Inc.", "citation": "N.J. Superior Court, Law Division, Ocean County, Docket No. OCN-L-2653-17 (jury verdict Aug. 2024; final judgment Aug. 2025)", "sourceUrl": "https://www.ownerscounsel.com/new-jersey-beach-replenishment-case-with-record-high-jury-verdict-nearly-a-year-ago-finally-concludes-after-pre-judgment-interest-agreement-is-reached/", "confidence": "high", "dollarAmount": 4707631, "jurisdiction": "NJ"}, {"year": 2025, "notes": "Residential/agricultural rather than commercial, but a real, well-documented ~13x uplift over the county's original offer (and ~5x its own final pretrial expert valuation) -- a genuine data point above the top of the existing severanceAccessOrBusinessValueDispute 2.0-5.0x tier, driven by an avigation-easement severance theory analogous to the Foothills/Hanke proximity-damages fact pattern already in this claim's sample.", "outcome": "The County sought to partially condemn a 79-acre property with a single-family home (a fee-simple taking of 1/3 acre plus an avigation easement over the remaining 78 acres) for an airport runway extension, opening with an offer of $268,500 that was later raised to $400,000 and then $700,000 before trial. The county's own appraisers valued the taking at $645,000-$700,000; the landowners' expert valued the damage at $2.2 million. The jury returned the maximum amount requested -- $3,500,000 in just compensation.", "caseName": "Commissioners of Carroll County, Maryland v. Kathleen O'Connor, et al.", "citation": "Circuit Court for Carroll County, Maryland, No. C-06-CV-23-000315 (jury verdict Nov. 2025)", "sourceUrl": "https://www.ownerscounsel.com/joe-suntum-ocas-maryland-member-prevails-in-landmark-eminent-domain-trial/", "confidence": "high", "dollarAmount": 3500000, "jurisdiction": "MD"}, {"year": 2025, "notes": "The specific dollar figure for the jury's award could not be independently confirmed from available public sources despite multiple attempts -- included only for the doctrinal point (appellate deference to a landowner's valuation expert and evidentiary sufficiency), not as a dollar data point. Flag for follow-up if the underlying trial-court record becomes accessible.", "outcome": "A gas utility acquired a pipeline easement over the landowner's property through eminent domain, and a jury assessed just compensation for the taking. On appeal, the utility argued the trial court erroneously admitted the landowner's valuation expert testimony and that the evidence was insufficient to support the jury's award. The Tennessee Court of Appeals found no abuse of discretion and affirmed the award in full.", "caseName": "Piedmont Natural Gas Company, Inc. v. BlueRoad Fontanel, LLC", "citation": "Tenn. Ct. App., No. M2024-01860-COA-R3-CV (argued Nov. 5, 2025)", "sourceUrl": "https://www.courtlistener.com/opinion/10831508/piedmont-natural-gas-company-inc-v-blueroad-fontanel-llc/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "TN"}], "contractor_breach_negligence": [{"year": 2014, "outcome": "Global settlement reached on the eve of a trial expected to last over a year: MGM Resorts agreed to pay $153 million to Perini and $20 million to CityCenter/developer interests, which combined with roughly $85 million in prior insurance settlement proceeds brought CityCenter's total recovery on the Harmon defect claims to approximately $195 million.", "caseName": "CityCenter Holdings, LLC v. Tutor Perini Building Corp. (Harmon Hotel Construction Defect Litigation)", "citation": "Case No. A-10-627691-B, Eighth Judicial District Court, Clark County, Nevada", "sourceUrl": "https://www.enr.com/articles/2134-substantial-payouts-end-harmon-hotel-legal-battle-in-las-vegas", "confidence": "high", "dollarAmount": 195000000}, {"year": 2022, "outcome": "Global class-action settlement of $997 million (potentially rising to ~$1.1 billion with sale of the site), funded primarily by insurance policies plus a reported $400 million specifically contributed by the developer, contractor, engineer, and subcontractors on the adjacent Eighty Seven Park project.", "caseName": "In re: Champlain Towers South Collapse Litigation", "citation": "Case No. 2021-015089-CA-01, Circuit Court of the 11th Judicial Circuit, Miami-Dade County, Florida", "sourceUrl": "https://www.enr.com/articles/54112-possible-funding-sources-for-the-997m-champlain-towers-settlement", "confidence": "high", "dollarAmount": 997000000}, {"year": 2021, "outcome": "Settled for $17.5 million, funded by insurers of the developer/contractor/architect defendants and some subcontractors: $9.6 million cash for repairs plus an $8.5 million markdown on replacement sliding glass doors for all 39 units.", "caseName": "Regalia on the Ocean Condominium Association, Inc. v. Regalia Beach Developers, LLC et al.", "citation": "Filed 2018, Circuit Court of the 11th Judicial Circuit, Miami-Dade County, Florida (settled 2021, docket number not independently verified)", "sourceUrl": "https://www.burnsandwilcox.com/insights/construction-defects-lawsuit-leads-to-17-5-million-settlement-for-condo-association/", "confidence": "high", "dollarAmount": 17500000}, {"year": 2017, "outcome": "Jury awarded $3 million against the developer under the Consumer Fraud Act, automatically trebled to $9 million, plus attorneys' fees and costs; separately awarded $1 million against architect RTKL for professional negligence. The jury also pierced the corporate veil, holding parent Hovnanian Enterprises liable for the full judgment against its subsidiary.", "caseName": "Grandview at Riverwalk Port Imperial Condominium Association v. K. Hovnanian at Port Imperial Urban Renewal II, LLC et al.", "citation": "Hudson County Superior Court, New Jersey (Judge Jeffrey Jablonski), verdict June 1, 2017", "sourceUrl": "https://beckerlawyers.com/hudson-county-jury-awards-10m-in-consumer-fraud-case-against-builder/", "confidence": "high", "dollarAmount": 10000000}, {"year": 2018, "notes": "A full-cycle, appellate-affirmed defense win for a commercial property owner against a subcontractor's defective-installation work, including recovery of a substantial mechanic's-lien bond -- reported trial verdict was $3.1 million plus roughly $644,000 in prejudgment interest, though this citation's dollarAmount reflects only the $3.1M verdict figure since the interest award wasn't independently confirmed from the appellate opinion itself.", "outcome": "Subcontractor installed drywall and wallboard at what became 1 Hotel South Beach (Miami Beach); the property's later owners claimed the work used noncode-compliant materials and was incorrectly installed in bathrooms, causing water leaks and millions in damage. After the subcontractor filed a mechanic's-lien lis pendens, the case went to trial; the Miami-Dade Circuit Court entered final judgment for the property owners, awarded them attorney's fees and costs, and ordered return of the roughly $617,183 bond the owners had posted against the lien. The Third District Court of Appeal affirmed, denying the subcontractor's motion for judgment notwithstanding the verdict or a new trial.", "caseName": "JVP Drywall & Finish, Inc. v. 2377 Collins Resort, L.P.", "citation": "No. 3D17-2413 (Fla. 3d DCA Nov. 7, 2018)", "sourceUrl": "https://law.justia.com/cases/florida/third-district-court-of-appeal/2018/3d17-2413.html", "confidence": "high", "dollarAmount": 3100000, "jurisdiction": "FL"}, {"year": 2012, "notes": "Older than the file's other citations but real, well-documented, multifamily (condo association, not single-family), and a useful mid-range full-trial verdict data point between the small subcontractor-defect cases and the nine/ten-figure catastrophic-collapse outliers already in the file.", "outcome": "Condo association for a 55-and-older community in Odenton, MD sued NVR (parent of Ryan Homes) for faulty construction after leaks forced some homeowners to keep buckets in their units, brickwork failed to meet industry standards, and undersized AC units caused chronic cooling problems; the association also alleged NVR misrepresented the quality of the buildings during construction and failed to maintain them. Attorneys interviewed 26 homeowners before filing suit in 2011. After a five-week trial, the jury awarded $5.6 million in compensatory damages -- against a $10 million ask in the complaint.", "caseName": "Eden Brook Condominium, Inc. v. NVR, Inc. d/b/a Ryan Homes", "citation": "Circuit Court for Anne Arundel County, Maryland, jury verdict Nov. 19, 2012", "sourceUrl": "https://thedailyrecord.com/2012/11/20/odenton-condominiums-awarded-5-6m-damages-in-suit-against-ryan-homes/", "confidence": "high", "dollarAmount": 5600000, "jurisdiction": "MD"}, {"year": 2024, "notes": "Verified only via the prevailing law firm's own case-results page, not an independently pulled docket entry or reported opinion -- flagged accordingly. Framed as fraud + breach of contract rather than pure negligence, and the $1.6B figure includes fraud damages far beyond a repair-cost estimate, so it should be read as a new outlier ceiling for what a 'contractor breach' claim can be worth in the most egregious, bad-faith fact patterns -- not as a data point for calibrating the ordinary repairCostEstimate formula.", "outcome": "Developer BML Properties won a $1.6 billion trial verdict against China Construction America, Inc. (and related China State Construction entities) in New York's Commercial Division on fraud and breach-of-contract claims arising from the deeply troubled construction of the Baha Mar resort in Nassau, Bahamas -- a project plagued by years-long delays and defects that led to a bankruptcy filing before the resort finally opened.", "caseName": "BML Properties Ltd. v. China Construction America, Inc. (Baha Mar Resort Litigation)", "citation": "N.Y. Sup. Ct., Commercial Division (New York County), trial verdict Oct. 2024 (exact index number not independently confirmed from a primary court source)", "sourceUrl": "https://www.susmangodfrey.com/industry/construction-engineering/", "confidence": "medium", "dollarAmount": 1600000000, "jurisdiction": "NY"}, {"year": 2024, "notes": "Not a damages case -- a standing/doctrine case -- but directly relevant to appliesIf logic: it expands WHO can bring a contractor-breach claim (a common-interest-community association, not just the unit owners individually) for common-area and exterior defects, in a state that had not previously settled the question. Still pending further review at the Arizona Supreme Court as of this research.", "outcome": "Developer Hovnanian built and sold eighteen townhomes and conveyed the common areas to a homeowners' association, which was also given control over exterior maintenance of the units. The trial court granted summary judgment to Hovnanian, holding the association held no implied warranty of workmanship/habitability because it did not own the residences. The Arizona Court of Appeals vacated that ruling, holding A.R.S. Sec. 33-2002(A) lets the association invoke the implied warranty to sue the developer over defects in common-area structures and in the exterior portions of homes it is obligated to maintain. The Arizona Supreme Court granted review in 2025/2026.", "caseName": "Gallery Community Association v. K. Hovnanian at Gallery, LLC", "citation": "No. 1 CA-CV 23-0375 (Ariz. Ct. App. 2024); review granted, Ariz. Sup. Ct. No. CV-24-0252-PR", "sourceUrl": "https://www.azcourts.gov/Portals/0/21/0252%20op.pdf", "confidence": "high", "dollarAmount": null, "jurisdiction": "AZ"}, {"year": 2026, "notes": "Included for volume/severity of defect allegations in a recent large commercial high-rise, not for a dollar figure -- outcome is entirely undetermined at this stage. A companion suit (OKO Group v. its own insurers, seeking $22M) is pending over coverage for the same defects.", "outcome": "Condo association for the 249-unit, 60-story Missoni Baia tower in Edgewater (Miami) sued developer OKO Group, design firms Asymptote and Revuelta, general contractor Civic Construction, and 19 subcontractors, alleging 76 separate construction and design defects -- cracked floor slabs and columns, water intrusion into units/stairwells/the parking garage, defective fire-alarm devices and sprinklers, leaking pool plumbing, missing hot water in parts of the tower, and non-functioning elevators. No damages figure has been pled yet; the case is at an early pleading stage.", "caseName": "700 Edgewater Condominium Association, Inc. v. OKO Group, LLC et al. (Missoni Baia)", "citation": "Miami-Dade County Circuit Court, Florida, filed Jan. 30, 2026", "sourceUrl": "https://therealdeal.com/miami/2026/02/12/oko-group-accused-of-shoddy-work-at-missoni-baia-condos/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "FL"}, {"year": 2026, "notes": "Secondary reporting only; no docket number independently verified and outcome fully pending. Included to round out the sample of currently-active South Florida high-rise construction-defect litigation, alongside Missoni Baia above.", "outcome": "The buyer of a penthouse at the Arte Surfside condominium (purchased for approximately $33 million in 2020) sued developer Alex Sapir and joint-venture general contractor Americaribe-Moriarty, alleging glass and glazing defects and a mechanical system that allows water intrusion, causing excessive condensation throughout the building. No damages figure or resolution has been publicly reported.", "caseName": "Musallam / Veritas Capital Management, LLC v. Sapir / Americaribe-Moriarty (Arte Surfside Construction Defect Litigation)", "citation": "Miami-Dade County Circuit Court, Florida, reported 2026 (exact filing date and index number not independently confirmed)", "sourceUrl": "https://commercialobserver.com/2026/03/florida-condo-construction-lawsuits/", "confidence": "low", "dollarAmount": null, "jurisdiction": "FL"}, {"year": 2025, "notes": "A defense-favorable limiting doctrine directly relevant to the 'negligence' half of this claim type's label: in economic-loss-rule states, a plaintiff confined to a contractual relationship with the contractor may be unable to plead a tort/negligence claim at all (even for reckless deviation from plans), win or lose on the facts -- pushing realistic probability toward the bottom of the current [0.55, 0.8] range whenever the claim is pled purely in tort in such a jurisdiction.", "outcome": "HIVE Construction, general contractor for a Denver-area restaurant build-out, substituted plywood for one of two required layers of fire-rated drywall on a wall separating the kitchen and dining area, without seeking approval or a change order. A fire later started inside that wall, causing significant damage and forcing the restaurant to close. The property insurer, as subrogee, sued HIVE for negligence, alleging willful and wanton conduct. The Colorado Supreme Court held the economic loss rule bars the negligence claim because HIVE's duty not to deviate from the specified materials arose from the contract itself, not from an independent tort duty -- and that there is no willful-and-wanton exception to the economic loss rule in Colorado.", "caseName": "Mid-Century Insurance Co. v. HIVE Construction, Inc.", "citation": "No. 23SC267, 2025 CO 21 (Colo. Apr. 21, 2025)", "sourceUrl": "https://law.justia.com/cases/colorado/supreme-court/2025/23sc267.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "CO"}, {"year": 2024, "notes": "Reported only via the prevailing law firm's own case-result page -- no independently verifiable case name or docket. Included anyway because it is a real, well-documented recent outcome consistent in magnitude with the file's other post-occupancy latent-defect entries (roughly $111,000/unit here, in the same order of magnitude as Park Hill's per-unit figure), and because confidential arbitration -- not a published opinion -- is how a large share of real-world commercial construction-defect disputes actually resolve.", "outcome": "An 88-unit condominium association arbitrated construction-defect claims arising from vinyl window and sliding-glass-door frames that literally melted in the Palm Springs desert heat, plus failed deck waterproofing, corroded steel posts, significant stucco cracking, and water trapped behind stone veneer. The dispute settled/resolved in arbitration for $9.75 million.", "caseName": "Confidential Construction-Defect Arbitration re: 88-Unit Condominium, Palm Springs, CA", "citation": "Private arbitration (mediation failed first), resolved late 2024; case name, arbitrator, and docket not publicly disclosed", "sourceUrl": "https://actslaw.com/acts-law-attorneys-obtain-9-75-million-construction-defect-settlement/", "confidence": "low", "dollarAmount": 9750000, "jurisdiction": "CA"}], "development_agreement_breach": [{"year": 2010, "outcome": "A jury found the Town breached the development agreement. The trial court entered judgment for the developer, and the Court of Appeal affirmed both the compensatory damages award and a separate attorney-fee award, rejecting the Town's exhaustion and performance-excuse defenses.", "caseName": "Mammoth Lakes Land Acquisition, LLC v. Town of Mammoth Lakes", "citation": "191 Cal. App. 4th 435 (2010)", "sourceUrl": "https://caselaw.findlaw.com/court/ca-court-of-appeal/1551026.html", "confidence": "high", "dollarAmount": 30000000}, {"year": 2024, "outcome": "The arbitrator ruled the City breached the 2011 development agreement and assessed damages against the City several times larger than the City's entire annual general fund, prompting the City Council to vote 5-2 in January 2025 to pursue Chapter 9 municipal bankruptcy -- the first in Washington State since 1991.", "caseName": "City Heights Holdings LLC v. City of Cle Elum", "citation": "Arbitration award (Hon. Paris Kallas, ret., arbitrator), November 2024; related confirmation proceedings in King County Superior Court", "sourceUrl": "https://www.cascadepbs.org/politics/2025/02/how-22m-judgment-against-cle-elum-pushed-city-bankruptcy/", "confidence": "medium", "dollarAmount": 22000000}, {"year": 2016, "outcome": "The Commonwealth Court affirmed a judgment for the Township against the developer for the cost of remedying the defective public improvements, rejecting both the Township's larger, more speculative damages claim and the developer's statute-of-limitations defense under the nullum tempus doctrine (limitations periods do not run against a government enforcing public rights).", "caseName": "Township of Salem v. Miller Penn Development LLC", "citation": "Nos. 2083 C.D. 2015 & 2174 C.D. 2015 (Pa. Commw. Ct. May 26, 2016)", "sourceUrl": "https://caselaw.findlaw.com/court/pa-commonwealth-court/1736850.html", "confidence": "medium", "dollarAmount": 25558}, {"year": 2026, "outcome": "The developers and the City entered a development agreement for a downtown multi-use project (parking garage, residential tower, theater). The project was repeatedly delayed by title issues, design changes, and COVID-19; the City issued default notices in mid-2020 for missed construction deadlines, which triggered the project lender's foreclosure, and the City then purchased the garage at that foreclosure sale -- extinguishing the developers' debt but also cutting off their ability to complete the project and realize the deal's contractual upside. The Iowa Supreme Court affirmed the district court's finding that the CITY, not the developers, breached the agreement, and affirmed a damages award of over $4.3 million for the developers' lost contractual benefits. The Court separately reversed a companion judgment against the City for tortious interference with contract, holding a breach of contract alone -- without additional improper conduct -- does not support that separate tort claim.", "caseName": "5th & Walnut Parking, LLC, et al. v. City of Des Moines", "citation": "No. 24-1886 (Iowa June 12, 2026)", "sourceUrl": "https://storage.courtlistener.com/pdf/2026/06/12/5th_and_walnut_parking_llc_5th_and_walnut_tower_llc_5th_and_court_llc.pdf", "confidence": "high", "dollarAmount": 4300000}, {"year": 2025, "outcome": "COMPLEX, MULTI-LEVEL SAGA -- included for real downside-risk illustration, not a clean win/loss. PML agreed to grade and fill a 62-acre parcel and later convey it to the Village; performance broke down over permitting delays. Trial court (2020): found BOTH parties materially breached, but held the Village breached first (excusing PML's breach), and awarded PML ~$5.3M. Appellate court (2022): reversed -- held mutual material breach barred recovery for EITHER side. Illinois Supreme Court (2023): reversed again, adopting the 'partial-breach doctrine' (a party who continues performing after the other's material breach may still sue for damages, though it can be liable for its own breach too) -- remanded for both parties' damages to be determined and offset against each other. FINAL result (2025, on remand and second appeal): PML awarded $5,081,293 in damages -- but the Village was ALSO awarded $408,000 for two of PML's own breaches (failing to fund a draw-down account and failing to repair a road), netted against PML's recovery; PML was found the prevailing party overall and entitled to attorney fees for the entire litigation, including the earlier appeals. Real illustration that even a large, ultimately-successful developer claim against a municipality can face a substantial, legitimate offsetting counterclaim that meaningfully reduces net recovery -- not a clean win.", "caseName": "PML Development LLC v. Village of Hawthorn Woods", "citation": "Trial: Cir. Ct. Lake County, No. 15-CH-848; PML I: 2022 IL App (2d) 200779; PML II (Ill. Supreme Court): 2023 IL 128770; final: 2025 IL App (2d) 240191-U (Mar. 26, 2025)", "sourceUrl": "https://www.clausen.com/pml-development-v-village-of-hawthorn-woods-supreme-court-decision/", "confidence": "high", "dollarAmount": 5081293}, {"year": 2025, "notes": "REVERSE-DIRECTION citation: here the MUNICIPALITY is the one suing to enforce a development agreement, against a developer/foundation entity, and losing -- useful defensive precedent for a developer facing a municipality's enforcement claim, particularly where the parties later amended or superseded the original agreement's specific terms. Confirms that a later, more specific agreement provision governing the same subject matter can fully displace an earlier obligation, even one the municipality reasonably believed still applied.", "outcome": "A 1999 annexation/development agreement required the Foundation to donate a parcel to the Village if an NIU branch campus wasn't built there within 10 years. A 2005 amendment exchanged parcels and stated the new agreement's terms governed all donations and fees going forward, not the 1999 agreement's. When NIU never built the campus, the Village demanded the Foundation donate the parcel anyway; the Foundation refused, arguing the 2005 amendment eliminated that obligation. The circuit court dismissed the Village's specific-performance and unjust-enrichment claims with prejudice, and the Appellate Court affirmed.", "caseName": "Village of Hoffman Estates v. Northern Illinois University Foundation", "citation": "2025 IL App (1st) 231720-U (Apr. 17, 2025)", "sourceUrl": "https://www.dailyherald.com/20250418/news/hoffman-estates-loses-appeal-of-case-seeking-donation-of-20-acres-from-niu-foundation/", "confidence": "high", "dollarAmount": null, "jurisdiction": "IL"}, {"year": 2021, "notes": "Well-corroborated by multiple independent local news outlets (Minot Daily News, KX News, KFYR-TV) with a specific, consistent dollar figure, but no court docket/case number or written appellate opinion was located, so treat as a real, credible reported verdict rather than a citable published opinion.", "outcome": "The City sued its private development partner for breaching a series of 2011-2015 agreements (development agreement, disposition agreement, lease, and management agreement) covering two downtown mixed-use parking/retail/apartment structures, alleging Cypress failed to make required lease payments and breached construction obligations. Cypress counter-sued for over $50 million, alleging the City's own change in leadership caused it to abandon the project. After trial, the jury found FOR THE CITY and AGAINST the developer, awarding the City $2,442,479.94 in damages for unpaid lease payments and excess/remedial construction costs, and rejected Cypress's $50M+ counterclaim in its entirety. A clean, well-documented example of the reverse fact pattern from most of this claim type's other citations: here it is the MUNICIPALITY recovering from the DEVELOPER for the developer's own breach of a development-related agreement, not the other way around.", "caseName": "City of Minot v. Cypress Development", "citation": "North Central Judicial District Court, Ward County, N.D., jury verdict July 20, 2021 (docket number not independently confirmed)", "sourceUrl": "https://www.minotdailynews.com/news/local-news/2021/07/city-of-minot-wins-2-44-million-in-parking-ramp-dispute-with-cypress-development/", "confidence": "medium", "dollarAmount": 2442479, "jurisdiction": "ND"}, {"year": 2024, "notes": "dollarAmount reflects the County's current estimate of the total (uncapped) road-widening cost obligation the courts held the developer must bear -- it is a contractual cost-exposure figure vindicated against the developer, not a discrete compensatory-damages award, similar in spirit to how the file's existing W.J.F. Realty citation uses a 'total exposure' figure. This is a genuinely useful new addition because it is a CLEAN, FINAL loss for the developer on its own breach/interpretation theory -- directly responsive to the existing file note that no clean final loss for a developer's affirmative breach claim had yet been found. Corroborated across three independently-fetched sources: sjcitizen.com, the official St. Johns County government site (sjcfl.us), and (via WebSearch summary only, direct fetch blocked) floridapolitics.com.", "outcome": "Southeast Development Partners agreed, as part of a 2016 development agreement for its roughly 524-acre Grand Oaks mixed-use project (approved for up to 999 homes plus commercial and office space) in St. Johns County's World Golf Village area, to fund a widening of a 3-mile stretch of State Road 16, with the agreement stating a $15 million figure explicitly labeled as 'an estimate.' After a 2021 redesign requirement pushed the County's projected cost to more than $57-60 million, the developer sued, arguing its funding obligation was effectively capped near the original $15 million estimate and that the County itself had breached the agreement by demanding more; the County had withheld further plat and construction-plan approvals pending the developer's compliance. The district court ruled for the County on every count on September 13, 2024, holding the developer's obligation to fund 'all costs' of the road work was uncapped rather than limited to the original estimate, and upheld the County's authority to withhold further development approvals until the developer complied. The Eleventh Circuit affirmed nearly all of that ruling on August 7, 2026, agreeing Southeast Development Partners breached the agreement.", "caseName": "Southeast Development Partners, LLC v. St. Johns County, Florida", "citation": "No. 3:23-cv-00846 (M.D. Fla. Sept. 13, 2024), aff'd in relevant part, No. 24-13385 (11th Cir. Aug. 7, 2026)", "sourceUrl": "https://sjcitizen.com/road-warriors-st-johns-county-wins-60-million-showdown-with-developer/", "confidence": "high", "dollarAmount": 60000000, "jurisdiction": "FL"}, {"year": 2026, "notes": "This is a CLAIMED damages figure in a newly-filed, unresolved complaint, not an awarded or adjudicated amount -- included only to illustrate a real, currently-live, high-dollar development-agreement dispute fact pattern (a municipality allegedly reneging on/reinterpreting a recorded utility-service commitment tied to a development), not for calibration purposes until it resolves. Corroborated by multiple independent local outlets (The Augusta Press, Post and Courier/Aiken Standard, WRDW, HereAiken).", "outcome": "Crowell & Co., an Augusta-area developer, entered a 2020 utility-service and annexation agreement with the City of Aiken, South Carolina to provide water and sewer service to a planned 247-unit, roughly 60-acre residential subdivision on Toolebeck Road. In late 2025 the City told Crowell it would need to reapply for sewer access, taking the position that the 2020 agreement's service commitment had a two-year expiration; Crowell disputes that the recorded agreement contains any such term. Crowell filed suit on February 16, 2026 alleging breach of contract, claiming damages -- including loss of development value, lost profits from reduced density, reliance expenditures, increased costs, and delay damages -- believed to exceed $40 million. The case is newly filed and unresolved; no ruling, verdict, or settlement has been reported.", "caseName": "Crowell & Co., Inc. v. City of Aiken", "citation": "Complaint filed Feb. 16, 2026, Court of Common Pleas, Aiken County, S.C. (case pending; no ruling as of this research)", "sourceUrl": "https://theaugustapress.com/augusta-developer-suing-the-city-of-aiken-for-40-million/", "confidence": "medium", "dollarAmount": 40000000, "jurisdiction": "SC"}, {"year": 2025, "notes": "REVERSE-DIRECTION citation like the file's existing City of Minot and Village of Hoffman Estates entries: here the MUNICIPALITY is the one alleging a development agreement breach by a developer (via its own former official's alleged misconduct). No dollar figure was disclosed in the reporting located. Given today's date, the calendared August 2025 trial has very likely concluded one way or another by now, but this research round's tooling constraints (WebSearch budget exhausted, WebFetch to most legal-news aggregators and court sites blocked) prevented confirming the actual result -- flagged honestly rather than guessed.", "outcome": "The City of Bee Cave, Texas sued its former city manager, Clint Garza, along with several development companies, alleging Garza received cash payments and gifts from developers and then helped conceal from the City Council an industrial warehouse project built on land subject to a 2015 development agreement that had promised a mixed residential/commercial/recreational project at Highway 71 and Serene Hills Drive. The City alleges the warehouse use itself breached the binding development agreement, and that Garza left City employment for a job with a land developer the same month warehouse construction began. As of the most recent reporting located (May 2025), several developer defendants had moved to be dismissed from the case, with dismissal-motion hearings set for May 27, 2025 and a jury trial calendared for August 2025; this research could not confirm the case's ultimate outcome (verdict, dismissal, or settlement) because the session's search tooling was exhausted before a follow-up could be run.", "caseName": "City of Bee Cave v. Garza", "citation": "Travis County District Court, Tex.; dismissal hearings reported for May 27, 2025 and jury trial calendared for August 2025 as of the most recent reporting located (ultimate disposition not independently confirmed)", "sourceUrl": "https://www.fox7austin.com/news/bee-cave-warehouse-clint-garza-lawsuit-response", "confidence": "medium", "dollarAmount": null, "jurisdiction": "TX"}], "eminent_domain_attorney_fees": [{"year": 2015, "notes": "A real, Florida Supreme Court-level application of the fee-shifting mechanism this claim's eminentDomainAttorneyFees table already documents for Florida (Fla. Stat. Sec. 73.092(1), benefit-achieved formula) -- and an important refinement beyond the bare statute: where the condemning authority's OWN litigation conduct unreasonably drove up the owner's fees, a rigid benefit-achieved cap can be held unconstitutional as applied, entitling the owner to a fuller fee recovery than the base formula alone would yield. dollarAmount reflects the initial $816,000 award; the final, remanded figure (accounting for the excessive-litigation add-on) was not independently confirmed.", "outcome": "Authority's presuit written offer to purchase 9.81 acres was $4,914,221; the owner rejected it and the case proceeded to a condemnation trial, where the jury awarded $5.7 million -- roughly $800,000 above the offer. Under Fla. Stat. Sec. 73.092, the trial court initially awarded the owner $816,000 in attorney's fees. On further proceedings, the trial court found the Authority itself had caused 'excessive litigation' and held the standard benefit-achieved fee formula unconstitutional as applied, because it would have denied the owner full compensation net of fees. The Florida Supreme Court remanded for an evidentiary hearing to set total fees accounting for both the statutory benefit-achieved formula AND the portion of legal work attributable to the Authority's excessive litigation conduct.", "caseName": "Joseph B. Doerr Trust v. Central Florida Expressway Authority", "citation": "177 So. 3d 1209 (Fla. 2015)", "sourceUrl": "https://law.justia.com/cases/florida/supreme-court/2015/sc14-1007.html", "confidence": "high", "dollarAmount": 816000, "jurisdiction": "FL"}, {"year": 2025, "notes": "A commercial-property fee-shifting case with the full underlying record confirmed (initial offer, deposit, final pretrial offer, verdict, and fee award all independently verified from the opinion itself) -- a strong, current illustration of SDCL 21-35-23's >20%-above-offer trigger operating on real numbers, and of courts endorsing contingent-fee awards over rigid hourly billing in this practice area.", "outcome": "The City condemned two portions of a commercial property (housing the Alibi Bar & Grill) for a road-realignment project, initially offering $32,454 and depositing an appraised $51,647, later raising its pretrial offer to $250,000. A jury awarded Johnson Properties $382,600 in just compensation -- exceeding the City's final offer by more than 20%, the statutory trigger under SDCL 21-35-23. The circuit court awarded $139,724.60 in attorney's fees using a contingent-fee ('lift') methodology rather than a straight lodestar/hourly calculation, supported by affidavits that contingent fees (typically 25%-50%) are the customary arrangement in South Dakota eminent domain practice. The South Dakota Supreme Court affirmed, holding the circuit court did not abuse its discretion in either the methodology or the amount.", "caseName": "City of Sioux Falls v. Johnson Properties, LLC", "citation": "South Dakota Supreme Court, 2025 S.D. 66, Docket No. 30947 (argued Oct. 9, 2025; decided Nov. 19, 2025)", "sourceUrl": "https://ujs.sd.gov/media/muoemfqe/30947.pdf", "confidence": "high", "dollarAmount": 139725, "jurisdiction": "SD"}, {"year": 2025, "notes": "A striking, fully-verified real-world data point: the statutory fee award ($127,657.10) actually EXCEEDED the underlying $100,000 damages settlement -- a vivid illustration of how a state's percentage-above-offer fee-shifting trigger can produce a fee recovery larger than the compensation claim itself once the statutory threshold is crossed.", "outcome": "MnDOT condemned parcels (including one owned by Mike's Holiday) for a highway improvement project, with a final written pre-litigation offer of $14,600. The parties ultimately settled the underlying just-compensation claim for $100,000, after a commissioners' panel had valued the taking at over $200,000. Because the settlement exceeded both the $25,000 floor and MnDOT's last offer by more than 40%, Mike's Holiday was entitled to fees under Minn. Stat. section 117.031(a); the district court awarded $127,657.10 in fees and expenses (including fees incurred defending the condemnation petition itself), using the lodestar method. The Court of Appeals affirmed in full, rejecting MnDOT's arguments that the fee award improperly included fees unrelated to obtaining the final judgment.", "caseName": "State of Minnesota, by its Commissioner of Transportation v. David P. Williams, d/b/a Bear Track Outfitting Co., et al. (Mike's Holiday)", "citation": "Minnesota Court of Appeals, No. A24-1713 (filed Aug. 4, 2025)", "sourceUrl": "https://mn.gov/law-library-stat/archive/ctappub/2025/OPa241713-080425.pdf", "confidence": "high", "dollarAmount": 127657, "jurisdiction": "MN"}, {"year": 2025, "notes": "A useful loss/counterexample: illustrates that eminent-domain-adjacent fee-shifting statutes are typically tied tightly to a specific pleaded and prevailed-upon cause of action (here, inverse condemnation specifically), not triggered merely because a property/easement dispute involving a condemning-type authority exists.", "outcome": "In a dispute involving an easement and a counterclaim for declaratory/title relief, the property owners sought attorney's fees under Connecticut's inverse-condemnation fee-shifting statute (Conn. Gen. Stat. section 48-17b). The Appellate Court held the statute was inapplicable because the owners had neither pleaded an inverse condemnation claim in their counterclaim nor actually prevailed on one -- fee-shifting under that statute is tied to that specific cause of action, not to prevailing on a related property dispute generally. Fees were denied (and a separate fee argument under a different statute was deemed inadequately briefed and not considered).", "caseName": "Metropolitan District v. Mott", "citation": "Connecticut Appellate Court, No. AC46665 (filed Sept. 30, 2025)", "sourceUrl": "https://www.courtlistener.com/opinion/10679411/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "CT"}, {"year": 2025, "notes": "IMPORTANT CALIBRATION FLAG: this is a clean loss precisely because the condemnor exercised FEDERAL (not state) eminent-domain authority delegated under a federal statute (the Natural Gas Act). The specific district-court dollar figure that was vacated was not independently confirmed (multiple secondary sources describe the holding without repeating the number), so dollarAmount is left null, but the legal principle -- state fee-shifting statutes do NOT apply to federal-statute condemnations -- is confirmed by two independent secondary sources (FindLaw and Justia case summaries of the actual 8th Cir. opinion).", "outcome": "WBI Energy condemned a pipeline easement under the federal Natural Gas Act (15 U.S.C. Sec. 717f(h)) after negotiations with the landowning family failed. The parties eventually agreed on the amount of just compensation, but the district court separately awarded the landowners their attorney's fees, applying North Dakota's state-law condemnation fee-shifting rule. The Eighth Circuit VACATED the fee award, holding that when a private company exercises federal eminent-domain power delegated under the Natural Gas Act, the compensation due is governed exclusively by the federal Fifth Amendment 'just compensation' standard -- which does not include attorney's fees absent an express federal statute -- so state-law fee-shifting statutes cannot be borrowed to award fees in NGA condemnations.", "caseName": "WBI Energy Transmission, Inc. v. 189.9 Rods, More or Less, in Township 149 North", "citation": "132 F.4th 1000, No. 24-1693 (8th Cir. Mar. 24, 2025)", "sourceUrl": "https://caselaw.findlaw.com/court/us-8th-circuit/117089067.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal (8th Cir., ND pipeline condemnation)"}, {"year": 2026, "notes": "Directly confirmed via the Supreme Court's own docket page for No. 25-159 (case name, cert-granted date, lower-court docket number, and argument date all matched the underlying 8th Cir. case above) and independently corroborated by inversecondemnation.com's June 29, 2026 post title ('We're Going To Find Out Whether Attorneys Fees Are Part Of Just Compensation In Natural Gas Act Takings'). This is a MAJOR pending development for this claim type -- whatever the Court decides will directly determine whether the calculator's fee-shifting logic can ever apply to a federally-authorized (NGA-type) condemnor, and the file's note/damages formula should flag this pending case explicitly.", "outcome": "The landowners petitioned for certiorari after the Eighth Circuit vacated their attorney-fee award in the same WBI Energy Transmission condemnation described above. The Supreme Court granted certiorari on the question of whether attorney's fees are part of the 'just compensation' owed (or otherwise recoverable) in Natural Gas Act condemnations, with the United States filing an amicus brief and significant amicus participation from property-rights and state-government organizations. Argument is scheduled for November 9, 2026; no decision had issued as of this research.", "caseName": "Hoffmann v. WBI Energy Transmission, Inc. (cert. granted)", "citation": "U.S. Supreme Court, No. 25-159 (cert. granted June 29, 2026; oral argument set for Nov. 9, 2026)", "sourceUrl": "https://www.supremecourt.gov/DocketPDF/25/25-159/362295/20250604142018043_Appendix_Application%20for%20Extension%20of%20Time_FINAL.pdf", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal (U.S. Supreme Court, reviewing 8th Cir. No. 24-1693)"}, {"year": 2013, "notes": "This is the foundational Minnesota Supreme Court authority the file's existing 'Mike's Holiday' MnDOT citation and the new Schaffer/Hamlin citation below both directly cite and apply -- it establishes that Minnesota's 40%-above-offer trigger (and by extension, other states' similar percentage-above-offer triggers) is only a threshold gate, with the ultimate dollar award turning on an independent, unpredictable lodestar calculation that can land either above OR below the landowner's actual fee-agreement amount. Older than the 3-5 year window requested, but included because it is the direct precedent underlying the two more recent Minnesota cases below and is still the controlling rule.", "outcome": "In a Minnesota condemnation proceeding where the landowner cleared the Minn. Stat. Sec. 117.031(a) 40%-above-offer statutory threshold, the landowner's attorney requested $217,991.45 in fees. The district court, applying the lodestar method, reduced that request and awarded $161,964.50. The Minnesota Supreme Court affirmed, holding that meeting the 40% statutory threshold establishes only ELIGIBILITY for a fee award, not the amount -- the lodestar 'reasonable fee' inquiry (hours x reasonable rate, adjusted for the case-specific factors) is a wholly separate determination that can produce an award well below what the landowner's own fee agreement would have produced.", "caseName": "County of Dakota v. Cameron", "citation": "839 N.W.2d 700 (Minn. 2013)", "sourceUrl": "https://www.madgettlaw.com/news/minnesota-eminent-domain-minimum-compensation-117/", "confidence": "medium", "dollarAmount": 161965, "jurisdiction": "MN"}, {"year": 2023, "notes": "Read directly from the court's own published opinion (full text obtained and confirmed). This is the mirror image of County of Dakota v. Cameron above -- together the two cases show the lodestar method can push a Minnesota fee award either well BELOW (Cameron) or well ABOVE (this case, 4x) the landowner's actual contingency-fee exposure, confirming fee awards under a percentage-above-offer trigger are genuinely unpredictable in magnitude even once the threshold is met.", "outcome": "MnDOT condemned part of Hamlin's Dakota County land for a highway, offering $43,000; court-appointed commissioners valued the taking at $92,000 (about 114% above MnDOT's final offer), triggering Minn. Stat. Sec. 117.031(a). Hamlin's contingency-fee agreement (one-third of the amount above the final offer) would have entitled his attorney to only $16,333.33, but Hamlin sought $177,433.50 in fees plus $34,127.83 in appraisal/expert costs. Applying the lodestar method (a $325 reasonable hourly rate x 194.5 reasonable hours), the district court awarded $63,228 in attorney's fees -- nearly FOUR TIMES what the contingency agreement would have paid -- plus $24,049.98 in undisputed appraisal/expert costs and disbursements. The Court of Appeals affirmed in full, rejecting MnDOT's argument that section 117.031(a) caps fee awards at the landowner's actual contractual fee exposure.", "caseName": "State of Minnesota, by its Commissioner of Transportation v. David J. Schaffer, et al. (Joseph Hamlin)", "citation": "Minnesota Court of Appeals, No. A23-0036 (filed Aug. 7, 2023)", "sourceUrl": "https://mn.gov/law-library-stat/archive/ctappub/2023/OPa230036-080723.pdf", "confidence": "high", "dollarAmount": 63228, "jurisdiction": "MN"}, {"year": 2022, "notes": "No dollar figure was disclosed in available secondary reporting on this case. Included because it identifies a narrow but real, federally-applicable exclusion from fee-shifting recovery (attorney-spouse/pro se litigants) that is distinct from -- and a useful complement to -- the state-statute-threshold mechanics the file's existing eminentDomainAttorneyFees table otherwise documents.", "outcome": "In a rails-to-trails inverse-condemnation class action in Washington State, a husband-and-wife pair of joint property owners were both class members; the husband was also the couple's attorney of record. After the case settled, the wife sought to recover attorney's fees under the Uniform Relocation Assistance Act (URA), the federal fee-shifting statute that applies to many federal takings/condemnation matters. The Federal Circuit held that URA fees -- like fees under other federal fee-shifting statutes -- are not recoverable where the attorney performing the work is also a party (here, the wife's co-owner spouse), rejecting recovery for that portion of the claim while leaving the pro se litigant's separate, non-fee expenses recoverable.", "caseName": "Haggart v. United States", "citation": "Federal Circuit, No. 21-1660 (decided June 22, 2022)", "sourceUrl": "https://www.eminentdomainreport.com/recovery-of-attorneys-fees-not-permissible-for-lawyer-spouse-plaintiffs-under-uniform-relocation-act", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (Fed. Cir., Rails-to-Trails/Uniform Relocation Act)"}], "state_cleanup_consent_decree": [{"year": 2025, "outcome": "Proposed Judicial Consent Order: Solvay to pay $75 million for natural resource damages, $100 million to fund NJDEP-directed PFAS remediation projects in the area, and post $214 million in financial assurance to guarantee completion of its own ongoing remediation obligations (total $393 million).", "caseName": "New Jersey Dep't of Environmental Protection v. Solvay Specialty Polymers USA, LLC", "citation": "Proposed Judicial Consent Order, NJ state enforcement action (West Deptford PFAS matter)", "sourceUrl": "https://www.njoag.gov/attorney-general-platkin-and-dep-commissioner-latourette-announce-proposed-settlement-with-solvay-polymers-regarding-forever-chemical-pollution-in-and-around-west-deptford/", "confidence": "high", "dollarAmount": 393000000}, {"year": 2025, "outcome": "After selling the property to a third party in July 2025 (who separately agreed with NJDEP to complete remediation and pay outstanding fees), Sigma Realty and its owners paid a $117,500 civil penalty to resolve the enforcement lawsuit.", "caseName": "New Jersey Dep't of Environmental Protection v. Sigma Realty, Inc.", "citation": "NJDEP civil enforcement action, filed 2022, settled 2025 (Ewing Township, Mercer County, NJ)", "sourceUrl": "https://www.njoag.gov/ag-platkin-and-dep-commissioner-latourette-announce-resolution-of-two-environmental-lawsuits-and-the-filing-of-six-new-enforcement-actions-including-four-in-environmental-justice-communities/", "confidence": "high", "dollarAmount": 117500}, {"year": 2023, "outcome": "$1.7 million settlement requiring civil penalties plus employment of an environmental compliance coordinator and ongoing annual compliance reporting.", "caseName": "People of the State of California v. Bay Area/Diablo Petroleum Co. (dba Golden Gate Petroleum), et al.", "citation": "Civil complaint filed 2018; settlement announced Mar. 6, 2023 (Northern California)", "sourceUrl": "https://www.oag.ca.gov/news/press-releases/attorney-general-bonta-announces-17-million-settlement-five-gas-station-owners", "confidence": "high", "dollarAmount": 1700000}, {"year": 2025, "outcome": "$85,000 civil administrative penalty docketed as a judgment against the Knapp estate/heirs.", "caseName": "New Jersey Dep't of Environmental Protection v. Estate of Kenneth Knapp / Solomon Dwek (Chatsworth Deli site)", "citation": "NJDEP civil enforcement action, Woodland Township, Burlington County, NJ", "sourceUrl": "https://www.njoag.gov/ag-platkin-and-dep-commissioner-latourette-announce-resolution-of-two-environmental-lawsuits-and-the-filing-of-six-new-enforcement-actions-including-four-in-environmental-justice-communities/", "confidence": "medium", "dollarAmount": 85000}, {"year": 2026, "notes": "Described by NJ's AG as the largest environmental recovery in state history. Encompasses/supersedes the earlier-announced standalone 3M settlement (up to $450 million, announced May 13, 2025, covering Chambers Works and Parlin plus the statewide PFAS directive) -- do not double-count both as separate benchmark data points; this $2.5B figure is the final, court-approved combined total.", "outcome": "Federal court gave final approval to two combined settlements, together valued at approximately $2.5 billion, resolving New Jersey's long-running PFAS natural-resource-damage and remediation claims against DuPont-family entities (~$2 billion) and 3M (~$450 million) arising from decades of PFAS manufacturing at four industrial sites: Pompton Lakes Works (Passaic County), Parlin (Middlesex County), Repauno (Gloucester County), and Chambers Works (Salem County). Breakdown: up to $795 million to a PFAS abatement fund, up to $365 million in natural resource damages, up to $1.2 billion in remediation funding (with a $475 million reserve), and roughly $195 million in legal fees/costs, paid out via annual disbursements over 25 years.", "caseName": "State of New Jersey, et al. v. E.I. du Pont de Nemours & Co. (n/k/a EIDP, Inc.), The Chemours Co., DuPont Specialty Products USA, LLC, Corteva Inc., DuPont de Nemours, Inc., and 3M Co.", "citation": "Federal court approval of two combined consent judgments, D.N.J., approved Aug. 7, 2026", "sourceUrl": "https://www.njoag.gov/federal-court-approves-historic-pfas-settlements-valued-at-approximately-2-5-billion/", "confidence": "high", "dollarAmount": 2500000000, "jurisdiction": "NJ (federal court approval)"}, {"year": 2025, "outcome": "$49.5 million settlement ($45 million in natural resource damages plus $4.5 million in past remediation costs) for a nearly 10,000-acre TCE/PCE groundwater plume (once nine miles long) under Pohatcong Valley, Warren County (Washington Township, Washington Borough, Franklin Township, Greenwich Township), which reached two public water-supply wells and multiple private residential wells. Pechiney Plastic Packaging, Inc. bears the large majority (~$43.9 million of NRD plus most cleanup costs); Bristol Myers Squibb pays the balance (~$1.1 million NRD plus $179,000 past costs). Original state lawsuit filed in 2018.", "caseName": "New Jersey Dep't of Environmental Protection v. Pechiney Plastic Packaging, Inc., Bristol Myers Squibb, Citigroup, MRC Holdings, Rexam Beverage Can Co., and Albea Americas, Inc. (Pohatcong Valley Groundwater Contamination Site)", "citation": "Proposed Consent Judgment, published N.J. Register Nov. 17, 2025; announced Nov. 24, 2025 (public comment through Jan. 16, 2026)", "sourceUrl": "https://www.njoag.gov/ag-platkin-and-dep-commissioner-latourette-announce-49-5-million-settlement-to-resolve-pohatcong-valley-groundwater-contamination/", "confidence": "high", "dollarAmount": 49500000, "jurisdiction": "NJ"}, {"year": 2026, "notes": "A close California analog to the existing NJ small-dry-cleaner penalty data points (Sigma Realty $117,500; Knapp estate $85,000) and to the Golden Gate Petroleum gas-station action already in this claim type's sample -- confirms the smallCommercialStateEnforcementPenalty-style range ($85K-$120K) generalizes beyond New Jersey. The source page itself could not be re-fetched directly in this session (blocked); this entry relies on a corroborating secondary search summary of the same DTSC release and should be spot-checked before heavy reliance.", "outcome": "DTSC secured more than $100,000 (reported as $100,800) in penalties from the current owners and former operators of a Bay Area dry-cleaning business for cleanup violations tied to legacy solvent (PCE-type) contamination.", "caseName": "California Department of Toxic Substances Control settlement \u2014 former Bay Area dry cleaner ('Omo's')", "citation": "DTSC administrative settlement, Bay Area, CA, announced March 26, 2026", "sourceUrl": "https://dtsc.ca.gov/2026/03/26/dtsc-secures-more-than-100000-settlement-with-former-bay-area-dry-cleaner-for-cleanup-violations/", "confidence": "medium", "dollarAmount": 100800, "jurisdiction": "CA"}, {"year": 2025, "notes": "Specific contamination site and full underlying facts were not disclosed in the source reviewed -- included as a real, sourced dollar figure illustrating that state environmental recoveries increasingly run through bankruptcy claims processes (an important collections-risk factor this claim type doesn't currently model), not as a fully-documented case study. Verify against the underlying bankruptcy docket before relying on it for anything beyond the dollar figure.", "outcome": "New Jersey recovered $1,667,830.29 from Presperse Corporation via a proof-of-claim filed in what appears to be a bankruptcy/creditor proceeding, as part of the state's broader $193 million in total 2025 civil-enforcement recoveries (environmental and non-environmental combined).", "caseName": "New Jersey civil enforcement recovery \u2014 Presperse Corporation (bankruptcy proof-of-claim)", "citation": "NJ AG 2025 civil-enforcement recoveries summary, announced July 22, 2026", "sourceUrl": "https://www.njoag.gov/ag-davenport-2025-state-recoveries-reach-193-million/", "confidence": "low", "dollarAmount": 1667830.29, "jurisdiction": "NJ"}, {"year": 2025, "notes": "IMPORTANT CAVEAT: this appears to be DISTINCT from the $393 million Solvay Specialty Polymers West Deptford PFAS consent order already cited in this claim type's existing sample (different dollar figure, different associated company name 'Arkema,' different document date) -- but the source reviewed did not disclose the underlying site or full case name clearly enough to confirm it is not somehow a partial/duplicate reference to the same overall Solvay PFAS matter. Flagged as low confidence and should be independently verified against NJDEP's site-specific settlement records before being relied upon as a separate data point.", "outcome": "$33,950,000 recovered under a Judicial Consent Order involving Solvay/Arkema, referenced in New Jersey's 2025 civil-enforcement recoveries summary.", "caseName": "New Jersey civil enforcement recovery \u2014 Solvay/Arkema Judicial Consent Order", "citation": "Arkema Judicial Consent Order, NJ, court document dated June 30, 2025; reported in NJ AG's 2025 recoveries summary (July 22, 2026)", "sourceUrl": "https://www.njoag.gov/ag-davenport-2025-state-recoveries-reach-193-million/", "confidence": "low", "dollarAmount": 33950000, "jurisdiction": "NJ"}], "variance_permit_denial_appeal": [{"year": 2013, "outcome": "The Court of Appeal affirmed a damages award against the County for the temporary regulatory-taking effect of its erroneous permit-extension denial, plus attorney's fees; the California Supreme Court denied the County's petition for review (6-0), leaving the award intact.", "caseName": "Lockaway Storage v. County of Alameda", "citation": "216 Cal. App. 4th 161 (2013)", "sourceUrl": "https://www.counties.org/post/lockaway-storage-v-county-alameda-s211470", "confidence": "high", "dollarAmount": 1700000}, {"year": 2023, "outcome": "The Court of Appeals reversed, holding the Board misinterpreted the ordinance and that ambiguity in a billboard-permitting ordinance must be resolved in favor of the free use of property; the court remanded with instructions that the permit be issued.", "caseName": "Sam Commercial Properties LLC v. Town of Mooresville", "citation": "No. COA22-1006 (N.C. Ct. App. Nov. 7, 2023)", "sourceUrl": "https://caselaw.findlaw.com/court/nc-court-of-appeals/115416824.html", "confidence": "high", "dollarAmount": null}, {"year": 2025, "outcome": "The Appellate Division upheld the Board's determination as having a rational basis and not being arbitrary and capricious, denying the petitioner's Article 78 challenge to the permit denial.", "caseName": "Matter of Franklin Sq. Realty Assoc., LLC v. Board of Appeals of the Town of Hempstead", "citation": "2025 NY Slip Op 02065 (App. Div., 2d Dep't 2025)", "sourceUrl": "https://www.nycourts.gov/reporter/3dseries/2025/2025_02065.htm", "confidence": "high", "dollarAmount": null}, {"year": 2026, "outcome": "The Court of Appeals reversed, holding the City Council's denial violated its own ordinance and was arbitrary and made without reason, and remanded for the City to reconsider the application under the correct standard.", "caseName": "The Smoking Tree LLC (Jacob Schlichter) v. City of Albert Lea", "citation": "Minnesota Court of Appeals, decided May 18, 2026 (unpublished)", "sourceUrl": "https://www.startribune.com/albert-lea-cannabis-business-appeals-court-overturn-rejection-smoking-tree/601847996", "confidence": "medium", "dollarAmount": null}, {"year": 2026, "notes": "A landmark, state-supreme-court-level doctrinal shift that raises the bar for a specific, common category of variance application (inherently beneficial uses, e.g. affordable housing, schools, hospitals, houses of worship) in New Jersey -- applicants can no longer rely on public-benefit showings alone. This should push variance_permit_denial_appeal's baseProbability toward the lower end of its range for New Jersey inherently-beneficial-use applications specifically, until the applicant's own facts clearly satisfy the new independent zoning-plan-consistency requirement.", "outcome": "The New Jersey Supreme Court modified the long-standing Sica v. Board of Adjustment of Wall, 127 N.J. 152 (1992), test for inherently-beneficial-use variances. Under the revised standard, before the traditional balancing of positive and negative criteria, the applicant must now separately and affirmatively show the variance 'will not substantially impair the intent and purpose of the zoning plan and zoning ordinance' -- an independent showing beyond simply proving public benefit and no substantial detriment.", "caseName": "Monarch Communities, LLC v. Township of Montville", "citation": "A-70-24 (090407) (N.J. July 13, 2026)", "sourceUrl": "https://www.njcourts.gov/system/files/court-opinions/2026/a_70_24.pdf", "confidence": "high", "dollarAmount": null, "jurisdiction": "NJ"}, {"year": 2025, "notes": "Confirmed via the court's own published opinion and independently via Justia/Casemine case summaries.", "outcome": "The Twelfth District Court of Appeals reversed the Butler County Court of Common Pleas's affirmance of the Zoning Board's denial of a variance, holding the common pleas court abused its discretion by crediting three of the Board's stated statutory criteria for denial while entirely failing to weigh four other statutory factors that favored granting the variance. The court remanded with instructions that the trial court properly weigh the one valid factor supporting denial against the multiple factors favoring approval -- an interim procedural win for the property owner (variance not yet finally granted, but the denial could not stand on the record as analyzed).", "caseName": "Calista Enterprises, L.L.C. v. Oxford Board of Zoning Appeals", "citation": "2025-Ohio-1692 (Ohio Ct. App., 12th Dist., Butler County, No. CA2024-09-116, May 12, 2025)", "sourceUrl": "https://www.supremecourt.ohio.gov/rod/docs/pdf/12/2025/2025-Ohio-1692.pdf", "confidence": "high", "dollarAmount": null, "jurisdiction": "OH"}, {"year": 2024, "outcome": "The Commonwealth Court affirmed the trial court's reversal of the Zoning Hearing Board's denial of a dimensional variance for 7.5-foot side yards (vs. the required 15 feet) on a small nonconforming residential lot. The court held the parcel had not merged with adjacent commonly-owned parcels under the merger doctrine (a garden and doghouse did not constitute the kind of intensive, unified use required for merger), and that the lot's nonconforming, undersized status created a genuine, non-self-imposed unnecessary hardship justifying the variance. Property owner win; variance ultimately granted.", "caseName": "Craft Custom Homes, LLC v. Zoning Hearing Board of Newtown Township", "citation": "2025 Pa. Commw. Unpub. LEXIS 27 (Pa. Commw. Ct., Nov. 7, 2024)", "sourceUrl": "https://nochumson.com/resources/commonwealth-court-overturns-zoning-boards-denial-based-on-merger-doctrine-and-unnecessary-hardship-questions", "confidence": "high", "dollarAmount": null, "jurisdiction": "PA"}, {"year": 1996, "notes": "Older landmark-level New York area-variance case included because it is a frequently-cited, clean example of the 'community opposition alone is not substantial evidence' doctrine that recurs across many modern variance appeals; full case caption (which town/board) not independently confirmed beyond the citation itself.", "outcome": "In an Article 78 proceeding, the Appellate Division annulled the Zoning Board's denial of an area variance, holding the denial was arbitrary and capricious and unsupported by substantial evidence because the Board failed to actually conduct the statutorily-required balancing test under Town Law Section 267-b(3) (weighing benefit to the applicant against detriment to the neighborhood) and instead based its denial on generalized community opposition. Property owner win.", "caseName": "D'Angelo v. Zoning Board", "citation": "229 A.D.2d 945, 645 N.Y.S.2d 378 (N.Y. App. Div., 4th Dep't, 1996)", "sourceUrl": "https://www.courtlistener.com/opinion/6139042/dangelo-v-zoning-board/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 2025, "notes": "Case name and disposition ('affirmed') cross-referenced from a secondary legal-search summary and the court's own docket-numbered opinion file, but the full opinion text could not be directly read to confirm every detail -- treat the citation and outcome direction as reliable, but the fact narrative as unconfirmed.", "outcome": "The Commonwealth Court affirmed the Zoning Hearing Board's denial of a variance application, siding with the municipality. Included specifically as a counterweight to the mostly-successful appeals above, since a search focused only on 'variance reversed' language would otherwise skew the sample toward property-owner wins.", "caseName": "Palmer v. Susquehanna Township Zoning Hearing Board", "citation": "No. 1235 C.D. 2023 (Pa. Commw. Ct., Feb. 4, 2025)", "sourceUrl": "https://wwwsecure.pacourts.us/assets/opinions/Commonwealth/out/1235CD23_2-4-25.pdf?cb=1", "confidence": "medium", "dollarAmount": null, "jurisdiction": "PA"}, {"year": 2026, "notes": "Could not directly retrieve and read the full opinion (site blocked automated fetch); outcome description is reconstructed from secondary search snippets and may not capture the court's final disposition precisely. Include with caution -- useful mainly to illustrate that a board's refusal to decide a variance application at all is itself litigable, not as a clean merits data point.", "outcome": "A historic inn's owner sought variances for a pool, spa, and patio as part of a larger building-addition application; the Village's ZBA approved the larger addition (including ADA access) but took the position that the accessory-structure area variances for the pool/spa/patio were beyond its authority to decide, effectively refusing to rule on that portion of the application. The court held that refusing to adjudicate the pool variances on the merits would leave the applicant with no avenue for review, and addressed the resulting ripeness/procedural posture in the applicant's favor.", "caseName": "Huntting Hospitality LLC v. Zoning Board of Appeals of the Village of East Hampton", "citation": "2026 NY Slip Op 50502(U) (N.Y. Sup. Ct., Suffolk Cnty., decided ~April 2026)", "sourceUrl": "https://www.nycourts.gov/reporter/current/3dseries/2026/2026_50502.shtml", "confidence": "low", "dollarAmount": null, "jurisdiction": "NY"}], "design_professional_malpractice": [{"year": 2019, "outcome": "Complaint sought $10.7 million for breach of contract including design negligence and delay-related costs; final resolution/settlement terms not disclosed in available reporting.", "caseName": "Trustees of Princeton University v. Tod Williams Billie Tsien Architects, LLP et al.", "citation": "No. 3:19-cv-21248, U.S. District Court for the District of New Jersey, filed December 2019", "sourceUrl": "https://www.dezeen.com/2020/01/02/princeton-lawsuit-tod-williams-billie-tsien-university-building/", "confidence": "medium", "dollarAmount": 10700000}, {"year": 2018, "outcome": "Clark and Perkins Eastman filed and then jointly dismissed their respective lawsuits in 2020, settling on confidential/undisclosed terms.", "caseName": "Clark Construction Group, LLC v. Perkins Eastman DC, PC", "citation": "U.S. District Court for the District of Columbia, filed March 9, 2018; dismissed by joint stipulation 2020", "sourceUrl": "https://www.constructiondive.com/news/clark-settles-5m-the-wharf-dc-lawsuit-with-perkins-eastman-for-undisclosed/573619/", "confidence": "medium", "dollarAmount": 5000000}, {"year": 2024, "outcome": "CONFIRMED FINAL settlement, not just an amount sought: KDA Architecture agreed to pay the school district $1.7 million within 30 days of settlement approval over a design defect in a ~750-foot decorative wall -- a water-resistant barrier melted after interior temperatures exceeded the manufacturer's 180-degree limit, causing 23 of 26 windows to leak and leading to mold. The contractor and subcontractors who built the wall separately settled for an additional $1.1 million.", "caseName": "Yakima School District No. 7 v. KDA Architecture, PLLC (Eisenhower High School 'Blue Wall')", "citation": "Yakima County Superior Court, Washington, settlement announced February 2024", "sourceUrl": "https://www.yakimaherald.com/news/local/yakima-school-district-reaches-1-7-million-settlement-with-architects-over-ikes-blue-wall/article_4259a101-fb1f-5940-98cd-3f8533460518.html", "confidence": "high", "dollarAmount": 1700000}, {"year": 2010, "outcome": "Settled after roughly three years of litigation over persistent leaks, cracking masonry, mold, and drainage problems at the ~$300 million Stata Center. Per Gehry's own public statement, NO MONEY changed hands in the settlement -- terms instead centered on collaborative funding/responsibility for repairs. Included as a real data point that even a design-malpractice claim against a globally prominent architect over well-documented, expensive defects can resolve with a confirmed $0 direct cash recovery to the owner.", "caseName": "Massachusetts Institute of Technology v. Frank O. Gehry, Gehry Partners, LLP, and Skanska USA Building Inc. (Stata Center)", "citation": "Massachusetts Superior Court (Middlesex County), filed 2007; case reported settled Feb. 5, 2010, dismissed March 8, 2010", "sourceUrl": "https://thetech.com/2010/03/19/statasuit-v130-n14", "confidence": "high", "dollarAmount": 0}, {"year": 2015, "outcome": "Cornell alleged 'architectural malpractice' -- inherently flawed, materially defective expansion designs causing structural deficiencies, roof cavities, and ceiling cracks -- and claimed at least $1.1 million in resulting damages. Multiple secondary sources describe the firm as having ultimately paid this amount, but a primary settlement agreement or final docket entry confirming that figure as an actual payment (rather than just the amount originally claimed) was not independently located.", "caseName": "Cornell University v. Pei Cobb Freed & Partners Architects LLP (Herbert F. Johnson Museum of Art expansion)", "citation": "N.Y. Sup. Ct., filed May 2015 (exact index number not independently confirmed)", "sourceUrl": "https://www.artforum.com/news/cornell-university-sues-i-m-peis-firm-over-campus-museums-design-224103/", "confidence": "medium", "dollarAmount": 1100000}, {"year": 2006, "notes": "Real, well-documented filed suit against a nationally prominent architecture firm and design-builder, with specific and credible defect allegations (sightlines, seating design, budget overrun), but the final resolution amount is not independently confirmed beyond a general 'Center won' characterization in secondary compilation sources -- treat the outcome direction as more reliable than any specific dollar figure, since none is included here. A useful addition to this claim type's sample regardless, since it involves a design-builder (Fluor) as co-defendant alongside the architect, a structure not otherwise represented in this claim type's citations.", "outcome": "The Center sued architect Cesar Pelli's firm and design-builder Fluor Corp. over the Renee and Henry Segerstrom Concert Hall, alleging design and construction errors including obstructed sightlines to the stage and inadequately designed seating, plus a roughly $40 million budget overrun (from an original ~$200M budget to ~$240M). Most defects were remedied at a cost of millions of dollars; some were reported as irreversible. Secondary sources report the Center ultimately prevailed, though the specific settlement terms or judgment amount were not independently confirmed.", "caseName": "Orange County Performing Arts Center v. Cesar Pelli (Pelli Clarke Pelli) and Fluor Corp.", "citation": "Orange County Superior Court, CA, filed Aug. 17, 2006", "sourceUrl": "https://playbill.com/article/orange-county-pac-sues-architect-cesar-pelli-fluor-corp", "confidence": "medium", "dollarAmount": null, "jurisdiction": "CA"}, {"year": 2023, "notes": "Outcome undisclosed/unconfirmed -- treat the $8M figure as the amount sought, not a resolved recovery.", "outcome": "The hospital sued its architect, CannonDesign, for breach of contract, negligence, and malpractice over the design of its new facility (opened 2019), alleging Cannon designed non-load-bearing exterior walls using flammable cedar shingles to satisfy the local Historic District Commission -- a fire-code violation that prevented the hospital from obtaining full Medicare/Medicaid licensure and forced it to operate under temporary waivers while redesigning and rebuilding the walls at a cost of millions. The hospital sought at least $8 million. No settlement or judgment has been located in available reporting.", "caseName": "Nantucket Cottage Hospital v. CannonDesign, Inc.", "citation": "Suffolk Superior Court, Massachusetts, complaint filed June 2023 (exact docket number not independently confirmed)", "sourceUrl": "https://nantucketcurrent.com/news/hospital-sues-architects-of-its-new-facility-for-8-million", "confidence": "medium", "dollarAmount": 8000000, "jurisdiction": "MA"}, {"year": 2024, "notes": "A large, recent, commercial multifamily design-error claim with a specific, verifiable defect mechanism (missing sump-pump specification) rather than a vague 'design was bad' allegation -- useful even though pending.", "outcome": "A Bozzuto affiliate sued Boston-based Icon Architecture over dozens of alleged design errors at The Abby, a 610-unit mixed-use development next to the North Quincy MBTA station, claiming more than $3 million in resulting damages. Among the specific errors alleged: construction drawings for elevator pits in two buildings failed to specify code-required sump pumps, requiring demolition and re-pour of already-completed concrete slabs. Icon's president publicly disputed the allegations. Outcome/resolution not yet reported.", "caseName": "Bozzuto affiliate v. Icon Architecture, Inc. (The Abby, North Quincy)", "citation": "Massachusetts state court, filed April 2024 (exact venue/docket number not independently confirmed)", "sourceUrl": "https://www.bisnow.com/boston/news/construction-development/bozzuto-sues-design-firm-over-alleged-errors-that-led-to-3m-in-damages-at-quincy-site-123927", "confidence": "medium", "dollarAmount": 3000000, "jurisdiction": "MA"}, {"year": 2023, "notes": "The most severe design/inspection-malpractice fact pattern found for this claim type -- deaths and mass displacement, comparable in severity to the catastrophicLifeSafetyFailure tier already used for contractor_breach_negligence -- but here the alleged malpractice is against a structural engineering/inspection firm rather than a general contractor. No dollar outcome available, but it confirms this claim type can reach the same top-of-range severity as the contractor-side claim, not only the mid-size redesign-cost claims the current sample otherwise reflects.", "outcome": "A 116-year-old mixed-use/apartment building at 324 Main St. in Davenport partially collapsed on May 28, 2023, killing three residents and displacing roughly 100 households. Building owner Andrew Wold had retained Select Structural Engineering to inspect the building and advise on repairs; Wold sued the firm for negligence and breach of contract, alleging it advised the building was not in danger despite noting wall damage during inspection. Select Structural counterclaimed against Wold and Davenport Hotel LLC, alleging dozens of its own claims including negligence and contribution. At least six related lawsuits (including from injured/displaced residents) were filed and consolidated. Outcome undisclosed as of available reporting.", "caseName": "Wold v. Select Structural Engineering, LLC (Davenport, Iowa Building Collapse Litigation)", "citation": "Scott County District Court, Iowa (multiple related actions filed and consolidated in 2023; individual docket numbers not independently confirmed)", "sourceUrl": "https://cbs2iowa.com/news/local/davenport-building-owner-files-lawsuit-against-engineering-firm-following-collapse", "confidence": "medium", "dollarAmount": null, "jurisdiction": "IA"}, {"year": 2020, "notes": "An older filing with no confirmed final outcome, but factually rich on the design/spec-substitution mechanism and useful as a smaller-project, commercial-amenity data point distinct from the campus/institutional-building fact patterns that dominate this claim type's existing sample.", "outcome": "A homeowners association sued five defendants -- including architect D3G and engineer Wingate Consulting -- over a $1.5 million beach cabana project at a North Myrtle Beach resort, identifying 13 alleged construction and design defects, most notably the substitution of galvanized steel for specified stainless-steel building hangers and truss plates (workers attempted to coat the galvanized steel rather than replace it), plus improper laminated-veneer-lumber beams, incompatible anchors, and defective concrete-block column construction. The association terminated its contracts with the architect and general contractor, hired replacements, and proceeded with the project while litigation continued. Final resolution not confirmed in available reporting.", "caseName": "Barefoot Resort Residential Owners Association v. D3G Architects, Wingate Consulting Engineers, UFP Mid-Atlantic, JM Allen Construction, and Excel Custom Builders", "citation": "Horry County, South Carolina state court, filed Aug. 11, 2020 (exact case number not independently confirmed)", "sourceUrl": "https://www.burnsandwilcox.ca/insights/architects-engineers-sued-for-negligence-defects-in-1-5-million-beach-cabana-project/", "confidence": "medium", "dollarAmount": 1500000, "jurisdiction": "SC"}, {"year": 2021, "notes": "A large, CONFIRMED final multi-defendant settlement (not merely an amount sought) that includes a nationally prominent architecture firm (Arquitectonica) as one of the paying defendants alongside the developer and GC -- the settlement is reported as a combined figure across all defendants' insurers rather than broken out architect-by-architect, so treat this as evidence design-malpractice exposure was part of a confirmed real recovery, not proof of Arquitectonica's individual share.", "outcome": "CONFIRMED FINAL settlement: the condominium association for the Regalia on the Ocean luxury tower in Sunny Isles Beach sued developer Regalia Beach Developers, general contractor Charleville Development Corp., architect Arquitectonica, and subcontractors over alleged flawed design and building-code violations -- including improperly installed pool joints, cracking tiles, unsafe steam rooms, and flawed balcony sliding-glass doors and railings. Insurers for the developer, GC, architect, and subcontractors settled for a combined $17.5 million, structured as a $9.6 million cash payment to the association for repairs (bathrooms, balconies, driveway pavers) plus an $8.5 million markdown on the ~$10.5 million cost of replacing sliding glass doors on all 39 units. (Some contemporaneous reporting rounds this to '$18 million.')", "caseName": "Regalia Condominium Association, Inc. v. Regalia Beach Developers, LLC, Charleville Development Corp., Arquitectonica International Corp., et al.", "citation": "Miami-Dade County Circuit Court, Florida, filed November 2018 (exact case/docket number not independently confirmed); settlement reported May 2021", "sourceUrl": "https://www.haber.law/regalia-association-scores-18m-settlement-in-construction-defects-lawsuit/", "confidence": "high", "dollarAmount": 17500000, "jurisdiction": "FL"}, {"year": 2025, "notes": "A wrongful-death/personal-injury fact pattern rather than a classic building-defect repair-cost claim (parallel to Wold v. Select Structural Engineering, already in this claim type's sample, which is also a death/collapse case against a design/inspection firm rather than a redesign-cost dispute). dollarAmount reflects ONLY the confirmed $100,000 each paid by the architect and the engineering firm -- the smallest confirmed per-defendant design-professional payment found in this research round, useful as a low-end real data point alongside the much larger Regalia and bridge-collapse settlements below. Local-news sourcing only; exact case captions/docket numbers not independently verified against the court's own records.", "outcome": "CONFIRMED FINAL settlements as to two design professionals: after a May 28, 2024 natural-gas explosion at the Realty Tower building in Youngstown, Ohio killed Chase Bank employee Akil Drake (workers had cut into a pressurized but supposedly decommissioned gas line in the basement), his family and other plaintiffs sued the gas utilities and design professionals, alleging engineering firm MS Consultants failed to properly identify the decommissioned natural gas line and that project architect A. Nieder Architecture likewise bore responsibility for the design/as-built failure to flag it. As part of the resulting settlement, MS Consultants agreed to pay $100,000 and A. Nieder Architecture agreed to pay $100,000, while the gas-utility defendants paid a combined $2.9 million and the building's property-management defendants paid $3 million.", "caseName": "Drake (Estate/family) v. Enbridge Gas Ohio, East Ohio Gas, A. Nieder Architecture, MS Consultants, Inc., et al. (Realty Tower gas explosion litigation)", "citation": "Mahoning County Common Pleas Court, Ohio, lawsuits filed June 2025; related wrongful-death settlement approved through Mahoning County Probate Court (exact case/docket numbers not independently confirmed)", "sourceUrl": "https://www.vindy.com/news/local-news/2025/06/engineering-gas-companies-sued-over-blast-at-realty-tower/", "confidence": "medium", "dollarAmount": 100000, "jurisdiction": "OH"}, {"year": 2016, "notes": "Older than the 3-5 year recency preference (2016), but included because it is a CONFIRMED, appellate-affirmed final judgment with an exact dollar figure and a clean, well-documented seismic-design-defect fact pattern -- exactly the category of confirmed final outcome this research round was tasked with finding, which is thinner in the existing sample than pending/undisclosed matters.", "outcome": "CONFIRMED FINAL judgment, affirmed on appeal: a condominium HOA sued its structural engineer over multiple design flaws compromising seismic safety -- improperly nailed shear walls, weak shear-wall-to-floor-joist connections, improperly sized floor sheathing, a weak second-floor diaphragm, omitted hold-downs, and corrosion-prone gypsum sheathing near steel components -- that collectively rendered the building 'unreasonably dangerous to its occupants' in a significant earthquake. The jury found the engineer 97.5% at fault (contractor 2.5%) and awarded $1,149,332 in damages; the Washington Court of Appeals affirmed.", "caseName": "The Pointe at Westport Harbor Homeowners' Ass'n v. Engineers Northwest, Inc., P.S.", "citation": "No. 45839-0-II (Wash. Ct. App. May 3, 2016)", "sourceUrl": "https://acslawyers.com/claims/structural-engineer-found-liable-for-defects-that-rendered-a-condominium-dangerously-unsafe/", "confidence": "high", "dollarAmount": 1149332, "jurisdiction": "WA"}, {"year": 2010, "notes": "Older than the 3-5 year recency preference, but one of the largest, most thoroughly documented CONFIRMED final design/engineering-malpractice settlements on record and a useful top-of-range anchor for this claim type, comparable in role to the catastrophicLifeSafetyFailure outlier cases already anchoring the contractor_breach_negligence claim type (Champlain Towers, Harmon Hotel, Tropicana garage, Milwaukee garage). Sourced to a tertiary (Wikipedia) reference rather than a primary settlement document or news article with full case caption -- flagged accordingly, though the $52.4M figure is widely and consistently reported.", "outcome": "CONFIRMED FINAL settlement: following the August 1, 2007 collapse of the I-35W Mississippi River bridge in Minneapolis (13 killed, ~145 injured), which investigators attributed to an original design flaw in undersized gusset plates, victims and families sued URS Corporation, the engineering firm the state had separately retained to review the bridge's structural adequacy shortly before the collapse, alleging URS's review failed to catch the deficiency. In August 2010, the last of the lawsuits against URS were settled for a confirmed $52.4 million.", "caseName": "Minnesota residents/estates (multiple consolidated plaintiffs) v. URS Corporation", "citation": "Hennepin County District Court, Minnesota (consolidated I-35W bridge collapse litigation); settlement announced August 2010 (exact docket numbers not independently confirmed)", "sourceUrl": "https://en.wikipedia.org/wiki/I-35W_Mississippi_River_bridge", "confidence": "high", "dollarAmount": 52400000, "jurisdiction": "MN"}, {"year": 2026, "notes": "The $106 million figure is a CONFIRMED final resolution of the litigation as a whole, but available reporting does not disclose Heaslip Engineering's (or any other individual design professional's) specific share of that total -- treat this as confirmation that the design-malpractice allegations were part of a real, closed-out recovery, not as a design-professional-specific dollar figure. A second-largest confirmed catastrophic-collapse design-liability settlement located in this round, after URS/I-35W above. Sourced to a tertiary (Wikipedia) reference; a primary settlement document or contemporaneous news article with the case caption was not independently located within this round's research budget.", "outcome": "CONFIRMED FINAL global settlement, though not broken out defendant-by-defendant: following the October 12, 2019 partial collapse of the Hard Rock Hotel New Orleans during construction (killing 3 workers), OSHA found in April 2020 that the project's structural engineer, Heaslip Engineering, LLC, 'failed to adequately design, review or approve steel bolt connections affecting the structural integrity' of the building (the engineer denied wrongdoing and appealed). Hard Rock International and other plaintiffs sued the developer, architects, engineers, and other companies involved in construction; a special master was appointed in September 2022 to arbitrate settlements among the many defendants, and a global settlement of $106 million was finally reached on August 6, 2026.", "caseName": "Hard Rock International / building owner and related plaintiffs v. developer, project architect, Heaslip Engineering, LLC, and other companies involved in construction (Hard Rock Hotel New Orleans collapse litigation)", "citation": "Civil District Court for the Parish of Orleans, Louisiana (exact case/docket number not independently confirmed); global settlement reported August 6, 2026", "sourceUrl": "https://en.wikipedia.org/wiki/Hard_Rock_Hotel_collapse", "confidence": "medium", "dollarAmount": 106000000, "jurisdiction": "LA"}], "foreclosure_deficiency_judgment": [{"year": 2026, "outcome": "Ardent's complaint sought a money judgment of $9,320,807 against the borrower/guarantor in addition to foreclosure. After more than a year under receivership, the property was sold at a April 2026 foreclosure auction for $5.1M \u2014 less than half its 2022 purchase price of roughly $12M and well short of the ~$9.3M owed, leaving a substantial unrecovered deficiency.", "caseName": "The Ardent Companies (Ardent Cos.) v. Baruch Broad Street LLC / Zamir Equities", "citation": "Franklin County Court of Common Pleas, Ohio (case no. not independently verified)", "sourceUrl": "https://www.aol.com/news/downtown-columbus-keybank-building-sold-194109422.html", "confidence": "high", "dollarAmount": 9320807}, {"year": 2026, "outcome": "Miami-Dade Circuit Judge Joseph Perkins granted a stipulated final foreclosure judgment in favor of the lender (through affiliate AFF IV 200 Miami LLC) for $65.7M \u2014 $41.1M principal plus accrued interest and fees \u2014 clearing the way for both buildings to be sold at online auction.", "caseName": "AFF IV 200 Miami LLC v. SRCTD 44-200 LLC and FS Equity Investments II LLC", "citation": "Miami-Dade County Circuit Court (Fla.), stipulated foreclosure judgment entered June 11, 2026", "sourceUrl": "https://therealdeal.com/miami/2026/06/23/stonerock-capital-loses-downtown-miami-office-foreclosure/", "confidence": "high", "dollarAmount": 65700000}, {"year": 2026, "outcome": "Broward County Circuit Judge Martin Bidwill entered a $40M final foreclosure judgment in April 2026. Emerald Creek Capital itself acquired the resort at the resulting July 16, 2026 foreclosure sale.", "caseName": "Emerald Creek Capital 3 LLC v. BH3-affiliated ownership entities (Hillsboro Beach Resort)", "citation": "Broward County Circuit Court (Fla.), final foreclosure judgment entered April 2026", "sourceUrl": "https://therealdeal.com/miami/2026/07/30/hillsboro-beach-resort-sold-to-lender-in-foreclosure-sale/", "confidence": "high", "dollarAmount": 40000000}, {"year": 2026, "outcome": "The property's appraised value had collapsed to roughly $41M (down 86% from a pre-pandemic value of about $300M). At the January 21, 2026 foreclosure auction, with an upset price of $161,854,848.66, no bidder appeared \u2014 the property reverted to lender U.S. Bank for a nominal $1,000, leaving the loan's full ~$155.9M-plus balance effectively unrecovered from the collateral.", "caseName": "LNR Partners (special servicer) v. Cohen Brothers Realty Corp. (750 Lexington Avenue)", "citation": "Supreme Court of the State of New York, New York County (foreclosure judgment ~$155.9M, entered 2025)", "sourceUrl": "https://www.crainsnewyork.com/real-estate/750-lexington-ave-fetches-nominal-sum-foreclosure-auction/", "confidence": "high", "dollarAmount": 155900000}, {"year": 2026, "notes": "A real, current lender-loss outcome illustrating a procedural trap distinct from the substantive deficiency-judgment/anti-deficiency issues the other citations in this claim type address: a lender holding multiple defaulted liens on the same property who forecloses on them sequentially rather than together risks losing the later lien entirely to claim-preclusion doctrines, regardless of the underlying default being real and undisputed. Worth flagging to a lienholder client with more than one defaulted instrument on the same collateral.", "outcome": "Wells Fargo held both a first and second mortgage on the property, both in default, but chose to foreclose only on the second mortgage. Roughly two years later, it filed a separate new foreclosure action on the still-defaulted first mortgage. The Chancery judge dismissed the second foreclosure action with prejudice, holding it violated New Jersey's Entire Controversy Doctrine and res judicata by splitting claims that should have been brought together, and ordered the first mortgage discharged.", "caseName": "Wells Fargo Bank, N.A. v. 9 Schindler Court", "citation": "Docket No. F-6328-25 (N.J. Super. Ct., Ch. Div., Morris Cnty., Jan. 2026)", "sourceUrl": "https://njlawconnect.com/commercial-tenant-rights-foreclosure-nj/", "confidence": "medium", "dollarAmount": 0, "jurisdiction": "NJ"}, {"year": 2026, "notes": "Borrower's decision not to oppose foreclosure despite live self-dealing allegations is itself a data point: even where a lender's complaint alleges borrower misconduct, an undisputed-default posture can still resolve as a clean, uncontested foreclosure once the numbers are hopeless. Also illustrates a garment-district office tower where original 1999 leasehold acquisition cost ($140M) was far below the 2018 loan amount ($375M), i.e., significant equity extraction well before the default.", "outcome": "AIG-affiliated lenders (American General Life, Variable Annuity Life, United States Life) sued to foreclose on the $375M loan taken against the leasehold in 2018, alleging intentional self-dealing and diversion of funds by the Chetrit/Moinian/Minskoff ownership group. Facing a debt that had grown to roughly $356M with accrued interest and fees, the borrower agreed not to oppose the lender's foreclosure motion, and the court ordered the buildings sent to a foreclosure auction to satisfy the debt.", "caseName": "American General Life Insurance Company, et al. v. 500-512 Seventh Avenue Limited Partnership (Chetrit/Moinian/Minskoff Garment District Building)", "citation": "Supreme Court of the State of New York, New York County (foreclosure order entered August 2026)", "sourceUrl": "https://therealdeal.com/new-york/2026/08/24/chetrit-moinian-minskoffs-midtown-tower-faces-foreclosure/", "confidence": "high", "dollarAmount": 356000000, "jurisdiction": "NY"}, {"year": 2025, "notes": "A mezzanine UCC Article 9 foreclosure is legally distinct from a mortgage foreclosure/deficiency judgment (it forecloses on pledged personal property -- equity interests -- not the real property itself, and is typically non-judicial and much faster), but produces the same economic result for the borrower: total loss of the asset with no further deficiency exposure beyond the mezz collateral. Relevant to calibrating this claim type wherever the fact pattern involves mezzanine rather than senior mortgage debt, which is now common in stacked CRE capital structures.", "outcome": "The $205M mezzanine loan on RFR's 511,000-square-foot Midtown Manhattan office tower fell into maturity default in late 2022; an extension bought time but the loan defaulted again in late 2024 when that extension expired. The mezzanine lender consortium (advised by Ocean West Capital Partners and Daol Asset Management) foreclosed non-judicially under UCC Article 9 on the pledged LLC equity interests rather than proceeding through a judicial mortgage foreclosure, and took ownership of the property at the April 2025 auction, wiping out RFR's equity with no reported cash deficiency recovery pursued against RFR beyond the loss of the collateral itself.", "caseName": "Ocean West Capital Partners / Daol Asset Management (on behalf of a consortium of South Korean insurers) v. RFR Realty (285 Madison Avenue)", "citation": "UCC Article 9 public foreclosure auction of pledged mezzanine equity interests, held April 15, 2025 at DLA Piper LLP offices, New York (and via Zoom)", "sourceUrl": "https://therealdeal.com/new-york/2025/04/18/daol-takes-rfrs-285-madison-at-foreclosure-auction/", "confidence": "high", "dollarAmount": 205000000, "jurisdiction": "NY"}, {"year": 2022, "notes": "A real, recent example of a lender winning the foreclosure/deficiency claim in principle but recovering far less than sought because of a valuation methodology fight -- useful even where the default itself is undisputed, since the deficiency AMOUNT (not just the right to one) can be knocked down substantially on appeal when a liquidation-value appraisal is used instead of fair market value.", "outcome": "After the collateral sold at foreclosure auction for $795,001 against a judgment of roughly $1.16M, the trial court calculated the deficiency using the lender's appraiser's lower 'liquidation value' ($620,000) rather than fair market value, awarding a larger deficiency. The Second Department reversed, holding fair market value (found to be approximately $1.06M) is the correct benchmark under RPAPL 1371, not a discounted liquidation value -- which, because $1.06M exceeded the auction price, sharply reduced the deficiency judgment to $104,186.56.", "caseName": "Rhinebeck Bank v. WA 319 Main, LLC", "citation": "210 A.D.3d 179, 176 N.Y.S.3d 100 (2d Dep't 2022), decided November 16, 2022", "sourceUrl": "https://www.fhnylaw.com/second-department-calculates-deficiency-judgment-in-mortgage-foreclosure-action", "confidence": "high", "dollarAmount": 104187, "jurisdiction": "NY"}, {"year": 2024, "notes": "Illustrates a real procedural trap distinct from the substantive availability-of-deficiency issue already modeled in foreclosureStateModifiers: which state's deficiency-judgment statute (if any) even applies can itself be contested and require its own choice-of-law-style analysis, independent of the merits of the underlying debt. Outcome on guarantor liability itself was not fully resolved as of this research pass -- confidence marked medium because only the procedural ruling, not a final merits disposition, was confirmed.", "outcome": "After the lender purchased the collateral for a nominal $1,191.55 at a July 2018 Pennsylvania sheriff's sale following the underlying mortgage foreclosure (which had produced a roughly $4.9M judgment), the lender sued the guarantors in federal court to collect that judgment amount under the guaranty via breach-of-contract and unjust-enrichment theories. The court held that Pennsylvania's Deficiency Judgment Act did not govern the action because the only Pennsylvania connection was the pledged (vacant) collateral, and expressly declined to resolve the guarantors' ultimate contractual liability for the ~$4.9M on that motion, leaving the merits of guarantor liability for further proceedings rather than deciding it outright.", "caseName": "Lifestyle Real Estate Lender, LLC v. Fred Rappaport, et al.", "citation": "No. 2:21-cv-01781 (E.D. Pa.)", "sourceUrl": "https://www.courtlistener.com/opinion/10710710/lifestyle-real-estate-lender-llc-v-fred-rappaport-et-al/", "confidence": "medium", "dollarAmount": 4900000, "jurisdiction": "Federal (E.D. Pa.)"}], "pre_condemnation_access_dispute": [{"year": 2012, "outcome": "The Texas Supreme Court held that simply checking a box on a state regulatory form does not conclusively establish common-carrier (and thus eminent domain) status; a landowner may challenge that status in court, and the entity bears the burden of proving a reasonable probability that the pipeline will serve the public rather than solely the owner's own affiliated interests. Remanded for further proceedings on Denbury's actual common-carrier status.", "caseName": "Texas Rice Land Partners, Ltd. v. Denbury Green Pipeline-Texas, LLC", "citation": "363 S.W.3d 192 (Tex. 2012)", "sourceUrl": "https://agrilife.org/texasaglaw/2020/07/13/win-for-tx-landowner-challenging-eminent-domain-power-of-pipeline/", "confidence": "high", "dollarAmount": null}, {"year": 2026, "outcome": "The Fourth Circuit affirmed a preliminary injunction letting PSEG enter the properties to survey, holding PSEG qualified as an entity with eminent domain power under the statute even without a completed certification, and holding a temporary survey entry is not itself a compensable physical taking.", "caseName": "PSEG Renewable Transmission LLC v. Arentz Family, LP", "citation": "No. 25-1730 (4th Cir. Aug. 6, 2026)", "sourceUrl": "https://marylandmatters.org/2026/08/06/piedmont-power-line-surveys-4th-circuit/", "confidence": "high", "dollarAmount": null}, {"year": 2025, "outcome": "The North Dakota Supreme Court upheld Summit Carbon Solutions' right to conduct pre-condemnation surveys over the landowner's objection.", "caseName": "Summit Carbon Solutions, LLC v. Malloy", "citation": "North Dakota Supreme Court (decided January 2025)", "sourceUrl": "https://iowacapitaldispatch.com/2023/12/18/landowner-attorneys-argue-survey-access-law-is-unconstitutional/", "confidence": "medium", "dollarAmount": null}, {"year": 2026, "outcome": "Ongoing as of mid-2026; no rulings on the merits reported yet.", "caseName": "In re Elba Express Co., LLC Petitions for Ex Parte Survey Entry", "citation": "Court of Common Pleas, Hampton and Colleton Counties, South Carolina (approx. 88+ separate petitions, 2026, ongoing)", "sourceUrl": "https://www.postandcourier.com/rising-waters/pipeline-company-sues-sc-landowners-for-survey-access-as-residents-fret-over-ace-basin-gas/article_876c8735-4f8b-4517-a568-e5925818382c.html", "confidence": "medium", "dollarAmount": null}, {"year": 2016, "notes": "The leading, most-cited California authority on precondemnation entry rights -- confirms the general pattern this claim type's baseProbability already reflects (courts side with the entity seeking access once it shows a plausible eminent-domain purpose), while also establishing the procedural and compensation safeguards a landowner can still insist on even while losing the access fight itself.", "outcome": "The California Supreme Court reinforced the statutory right of an entity holding the power of eminent domain to enter private property before any condemnation filing to conduct precondemnation testing and investigatory work (soil borings, environmental testing, etc.) needed to assess a property's suitability for a public project, subject to procedural safeguards and compensation for any resulting damage, but without treating the entry itself as an independent 'taking' requiring a full condemnation proceeding.", "caseName": "Property Reserve, Inc. v. Superior Court", "citation": "1 Cal.5th 151 (2016)", "sourceUrl": "https://law.justia.com/cases/california/supreme-court/2016/s217738.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "CA"}, {"year": 2024, "notes": "A clean loss for the landowner on a facial constitutional challenge to a modern survey-access statute -- consistent with, and reinforcing, this claim type's existing low 0.05-0.2 baseProbability.", "outcome": "A Hardin County landowner refused to allow Summit Carbon Solutions' surveyors onto his land to survey a proposed CO2 pipeline route, arguing Iowa Code section 479B.15 (which authorizes a pipeline company to enter private land to survey) was facially unconstitutional because it allows an uncompensated physical invasion without due process or a jury trial. The Iowa Supreme Court affirmed the district court's rejection of the facial constitutional challenge under both the federal and Iowa constitutions, upholding the statute and the company's survey access.", "caseName": "Summit Carbon Solutions, LLC v. Kasischke", "citation": "Iowa Supreme Court, No. 23-1186 (decided Nov. 22, 2024)", "sourceUrl": "https://iowacapitaldispatch.com/2024/11/22/iowa-supreme-court-upholds-land-survey-abilities-of-pipeline-companies-in-summit-case/", "confidence": "high", "dollarAmount": null, "jurisdiction": "IA"}, {"year": 2024, "notes": "A genuinely mixed outcome: a clean loss on the access/survey-statute constitutionality question itself (consistent with the existing sample), paired with a real partial win reopening the separate common-carrier / eminent-domain-authority threshold question -- illustrates that even where survey access itself is essentially unwinnable, a landowner can still meaningfully contest whether the entity qualifies for eminent domain power in the first place.", "outcome": "The South Dakota Supreme Court held that SDCL 21-35-31 authorizes only 'minimally invasive superficial inspections' for pre-condemnation pipeline surveys (not invasive geotechnical/deep-dig work), and that the statute's incorporated right to a jury trial on any resulting damages satisfies constitutional requirements -- rejecting the landowners' broader takings challenge to the survey-access statute itself. However, the Court also reversed summary judgment for Summit Carbon Solutions on the separate, threshold question of whether Summit actually qualifies as a 'common carrier' with eminent domain authority at all, holding the lower courts abused their discretion by denying landowners' discovery requests into Summit's business model and offtake agreements, and remanded for further proceedings on that common-carrier status.", "caseName": "Betty Jean Strom Trust v. SCS Carbon Transport, LLC", "citation": "South Dakota Supreme Court, 2024 S.D. 48, Nos. 30317 & 30338 (decided Aug. 21, 2024)", "sourceUrl": "https://caselaw.findlaw.com/court/sd-supreme-court/116507602.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "SD"}, {"year": 2026, "notes": "An outright Texas Supreme Court win for the landowner -- but on a distinguishable theory (the SCOPE of an existing, informal 1947 easement held by an entity with general condemnation authority) rather than a challenge to a fresh statutory survey/entry request, which is the more typical fact pattern already in this claim's sample. Best treated as a separate, more landowner-favorable sub-scenario (disputes over whether an entity's use exceeds its existing easement) rather than folded into the general pre-condemnation access/survey base rate.", "outcome": "A ranch purchaser sued an electric cooperative holding condemnation authority for trespass after it tripled the number of poles and nearly doubled the wires on a decades-old distribution line crossing his property to serve a new industrial customer and substation. The cooperative's only claimed right derived from an unrecorded 1947 easement-by-estoppel. The Texas Supreme Court held the jury correctly found an easement by estoppel existed, but that the cooperative's major upgrade -- built to serve new customers, not to continue its original use -- exceeded the scope of that easement as a matter of law. The Court reversed the court of appeals, rendered judgment for the landowner on the trespass claim, and remanded for further proceedings (including damages).", "caseName": "John P. Boerschig v. Rio Grande Electric Cooperative, Inc.", "citation": "Texas Supreme Court, No. 24-0213 (decided May 22, 2026)", "sourceUrl": "https://www.txcourts.gov/media/1462760/240213.pdf", "confidence": "high", "dollarAmount": null, "jurisdiction": "TX"}, {"year": 2023, "notes": "IMPORTANT CAVEAT: I could not independently confirm the exact case caption or a docket/citation number (secondary news coverage identifies only the parties -- Navigator CO2/Navigator Heartland Greenway and landowner Martin Koenig -- and the county and approximate date, not a formal citation), so treat the caption above as a reasonable reconstruction, not a verified citation. More importantly, this trial-level landowner win concerns the SAME Iowa Code Sec. 479B.15 survey-access statute that the Iowa Supreme Court later upheld as constitutional in Summit Carbon Solutions, LLC v. Kasischke (Nov. 22, 2024), which is already cited in this file. Include only as a data point that a landowner CAN win at the trial-court level on this exact theory, while flagging clearly that Iowa's own supreme court has since foreclosed that theory for future cases.", "outcome": "Navigator sued Clay County landowner Martin Koenig after he twice denied its surveyors entry to his farmland to survey a proposed CO2 pipeline route. District Judge John Sandy denied Navigator's request for an injunction compelling entry, holding Iowa Code Sec. 479B.15 (the survey-access statute) unconstitutional because it authorizes a government-sanctioned physical invasion of private land without providing compensation for the intangible/subjective damages the invasion causes -- reasoning the statute effects a 'per se' taking that the statute itself does not adequately compensate. Navigator stated it would appeal.", "caseName": "Navigator Heartland Greenway, LLC v. Koenig (exact caption not independently confirmed)", "citation": "Iowa District Court, Clay County (ruling issued approx. May 2-3, 2023)", "sourceUrl": "https://www.dtnpf.com/agriculture/web/ag/news/business-inputs/article/2023/05/04/court-rules-iowa-law-governing-land", "confidence": "low", "dollarAmount": null, "jurisdiction": "IA"}, {"year": 2026, "notes": "A direct, very recent (2026) reaffirmation and extension of the file's existing leading authority, Property Reserve, Inc. v. Superior Court (Cal. 2016) -- confirms California courts continue to reject landowner arguments that a fully-formed, funded project must exist before precondemnation entry/testing can proceed. Verified via a single specialty legal-commentary source rather than the court's own opinion text.", "outcome": "Property owners argued the California Department of Water Resources could not conduct precondemnation entry and testing activities for a water-infrastructure project without first satisfying statutory project-authorization and funding requirements under California Water Code Sections 250 and 11580. The Court of Appeal rejected that argument, holding a public entity need not first complete formal project authorization/funding steps before conducting precondemnation entry and testing -- the entire purpose of the precondemnation entry procedure is to let the entity determine whether the property is even suitable for, and should be acquired for, a public project in the first place.", "caseName": "Department of Water Resource Cases", "citation": "California Court of Appeal, 3d Dist., No. C103207 (decided Mar. 26, 2026)", "sourceUrl": "https://www.inversecondemnation.com/2026/04/property-reserve-revisited-project-we-dont-need-a-project-to-do-precondemnation-entries.html", "confidence": "medium", "dollarAmount": null, "jurisdiction": "CA"}, {"year": 2026, "notes": "Directly parallel to the file's existing Texas Rice Land Partners v. Denbury Green Pipeline (TX 2012) and Betty Jean Strom Trust v. SCS Carbon Transport (SD 2024) entries -- another 'does this entity even qualify to exercise eminent domain power' common-carrier-status dispute, this time resolved against the landowner. Verified via a single specialty legal-commentary source rather than the court's own opinion text.", "outcome": "The Mendocino Railway (operator of the tourist 'Skunk Train' scenic excursion line) sought to exercise eminent domain to acquire private property from landowner Meyer, asserting common-carrier status. The trial court initially rejected that classification, but the Court of Appeal reversed, holding the railway qualified as a common carrier with eminent-domain authority even though the railway itself did not directly own all of the relevant operating property (which belonged to affiliated/subsidiary entities) -- a loss for the landowner, whose objection to the entity's threshold eminent-domain authority was rejected.", "caseName": "Mendocino Railway v. Meyer", "citation": "California Court of Appeal, No. A168497 (decided Jan. 7, 2026)", "sourceUrl": "https://www.inversecondemnation.com/2026/01/cal-app-skunk-train-is-a-common-carrier-with-power-of-eminent-domain.html", "confidence": "medium", "dollarAmount": null, "jurisdiction": "CA"}], "breach_fiduciary_duty_derivative": [{"year": 2020, "outcome": "On February 20, 2020, the court granted preliminary approval to a proposed settlement providing for an aggregate cash payment to the company of $15,181,108.47 (with $250,000 of that paid personally by the former CFO and the remainder by the company's D&O insurers), plus the tender of 83,504 shares of common stock back to the company. Final approval followed a June 9, 2020 settlement hearing, alongside a separate $2,250,000 award for plaintiff's counsel fees, expenses, and a case-contribution award. (Hospitality Investors Trust itself later filed for Chapter 11 bankruptcy in 2021, unrelated to this settlement.)", "caseName": "Milliken v. American Realty Capital Hospitality Advisors, LLC, et al. (Hospitality Investors Trust Shareholder Derivative Litigation)", "citation": "No. 1:18-cv-01757 (S.D.N.Y.)", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/1583077/000110465920023347/tm209391-1_8k.htm", "confidence": "high", "dollarAmount": 15181108}, {"year": 2017, "outcome": "The parties reached a settlement just days before trial; the court approved it on March 16, 2017, requiring Apple Hospitality REIT to pay $32 million to former Apple REIT Ten shareholders. Class counsel were awarded $8.96 million in fees (28% of the fund) plus roughly $430,000 in expense reimbursement, and the named plaintiff received a $15,000 incentive award. It was reported at the time as the largest derivative settlement in the Fourth Circuit.", "caseName": "Quinn v. Knight (Apple REIT Ten / Apple Hospitality REIT Derivative Litigation)", "citation": "No. 3:16-cv-00610 (E.D. Va.)", "sourceUrl": "https://richmondbizsense.com/2017/03/29/real-estate-firm-settles-shareholder-suit-for-32m/", "confidence": "high", "dollarAmount": 32000000}, {"year": 2010, "outcome": "The parties reached a settlement that received preliminary court approval in July 2010: the insider sellers agreed to forfeit and return 9 million of the 37.5 million shares they had received in the internalization deal (valued at approximately $90 million at the time of the original transaction), and Inland Western separately agreed to cover up to $10 million of the plaintiffs' legal fees.", "caseName": "In re Inland Western Retail Real Estate Trust, Inc. Shareholder Litigation", "citation": "Shareholder derivative/class action, N.D. Ill. (filed Nov. 2007, settled 2010)", "sourceUrl": "https://www.chicagobusiness.com/article/20100723/CRED03/200038980/inland-western-settles-shareholder-lawsuit", "confidence": "medium", "dollarAmount": 90000000}, {"year": 2015, "outcome": "Equity Commonwealth (the REIT's new name/management following the 2014 board overhaul) entered into a Settlement and Release Agreement on July 31, 2015 resolving both actions. The settlement was overwhelmingly non-monetary \u2014 largely mooted by the 2014 change in control and governance reforms already implemented \u2014 with the company agreeing to pay $200,000 toward plaintiffs' counsel's costs and expenses.", "caseName": "Katz v. CommonWealth REIT; Central Laborers' Pension Fund v. CommonWealth REIT (Equity Commonwealth Trustee Litigation)", "citation": "Circuit Court for Baltimore City, Maryland (Katz Action, filed March 2013; Central Laborers Action, filed April 2013)", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/0000803649/000141057815000405/a15-16477_18k.htm", "confidence": "medium", "dollarAmount": 200000}, {"year": 2024, "outcome": "Wheeler REIT's ousted former CEO, as a shareholder, alleged current and certain former directors breached their fiduciary duty to the company and common stockholders in connection with the board's handling of the company's Series D Preferred Stock following a 2021 rights offering, and that allied hedge funds aided and abetted the breach by diluting common stock. The court found the fiduciary-duty claim adequately alleged and let it proceed against the directors and (in part) the hedge funds; the parties reached a $7.125 million class settlement, approved by the court.", "caseName": "Khoshaba v. Stilwell, et al. (Wheeler Real Estate Investment Trust Shareholder Litigation)", "citation": "No. 2:24-cv-00237 (E.D. Va., Norfolk Div.), filed April 10, 2024", "sourceUrl": "https://news.bloomberglaw.com/securities-law/wheeler-boards-7-1-million-investor-settlement-gets-court-nod", "confidence": "high", "dollarAmount": 7125000}, {"year": 2025, "outcome": "Stockholders alleged AR Global's CEO Michael Weil and other individual defendants, along with AR Global Investments, LLC, breached their fiduciary duties to RTL stockholders in connection with company governance and transactions. Reached a proposed $3,250,000 cash class settlement, with a settlement hearing set for September 16, 2025. Notably, a related but separate RTL shareholder action over the same AR Global/Global Net Lease merger controversy (alleging conflicts of interest in the merger process, inadequate price, and inadequate disclosure -- a claim closer to merger_objection_suit) was DISMISSED on the merits in July 2024 under Maryland's business judgment rule -- see the merger_objection_suit citation for that companion case. The two outcomes together illustrate how much result varies with the specific theory pled, even against the same defendants over the same underlying conduct.", "caseName": "Meyer v. Weil, et al. (The Necessity Retail REIT, Inc. / AR Global Shareholder Litigation)", "citation": "Case No. 24-C-23-003628, Circuit Court for Baltimore City, Maryland", "sourceUrl": "https://www.globenewswire.com/news-release/2025/08/01/3125831/3080/en/Levi-Korsinsky-LLP-Announces-Pendency-of-Stockholder-Class-Action-and-Proposed-Settlement-Settlement-Hearing-and-Right-To-Appear-Involving-Owners-of-The-Necessity-Retail-Reit-Inc-C.html", "confidence": "high", "dollarAmount": 3250000}, {"year": 2021, "notes": "A clean, confirmed cash-plus-tender-offer recovery tied to a concrete, quantifiable insider-self-dealing internalization transaction -- directly on point for the tiedToConcreteQuantifiableSelfDealingTransaction modifier (0.55-0.8 range) alongside Quinn v. Knight, Inland Western, and Hospitality Investors Trust already in this sample.", "outcome": "Class and derivative action alleging The Parking REIT's stockholders were injured by the internalization of the REIT's external advisor, a transaction in which the company's CEO, Michael Shustek, held a substantial personal stake. The Circuit Court for Baltimore City granted final approval to a global settlement of the consolidated Maryland action and the parallel Nevada federal action (SIPDA Revocable Trust v. The Parking REIT, Inc.), requiring the company to pay approximately $9.25 million in cash and to conduct a tender offer for up to 15% of common shares outstanding (excluding shares held by the advisor and its affiliates).", "caseName": "In re The Parking REIT, Inc. Stockholder Litigation (SIPDA Revocable Trust v. The Parking REIT, Inc.)", "citation": "Consolidated action, Circuit Court for Baltimore City, Maryland, with a related federal action, No. 2:19-cv-00428 (D. Nev.)", "sourceUrl": "https://www.girardsharp.com/newsroom-news-parking-reit-settlement-order", "confidence": "high", "dollarAmount": 9250000, "jurisdiction": "MD (state) and Federal (D. Nev.)"}, {"year": 2024, "notes": "Pending, not yet resolved -- included for completeness and because the tied companion securities class actions (see securities_fraud_10b5) were both dismissed, which is itself informative: a dismissed 10b-5 claim for failure to plead scienter does not necessarily doom a parallel derivative fiduciary-duty claim built on the same facts, since the pleading standards differ.", "outcome": "Shareholder derivative suits against members of Medical Properties Trust's board alleging breach of fiduciary duty in connection with the board's oversight of, and disclosures regarding, related-party loans and financing arrangements extended to help prop up rent payments from the REIT's largest and financially distressed tenant, Steward Health Care (which filed for bankruptcy in May 2024). As of this research pass the derivative actions remain pending in the Northern District of Alabama with no settlement, dismissal, or trial outcome yet reported.", "caseName": "In re Medical Properties Trust, Inc. Derivative Litigation", "citation": "Two related derivative actions, N.D. Ala. (filed Oct. 19, 2023 and Dec. 7, 2023)", "sourceUrl": "https://ksfcounsel.com/news/stockholder-derivative-medical-properties-trust/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (N.D. Ala.)"}, {"year": 2021, "notes": "Included specifically because it illustrates a resolution pathway NOT otherwise represented in this sample: many derivative demands over REIT internalization/self-dealing transactions never become a captioned lawsuit at all -- they are absorbed and (often quietly) resolved or rejected by an internal special/demand-review committee. Any base-rate calibration built only from filed-and-settled cases will systematically overstate how often these disputes turn into real litigation exposure, since this channel is invisible to case-law and class-action databases.", "outcome": "Following Independence Realty Trust's August 31, 2020 internalization of external management functions previously performed by its sponsor, Steadfast REIT Investments, LLC, purported stockholders sent the board a pre-suit derivative demand letter (rather than filing suit directly) asking the board to investigate whether a basis existed to pursue claims -- including recovery of internalization-transaction payments. The board responded by forming a two-independent-director Demand Review Committee in September 2021. No further public disclosure of the Committee's findings, a settlement, or a filed lawsuit could be located in this research pass.", "caseName": "Independence Realty Trust, Inc. -- Steadfast Internalization Derivative Demand", "citation": "Pre-suit derivative demand letter, delivered July 16, 2021; Demand Review Committee formed September 2021 (no litigation caption; resolved internally, per company SEC disclosures)", "sourceUrl": "https://www.sec.gov/Archives/edgar/data/1466085/000156459021056728/irt-ex992_6.htm", "confidence": "low", "dollarAmount": null, "jurisdiction": "MD (state law claim, resolved without a filed suit)"}], "insurance_coverage_defect_dispute": [{"year": 2024, "outcome": "First Circuit affirmed that Admiral had no duty to defend Tocci in the underlying construction-defect suit.", "caseName": "Admiral Insurance Co. v. Tocci Building Corp.", "citation": "No. 22-1462, 122 F.4th 1 (1st Cir. Nov. 8, 2024)", "sourceUrl": "https://law.justia.com/cases/federal/appellate-courts/ca1/22-1462/22-1462-2024-11-08.html", "confidence": "high", "dollarAmount": null}, {"year": 2026, "outcome": "Pending as of filing. Mycon seeks more than $1 million in damages plus treble damages, exemplary damages, attorneys' fees, and 18% statutory interest for the insurers' denial of defense/coverage.", "caseName": "Mycon General Contractors, Inc. v. Employers Mutual Casualty Company et al.", "citation": "No. 3:26-cv-01098, U.S. District Court for the Northern District of Texas, filed April 6, 2026", "sourceUrl": "https://www.insurancebusinessmag.com/us/news/claims/contractor-sues-six-cgl-insurers-after-all-deny-facade-failure-claim-571023.aspx", "confidence": "medium", "dollarAmount": null}, {"year": 2024, "outcome": "The Seventh Circuit reversed, holding the architecture firm's insurer Acuity did owe a duty to defend under the CGL policy.", "caseName": "Cornice & Rose International, LLC v. Acuity", "citation": "No. 23-1152, 2024 WL 4880102 (7th Cir. Nov. 25, 2024)", "sourceUrl": "https://law.justia.com/cases/federal/appellate-courts/ca7/23-1152/23-1152-2024-11-25.html", "confidence": "medium", "dollarAmount": null}, {"year": 2025, "outcome": "Oregon Supreme Court reversed lower courts and held that CGL coverage for a construction-defect claim turns on the underlying FACTS (whether there is a basis for imposing tort liability, i.e., accidental property damage from negligent conduct), not on how the claim happens to be pleaded (contract vs. tort) -- rejecting the insurer's argument that a contract-only complaint automatically falls outside coverage. Remanded for further proceedings on whether policy exclusions still bar recovery. Underlying dispute involved a $150,000 arbitration award for defective concrete garage-floor overlay work (missing control joints, causing voids and cracking) -- smaller-dollar and residential-adjacent, but the coverage HOLDING is a significant, recent, directly-applicable precedent for CRE construction-defect CGL disputes generally.", "caseName": "Twigg v. Admiral Insurance Co.", "citation": "373 Or. 445 (Or. Apr. 17, 2025)", "sourceUrl": "https://www.stoel.com/insights/publications/oregon-supreme-court-expands-cgl-coverage-for-construction-defects-twigg-v-admiral-insurance-company", "confidence": "high", "dollarAmount": 150000}, {"year": 2025, "notes": "A real, current, insurer-win outcome on a common builder's-risk coverage fight: an ensuing-loss clause does not resurrect coverage for defective-workmanship damage unless the insured can point to a genuinely separate covered peril that caused (or worsened) the loss, not just a different way of describing the same faulty work. dollarAmount reflects the $0 coverage recovered, not the $181,415.39 repair cost itself, which the insured bore.", "outcome": "Insured was hired to install a vinyl gym floor with painted lines and subcontracted the painting; the painting work was faulty (crooked lines, incorrect markings, smudges), requiring the insured to remove and replace the entire floor at a cost of $181,415.39. Its builder's-risk insurer denied the claim under a workmanship-error exclusion. The Eighth Circuit affirmed, holding the policy's ensuing-loss provision did not restore coverage because the damage was caused solely by the excluded peril (defective workmanship) with no separate, independent covered peril in the causal chain.", "caseName": "Bob Robison Commercial Flooring Inc. v. RLI Insurance Company", "citation": "No. 23-3531 (8th Cir. Mar. 19, 2025)", "sourceUrl": "https://law.justia.com/cases/federal/appellate-courts/ca8/23-3531/23-3531-2025-03-19.html", "confidence": "high", "dollarAmount": 0, "jurisdiction": "Federal (8th Cir.)"}, {"year": 2023, "notes": "A landmark, widely-cited decision that materially EXPANDS CGL coverage availability for construction-defect claims in a major jurisdiction, reversing a more insurer-favorable prior rule. Underlying claim was a residential townhome HOA dispute, but the coverage holding applies with equal force to commercial CGL disputes and should be treated as a real doctrinal shift pushing Illinois-sited claims toward the higher end of the coverage-probability range.", "outcome": "A townhome owners' association sued developer M/I Homes for breach of contract and breach of the implied warranty of habitability, alleging M/I's subcontractors caused construction defects through defective materials, faulty workmanship, and code violations. M/I demanded a defense from Acuity as an additional insured under a subcontractor's CGL policy; Acuity sought a declaratory judgment that the underlying complaint alleged no 'property damage' caused by an 'occurrence.' The trial court agreed with Acuity and found no duty to defend. The Illinois Supreme Court reversed in relevant part, holding that negligent subcontractor work causing damage to the project can constitute 'property damage' caused by an 'occurrence' under a standard CGL policy -- expressly overruling prior Illinois appellate precedent that had treated construction-defect claims as categorically uninsurable business-risk exclusions.", "caseName": "Acuity, a Mutual Insurance Co. v. M/I Homes of Chicago, LLC", "citation": "2023 IL 129087 (Ill. Nov. 30, 2023)", "sourceUrl": "https://www.isba.org/cases/illinois/supreme/2023/11/30/acuityvmihomesofchicagollc", "confidence": "high", "dollarAmount": null, "jurisdiction": "IL"}, {"year": 2024, "notes": "Underlying dispute was residential (homebuilder/homeowner), included because the defect-repair-cost-vs-resulting-damage-cost distinction is one of the most heavily litigated CGL construction-defect coverage issues nationally and directly bears on the file's coveredPortionOfUnderlyingDefectDamages formula -- that formula likely should already discount for the slice of repair cost attributable to the defect itself, since that slice is frequently uninsured even where a duty to defend/broader coverage exists.", "outcome": "After homeowners won a jury verdict against homebuilder R.C. Havens & Sons over construction defects, the homebuilder's CGL insurer intervened seeking a declaration it owed no duty to indemnify. The Massachusetts Appeals Court held that the cost of repairing or removing a construction defect ITSELF is not 'property damage' within the meaning of a CGL policy, but the cost of repairing damage CAUSED BY that defect to otherwise non-defective work or property IS covered 'property damage' -- a split, partially insurer-favorable holding rather than a clean win for either side.", "caseName": "Lessard v. R.C. Havens & Sons, Inc.", "citation": "104 Mass. App. Ct. 572 (2024)", "sourceUrl": "https://www.constructionlawzone.com/2024/12/massachusetts-appellate-court-confirms-construction-defects-are-not-covered-under-commercial-general-liability-policies/", "confidence": "high", "dollarAmount": null, "jurisdiction": "MA"}, {"year": 2024, "notes": "Based on secondary case-summary reporting rather than a full read of the opinion text -- flagged accordingly. Consistent with the general national trend (also seen in Lessard) of appellate courts narrowing what counts as covered 'property damage' in pure water-intrusion/defect-only fact patterns.", "outcome": "A contractor sued its own CGL insurer, Arbella, to recover defense costs incurred in an underlying construction-defect action alleging water intrusion. The Connecticut Appellate Court held that water intrusion alone, without resulting damage to other property, does not constitute 'property damage' caused by an 'occurrence' under the CGL policy -- an insurer-favorable ruling limiting the contractor's ability to recover its defense costs for that portion of the underlying claim.", "caseName": "Westchester Modular Homes of Fairfield County, Inc. v. Arbella Protection Ins. Co.", "citation": "224 Conn. App. 526 (2024)", "sourceUrl": "https://www.constructionlawzone.com/2024/07/water-alone-is-not-property-damage-under-a-cgl-policy-in-connecticut/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "CT"}, {"year": 2025, "notes": "An interim/procedural ruling (motion to dismiss plus a denied default-judgment motion), not a final coverage determination -- included as a very recent, real data point showing insurers still frequently losing duty-to-defend declaratory actions at the pleading stage whenever the underlying complaint is pled broadly enough to allege potentially-covered property damage.", "outcome": "Travelers sought a declaratory judgment that it owed no duty to defend or indemnify its insureds, I.C. Refrigeration Service and Flory Construction, in a construction-defect action brought against them by project owner Highbridge Oakland. The court granted the insureds' motion to dismiss Travelers' duty-to-defend claim, holding Travelers could not show the damages Highbridge sought were not potentially covered 'property damage,' and stayed the remaining duty-to-indemnify claim pending resolution of the underlying suit. The court separately denied, without prejudice, Travelers' later motion for default judgment seeking a declaration that the damages alleged were purely economic rather than property damage.", "caseName": "The Travelers Indemnity Co. of Connecticut v. I.C. Refrigeration Service, Inc. et al.", "citation": "Order filed Nov. 10, 2025, U.S. District Court for the Northern District of California (case/docket number not independently confirmed beyond the CourtListener docket entry)", "sourceUrl": "https://www.courtlistener.com/opinion/10736966/the-travelers-indemnity-company-of-connecticut-v-ic-refrigeration/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (N.D. Cal.)"}], "slip_and_fall_hazardous_condition": [{"year": 2024, "notes": "Relied on plaintiff-firm and wire-service reporting (PARRIS Law Firm, PR Newswire) rather than a directly retrieved court record -- a trial-court jury verdict, not an appellate opinion, so treat as illustrative of catastrophic-injury upside rather than a settled point of law. Real anchor for how far a slip-and-fall verdict can run once causation and a serious, permanent injury are both established.", "outcome": "An electrical technician working for an independent contractor was called to a Palmdale train-manufacturing facility at 2:00 a.m. and told the repair had to be finished by 5:00 a.m. He slipped on a patch of ice atop a train car and suffered a permanent, catastrophic spinal injury. The jury found the property owner/operator failed to take adequate steps to prevent ice buildup or otherwise ensure a safe work environment, and returned a $58,358,431 verdict -- reported as the largest slip-and-fall verdict in U.S. history.", "caseName": "(Unnamed plaintiff) v. Kinkisharyo International, LLC", "citation": "Los Angeles County Superior Court jury verdict, May 21, 2024 (docket number not independently confirmed)", "sourceUrl": "https://www.prnewswire.com/news-releases/los-angeles-jury-awards-over-58-000-000-to-injured-palmdale-train-yard-worker-302152522.html", "confidence": "medium", "dollarAmount": 58358431, "jurisdiction": "CA"}, {"year": 2017, "notes": "Also cited under 'Punitive Damages' below -- documented, camera-captured evidence of PRIOR similar incidents on the exact same hazard is what elevated this from an ordinary notice-based slip-and-fall claim into a wantonness (Alabama's willful/wanton punitive-damages standard) finding. Illustrates how directly the 'hazardNoticeProven' fact and the punitive-damages 'egregiousConductAlleged' fact can be linked in a real fact pattern -- the same prior-incident evidence proved both.", "outcome": "Plaintiff's foot became trapped in a display pallet while reaching for a watermelon; when he tried to turn, his foot caught and he fell, suffering a severe hip injury. Store security footage showed multiple OTHER shoppers had gotten their feet caught in the same pallet before the plaintiff's fall -- evidence the jury found sufficient to establish wantonness, not just ordinary negligence. Jury awarded $2.5 million in compensatory damages and $5 million in punitive damages ($7.5 million total).", "caseName": "Henry Walker v. Walmart Stores, Inc.", "citation": "Russell County, Alabama (Phenix City) jury verdict, November 2017 (docket number not independently confirmed)", "sourceUrl": "https://www.cbsnews.com/news/walmart-shopper-hurt-while-buying-melon-wins-7-5m-verdict/", "confidence": "medium", "dollarAmount": 7500000, "jurisdiction": "AL"}, {"year": 2024, "notes": "The clean, current, high-court illustration of why 'no notice evidence' is the single most common reason a slip-and-fall claim fails -- Texas requires proof the specific hazard existed long enough for the owner to have discovered it, not just evidence the owner knew about a related risk in the abstract. Also cited under 'Dangerous Condition / Failure to Warn' below, since the underlying theory pled was failure to warn of the puddle.", "outcome": "Plaintiff, a bank employee working inside a Randalls grocery store, slipped on a puddle of water that formed after another employee placed a leaking item in a shopping cart. She argued the store's knowledge of the leaking item was itself evidence of actual knowledge of the resulting puddle. The Texas Supreme Court disagreed, holding that actual knowledge of a dangerous condition requires specific evidence the condition ITSELF existed at the time of the accident -- knowledge of an upstream cause is not enough. Reversed the court of appeals in the store's favor.", "caseName": "Albertsons, LLC v. Mohammadi", "citation": "___ S.W.3d ___, No. 23-0041 (Tex. Apr. 5, 2024)", "sourceUrl": "https://law.justia.com/cases/texas/supreme-court/2024/23-0041.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "TX"}, {"year": 2025, "notes": "Corroborated by independent reporting (Yahoo News, jamesalexanderlaw.com) but the plaintiff's full name and the case caption/docket were not disclosed in any source found. A useful commercial-retail (sidewalk area used for the store's own business operations) illustration of a very long-tail claim, and of how a weak causation defense (blaming a pre-existing condition) can backfire with a jury once notice and a serious injury are both established.", "outcome": "During Labor Day weekend 2014, plaintiff slipped on fish debris/guts that had accumulated on the public sidewalk directly outside a Citarella gourmet grocery store on the Upper West Side. She suffered a total knee dislocation and three ruptured ligaments, underwent at least twelve surgeries over the ensuing decade, and never regained full mobility. After a roughly ten-year litigation, a Manhattan jury found the store liable for failing to keep the sidewalk area it used for its fish business clean and safe, and awarded $6.45 million. The store's defense -- that a pre-existing lupus diagnosis, not the fall, explained her injuries -- was rejected by the jury.", "caseName": "(Plaintiff identified only as \"Castillo\") v. Citarella (2135 Broadway LLC / Citarella Operating LLC)", "citation": "Manhattan (New York County) jury verdict, reported April 8, 2025 (case name/docket not independently confirmed)", "sourceUrl": "https://www.ilovetheupperwestside.com/salsa-dancer-awarded-6-45-million-after-slipping-on-fish-guts-outside-citarella/", "confidence": "medium", "dollarAmount": 6450000, "jurisdiction": "NY"}, {"year": 2025, "notes": "Real docket number, court, and judge independently confirmed across multiple outlets (WFTV, CBS Miami, WSOC, Law Blog). A strong, current (Oct. 2025) commercial PARKING LOT hazardous-condition exemplar -- exactly the fact pattern this claim type is meant to model -- and illustrates how dramatically an unreasonable pretrial settlement position can backfire once liability and building-code evidence are strong.", "outcome": "On December 23, 2019, a 44-year-old woman parked at a Target store in the Winter Garden Village shopping center and, while carrying her daughter and navigating between vehicles to avoid holiday traffic, stepped on a spot where the seam between the parking lot's asphalt and a concrete gutter/curb created an abrupt, code-violating elevation change. She fractured her tibia, fibula, and lateral malleolus. She rejected the defense's highest pretrial settlement offer of $250,000; the jury found Target 90% at fault and Site Centers (the shopping-center owner) partially at fault, awarding $11,391,183.28 -- more than 45 times the rejected offer.", "caseName": "(Plaintiff not named in public reporting) v. Target Corporation and Site Centers Corp.", "citation": "Circuit Court for the Ninth Judicial Circuit, Orange County, Florida, Case No. 2021-CA-000145-O, jury verdict Oct. 17, 2025 (Judge John Marshall Kest)", "sourceUrl": "https://www.forthepeople.com/blog/morgan-morgan-wins-113-million-verdict-against-target/", "confidence": "high", "dollarAmount": 11391183, "jurisdiction": "FL"}, {"year": 2016, "notes": "Sourced from a plaintiff-firm litigation-summary blog rather than a directly retrieved court record; case caption and county court not independently confirmed. Included as a real, large, commercial-parking-lot (grocery store) ice/snow hazardous-condition data point, an older but still commonly cited verdict in NY practice.", "outcome": "Plaintiff slipped and fell on ice in a Scarsdale-area supermarket's parking lot, fracturing her shoulder, injuring her elbow, and herniating a disc. The jury found the supermarket failed to adequately clear or treat the ice given winter conditions and awarded $10.9 million.", "caseName": "(Plaintiff, elementary-school music teacher/cellist) v. (Scarsdale-area supermarket operator)", "citation": "Westchester County, New York jury verdict, 2016 (case name/docket not independently confirmed)", "sourceUrl": "https://www.jamesalexanderlaw.com/blog/significant-personal-injury-verdicts-in-slip-and-fall-cases/", "confidence": "low", "dollarAmount": 10900000, "jurisdiction": "NY"}, {"year": 2023, "notes": "Institutional/campus common-area fact pattern rather than pure retail, but structurally identical to a commercial-property hazardous-condition claim (an unmarked/unwarned tripping hazard placed by the property occupier itself). Sourced from a litigation-summary blog; case caption not independently confirmed.", "outcome": "An elderly Bronx woman tripped over an art installation on the Sarah Lawrence College campus, requiring hip surgery followed by two additional surgeries for complications. The jury found the college 100% at fault and awarded $10 million.", "caseName": "(Elderly plaintiff) v. Sarah Lawrence College", "citation": "Bronxville / Westchester County, New York jury verdict, 2023 (case name/docket not independently confirmed)", "sourceUrl": "https://www.jamesalexanderlaw.com/blog/significant-personal-injury-verdicts-in-slip-and-fall-cases/", "confidence": "low", "dollarAmount": 10000000, "jurisdiction": "NY"}, {"year": 2023, "notes": "A genuine, state-wide, doctrine-shifting decision directly relevant to this claim type -- it made Michigan meaningfully more plaintiff-favorable at the summary-judgment stage than the modifier note's implicit assumption of a stable, cross-state 'open and obvious' bar. Also independently relevant to 'Dangerous Condition / Failure to Warn' below.", "outcome": "In the companion Pinsky case, a customer tripped over a cable strung from a checkout counter to a display basket at a Kroger supermarket -- squarely a hazardous-condition slip/trip claim. The Michigan Supreme Court used the consolidated appeals (with the Kandil-Elsayed ice/snow gas-station case) to overrule three decades of precedent holding that an 'open and obvious' hazard categorically barred a premises-liability duty. The Court held the openness/obviousness of a condition is now folded into the BREACH and comparative-fault analysis -- ordinarily a jury question -- rather than defeating the claim at the duty stage on summary disposition.", "caseName": "Kandil-Elsayed v. F & E Oil, Inc.; Pinsky v. Kroger Co. of Michigan", "citation": "512 Mich. 95, 993 N.W.2d 178 (Mich. July 28, 2023)", "sourceUrl": "https://law.justia.com/cases/michigan/supreme-court/2023/162907.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "MI"}, {"year": 2024, "notes": "Full underlying facts of the alleged hazard were not independently retrieved (source is a secondary law-firm summary of the docket/outcome, not the opinion itself) -- treat as illustrative only that defense wins remain very much available in Michigan even under the new, more plaintiff-friendly Kandil-Elsayed framework, not as a fully verified fact pattern. Recommend pulling the actual unpublished opinion (Mich. Ct. App. No. 359033) before relying on it for anything beyond the bare outcome.", "outcome": "Applying the post-Kandil-Elsayed framework, the Michigan Court of Appeals reversed a trial court's denial of summary disposition and remanded for entry of summary disposition in favor of the defendant property owner (the City of Detroit).", "caseName": "Wright-Burton v. City of Detroit", "citation": "Unpublished per curiam opinion, Mich. Ct. App., No. 359033 (May 9, 2024)", "sourceUrl": "https://www.harveykruse.com/news-insights/fall-of-the-open-and-obvious-defense/", "confidence": "low", "dollarAmount": null, "jurisdiction": "MI"}, {"caseName": "Victoria Marcano v. Publix Super Markets, Inc.", "citation": "Case No. 2024-CA-001128, Circuit Court, Osceola County, Florida (jury verdict, reported Feb. 2026)", "year": 2026, "outcome": "Marcano slipped on liquid in the beverage aisle of a Publix grocery store in Kissimmee, Florida on June 5, 2023; trial evidence showed employees had already cleaned liquid in the same spot before her fall. After a six-day trial the jury found Publix 100% liable. She required three spinal surgeries (one cervical, two lumbar), and the jury awarded $3,967,000.", "dollarAmount": 3967000, "sourceUrl": "https://westorlandonews.com/multi-million-dollar-jury-verdict-against-publix-super-markets-in-florida/", "confidence": "high", "jurisdiction": "FL"}, {"caseName": "Deborah Fenton v. Nevada Property 1, LLC (The Cosmopolitan of Las Vegas)", "citation": "Eighth Judicial District Court, Clark County, Nevada, before Judge Eric Johnson (jury verdict, April 2025)", "year": 2025, "outcome": "Fenton slipped and fell on spilled water and glass at the Chandelier Bar during a private event at The Cosmopolitan Las Vegas hotel-casino on September 24, 2021, developing Complex Regional Pain Syndrome. A Clark County jury found the hotel liable for an unsafe/dangerous condition on its commercial premises and awarded $15,000,000 (about $1.24 million in past/future medical costs and roughly $13.7 million in past and future pain and suffering).", "dollarAmount": 15000000, "sourceUrl": "https://www.casino.org/news/jury-awards-15m-to-slip-and-fall-victim-at-cosmopolitan-las-vegas/", "confidence": "high", "jurisdiction": "NV"}, {"caseName": "William & Elaine Kidd v. WKS Restaurant Corporation (dba El Pollo Loco)", "citation": "Jury verdict, Kern County Superior Court, Bakersfield, California (exact verdict date and docket number not independently confirmed; reported figures range $16M-$16.5M across sources, most commonly cited as $16.2M)", "year": 2015, "outcome": "Kidd slipped and fell on a wet floor leaving the restroom of an El Pollo Loco restaurant in Bakersfield in 2012; employees had been cleaning the grills with slippery cleaning solution about an hour before closing (in violation of company policy against paying overtime for after-close cleaning). Kidd suffered a torn quadriceps tendon and a claimed mild traumatic brain injury. After a four-week trial, the jury found the restaurant negligent and awarded approximately $16.2 million.", "dollarAmount": 16200000, "sourceUrl": "https://www.turnto23.com/news/local-news/jury-awards-16-million-to-man-who-slipped-and-fell-at-bakersfield-el-pollo-loco", "confidence": "medium", "jurisdiction": "CA"}], "indemnification_contribution_claim": [{"year": 2013, "outcome": "Jury awarded $39 million and apportioned fault: 88% to subcontractor Advance Cast Stone, 10% to general contractor J.H. Findorff and Son, and 2% to owner Milwaukee County -- an allocation that then governed each defendant's indemnification/contribution exposure.", "caseName": "Kellner v. Advance Cast Stone Co. (Milwaukee Parking Structure Panel Collapse)", "citation": "Milwaukee County Circuit Court, Wisconsin (incident June 2010; jury verdict reported 2013)", "sourceUrl": "https://frenkelfirm.com/blog/39-million-awarded-in-parking-garage-collapse-lawsuit/", "confidence": "high", "dollarAmount": 39000000}, {"year": 2025, "notes": "The underlying liquidated-damages indemnification obligation itself was not in dispute in this ruling -- what was denied was the GC's attempt to also shift its OWN enforcement-litigation fees onto the subcontractor under the same clause. Useful as a real, current limiting citation: broad indemnity language does not automatically include fee-shifting for the indemnitee's cost of proving the claim, absent explicit contract language to that effect. dollarAmount reflects the $0 result of the fee-recovery motion specifically, not the separately-owed liquidated damages.", "outcome": "Subcontract required the subcontractor to indemnify the general contractor for liquidated damages the owner assessed against the GC due to the subcontractor's schedule failure. The GC then moved to also recover nearly $3.3 million in its own attorney's fees and costs incurred proving the indemnification claim itself; the court denied that fee-recovery motion, holding that indemnity language covering claims 'arising or in any way resulting from' the indemnified liability does not, without more explicit language, extend to fees incurred enforcing the indemnity provision against the indemnitor.", "caseName": "Engineering & Construction Innovations, Inc. v. Bradshaw Construction Corp.", "citation": "No. 20-CV-808 (ECT/SGE), 2025 WL 1790679 (D. Minn. June 30, 2025)", "sourceUrl": "https://www.fwhtlaw.com/blog/2025/08/15/recovery-of-attorneys-fees-under-indemnity-provisions-the-devil-is-in-the-details/", "confidence": "medium", "dollarAmount": 0, "jurisdiction": "Federal (D. Minn.)"}, {"year": 2017, "notes": "Unpublished (no binding precedential effect in Arizona) but factually rich and directly on point: confirms that broad 'arising out of or in connection with' indemnity language reaches a subcontractor's defective work WITHOUT the indemnitee having to separately prove negligence or causation -- a meaningfully lower bar for the general contractor than a narrower indemnity clause would impose, and the percentage-apportionment approach (72%/70.6% rather than 100%) is itself a useful data point for how courts split indemnification exposure among multiple responsible parties on the same underlying award.", "outcome": "General contractor sought indemnification from its grading subcontractor for a $1.75 million arbitration award to homeowners and $723,900 in separate litigation settlements, all arising from defects in a housing development. The subcontract required the subcontractor to indemnify for claims 'arising out of or in connection with' its work. The trial court, affirmed on appeal, held the subcontractor did not need to be shown negligent or at fault -- the broad 'arising out of or in connection with' language tied the indemnity obligation to the work itself, not to proof of fault -- and apportioned the subcontractor responsible for 72% of the arbitration award (~$1.26M) and 70.6% of the settlements (~$511,073), roughly $1.77 million combined.", "caseName": "Amberwood Development, Inc. v. Swann's Grading, Inc.", "citation": "No. 1 CA-CV 15-0786, 2017 Ariz. App. Unpub. LEXIS 207 (Ariz. Ct. App. Feb. 23, 2017) (unpublished)", "sourceUrl": "https://arizonaconstructionandthelaw.com/amberwood-development-inc-et-al-v-swanns-grading-inc-persuasive-authority-on-the-scope-of-indemnification-provisions/", "confidence": "medium", "dollarAmount": 1770000, "jurisdiction": "AZ"}, {"year": 2025, "notes": "Commercial multifamily (apartment building) fact pattern. Directly confirms the file's existing constructionIndemnityStateModifiers treatment of Virginia-style anti-indemnity statutes: an improperly broad clause is VOIDED outright (no partial enforcement/reformation), not merely narrowed to a proportionate-fault ceiling.", "outcome": "General contractor Fortune-Johnson was sued for breach of contract over construction of an apartment building and, in turn, filed separate indemnification actions against each of its subcontractors. The Virginia Court of Appeals held the subcontracts' primary indemnity clause was void under Va. Code Sec. 11-4.1 because it expressly required the subcontractors to indemnify the general contractor for the general contractor's OWN negligence -- an obligation the statute squarely prohibits -- and rejected the contractor's argument that the clause's 'to the fullest extent permitted by law' language saved it, holding Virginia courts lack authority to blue-pencil an overbroad indemnity provision into an enforceable one.", "caseName": "Fortune-Johnson, Inc. v. QFS, LLC", "citation": "No. 1757-23-4 (Va. Ct. App., decided/reported Mar. 2025)", "sourceUrl": "https://valawyersweekly.com/2025/03/16/general-contractors-actions-asserting-indemnification-fail/", "confidence": "high", "dollarAmount": null, "jurisdiction": "VA"}, {"year": 2025, "notes": "A very recent, high-profile New York Court of Appeals decision on a commercial building. Key addition to the model: it shows a facially enforceable indemnity clause can still fail on CAUSATION/SCOPE grounds (whether the claim 'arises out of' the indemnitor's specific work) -- a distinct failure mode from the enforceability-ceiling logic (indemnityForm: limited/intermediate/broad) that the state-law modifier currently captures.", "outcome": "A worker fell from a ladder that had been left open and unattended by an employee of DAL Electrical Corporation, the electrical subcontractor on a Rockefeller Center-area project where Rockefeller Center North, Inc. was the owner and JRM Construction Management LLC was the construction manager/general contractor. The New York Court of Appeals held DAL owed no contractual indemnity to the owner or GC because the injury did not 'arise out of, or result from,' the performance of DAL's own contracted electrical work -- and refused to fall back on a broader indemnity clause elsewhere in the same contract, reasoning that doing so would render the narrower, more specific indemnity provision meaningless.", "caseName": "Dibrino v. Rockefeller Center North, Inc.", "citation": "2025 N.Y. Slip Op. 07077 (N.Y. Dec. 18, 2025)", "sourceUrl": "https://www.courtlistener.com/opinion/10771263/dibrino-v-rockefeller-ctr-n-inc/", "confidence": "high", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 2024, "notes": "Not a GC-vs-subcontractor indemnification fight -- an insurer-vs-insured dispute over whether the insured association's own settlement with the underlying construction-defect tortfeasors improperly extinguished the carrier's contribution/subrogation rights. Directly relevant to any owner/association negotiating a global construction-defect settlement while a property or liability carrier has already paid out: releasing the contractors without protecting the carrier's contribution rights can itself become a second, independent claim.", "outcome": "After a unit owner sued the Jade Beach condominium association and two construction companies, the association's insurer, Seneca, paid the association $1 million under its policy. The association then settled with and released the construction-defect defendants. Seneca sued the association for breach of contract, alleging the releases impaired Seneca's subrogation/contribution rights against those construction defendants. The trial court dismissed Seneca's suit as premature, reasoning Seneca first had to sue the released construction defendants itself and obtain a judgment establishing impairment. The Third District Court of Appeal reversed, holding the policy did not require the insurer to sue the released parties first before pursuing its own breach-of-contract claim against its insured.", "caseName": "Seneca Specialty Insurance Co. v. Jade Beach Condominium Association, Inc.", "citation": "No. 3D22-1290, 388 So. 3d 292 (Fla. 3d DCA Apr. 3, 2024)", "sourceUrl": "https://law.justia.com/cases/florida/third-district-court-of-appeal/2024/3d22-1290.html", "confidence": "high", "dollarAmount": 1000000, "jurisdiction": "FL"}, {"year": 2026, "notes": "CAVEAT: the underlying project here was a single-family residence, not commercial/multifamily -- included despite that because the holding restates a live, currently-litigated New York rule with obvious commercial application: where a construction-defect plaintiff alleges the GC's OWN failure to build to spec (the typical construction-defect pleading), COMMON-LAW indemnification against downstream subs is categorically unavailable no matter how the sub-subcontracts are worded -- a failure mode distinct from, and not currently modeled alongside, the contractual-indemnity-ceiling logic already in the file.", "outcome": "An owner sued general contractor Gentry for breach of contract, alleging its work on a residence failed to comply with codes, plans, and specifications. Gentry brought a third-party action against sub-subcontractors D&C and Shope seeking common-law indemnification and contribution. The Appellate Division affirmed dismissal of Gentry's common-law indemnification claim against both, holding common-law indemnification is available only where the indemnitee's own conduct is 'solely passive' and its potential liability purely vicarious -- and here the owner's complaint alleged Gentry's OWN failure to construct the project according to the required standards, precluding common-law indemnification regardless of what D&C's and Shope's subcontracts said.", "caseName": "450 Gin Lane SH, LLC v. Gentry Constr. Co., Inc.", "citation": "2026 NY Slip Op 00228 (App. Div., 2d Dep't 2026)", "sourceUrl": "https://www.nycourts.gov/Reporter/3dseries/2026/2026_00228.htm", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 2023, "notes": "Atypical fact pattern for this claim type -- a staffing-agency/temporary-worker agreement rather than a classic GC-subcontractor construction subcontract, and the underlying loss was property damage to the GC's own project rather than a third-party claim. Useful anyway as a real, current illustration that an indemnity clause only functions as true 'indemnification' when it shifts liability for a THIRD PARTY's claim -- a first-party loss dressed up as an indemnity claim will fail regardless of how the anti-indemnity statute would otherwise apply. dollarAmount reflects Calabretto's $0 recovery on the indemnity theory, not the $61,653.92 underlying property damage.", "outcome": "A temporary forklift operator supplied to general contractor Calabretto by staffing agency Tradesmen International damaged a precast beam and concrete floor, causing $61,653.92 in damages. Calabretto sought that amount from Tradesmen under the staffing agreement's indemnification clause; Tradesmen refused to pay. The Iowa Court of Appeals affirmed judgment for Tradesmen, holding (1) Iowa's construction-contract anti-indemnity statute (Iowa Code \u00a7 537A.5, enacted 2011) did not apply because the staffing agreement predated the statute, but (2) even without the statute, the clause did not create 'true indemnity' because only Calabretto itself -- not a third party -- was injured, so Calabretto's claim was really one for breach of contract/negligence, not indemnification, and it had not adequately pleaded or proven that theory.", "caseName": "Calabretto Building Group v. Tradesmen International, LLC", "citation": "Iowa Court of Appeals, opinion issued November 8, 2023 (exact reporter citation not independently confirmed)", "sourceUrl": "https://www.fredlaw.com/the-construction-counselor/iowa-court-of-appeals-issues-opinion-re-construction-contracts-temporary-workers-indemnity", "confidence": "medium", "dollarAmount": 0, "jurisdiction": "IA"}, {"year": 2010, "notes": "This is the foundational Virginia Supreme Court precedent underlying the reasoning the Virginia Court of Appeals applied 15 years later in Fortune-Johnson, Inc. v. QFS, LLC (already cited in this claim type's sample) -- pairing the two shows the same Virginia rule (broad/intermediate indemnity void, no blue-penciling) being applied consistently from a severe personal-injury/wrongful-death fact pattern (2010) through to a pure commercial defect-repair-cost fact pattern (2025). No confirmed dollar amount located for the indemnification claim itself; dollarAmount left null rather than guessed.", "outcome": "General contractor Uniwest sought contractual indemnification from its elevator subcontractor, Amtech, after a scaffold erected in an elevator shaft collapsed, injuring and killing Amtech's own employees. The Supreme Court of Virginia held Virginia's anti-indemnity statute (now Va. Code \u00a7 11-4.1) voids indemnification clauses requiring a subcontractor to indemnify a general contractor for the GC's OWN negligence, whether that negligence is sole or merely concurrent with the subcontractor's -- i.e., Virginia permits only a narrower, proportionate/partial-indemnity form, not the full ('intermediate-form') indemnity Uniwest's contract sought to enforce.", "caseName": "Uniwest Constr., Inc. v. Amtech Elevator Servs., Inc.", "citation": "699 S.E.2d 223 (Va. 2010), opinion withdrawn in part on reh'g, 714 S.E.2d 560 (Va. 2011)", "sourceUrl": "https://www.haynesboone.com/news/publications/construction-law-practice-tip-anti-indemnity-statutes", "confidence": "medium", "dollarAmount": null, "jurisdiction": "VA"}, {"year": 2022, "notes": "Based on a secondary source's discussion and pin-cite quotation of the opinion rather than a full read of the case; the underlying parties' precise roles (GC/subcontractor/owner) and any dollar amount were not independently confirmed beyond the quoted holding. Included because it is the Texas Supreme Court's own recent, controlling interpretation of Chapter 151 -- directly relevant to the 'limited' classification Texas already carries in this file's constructionIndemnityStateModifiers table -- and it illustrates the same causation/scope failure mode as Dibrino v. Rockefeller Center North (already cited) arising in a different state's statutory scheme rather than New York's common law.", "outcome": "The Texas Supreme Court construed Chapter 151 of the Texas Insurance Code (Texas's construction anti-indemnity statute), holding that whether an indemnity clause is enforceable turns not on who was ACTUALLY at fault for the underlying injury, but on whether the claim for which indemnity is sought was 'caused by' the fault or contractual breach of the INDEMNITEE specifically -- a causation/scope inquiry distinct from a pure fault-allocation analysis.", "caseName": "Signature Industrial Services, LLC v. International Paper Co.", "citation": "638 S.W.3d 179 (Tex. 2022)", "sourceUrl": "https://www.texasconstructionlawblog.com/2024/04/broad-form-indemnities-in-construction-contracts/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "TX"}, {"year": 2017, "notes": "Unpublished/memorandum decision (limited precedential weight in Indiana) but a real, on-point illustration of Indiana's anti-indemnity statute defeating a GC's indemnification claim in a personal-injury-during-construction fact pattern -- adds a fifth distinct state (after WI/AZ/VA/NY/FL already represented in this claim type's sample) to the anti-indemnity variation record. dollarAmount reflects the $0 indemnification recovery Wilhelm obtained from Secura/the sub-subcontractor, not the underlying injury damages.", "outcome": "A sub-subcontractor's employee was injured when scaffolding toppled during a lift operation. General contractor Wilhelm Construction sought contractual indemnification from the sub-subcontractor and its insurer, Secura. The Indiana Court of Appeals held Indiana's Anti-Indemnity Statute rendered the indemnity clause void because it purported to require indemnification for the SOLE negligence of the promisee (Wilhelm) or of Wilhelm's other independent contractors -- and because the sub-subcontractor qualified as an 'independent contractor' under the statute's protections, neither it nor Secura owed Wilhelm indemnity.", "caseName": "Wilhelm Construction, Inc. v. Secura Ins.", "citation": "2017 WL 2265402 (Ind. Ct. App. 2017) (unpublished/memorandum decision)", "sourceUrl": "https://dsvlaw.com/indianas-anti-indemnity-statute-for-construction-and-design-professionals/", "confidence": "medium", "dollarAmount": 0, "jurisdiction": "IN"}, {"year": 2014, "notes": "Directly illustrates a THIRD approach to an over-broad indemnity clause, distinct from the two already in this file's sample: Virginia (Fortune-Johnson) VOIDS an overbroad clause outright and refuses to blue-pencil it, while North Carolina here BLUE-PENCILS the offending 'in part' language down to an enforceable 'in whole' standard and evaluates the claim under the narrowed clause -- a materially more indemnitee-friendly remedial approach even though the GC still lost here on the facts. This state-by-state variation in REMEDY (void vs. blue-pencil), not just in which clauses are barred, is not currently captured by the file's constructionIndemnityStateModifiers table and may be worth a future add.", "outcome": "In a construction-defect-adjacent contract dispute administered through bankruptcy proceedings, a general contractor sought indemnification from a subcontractor under a clause requiring the subcontractor to indemnify for claims caused 'in whole or in part' by the subcontractor's negligence. Applying North Carolina's anti-indemnity statute (N.C. Gen. Stat. \u00a7 22B-1), the court used the 'blue pencil' doctrine to strike the offending 'or in part' language, narrowing the clause to cover only damages caused entirely ('in whole') by the subcontractor. Because the evidence did not show the damages were caused ENTIRELY by the subcontractor, the GC's narrowed indemnity claim was ultimately dismissed.", "caseName": "In re New Bern Riverfront Development, LLC", "citation": "U.S. Bankruptcy Court, Eastern District of North Carolina, 2014 (exact reporter citation/docket not independently confirmed)", "sourceUrl": "https://nc-construction-law.com/2014/10/01/court-typically-will-enforce-north-carolinas-anti-indemnity-statute-but-how-far/", "confidence": "medium", "dollarAmount": 0, "jurisdiction": "NC"}], "tortious_interference_lost_profits": [{"url": "https://www.courtlistener.com/opinion/10460551/exrp-14-holdings-llc-v-ls-14-ave-llc/", "year": 2024, "notes": "IMPORTANT SCOPE NOTE: this is a construction-delay dispute between commercial parties, not a landlord self-help lockout case -- there is no directly on-point published decision found for a tenant suing its own landlord for tortious interference with the tenant's third-party contracts arising from a lockout, despite multiple search angles. Cited here only for the general doctrine this claim type relies on (interference by disabling a party's own performance is actionable even without inducing a third party's breach). The apparent rarity of a squarely on-point case suggests this theory is infrequently pursued as a stand-alone claim -- most wrongful-lockout plaintiffs recover through the direct lockout claim instead -- which is itself a reason to treat this claim's probability range as more speculative than the other lease-disputes claims until better authority surfaces.", "outcome": "Denied summary judgment dismissing a tortious interference claim, holding that a party who prevents the plaintiff from performing its own contract with a third party can be liable even where the third party exercised a lawful termination right rather than breaching -- the interference lies in disabling the plaintiff's performance, not in inducing a breach.", "caseName": "EXRP 14 Holdings LLC v. LS-14 Ave LLC", "citation": "Index No. 652698/2022 (N.Y. Sup. Ct., Com. Div., Oct. 7, 2024) (Crane, J.)", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 1989, "notes": "IMPORTANT VERIFICATION GAP: this session confirmed the case is real (citation, court, date, and core facts verified via CourtListener, which also shows it has been cited 145 times -- indicating real, lasting doctrinal significance), but could NOT independently confirm the specific dollar damages ultimately awarded (this is a well-known case in property-law teaching materials for its intentional-infliction-of-emotional-distress and business-tort holdings arising from a commercial lockout, but that general reputation was not re-verified against the primary opinion text in this session -- pull the full opinion before citing a specific damages figure or holding to a client). Still, this is by far the most squarely on-point real case found for this claim type's specific theory (a lockout disrupting the tenant's OWN business relationships, not just its occupancy) -- meaningfully better than the existing EXRP 14 Holdings citation, which the file's own note already flags as off-point (a construction-delay case, not a lockout case).", "outcome": "Motel owners (K & K Management) had contracted with the Lees to operate the motel's restaurant under a profit-sharing lease arrangement. About two years in, the motel owners decided terminating the arrangement was more efficient than continuing it, and LOCKED OUT the restaurant operators without notice as their chosen termination method -- disrupting the restaurant operators' ongoing business operations and their relationships with the business's own customers, suppliers, and staff. The Maryland Court of Appeals (the state's highest court at the time) addressed the propriety of self-help lockout as a termination strategy and the tort theories available to a locked-out commercial tenant whose business relationships are disrupted by the lockout itself, not merely its exclusion from the premises.", "caseName": "K & K Management, Inc. v. Chul Woo Lee", "citation": "557 A.2d 965, 316 Md. 137 (Md. 1989)", "sourceUrl": "https://www.courtlistener.com/opinion/2388193/k-k-management-inc-v-chul-woo-lee/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "MD"}, {"year": 1964, "notes": "DOLLAR AMOUNT NOT CONFIRMED (the $400/month sublease rate and remaining term/option period are confirmed via secondary summary; the final judgment total was not independently re-derived from the primary opinion in this session). This is a genuinely on-point precedent for this claim type's specific fact pattern -- a landlord's lockout disrupting the TENANT's own contractual relationship with an independent third party (here, a sublessee), not merely the tenant's occupancy -- arguably more squarely on point than either existing citation in this claim type's array. However, it is old (1964) and, based on the secondary description, the theory of recovery reads more like ordinary lockout/breach damages (lost rental income the tenant would have received) than a freestanding tortious-interference-with-contract tort claim; verify the actual pleaded cause of action in the full opinion before relying on it as a 'tortious interference' precedent specifically, as opposed to a lost-income component of ordinary wrongful-lockout damages.", "outcome": "A commercial landlord wrongfully locked a tenant out of leased space. At the time, the tenant was subletting part of the space to a third party for $400/month for the remainder of the lease term (plus a 10-year option period). The tenant sued for, among other things, the income lost from the disrupted sublease. The Texas court of appeals upheld the tenant's damages award for that lost sublease income, holding the tenant had adequately proven the income it was denied by the lockout's disruption of its sublease relationship with the third-party sublessee.", "caseName": "McKenzie v. Carte", "citation": "385 S.W.2d 520 (Tex. Civ. App.\u2014Houston 1964, no writ) -- NOTE: CourtListener also lists a related opinion captioned \"Carte v. McKenzie\" from an earlier stage of the same underlying dispute; confirm exact procedural posture and party alignment before citing.", "sourceUrl": "https://www.courtlistener.com/opinion/2406959/mckenzie-v-carte/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "TX"}, {"year": 2026, "notes": "SQUARELY ON POINT on the facts (self-help lockout that disrupted the tenant's own negotiated relationship/contract with a third party -- its prospective business purchaser) -- but the tenant LOST. Useful precisely because it shows that even in a fact pattern matching this claim type exactly, courts routinely grant summary judgment for the landlord absent proof of conduct beyond ordinary economic self-interest (i.e., true 'improper means' or malice). This should be read as evidence the claim is hard to win, not as a template for expected recovery.", "outcome": "Plaintiffs leased commercial space from defendant landlords (Edison Property Investing, LLC and Pina Property Investing, LLC) and operated a restaurant. While plaintiffs were negotiating to sell the restaurant business to a group of prospective purchasers (Petrick LLC and individual defendants), the landlords discovered rent arrears, changed the locks, and retook possession in February 2017 under a lease clause permitting reentry on default. The landlords then leased the premises directly to the tenant's own prospective purchasers. Plaintiffs sued for breach of contract, wrongful eviction, tortious interference with contract, and tortious interference with prospective business relations -- squarely alleging that the landlord's self-help re-entry disrupted the tenant's own negotiated business-sale relationship with a third party. The Appellate Division affirmed summary judgment for all defendants on all four causes of action: the self-help re-entry was valid because the lease reserved the right and the landlords gave proper default notice; the tortious-interference-with-contract claim failed because defendants did not intentionally procure breach of a specifically identified valid contract; and the tortious-interference-with-prospective-business-relations claim failed because the landlords' and purchasers' conduct was motivated by ordinary economic self-interest, which as a matter of law cannot be 'wrongful means' or 'sole malice.' No damages were awarded because the claims were dismissed.", "caseName": "Nolan v. Edison Property Investing, LLC", "citation": "2026 NY Slip Op 03175 (App. Div., 2d Dep't, May 20, 2026), appeal Nos. 2022-01120, 2022-03164", "sourceUrl": "https://caselaw.findlaw.com/court/ny-supreme-court/39905.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 2013, "notes": "DOCTRINAL/ANALOGOUS ONLY, and the fact pattern runs in the OPPOSITE direction from the claim type being modeled: here the LANDLORD is the plaintiff suing the TENANT for interfering with the landlord's prospective contract with a different (replacement) service provider, not a tenant suing a landlord over disrupted tenant-side contracts. Cited only because it is the leading, heavily-cited Texas Supreme Court authority establishing that unlawful possession/occupancy of leased commercial space can itself be the 'independently tortious' predicate act supporting a tortious-interference-with-prospective-business-relations claim in a landlord-tenant context.", "outcome": "Coinmach leased laundry rooms from an apartment complex and installed its own coin-operated machines used by the landlord's residential tenants. After the property was sold in foreclosure, the new owner (Aspenwood) demanded Coinmach vacate; Coinmach refused and held over for six years, at one point using self-help writs of reentry to forcibly remove a competing laundry vendor Aspenwood had installed in an abandoned laundry room. Aspenwood sued Coinmach (note: landlord suing tenant, not tenant suing landlord) for trespass and for tortious interference with prospective business relations, alleging Coinmach's continued unlawful occupancy prevented Aspenwood from contracting with a replacement laundry-service company. The Texas Supreme Court held that a tenant at sufferance is a trespasser and can be liable in tort, including for tortious interference with prospective business relations, because the ongoing trespass was independently tortious conduct capable of satisfying the 'improper means' element; it remanded for the trial court to determine whether Aspenwood could prove interference with a reasonably probable contract within the limitations period. No final damages figure was set by this opinion.", "caseName": "Coinmach Corp. f/k/a Solon Automated Services, Inc. v. Aspenwood Apartment Corp.", "citation": "417 S.W.3d 909 (Tex. 2013)", "sourceUrl": "https://cases.justia.com/texas/supreme-court/11-0213-1.pdf", "confidence": "high", "dollarAmount": null, "jurisdiction": "TX"}, {"year": 2020, "notes": "SQUARELY ON-POINT on the fact-pattern element (a landlord-side actor allegedly disrupting the tenant's own contracts with its third-party customers via exclusionary/harassing conduct at the leased premises), but only an order denying a motion to dismiss -- establishes the claim is legally viable on these facts, not that the tenant proved or recovered anything. The 'landlord' here is a municipal airport authority terminating a month-to-month lease through proper legal notice, a looser fit than a private landlord's self-help lockout.", "outcome": "Plaintiffs operated a flight training school out of two hangars leased month-to-month from the City of Hickory at the municipal airport. After the city gave notice terminating the leases, plaintiffs alleged that airport personnel harassed the tenant's own flight-training students -- the tenant's actual paying customers -- and prevented those students from accessing their aircraft, causing at least three students to cancel their contracted flight-instruction relationships with the tenant. The North Carolina Business Court dismissed the breach-of-contract claim (the city had given legally sufficient notice) but denied the motion to dismiss the tortious-interference-with-contract claim, holding that the complaint adequately alleged the city intentionally disrupted contracts the tenant had with its own third-party customers. This is a pleading-stage ruling; no damages or merits verdict is reported.", "caseName": "VanFleet v. City of Hickory", "citation": "2020 NCBC 25, 2020 WL 1528629 (N.C. Super. Ct., Bus. Ct. Div., Mar. 30, 2020), Docket No. 19-CVS-2798", "sourceUrl": "https://www.nccourts.gov/assets/documents/opinions/2020_NCBC_25.pdf", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NC"}, {"year": 2007, "notes": "PARTIALLY ON POINT with a real verification gap: confirms a NY appellate court recognizing and awarding damages on a 'tortious interference with prospective contractual relations' claim arising directly from a landlord's wrongful/self-help eviction -- one of the few citations found anywhere with an actual dollar recovery tied to this theory. Could not confirm whether the interfered-with relations were a SPECIFIC identified third party (customers, suppliers, a business sale) versus a more generalized 'lost ability to continue operating' theory. Treat as supporting authority for the general damages theory, not confirmed proof of the narrower fact pattern.", "outcome": "Plaintiff operated a bagel shop as a commercial tenant. On October 31, 1997, the landlord defendants committed a trespass and wrongfully evicted the tenant from the premises without legal process. Plaintiff sued for trespass, wrongful eviction, and tortious interference with prospective contractual relations. At trial, plaintiff established liability on all three causes of action; the trial court initially awarded only nominal damages of one dollar, but the Appellate Division modified the judgment on appeal and increased the award to $30,000, plus prejudgment interest running from the date of the wrongful eviction/lockout.", "caseName": "North Main St. Bagel Corp. v. Duncan", "citation": "2007 NY Slip Op 01700 (App. Div., 2d Dep't 2007)", "sourceUrl": "https://www.nycourts.gov/Reporter/3dseries/2007/2007_01700.htm", "confidence": "medium", "dollarAmount": 30000, "jurisdiction": "NY"}], "dangerous_condition_failure_to_warn": [{"year": 2023, "notes": "Relied entirely on a litigation-marketing aggregator summary rather than a directly retrieved court record -- exact trial date/docket not independently confirmed. Included as a real, on-point plaintiff-favorable data point for a pure failure-to-warn theory (building-code violation + no posted warning), which is otherwise harder to find a clean win for than a slip-and-fall or negligent-security claim.", "outcome": "Plaintiff, a lawful invitee, tripped and fell down an exterior stairway at a Winsted, Connecticut property that violated the Connecticut State Building Code and carried no warning of the defect. Jury awarded $3.68 million against the property owner/manager for the dangerous, unwarned condition.", "caseName": "James Papp v. Hedgerow Properties, LLC", "citation": "Connecticut Superior Court jury verdict re: incident of Nov. 4, 2021 (docket number not independently confirmed)", "sourceUrl": "https://jurimatic.com/slip-and-fall-victory-3-7m-verdict-in-premises-liability-lawsuit", "confidence": "low", "dollarAmount": 3680000, "jurisdiction": "CT"}, {"year": 2024, "notes": "The DEFENSE-favorable counterweight to the Papp v. Hedgerow citation above -- shows the same claim type can fail entirely where the specific-knowledge element isn't met, even though a hazard plainly existed and caused a real injury.", "outcome": "See full outcome under 'Slip-and-Fall / Hazardous Condition' above -- the underlying theory pled here was specifically failure to WARN of the puddle (not failure to remedy it), and the Texas Supreme Court held that knowledge of an upstream cause (a leaking item placed in a cart) is not evidence of knowledge of the specific hazard itself.", "caseName": "Albertsons, LLC v. Mohammadi", "citation": "___ S.W.3d ___, No. 23-0041 (Tex. Apr. 5, 2024)", "sourceUrl": "https://law.justia.com/cases/texas/supreme-court/2024/23-0041.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "TX"}, {"year": 2023, "notes": "Directly on point for the 'openAndObviousDefenseRaised' modifier -- this decision made that defense meaningfully weaker in Michigan specifically.", "outcome": "See full outcome under 'Slip-and-Fall / Hazardous Condition' above. The Michigan Supreme Court eliminated the open-and-obvious doctrine as a categorical, duty-defeating bar, holding instead that the obviousness of a danger (and thus the necessity/adequacy of any warning) is a breach-and-comparative-fault question ordinarily reserved for the jury.", "caseName": "Kandil-Elsayed v. F & E Oil, Inc.; Pinsky v. Kroger Co. of Michigan", "citation": "512 Mich. 95, 993 N.W.2d 178 (Mich. July 28, 2023)", "sourceUrl": "https://law.justia.com/cases/michigan/supreme-court/2023/162907.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "MI"}, {"year": 2023, "notes": "Confirms the doctrinal category/date and docket number, but the full underlying facts (what the hazard was, and the case's ultimate disposition on remand) were not independently retrieved before the research budget was exhausted -- treat the legal holding as reliable but the case's concrete outcome as unconfirmed.", "outcome": "The Louisiana Supreme Court clarified a line of prior, internally inconsistent decisions (Pitre, Broussard, Bufkin) on how the open-and-obvious doctrine fits into Louisiana's negligence framework, holding definitively that whether a condition was open and obvious (and therefore not unreasonably dangerous) is analyzed as part of the BREACH element under Louisiana's risk-utility balancing test, not as a threshold bar to the existence of a duty.", "caseName": "Farrell v. Circle K Stores, Inc.", "citation": "2022-00849 (La. Mar. 17, 2023)", "sourceUrl": "https://www.louisianalawblog.com/general-litigation/louisiana-supreme-court-clarifies-the-open-and-obvious-defense-in-farrell-v-circle-k-stores-inc-et-al/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "LA"}, {"year": 2023, "notes": "A strong, on-point DEFENSE-favorable reversal for a pure failure-to-warn theory in a commercial building -- notable because a warning WAS posted, distinguishing it from cases (like the existing Papp v. Hedgerow citation) where no warning existed at all. Case name and general holding were independently retrieved and consistent across the source, but the exact published reporter citation was not independently confirmed and should be verified (e.g., via Westlaw/Lexis) before use in a filing.", "outcome": "A lighting-company employee servicing a commercial building was injured when a broken roof-access hatch slammed shut on him after he climbed a fixed ladder to the roof. He sued the building's owner and management company on a pure failure-to-warn/failure-to-repair theory, and a jury awarded $12.6 million. The Court of Appeal REVERSED, holding the owner/manager owed no duty because the hazard was reasonably ascertainable by the plaintiff and his employer: he had used the same hatch frequently enough to have observed its broken condition, a warning had actually been posted, and the access ladder itself did not extend fully to the roof (an additional warning sign of the hazard).", "caseName": "Acosta v. MAS Realty, LLC, et al.", "citation": "California Court of Appeal, Second Appellate District, 2023 (published/unpublished status and exact reporter citation not independently confirmed)", "sourceUrl": "https://www.laborandemploymentlawcounsel.com/2023/11/property-owner-not-liable-for-injury-to-employee-of-independent-contractor-12-6-million-verdict-reversed/", "confidence": "medium", "dollarAmount": 12600000, "jurisdiction": "CA"}, {"year": 2024, "notes": "Same case cited under 'Slip-and-Fall' above; underlying facts not independently confirmed beyond the bare outcome. Included here because it shows a defense win is still achievable post-Kandil-Elsayed even on an open-and-obvious-adjacent fact pattern -- but this should be verified against the actual unpublished opinion before being relied on.", "outcome": "Applying the post-Kandil-Elsayed framework, the Court of Appeals reversed the trial court and remanded for entry of summary disposition in favor of the defendant property owner.", "caseName": "Wright-Burton v. City of Detroit", "citation": "Unpublished per curiam opinion, Mich. Ct. App., No. 359033 (May 9, 2024)", "sourceUrl": "https://www.harveykruse.com/news-insights/fall-of-the-open-and-obvious-defense/", "confidence": "low", "dollarAmount": null, "jurisdiction": "MI"}, {"caseName": "James Shelton McClure and Madeline McClure v. Hotel Crescent Court, et al.", "citation": "Cause No. DC-22-05954, 162nd Judicial District Court, Dallas County, Texas (jury verdict, June 6, 2025)", "year": 2025, "outcome": "While walking their dog through the courtyard of the Hotel Crescent Court (a commercial hotel) in the early morning, McClure stepped into an empty, drained fountain basin about two feet deep, level with the surrounding concrete, in an unlit area with no cones, barriers, or warning signs marking the drop-off. The hotel knew the basin had been drained for winter but posted no warning. A Dallas County jury found the hotel 95% responsible and McClure 5% comparatively at fault, awarding a total verdict of $9.45 million for his orthopedic and neurological injuries, which included four ankle surgeries and a total ankle replacement.", "dollarAmount": 9450000, "sourceUrl": "https://texaslawbook.net/injured-man-gets-9-45m-jury-verdict-against-dallas-hotel/", "confidence": "high", "jurisdiction": "TX"}, {"caseName": "Giannone v. Professional Janitorial Maid Services (Marshalls store slip-and-fall)", "citation": "Superior Court of New Jersey, Law Division, Monmouth County (reported settlement, 2019; incident May 30, 2014)", "year": 2019, "outcome": "Frank Giannone, manager of a Marshalls retail store, slipped and fell on a floor that a janitorial contractor's worker had just mopped but failed to mark with wet-floor warning signs. Giannone underwent two spinal fusion surgeries he attributed to the fall and sued the cleaning company for failing to warn of the known wet-floor hazard it had itself just created. The parties settled for $1.5 million. Primary NJ Law Journal source is paywalled -- verified only via a law firm's blog quoting it, no independent docket number located.", "dollarAmount": 1500000, "sourceUrl": "https://www.levinandmalkin.com/missing-wet-floor-sign-a-factor-in-1-5-million-settlement/", "confidence": "medium", "jurisdiction": "NJ"}, {"caseName": "Confidential claimant v. Kroger Limited Partnership I (Rutherford County, TN store)", "citation": "Pre-suit settlement, Rutherford County, Tennessee (Smyrna Kroger location); no docket number (resolved before filing)", "year": 2022, "outcome": "A customer slipped on liquid another shopper had spilled minutes earlier near a self-checkout aisle at a Kroger grocery store. A Kroger employee admitted staff already knew about the spill and was on the way to clean it, but no warning sign or cone was placed in the interim, and the customer fell and suffered a rotator cuff injury requiring surgery. The claim was resolved pre-suit for $153,500. Self-reported only by the handling law firm's own case-results page -- no docket number, independent corroboration, or exact date located.", "dollarAmount": 153500, "sourceUrl": "https://wkjustice.com/case-results/153-500-settlement-for-slip-and-fall-at-rutherford-county-kroger/", "confidence": "low", "jurisdiction": "TN"}], "inadequate_security_third_party_crime": [{"year": 2023, "notes": "A real, reported, high-court-affirmed illustration of the single most important fact in this claim type: documented PRIOR incidents/concerns at the exact location (here, employees' own repeated safety complaints and a very recent armed robbery) drove a finding of foreseeability strong enough to apportion effectively zero fault to the actual shooter.", "outcome": "Plaintiff was shot and seriously injured in a CVS parking lot in a high-crime area; CVS employees had repeatedly raised safety concerns, and another employee had been robbed at gunpoint just three weeks before the shooting. A jury apportioned 95% fault to CVS, 5% to the plaintiff, and 0% to the (non-party) shooter, awarding $42.75 million. The Georgia Supreme Court affirmed, holding that the reasonable foreseeability of a third-party criminal act is assessed under the totality of the circumstances as part of the proprietor's O.C.G.A. Sec. 51-3-1 duty to keep the premises safe.", "caseName": "Georgia CVS Pharmacy, LLC v. Carmichael", "citation": "316 Ga. 718, 890 S.E.2d 209 (2023)", "sourceUrl": "https://law.justia.com/cases/georgia/supreme-court/2023/s22g0527.html", "confidence": "high", "dollarAmount": 42750000, "jurisdiction": "GA"}, {"year": 2023, "notes": "Relied on secondary/aggregator reporting rather than a directly retrieved court record -- a trial-court jury verdict, not an appellate opinion, so treat as illustrative of catastrophic-injury upside (a commercial LANDLORD held liable for a TENANT business's security failures on common areas) rather than a settled point of law.", "outcome": "Plaintiff was shot outside a nightclub tenant (Tootsie's Cabaret) at a shopping center, leaving him a ventilator-dependent quadriplegic. The jury found the shopping center's owner failed to provide adequate security given the foreseeable risk, and returned a $102.7 million verdict -- reported as the largest negligent-security verdict in U.S. history.", "caseName": "Barrak v. Report Investment Corporation", "citation": "Miami-Dade County Circuit Court jury verdict (docket number not independently confirmed)", "sourceUrl": "https://www.law.com/verdictsearch/verdict/shooting-victim-shopping-center-is-liable-for-injuries/", "confidence": "medium", "dollarAmount": 102700000, "jurisdiction": "FL"}, {"year": 1998, "notes": "The leading PRIOR-SIMILAR-INCIDENTS-style test still controlling in Texas -- directly maps onto the calculator's 'priorSimilarCrimeIncidents' modifier and is the doctrinal backbone behind later Texas verdicts like the Magnolia Cove Apartments case below. A defense-favorable outcome on its own facts (foreseeability NOT established), unlike most of the other citations in this set.", "outcome": "The Texas Supreme Court articulated the controlling five-factor test Texas courts still use to assess foreseeability of third-party crime for a negligent-security duty: the proximity, publicity, recency, frequency, and similarity of prior criminal activity to the crime at issue, considered together rather than in isolation. The court held the evidence in that case (a sexual assault at an apartment complex) was insufficient to establish foreseeability under the test.", "caseName": "Timberwalk Apartments, Partners, Inc. v. Cain", "citation": "972 S.W.2d 749 (Tex. 1998)", "sourceUrl": "https://www.robertrodriguez.lawyer/blog/2024/04/negligent-security-cases-in-texas/", "confidence": "high", "dollarAmount": null, "jurisdiction": "TX"}, {"year": 1999, "notes": "The classic BALANCING-TEST alternative to Texas's Timberwalk factors and California's prior-incident-oriented rule -- exactly the kind of doctrinal variation the calculator's state-aware engine needs real citations for. A clean, high-court DEFENSE win.", "outcome": "The Louisiana Supreme Court adopted a BALANCING test rather than a strict prior-similar-incidents rule: foreseeability and the gravity of the risk are weighed against the burden of the security measure the plaintiff says should have been provided. A very high degree of foreseeability can justify a duty to post guards; lesser foreseeability supports only lesser measures (lighting, cameras, fencing). On the facts (a robbery in a Sam's Club parking lot with only three prior unrelated property crimes in six years), the court held no duty to provide a security guard arose, and affirmed judgment for the defendant.", "caseName": "Posecai v. Wal-Mart Stores, Inc.", "citation": "752 So. 2d 762 (La. 1999)", "sourceUrl": "https://law.justia.com/cases/louisiana/supreme-court/1999/99c1222-opn.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "LA"}, {"year": 1993, "notes": "California's original, more restrictive (specific-harm-adjacent) foreseeability rule tying the burden of the requested security measure to how much foreseeability evidence is required -- later narrowed in scope (not overruled) by Delgado v. Trax Bar & Grill, below. A defense win on its facts.", "outcome": "A shopping-center tenant's employee was raped in an unattended common-area storefront. The California Supreme Court held that imposing a duty to hire security guards requires a HEIGHTENED showing of foreseeability -- generally prior similar incidents of violent crime on the premises -- because guards are a high-burden measure; without such a showing, the court affirmed summary judgment for the shopping center.", "caseName": "Ann M. v. Pacific Plaza Shopping Center", "citation": "6 Cal. 4th 666, 863 P.2d 207, 25 Cal. Rptr. 2d 137 (1993)", "sourceUrl": "https://www.torhoermanlaw.com/legal-guides/negligent-security-lawsuit-guide/", "confidence": "high", "dollarAmount": null, "jurisdiction": "CA"}, {"year": 2005, "notes": "Shows the same state (California) moving from a stricter, near-specific-harm-like posture (Ann M.) toward a sliding-scale/totality approach -- directly useful for illustrating that a state's foreseeability test is not always static, which matters for the calculator's state-aware modifiers. A plaintiff-favorable (reversal of defense summary judgment) outcome.", "outcome": "A patron was beaten in a bar's parking lot after bar security ejected him into a hostile crowd without calling police. The California Supreme Court clarified Ann M.: prior similar incidents are not an invariable prerequisite for every negligent-security duty -- they matter most where the plaintiff seeks a HIGH-burden measure like hired guards, but a lower-burden duty (like summoning police once a fight is brewing) can arise from a lower showing of foreseeability under the totality of the circumstances. Reversed summary judgment for the bar.", "caseName": "Delgado v. Trax Bar & Grill", "citation": "36 Cal. 4th 661, 113 P.3d 1159, 30 Cal. Rptr. 3d 145 (2005)", "sourceUrl": "https://www.torhoermanlaw.com/legal-guides/negligent-security-lawsuit-guide/", "confidence": "high", "dollarAmount": null, "jurisdiction": "CA"}, {"year": 1980, "notes": "New York's foundational negligent-security foreseeability case -- notable because it does not require a specific-harm or strict prior-similar-incident showing where the owner has voluntarily undertaken some security measure; the adequacy of that undertaking becomes the jury issue instead.", "outcome": "Plaintiff was shot in the lobby of an office building at a time when the lobby attendant -- whom the landlord had voluntarily assigned to watch the lobby -- was off performing a janitorial task. The intermediate appellate court had held the shooting unforeseeable as a matter of law; the New York Court of Appeals reversed, holding that once a landlord assumes a duty to provide some minimal lobby security, whether that duty was breached and whether the harm was foreseeable are ordinarily jury questions, not resolvable on a directed verdict.", "caseName": "Nallan v. Helmsley-Spear, Inc.", "citation": "50 N.Y.2d 507, 407 N.E.2d 451, 429 N.Y.S.2d 606 (N.Y. 1980)", "sourceUrl": "https://www.courtlistener.com/opinion/5684302/nallan-v-helmsley-spear-inc/", "confidence": "high", "dollarAmount": null, "jurisdiction": "NY"}, {"year": 1997, "notes": "This was Georgia's controlling (and comparatively rigid, PRIOR-SUBSTANTIALLY-SIMILAR-INCIDENTS) foreseeability rule for over 25 years, until the Georgia Supreme Court's 2023 Georgia CVS Pharmacy, LLC v. Carmichael decision (already cited in the file) shifted Georgia to a broader totality-of-the-circumstances test. Citing both together directly documents the exact doctrinal shift the calculator's Georgia-specific logic should reflect.", "outcome": "The Georgia Supreme Court held that for a prior criminal act to establish foreseeability, it must be 'substantially similar' to the crime at issue -- not identical, but similar enough that it should have drawn the landlord's attention to the danger -- and articulated a multi-factor test (location, nature, and extent of the prior crimes and their relationship to the crime at issue) for that comparison.", "caseName": "Sturbridge Partners, Ltd. v. Walker", "citation": "267 Ga. 785, 482 S.E.2d 339 (1997)", "sourceUrl": "https://law.justia.com/cases/georgia/supreme-court/1997/s96g1117-1.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "GA"}, {"year": 2025, "notes": "Reported directly by defense counsel's own case-results page rather than a retrieved court order (case caption not given), but a genuine, current (2025), commercial-retail-parking-lot DEFENSE win -- a needed counterweight showing that citing prior incidents alone does not guarantee surviving summary judgment when the specific incident itself was fast-moving and not closely tied to the pattern alleged.", "outcome": "Plaintiff was assaulted by a third party in a warehouse club's parking lot before entering the store; the altercation lasted under two minutes. Plaintiff argued the attack was foreseeable given prior criminal incidents at the property. The court granted summary judgment for the defendant, agreeing the specific attack was 'sudden and unforeseeable' notwithstanding the cited prior incidents, and the ruling triggered a fee-shifting Proposal for Settlement in the defendant's favor.", "caseName": "(Plaintiff assaulted in store parking lot) v. (national retail warehouse club)", "citation": "Miami-Dade County, Florida Circuit Court, summary judgment order reported March 13, 2025 (case name/docket not disclosed)", "sourceUrl": "https://www.wickersmith.com/case-results-verdicts/summary-judgment-miami-dade-county-florida-negligent-security/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "FL"}, {"year": 2025, "notes": "A very recent, well-documented totality-of-the-circumstances-style Georgia verdict post-Carmichael, and directly useful for the premises_punitive_damages calibration note below: despite facts that sound egregious (a documented pattern of violence and warnings that were ignored), the verdict as reported was entirely compensatory with no punitive component.", "outcome": "On May 12, 2024, Mariam 'Mari' Creighton, a 21-year-old college volleyball player, was fatally shot by a stray bullet when an individual brought a firearm into Elleven45 Lounge in Atlanta's Buckhead district and opened fire on patrons, despite the venue's alleged 'long history of violent incidents and repeated warnings.' The jury returned a $66.575 million verdict against the nightclub operators and related entities ($5.625 million pain-and-suffering/pre-death damages plus $60.95 million for wrongful death) -- entirely compensatory.", "caseName": "Creighton v. Elleven45 Lounge, LLC, et al.", "citation": "Fulton County State Court, Georgia, jury verdict Oct. 27, 2025; order entered Nov. 14, 2025 (Judge Fred Eady)", "sourceUrl": "https://www.beasleyallen.com/article/66-5-million-verdict-awarded-after-nightclub-negligence/", "confidence": "high", "dollarAmount": 66575000, "jurisdiction": "GA"}, {"caseName": "Kathleen Dawson v. Hilton Management LLC and Larry Joe Clowers, Jr.", "citation": "Jury verdict, 189th Judicial District Court, Harris County, Texas, Cause No. 2018-84453, Nov. 17, 2021", "year": 2021, "outcome": "A Hilton Americas-Houston guest was found unconscious outside the hotel; hotel staff, without verifying her identity or room assignment, wheeled her into the room of a male conference attendee (not her own registered room), where she was sexually assaulted. A Harris County jury found Hilton Management LLC 90% liable for negligent security/verification failures and returned a $44 million verdict (with the assailant assigned roughly the remaining liability). Two weeks later, Hilton and Dawson settled the case for a confidential, undisclosed amount before final judgment -- the $44M figure is the jury verdict, not the final payout.", "dollarAmount": 44000000, "sourceUrl": "https://www.click2houston.com/news/local/2021/11/19/woman-wins-44m-in-suit-against-houston-hilton-hotel-after-alleged-sexual-assault-lawyers-say/", "confidence": "high", "jurisdiction": "TX"}, {"caseName": "Wahlstrom v. JPA I Management Co., Inc. and JPA IV Management Co., Inc.", "citation": "Jury verdict, Massachusetts Superior Court, Aug. 11, 2015", "year": 2015, "outcome": "A woman was raped in the parking garage of a Radisson Hotel in Massachusetts in 2009. The hotel's owner and operator had learned that another woman was raped in the same garage just 12 days earlier but failed to warn guests or add security. A jury found the ownership/management entities liable for inadequate security and awarded the plaintiff $6.6 million; the man responsible later pleaded guilty to both rapes.", "dollarAmount": 6600000, "sourceUrl": "https://www.cbsnews.com/news/jury-awards-6-6m-to-woman-raped-in-massachusetts-hotel-parking-garage", "confidence": "high", "jurisdiction": "MA"}, {"caseName": "Estate of Trabis Ward v. American Federated Title Corp., Fitzgerald Group, LLC, and Aquanysa 1, LLC (d/b/a J&L Liquors)", "citation": "Settlement, Broward County, Florida (announced Aug. 29, 2022)", "year": 2022, "outcome": "Trabis Ward was shot and killed by an unknown assailant in the parking lot of a Lauderdale Lakes shopping plaza around midnight on October 10, 2020. The plaintiff alleged the plaza's anchor tenant, a liquor store, was allowed to operate as an unlicensed late-night gathering/bar spot with no security, fostering the violence that led to the shooting, and that the plaza owner/manager and liquor store failed to provide adequate security. The case settled for $4.55 million total ($1 million from the liquor store's policy limits and $3.55 million from the property owner/manager). Sourced only via the plaintiff's law firm's own case-results page -- no independent news/docket confirmation located.", "dollarAmount": 4550000, "sourceUrl": "https://haggardlawfirm.com/4-55-million-obtained-in-broward-county-negligent-security-wrongful-death-case/", "confidence": "medium", "jurisdiction": "FL"}, {"caseName": "Raman Reyes v. Rain On Events, LLC (and Ivis Perdomo)", "citation": "Jury verdict, Superior Court of New Jersey, Bergen County (Judge Michael Beukas), Feb. 7, 2025", "year": 2025, "outcome": "Raman Reyes was shot in the head and left legally blind while leaving a private party at Rain nightclub in Teaneck, NJ, after the club's security allegedly admitted a visibly intoxicated attendee without checking his bag (which held the gun) and ignored his stated threat to shoot someone. Following a two-week civil trial, a Bergen County jury awarded $3 million, assigning 60% fault to the nightclub operator Rain On Events, 35% to the shooter, and 5% to Reyes, reducing his net recovery to $2.85 million. Sourced only via the plaintiff's law firm's own case-results page -- no independent news/docket confirmation located.", "dollarAmount": 3000000, "sourceUrl": "https://pagliaralawgroup.com/law-firm-in-new-jersey-wins-3-million-verdict-against-nightclub-for-patron-shooting/", "confidence": "medium", "jurisdiction": "NJ"}], "environmental_insurance_coverage_dispute": [{"year": 2025, "outcome": "Case pending as of the research date (filed Nov. 26, 2025); insurers seek a declaration of no coverage obligation and separately dispute whether the owner qualifies as an insured and whether contamination predated the relevant policy periods.", "caseName": "Travelers Property Casualty Co. of America and St. Paul Fire and Marine Ins. Co. v. Washington Shoppes LP and The Broadbent Co.", "citation": "No. 49D01-2511-CE-056363 (Marion Superior Court, Ind., filed Nov. 26, 2025)", "sourceUrl": "https://www.theindianalawyer.com/articles/insurance-companies-sue-indy-shopping-center-in-dispute-over-environmental-site-cleanup-costs", "confidence": "high", "dollarAmount": null}, {"year": 2024, "outcome": "Fox seeks recovery of $235,683.63 in investigation and remediation costs already incurred, pursuing the insurers directly on CERCLA cost recovery, negligence, and unjust enrichment theories rather than filing separate coverage litigation against the city first.", "caseName": "Fox Investments LLC v. City of Kaukauna, et al.", "citation": "U.S. District Court for the Eastern District of Wisconsin (filed 2024)", "sourceUrl": "https://www.insurancebusinessmag.com/us/news/risk-compliance-legal/property-owner-pulls-three-insurers-into-sixfigure-site-cleanup-suit-583623.aspx", "confidence": "medium", "dollarAmount": 235683.63}, {"year": 2026, "outcome": "The court ruled Indian Harbor owed no coverage, finding the insurer properly denied the claim under the policy's site-development and pollution exclusions.", "caseName": "Regency Centers Corp. v. Indian Harbor Insurance Co.", "citation": "No. 3:24-cv-00428 (M.D. Fla.), ruling issued May 7, 2026", "sourceUrl": "https://www.law360.com/insurance-authority/property/articles/2474868", "confidence": "medium", "dollarAmount": null}, {"year": 2026, "outcome": "POLICYHOLDER WIN, balancing the insurer-favorable skew in this claim type's earlier sample: the Second Circuit rejected the insurer's attempt to fragment a single PRP demand (arising partly from firefighting foam used in crash response) into multiple separate claims to limit coverage, holding 'a single claim cannot be a combined claim,' and found the insurers owed a duty to defend.", "caseName": "Town of Harrietstown v. Westchester Fire Insurance Co.", "citation": "No. 25-2253-cv (2d Cir. May 4, 2026) (applying New York law)", "sourceUrl": "https://uphelp.org/two-coasts-two-wins-for-policyholders-in-environmental-coverage-disputes/", "confidence": "high", "dollarAmount": null}, {"year": 2026, "outcome": "POLICYHOLDER WIN: the Ninth Circuit resolved an ambiguity over the umbrella policies' aggregate limits in the insured's favor, holding the policies 'do not specify an aggregate limit for property damage' -- meaning the disputed $9 million stated annual aggregate limit did not cap the insurer's exposure the way the insurer argued. No final dollar recovery figure was reported in available coverage of the ruling.", "caseName": "County of San Bernardino v. Insurance Co. of the State of Pennsylvania", "citation": "No. 24-6986 (9th Cir. Apr. 23, 2026) (applying California law)", "sourceUrl": "https://uphelp.org/two-coasts-two-wins-for-policyholders-in-environmental-coverage-disputes/", "confidence": "high", "dollarAmount": null}, {"year": 2008, "notes": "A landmark, frequently-cited illustration that an 'absolute' pollution exclusion in a general liability or E&O policy can eliminate coverage even for an environmental CONSULTANT's own negligent pollution-related advice -- not just for the underlying contamination itself. Directly relevant to any commercial party relying on an environmental consultant's clearance opinion: that consultant's own insurance may not cover a wrong call.", "outcome": "An environmental consulting firm incorrectly advised its client the client's property was free of pollutants; when that advice proved wrong, the consultant's insurer sought a declaratory judgment that it owed no duty to defend under the policy's pollution exclusion. The Eleventh Circuit's ruling applied the pollution exclusion to bar coverage for the consultant's core professional service of pollution testing and advice.", "caseName": "James River Insurance Co. v. Ground Down Engineering, Inc.", "citation": "540 F.3d 1270 (11th Cir. 2008)", "sourceUrl": "https://caselaw.findlaw.com/us-11th-circuit/1177959.html", "confidence": "high", "dollarAmount": 0, "jurisdiction": "Federal (11th Cir., applying FL law)"}, {"year": 2026, "notes": "This case is ALREADY referenced elsewhere in the dataset (in the Illinois state-modifier table for this claim type, at the 'Illinois' entry, which asserts it is 'already cited under...environmental_insurance_coverage_dispute elsewhere in this dataset') -- but it was NOT actually present in this claim type's citations array prior to this addition. Adding it here closes that gap and makes the cross-reference note accurate.", "outcome": "INSURER WIN: Griffith Foods operated a medical-equipment/food-related sterilization facility alleged to have emitted ethylene oxide for over 35 years, allegedly causing cancer and other illnesses in nearby residents. The Illinois Supreme Court held that a government permit or other regulatory emissions authorization has 'no relevance' to whether a CGL pollution exclusion applies -- the pollution exclusion is triggered by the nature of the contaminant and resulting injury, not by whether the release was legally authorized -- so the government-authorized emissions were still 'pollution' for coverage purposes and the exclusion applied.", "caseName": "Griffith Foods Int'l, Inc. v. National Union Fire Ins. Co. of Pittsburgh, PA", "citation": "2026 IL 131710 (Ill. Sup. Ct. 2026)", "sourceUrl": "https://ilcourtsaudio.blob.core.windows.net/antilles-resources/resources/f07723d1-119f-4c40-a855-86d02698f069/Griffith%20Foods%20Int%20v.%20National%20Union%20Fire%20Ins%202026%20IL%20131710.pdf", "confidence": "high", "dollarAmount": null, "jurisdiction": "Illinois"}, {"year": 2026, "notes": "Full case caption/docket number and the exact Travelers entity name were not confirmed beyond the trade-press summary (which itself sits behind a subscription paywall) -- party names as given ('Bradley' v. 'Travelers') are as reported, not independently verified against a court docket.", "outcome": "PARTIAL POLICYHOLDER WIN: an insured ('Bradley') sought partial summary judgment that Travelers owed a duty to defend against an underlying personal-injury suit alleging exposure to hydrogen sulfide gas. The court granted the motion in relevant part, holding Travelers had failed to show the policy's pollution exclusion barred coverage for that claim.", "caseName": "Bradley v. Travelers Casualty Insurance Co. (or affiliated Travelers entity)", "citation": "C.D. Cal. (Los Angeles), ruling issued Sept. 2, 2026", "sourceUrl": "https://www.mealeys.com/mealeys/mealeys-toxic-torts/articles/2520891", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (C.D. Cal., applying CA law)"}, {"year": 1992, "notes": "Citation and case existence independently confirmed via CourtListener docket search. The substantive summary above reflects general legal knowledge of this well-known, frequently-cited landmark rather than a fresh read of the full opinion text in this session (the opinion's rendered page returned no extractable text) -- recommend confirming the specific holding details against the primary opinion before relying on this for anything beyond 'a real, on-point landmark case exists here.'", "outcome": "Landmark, long-running dispute over historical CGL coverage for New Castle County's landfill-related CERCLA liabilities. Among other issues, the Third Circuit's decision is a leading citation for adopting a 'continuous trigger' theory for progressive, multi-year environmental contamination (rather than requiring the insured to pinpoint a single discrete 'occurrence' date), while resolving other coverage issues (including aspects of the pollution exclusion and number-of-occurrences questions) less favorably to the County -- an overall mixed outcome across the several issues litigated. This is one of several related opinions in the same multi-year New Castle County insurance-coverage litigation (other related decisions include 174 F.3d 338 (3d Cir. 1999) and 243 F.3d 744 (3d Cir. 2001)).", "caseName": "New Castle County v. Hartford Accident and Indemnity Co.", "citation": "970 F.2d 1267 (3d Cir. 1992)", "sourceUrl": "https://www.courtlistener.com/opinion/587606/new-castle-county-v-hartford-accident-and-indemnity-company/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (3d Cir., applying DE law)"}, {"year": 1987, "notes": "Citation and case existence independently confirmed via CourtListener (cited 109 times per that database, confirming its landmark status). As with New Castle County above, the substantive outcome summary reflects general legal knowledge of this well-known case rather than a fresh read of the full opinion text in this session -- confirm the specific holding against the primary opinion before relying on fine-grained details.", "outcome": "POLICYHOLDER WIN (duty to defend): an early, frequently-cited New Jersey landmark holding that a commercial property owner facing a state-agency-driven cleanup obligation for contamination migrating from its property was entitled to a defense from its CGL insurer, addressing what counts as an 'occurrence' and property damage in the context of gradual environmental contamination discovered and remediated under regulatory compulsion rather than through a conventional third-party tort suit.", "caseName": "Broadwell Realty Services, Inc. v. Fidelity & Casualty Co. of New York", "citation": "528 A.2d 76, 218 N.J. Super. 516 (App. Div. 1987)", "sourceUrl": "https://www.courtlistener.com/opinion/2258049/broadwell-realty-services-inc-v-fidelity-cas-co-of-ny/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "NJ"}, {"year": 2024, "outcome": "MIXED/SPLIT outcome on two certified questions -- a real, high-profile, and genuinely balanced data point for this claim type's sample. Honolulu and Maui sued Aloha Petroleum and major oil companies (Exxon, Shell, Chevron, BP, ConocoPhillips) alleging the companies knew since the 1960s that fossil fuel sales would cause climate change and recklessly continued anyway; Aloha sought a defense from its AIG-affiliated CGL insurers (National Union and American Home), which denied coverage. On certified questions from the federal district court, the Hawaii Supreme Court ruled (1) FOR THE POLICYHOLDER on the 'occurrence' question, holding an insured's alleged reckless conduct can qualify as an 'accident' triggering potential coverage, but (2) FOR THE INSURERS on the pollution-exclusion question, holding that greenhouse gases are 'pollutants' (gaseous contaminants) under the policies' pollution exclusions, so that exclusion independently bars coverage for the climate-change claims regardless of the occurrence ruling.", "caseName": "Aloha Petroleum, Ltd. v. National Union Fire Insurance Company of Pittsburgh, PA (and American Home Assurance Co.)", "citation": "No. SCCQ-23-0000515 (Haw. Oct. 7, 2024)", "sourceUrl": "https://law.justia.com/cases/hawaii/supreme-court/2024/sccq-23-0000515.html", "confidence": "high", "dollarAmount": null, "jurisdiction": "Federal certified question answered by Hawaii Supreme Court (underlying suit in D. Haw.)"}, {"year": 2025, "notes": "Case name/citation and outcome corroborated across two independent secondary sources (Morris Manning & Martin summary and a Law360-derived search summary) but the underlying opinion text itself was not directly re-read in this session; recommend a primary-source spot-check before heavy reliance on the precise reasoning language quoted above.", "outcome": "PARTIAL POLICYHOLDER WIN. The insureds operated a marine terminal and chemical storage facility and were sued for alleged environmental contamination after hazardous materials allegedly leaked from storage tanks over a roughly fifty-year period; the underlying complaint described the contamination as occurring both 'suddenly and accidentally, and over long periods of time.' The insurer issued a reservation of rights citing the CGL policies' (1982-1985 policy years) pollution exclusion. The Ninth Circuit affirmed in relevant part the district court's summary judgment for the policyholders, holding the insurer owed at least a potential duty to defend because the complaint did not foreclose the pollution exclusion's 'sudden and accidental' exception, and separately holding that the insurer's reservation of rights created a disqualifying conflict of interest -- because the insurer had 'both the motive and opportunity to defend more vigorously' toward a sudden-pollution theory that would trigger the exception over a gradual-pollution theory that would not -- entitling the policyholders to independent, insured-selected defense counsel at the insurer's expense.", "caseName": "L.A. Terminals, Inc. v. United National Insurance Co.", "citation": "No. 23-55483, 2025 WL 1024392 (9th Cir. Apr. 7, 2025)", "sourceUrl": "https://www.mmmlaw.com/news-resources/102k7rz-ninth-circuit-finds-pollution-exclusion-creates-conflict-requiring-independent-co/", "confidence": "medium", "dollarAmount": null, "jurisdiction": "Federal (9th Cir., applying CA law)"}], "negligent_maintenance_structural_failure": [{"year": 1996, "notes": "Older but well-documented illustration of the durable-defect dynamic this claim type is built on: the rot was concealed under building materials rather than genuinely repaired, and was established through post-collapse inspection rather than relying on a notice-timing argument the way a transient hazard claim would need to.", "outcome": "A fourth-floor balcony at a Pacific Heights apartment building collapsed during a party, caused by extensive dry rot in the supporting joists that had been concealed rather than repaired; one guest died and another suffered a severe brain injury. The jury awarded $12,389,050 against the building's owner/landlord for negligent maintenance of the structure, and additionally ordered the landlord to live in his own building.", "caseName": "(Balcony collapse litigation re: 2003 Franklin Street)", "citation": "San Francisco County Superior Court No. CGC-95-968644", "sourceUrl": "https://www.sfgate.com/news/article/Landlord-to-Pay-12-Million-in-Fatal-96-Deck-3009451.php", "confidence": "medium", "dollarAmount": 12389050, "jurisdiction": "CA"}, {"year": 2010, "notes": "Widely reported (originally by Milwaukee-area news outlets; summarized here via a plaintiff-firm blog) but the formal case caption/docket was not independently retrieved. A strong illustration of how a durable structural defect (a fabrication/installation error, not a transient hazard) is proven largely through forensic engineering evidence rather than notice timing, and of multi-defendant fault apportionment in a structural-failure claim.", "outcome": "A precast-concrete slab weighing over 13 tons fell from a Milwaukee County parking structure, killing 15-year-old Jared Kellner and injuring two others. The jury found the precast manufacturer, Advance Cast Stone, had attached the slab using only two steel connecting rods where four were required, and apportioned 88% fault to Advance Cast Stone, 10% to the construction-oversight contractor, and 2% to Milwaukee County. Total damages awarded reached $39 million.", "caseName": "(Kellner family, et al.) v. Advance Cast Stone Co., J.H. Findorff & Son, and Milwaukee County", "citation": "Milwaukee County, Wisconsin jury verdict (case caption and exact date not independently confirmed; underlying collapse occurred June 24, 2010)", "sourceUrl": "https://frenkelfirm.com/blog/39-million-awarded-in-parking-garage-collapse-lawsuit/", "confidence": "medium", "dollarAmount": 39000000, "jurisdiction": "WI"}, {"year": 2013, "notes": "Year is an approximation based on secondary reporting; exact verdict date not independently confirmed, though the case's existence is corroborated by an independent CourtListener docket entry (Valenti v. Central Parking). A commercial parking-STRUCTURE (not a surface lot) structural-failure exemplar, which the category's fact-pattern guidance specifically calls for.", "outcome": "A parking attendant suffered catastrophic crush injuries when a parking booth at the Wachovia Center (Philadelphia's sports arena, now Xfinity Mobile Arena) structurally failed and collapsed onto him. The jury returned a $5,000,000 verdict against the parking-facility operator/manager for negligent maintenance of the booth structure.", "caseName": "Valenti v. Central Parking System of Pennsylvania, Inc.", "citation": "Philadelphia County Court of Common Pleas jury verdict (docket not independently confirmed)", "sourceUrl": "https://beasleyfirm.com/blog/grays-ferry-parking-garage-collapse-lawsuit/", "confidence": "medium", "dollarAmount": 5000000, "jurisdiction": "PA"}, {"year": 2007, "notes": "Independently corroborated by multiple contemporaneous outlets (ABA Journal, Philadelphia Inquirer, Insurance Journal, hotelexecutive.com). Although this was a construction-phase (not yet-open-to-the-public) structural failure, it is a genuine, massive, well-documented illustration of catastrophic structural-defect exposure tied to a commercial parking structure.", "outcome": "A parking garage under construction at the Tropicana Casino in Atlantic City collapsed on October 30, 2003, killing four construction workers and injuring more than 30 others; the cause was determined to be a failure to properly fasten the parking-deck floors to the supporting walls. Tropicana, the general contractor (Keating Building Corp.), and subcontractors (Midstate Filigree Systems, Fabi Construction) reached a global settlement of approximately $101 million -- reported as the largest construction-accident settlement in U.S. history at the time.", "caseName": "In re: Tropicana Casino & Resort Parking Garage Collapse Litigation", "citation": "New Jersey Superior Court, Atlantic County; global settlement approved April 2007 (underlying collapse occurred Oct. 30, 2003)", "sourceUrl": "https://www.insurancejournal.com/news/east/2007/04/12/78674.htm", "confidence": "high", "dollarAmount": 101000000, "jurisdiction": "NJ"}, {"year": 2012, "notes": "Jurisdiction is inferred and not independently confirmed (source did not clearly state the state); case caption/docket not found. Included because it is a real, sizable, multifamily-common-area structural-failure verdict consistent with the claim type's fact pattern, but should be re-verified against a primary source before being relied on for anything beyond illustrative use.", "outcome": "A staircase at the Legacy Corner Apartments complex collapsed under the plaintiff as he reached the bottom step, causing him to fall and suffer an ankle injury that progressed to complex regional pain syndrome. He sued the complex's owner and manager for negligent maintenance, alleging they allowed the staircase to structurally deteriorate. The jury returned a $12 million verdict.", "caseName": "(37-year-old plaintiff) v. (owner/manager of Legacy Corner Apartments)", "citation": "Jury verdict (state/county and docket not independently confirmed; underlying incident occurred 2012)", "sourceUrl": "https://www.nstlaw.com/blog/verdict-12-million-awarded-negligence-lawsuit-apartment-complex/", "confidence": "low", "dollarAmount": 12000000, "jurisdiction": "FL"}, {"year": 2024, "notes": "Source is a reputable legal-industry publication (NJ Law Journal/Law.com), but the full article was not independently re-accessible (403) to confirm additional docket detail beyond the publicly available summary. A clean illustration of split liability between a property OWNER and a MAINTENANCE CONTRACTOR for the same structural-failure defect, relevant to apportionment modeling.", "outcome": "Plaintiff fell approximately eight feet into an open elevator shaft at a loading dock when the elevator doors opened even though the elevator car was not present at that floor, causing multiple fractures and a traumatic brain injury. The case settled for $8 million against the property owner and the elevator maintenance contractor jointly, reached on the first day of trial.", "caseName": "(53-year-old maintenance/loading-dock worker) v. (property owner and elevator maintenance company)", "citation": "New Jersey Superior Court, settlement reported by the New Jersey Law Journal, May 1, 2024 (case caption not disclosed)", "sourceUrl": "https://www.law.com/njlawjournal/2024/05/01/8-million-settlement-reached-for-fall-into-open-elevator-shaft/", "confidence": "medium", "dollarAmount": 8000000, "jurisdiction": "NJ"}, {"year": 2023, "notes": "Reported directly by plaintiff's counsel's own case-results page; case caption, exact date, and building type not independently confirmed. Included as a real, comparatively modest-dollar structural/mechanical-failure settlement, useful as a lower-end data point rather than only headline catastrophic verdicts.", "outcome": "While riding a commercial-building elevator, the car rapidly descended and stopped abruptly between floors, throwing the plaintiff to the ground; the elevator's escape hatch then fell and struck him in the head, neck, and shoulder, causing a herniated cervical disc requiring fusion surgery. The elevator repair company argued the unit was properly maintained; the case settled at mediation, before trial, for $1.9 million.", "caseName": "(29-year-old union maintenance worker) v. (commercial building owner and elevator repair company)", "citation": "Kings County, New York, settlement at mediation (case caption and date not disclosed)", "sourceUrl": "https://www.blockotoole.com/verdicts-settlements/elevator-accident-victim-awarded-settlement-for-shoulder-and-neck-injuries/", "confidence": "low", "dollarAmount": 1900000, "jurisdiction": "NY"}, {"caseName": "Valdez v. Macy's Retail Holdings, Inc. and ThyssenKrupp Elevator Corp.", "citation": "Jury verdict/settlement, Superior Court of New Jersey, Bergen County, settled May 2016", "year": 2016, "outcome": "An 11-year-old girl's foot and leg were caught, crushed, and torn in a 58-year-old escalator at a Macy's department store in the Garden State Plaza mall in Paramus, NJ in August 2013, requiring roughly 15-22 surgeries. An independent NBC New York investigation confirmed the escalator's required maintenance had not been completed and its temporary operating certificate had expired before the accident. Macy's (owner) and ThyssenKrupp Elevator (contracted for inspection/maintenance) settled the resulting lawsuit for $15 million without admitting liability.", "dollarAmount": 15000000, "sourceUrl": "https://www.nbcnewyork.com/news/local/girl-loses-toes-escalator-accident-macys-garden-state-plaza-mall-expired-certificate/1988386/", "confidence": "high", "jurisdiction": "NJ"}, {"caseName": "Siddiqui v. CBL & Associates Properties, Inc. and KONE Inc.", "citation": "Jury verdict, Pulaski County Circuit Court, Arkansas, Dec. 7, 2018", "year": 2018, "outcome": "A shopper's right big toe was crushed and severed when her foot was pulled into a gap created by a mechanical break in an escalator at Park Plaza Mall in Little Rock, Arkansas, in December 2013. Mall owner CBL & Associates and escalator manufacturer/maintenance contractor KONE Inc. admitted fault before trial but argued only $500,000 was warranted; a Pulaski County jury instead awarded $3 million in damages.", "dollarAmount": 3000000, "sourceUrl": "https://www.claimsjournal.com/news/southcentral/2018/12/10/288190.htm", "confidence": "high", "jurisdiction": "AR"}]}$$::jsonb, now())
